// ══════════════════════════════════════════════════════════════════════
//  🔊 POINT INVADERS — AUDIO ENGINE
// ══════════════════════════════════════════════════════════════════════
// Every sound in the arcade is SYNTHESISED at runtime out of oscillators and
// noise — there are no .wav/.mp3 files to ship, fetch, cache or 404 on. That
// keeps the whole hub a three-file drop-in that still works from a file:// URL
// or offline, and it means a laser can be pitched per-shot instead of being one
// frozen recording replayed 200 times a round.
//
// Public surface (all no-ops, never throwing, if Web Audio is missing):
//   SFX.play(name, opts)   — one-shot effect; opts {vol, semi, rate}
//   SFX.music(track)       — 'hub' | 'game' | null
//   SFX.mode / cycleMode() — 'full' → 'sfx' → 'mute' → 'full'
//   SFX.bindToggle(el)     — wires a button to cycleMode() and keeps it labelled
//
// The engine stays deliberately self-contained: a single IIFE that knows
// nothing about games, screens or scores and shares nothing with the rest of
// this file but the window.SFX handle, so it can still be lifted straight back
// out into another project. It sits at the very top because the code below
// binds the 🔊 buttons via SFX.bindToggle() while loading.
window.SFX = (function(){
'use strict';

// ── PERSISTED PREFERENCES ─────────────────────────────────────────────
// One control, three settings. Music is the part people turn off first, so it
// gets its own rung on the ladder rather than being all-or-nothing with the
// effects. localStorage is wrapped because Safari's private mode throws on it.
const LS_KEY = 'pi_audio_mode';
const MODES = ['full','sfx','mute'];
function loadMode(){
  try{ const v = localStorage.getItem(LS_KEY); return MODES.includes(v) ? v : 'full'; }
  catch(e){ return 'full'; }
}
function saveMode(m){ try{ localStorage.setItem(LS_KEY, m); }catch(e){} }

let mode = loadMode();

// Master volume, 0–100. 100 maps to the historical 0.85 master gain, and the
// curve is perceptual — half-slider should sound half as loud, not nearly full.
const LS_VOL = 'pi_audio_vol';
function loadVol(){
  try{
    const v = parseInt(localStorage.getItem(LS_VOL));
    return (v >= 0 && v <= 100) ? v : 100;
  }catch(e){ return 100; }
}
let volume = loadVol();
const volGain = () => 0.85 * Math.pow(volume / 100, 1.6);
function setVolume(v){
  volume = Math.max(0, Math.min(100, Math.round(v) || 0));
  try{ localStorage.setItem(LS_VOL, String(volume)); }catch(e){}
  if(ctx && master){
    const t = ctx.currentTime;
    master.gain.cancelScheduledValues(t);
    master.gain.setTargetAtTime(volGain(), t, 0.02);
  }
}

// ── GRAPH ─────────────────────────────────────────────────────────────
//   voices ─┬─▶ sfxBus  ──┬─▶ comp ─▶ master ─▶ speakers
//           └─▶ musicBus ─┘        (delay send hangs off musicBus)
// The compressor is the thing that keeps a Nova Bomb — thirty explosions in
// four frames — from clipping into a crackle. Buses are separate so muting the
// music can't cut an effect that's mid-decay.
let ctx=null, master=null, comp=null, sfxBus=null, musicBus=null, musicDelay=null;
let noiseBuf=null, unlocked=false;

const SUPPORTED = !!(window.AudioContext || window.webkitAudioContext);

function ensureCtx(){
  if(ctx || !SUPPORTED) return ctx;
  try{
    const AC = window.AudioContext || window.webkitAudioContext;
    ctx = new AC();

    comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16; comp.knee.value = 24; comp.ratio.value = 12;
    comp.attack.value = 0.003; comp.release.value = 0.25;

    master = ctx.createGain();   master.gain.value = volGain();
    sfxBus = ctx.createGain();   sfxBus.gain.value = (mode === 'mute') ? 0 : 1;
    musicBus = ctx.createGain(); musicBus.gain.value = (mode === 'full') ? 1 : 0;

    // Feedback delay on the music only — it's what turns four bare oscillators
    // into something that sounds like a soundtrack. Effects stay dry so a hit
    // still reads as instant feedback.
    musicDelay = ctx.createDelay(1.0);
    // Placeholder only — music() retunes this to the track's tempo on every
    // start. A delay is a rhythmic instrument here, not an ambience knob.
    musicDelay.delayTime.value = 0.30;
    const fb = ctx.createGain(); fb.gain.value = 0.34;
    const wet = ctx.createGain(); wet.gain.value = 0.30;
    const damp = ctx.createBiquadFilter(); damp.type='lowpass'; damp.frequency.value = 2600;
    musicDelay.connect(damp); damp.connect(fb); fb.connect(musicDelay);
    musicDelay.connect(wet); wet.connect(comp);

    sfxBus.connect(comp); musicBus.connect(comp);
    comp.connect(master); master.connect(ctx.destination);
  }catch(e){ ctx = null; }
  return ctx;
}

// Browsers hand back a SUSPENDED context until the page has been interacted
// with, and silently drop anything scheduled into it. Every plausible first
// gesture resumes it, then unhooks itself.
// resume() is a promise, and on the very first gesture the context is still
// SUSPENDED when the handler returns — so the retry has to hang off the promise
// rather than off a state read taken microseconds too early. Getting this wrong
// leaves the soundtrack permanently silent while effects work fine.
function unlock(){
  const c = ensureCtx();
  if(!c) return;
  unlocked = true;
  if(c.state === 'suspended') c.resume().then(resumeMusic).catch(()=>{});
  else resumeMusic();
}
['pointerdown','touchstart','keydown','mousedown','click'].forEach(ev=>{
  window.addEventListener(ev, unlock, { capture:true, passive:true });
});

// Tabbing away shouldn't leave a soundtrack playing in a background tab, and
// setInterval throttling there would bunch the scheduler up anyway.
document.addEventListener('visibilitychange', ()=>{
  if(!ctx) return;
  if(document.hidden){ try{ ctx.suspend(); }catch(e){} }
  else if(unlocked){ try{ ctx.resume().then(resumeMusic).catch(()=>{}); }catch(e){} }
});

function noiseBuffer(){
  if(noiseBuf) return noiseBuf;
  const len = Math.floor(ctx.sampleRate * 1.2);
  noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = noiseBuf.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = Math.random()*2 - 1;
  return noiseBuf;
}

// ── PRIMITIVES ────────────────────────────────────────────────────────
const mtof = m => 440 * Math.pow(2, (m - 69) / 12);
const clampF = f => Math.max(20, Math.min(18000, f || 20));

// A single pitched voice. f1 makes it a sweep, which is the whole vocabulary of
// retro sound design: up = good, down = bad, down-fast = laser.
function tone(t0, o){
  const g = ctx.createGain();
  const osc = ctx.createOscillator();
  const dur = o.dur, vol = o.vol == null ? 0.2 : o.vol;
  osc.type = o.type || 'square';
  osc.frequency.setValueAtTime(clampF(o.f0), t0);
  if(o.f1 && o.f1 !== o.f0){
    if(o.linear) osc.frequency.linearRampToValueAtTime(clampF(o.f1), t0 + dur);
    else osc.frequency.exponentialRampToValueAtTime(clampF(o.f1), t0 + dur);
  }
  if(o.detune) osc.detune.setValueAtTime(o.detune, t0);

  const atk = o.attack == null ? 0.005 : o.attack;
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + atk);
  if(o.hold) g.gain.setValueAtTime(Math.max(0.0002, vol), t0 + Math.min(dur, atk + o.hold));
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);

  osc.connect(g);
  let tail = g;
  if(o.filter){
    const f = ctx.createBiquadFilter();
    f.type = o.filter;
    f.frequency.setValueAtTime(clampF(o.fc), t0);
    if(o.fc1) f.frequency.exponentialRampToValueAtTime(clampF(o.fc1), t0 + dur);
    f.Q.value = o.q == null ? 1 : o.q;
    g.connect(f); tail = f;
  }
  tail.connect(o.bus || sfxBus);
  if(o.send) tail.connect(o.send);

  osc.start(t0);
  osc.stop(t0 + dur + 0.03);
  return osc;
}

// Noise through a swept filter: every impact, whoosh and explosion in the hub.
function noise(t0, o){
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer();
  src.loop = true;
  src.playbackRate.value = o.rate || 1;

  const f = ctx.createBiquadFilter();
  f.type = o.filter || 'lowpass';
  f.frequency.setValueAtTime(clampF(o.fc), t0);
  if(o.fc1) f.frequency.exponentialRampToValueAtTime(clampF(o.fc1), t0 + o.dur);
  f.Q.value = o.q == null ? 1 : o.q;

  const g = ctx.createGain();
  const vol = o.vol == null ? 0.2 : o.vol;
  const atk = o.attack == null ? 0.003 : o.attack;
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + atk);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + o.dur);

  src.connect(f); f.connect(g); g.connect(o.bus || sfxBus);
  if(o.send) g.connect(o.send);
  src.start(t0);
  src.stop(t0 + o.dur + 0.03);
  return src;
}

// Play a run of notes as one gesture — used by every chime, fanfare and denial.
function seq(t0, notes, o){
  o = o || {};
  notes.forEach((n, i) => {
    const step = o.step == null ? 0.075 : o.step;
    tone(t0 + i * step, {
      type: o.type || 'square',
      f0: mtof(n), f1: o.glide ? mtof(n) * o.glide : 0,
      dur: o.dur == null ? 0.16 : o.dur,
      vol: (o.vol == null ? 0.18 : o.vol) * (o.fade ? 1 - i * 0.12 : 1),
      attack: o.attack
    });
  });
}

// ── EFFECT BANK ───────────────────────────────────────────────────────
// `gap` is the minimum milliseconds between retriggers of the same effect. Game
// loops fire collision events dozens of times per frame; without a floor here,
// a Meltdown-tier Nebula wave stacks 40 identical explosions on the same sample
// boundary and the result is a click, not a bang. It also caps the voice count
// for free.
const BANK = {
  // ── INTERFACE ──
  ui:        { gap: 30,  fn:(t)=>{ tone(t,{type:'triangle',f0:880,f1:1180,dur:0.055,vol:0.13}); } },
  uiBack:    { gap: 30,  fn:(t)=>{ tone(t,{type:'triangle',f0:640,f1:400,dur:0.075,vol:0.13}); } },
  hover:     { gap: 45,  fn:(t)=>{ tone(t,{type:'sine',f0:1500,dur:0.028,vol:0.05}); } },
  tab:       { gap: 30,  fn:(t)=>{ tone(t,{type:'square',f0:1046,dur:0.045,vol:0.09}); } },
  toggle:    { gap: 30,  fn:(t)=>{ seq(t,[76,83],{type:'square',dur:0.09,vol:0.13,step:0.055}); } },
  error:     { gap: 120, fn:(t)=>{ tone(t,{type:'sawtooth',f0:190,f1:96,dur:0.28,vol:0.16,filter:'lowpass',fc:900});
                                   tone(t+0.09,{type:'sawtooth',f0:150,f1:80,dur:0.24,vol:0.12,filter:'lowpass',fc:700}); } },
  deny:      { gap: 90,  fn:(t)=>{ tone(t,{type:'square',f0:240,f1:150,dur:0.16,vol:0.14}); } },
  success:   { gap: 120, fn:(t)=>{ seq(t,[72,76,79,84],{type:'square',dur:0.2,vol:0.15,step:0.07}); } },
  login:     { gap: 200, fn:(t)=>{ seq(t,[60,67,72,76,79],{type:'triangle',dur:0.42,vol:0.13,step:0.085});
                                   noise(t,{dur:0.5,vol:0.05,filter:'highpass',fc:400,fc1:5000}); } },
  logout:    { gap: 200, fn:(t)=>{ seq(t,[72,67,60,55],{type:'triangle',dur:0.3,vol:0.12,step:0.085}); } },

  // ── ECONOMY ──
  coin:      { gap: 40,  fn:(t)=>{ tone(t,{type:'square',f0:mtof(88),dur:0.07,vol:0.15});
                                   tone(t+0.06,{type:'square',f0:mtof(93),dur:0.22,vol:0.15}); } },
  purchase:  { gap: 150, fn:(t)=>{ seq(t,[72,76,79,84,88],{type:'square',dur:0.26,vol:0.14,step:0.06});
                                   noise(t+0.1,{dur:0.5,vol:0.05,filter:'bandpass',fc:3000,fc1:8000,q:2}); } },
  equip:     { gap: 120, fn:(t)=>{ seq(t,[79,84,88],{type:'triangle',dur:0.3,vol:0.14,step:0.055});
                                   noise(t,{dur:0.35,vol:0.045,filter:'highpass',fc:2000,fc1:9000}); } },
  convert:   { gap: 150, fn:(t)=>{ tone(t,{type:'sine',f0:400,f1:1200,dur:0.3,vol:0.14});
                                   seq(t+0.14,[84,91],{type:'square',dur:0.2,vol:0.11,step:0.07}); } },

  // ── ROUND FLOW ──
  countdown: { gap: 200, fn:(t)=>{ tone(t,{type:'square',f0:520,dur:0.16,vol:0.16,hold:0.06});
                                   tone(t,{type:'sine',f0:1040,dur:0.1,vol:0.06}); } },
  go:        { gap: 200, fn:(t)=>{ tone(t,{type:'square',f0:880,dur:0.42,vol:0.2,hold:0.18});
                                   tone(t,{type:'square',f0:1320,dur:0.42,vol:0.09,hold:0.18});
                                   noise(t,{dur:0.3,vol:0.06,filter:'highpass',fc:1200,fc1:8000}); } },
  gameOver:  { gap: 400, fn:(t)=>{ seq(t,[65,62,58,53],{type:'sawtooth',dur:0.45,vol:0.16,step:0.15});
                                   tone(t+0.45,{type:'sine',f0:120,f1:45,dur:0.9,vol:0.18}); } },
  victory:   { gap: 400, fn:(t)=>{ seq(t,[72,76,79,84],{type:'square',dur:0.3,vol:0.16,step:0.1});
                                   seq(t+0.4,[88],{type:'square',dur:0.7,vol:0.17,step:0.1});
                                   noise(t+0.4,{dur:0.8,vol:0.05,filter:'bandpass',fc:2000,fc1:9000,q:1.5}); } },
  results:   { gap: 400, fn:(t)=>{ seq(t,[67,72,76],{type:'triangle',dur:0.35,vol:0.14,step:0.09}); } },

  // ── WEAPONS & IMPACTS ──
  shoot:     { gap: 45,  fn:(t,o)=>{ const p=Math.pow(2,(o.semi||0)/12);
                                   tone(t,{type:'square',f0:940*p,f1:180*p,dur:0.11,vol:0.11,filter:'lowpass',fc:5000,fc1:900}); } },
  plasma:    { gap: 55,  fn:(t)=>{ tone(t,{type:'sawtooth',f0:1300,f1:210,dur:0.16,vol:0.11,filter:'lowpass',fc:4000,fc1:700,q:6});
                                   tone(t,{type:'square',f0:650,f1:120,dur:0.14,vol:0.05}); } },
  missile:   { gap: 60,  fn:(t)=>{ noise(t,{dur:0.28,vol:0.10,filter:'bandpass',fc:500,fc1:2600,q:1.4});
                                   tone(t,{type:'sawtooth',f0:180,f1:640,dur:0.26,vol:0.07}); } },
  enemyShot: { gap: 70,  fn:(t)=>{ tone(t,{type:'sawtooth',f0:420,f1:110,dur:0.13,vol:0.07,filter:'lowpass',fc:2200,fc1:500}); } },
  hit:       { gap: 30,  fn:(t)=>{ noise(t,{dur:0.07,vol:0.13,filter:'bandpass',fc:2200,q:1.2});
                                   tone(t,{type:'square',f0:420,f1:200,dur:0.06,vol:0.07}); } },
  explode:   { gap: 45,  fn:(t)=>{ noise(t,{dur:0.34,vol:0.24,filter:'lowpass',fc:2400,fc1:120});
                                   tone(t,{type:'sine',f0:190,f1:48,dur:0.3,vol:0.16}); } },
  bigExplode:{ gap: 140, fn:(t)=>{ noise(t,{dur:0.75,vol:0.3,filter:'lowpass',fc:3800,fc1:80});
                                   tone(t,{type:'sine',f0:150,f1:34,dur:0.8,vol:0.26});
                                   tone(t,{type:'sawtooth',f0:90,f1:28,dur:0.6,vol:0.1,filter:'lowpass',fc:600}); } },
  slash:     { gap: 60,  fn:(t)=>{ noise(t,{dur:0.13,vol:0.14,filter:'bandpass',fc:3400,fc1:700,q:2.2});
                                   tone(t,{type:'sawtooth',f0:800,f1:260,dur:0.1,vol:0.05}); } },
  dash:      { gap: 90,  fn:(t)=>{ noise(t,{dur:0.24,vol:0.12,filter:'bandpass',fc:700,fc1:3400,q:1.6});
                                   tone(t,{type:'sine',f0:260,f1:820,dur:0.2,vol:0.06}); } },

  // ── PLAYER STATE ──
  hurt:      { gap: 110, fn:(t)=>{ tone(t,{type:'sawtooth',f0:340,f1:90,dur:0.32,vol:0.17,filter:'lowpass',fc:1600,fc1:400});
                                   noise(t,{dur:0.16,vol:0.11,filter:'lowpass',fc:1200}); } },
  shieldHit: { gap: 100, fn:(t)=>{ tone(t,{type:'sine',f0:900,f1:280,dur:0.22,vol:0.13});
                                   noise(t,{dur:0.12,vol:0.07,filter:'bandpass',fc:1800,q:3}); } },
  heal:      { gap: 150, fn:(t)=>{ seq(t,[72,79,84],{type:'sine',dur:0.4,vol:0.13,step:0.07}); } },
  shield:    { gap: 150, fn:(t)=>{ tone(t,{type:'sine',f0:300,f1:1100,dur:0.42,vol:0.13});
                                   tone(t+0.05,{type:'triangle',f0:450,f1:1650,dur:0.4,vol:0.07}); } },
  powerup:   { gap: 120, fn:(t)=>{ seq(t,[67,72,76,79,84],{type:'square',dur:0.24,vol:0.14,step:0.055}); } },
  levelUp:   { gap: 250, fn:(t)=>{ seq(t,[60,64,67,72,76,79,84],{type:'square',dur:0.34,vol:0.15,step:0.06});
                                   noise(t,{dur:0.6,vol:0.05,filter:'highpass',fc:600,fc1:8000}); } },
  ability:   { gap: 160, fn:(t)=>{ tone(t,{type:'sawtooth',f0:120,f1:1400,dur:0.4,vol:0.13,filter:'lowpass',fc:600,fc1:6000,q:5});
                                   seq(t+0.2,[84,91],{type:'square',dur:0.3,vol:0.11,step:0.07}); } },
  charge:    { gap: 200, fn:(t)=>{ tone(t,{type:'sawtooth',f0:200,f1:1600,dur:0.7,vol:0.1,filter:'lowpass',fc:800,fc1:5000,q:8}); } },

  // ── PICKUPS & SCORING ──
  pickup:    { gap: 35,  fn:(t,o)=>{ const p=Math.pow(2,(o.semi||0)/12);
                                   tone(t,{type:'triangle',f0:760*p,f1:1420*p,dur:0.1,vol:0.13}); } },
  eat:       { gap: 35,  fn:(t,o)=>{ const p=Math.pow(2,(o.semi||0)/12);
                                   tone(t,{type:'square',f0:600*p,f1:1000*p,dur:0.08,vol:0.12});
                                   tone(t+0.05,{type:'square',f0:1000*p,dur:0.09,vol:0.09}); } },
  score:     { gap: 45,  fn:(t,o)=>{ const s=o.semi||0; seq(t,[84+s,91+s],{type:'square',dur:0.2,vol:0.13,step:0.055}); } },
  combo:     { gap: 45,  fn:(t,o)=>{ const s=Math.min(12,o.semi||0); seq(t,[79+s,86+s],{type:'square',dur:0.18,vol:0.12,step:0.045}); } },
  wave:      { gap: 300, fn:(t)=>{ seq(t,[62,69,74,81],{type:'square',dur:0.36,vol:0.15,step:0.08});
                                   noise(t,{dur:0.5,vol:0.05,filter:'bandpass',fc:800,fc1:6000,q:1.5}); } },

  // ── PHYSICS / BOARD ──
  bounce:    { gap: 25,  fn:(t,o)=>{ const p=Math.pow(2,(o.semi||0)/12);
                                   tone(t,{type:'square',f0:620*p,f1:520*p,dur:0.07,vol:0.13}); } },
  bounceWall:{ gap: 25,  fn:(t)=>{ tone(t,{type:'square',f0:330,f1:290,dur:0.06,vol:0.10}); } },
  brick:     { gap: 25,  fn:(t,o)=>{ const s=o.semi||0;
                                   tone(t,{type:'square',f0:mtof(72+s),dur:0.08,vol:0.13});
                                   noise(t,{dur:0.06,vol:0.06,filter:'bandpass',fc:3200,q:2}); } },
  jump:      { gap: 40,  fn:(t)=>{ tone(t,{type:'square',f0:300,f1:760,dur:0.13,vol:0.12,filter:'lowpass',fc:3000});
                                   noise(t,{dur:0.09,vol:0.05,filter:'highpass',fc:2000}); } },
  flap:      { gap: 40,  fn:(t)=>{ tone(t,{type:'triangle',f0:420,f1:900,dur:0.1,vol:0.12});
                                   noise(t,{dur:0.08,vol:0.06,filter:'bandpass',fc:1400,fc1:3000,q:1.2}); } },
  rotate:    { gap: 25,  fn:(t)=>{ tone(t,{type:'square',f0:520,f1:640,dur:0.045,vol:0.09}); } },
  move:      { gap: 25,  fn:(t)=>{ tone(t,{type:'square',f0:300,dur:0.028,vol:0.06}); } },
  land:      { gap: 40,  fn:(t)=>{ tone(t,{type:'sine',f0:200,f1:70,dur:0.14,vol:0.16});
                                   noise(t,{dur:0.09,vol:0.09,filter:'lowpass',fc:900}); } },
  hardDrop:  { gap: 60,  fn:(t)=>{ tone(t,{type:'sawtooth',f0:700,f1:90,dur:0.13,vol:0.13,filter:'lowpass',fc:2600,fc1:400});
                                   noise(t+0.1,{dur:0.16,vol:0.14,filter:'lowpass',fc:1000,fc1:200}); } },
  lineClear: { gap: 80,  fn:(t,o)=>{ const n=Math.max(1,Math.min(4,o.semi||1));
                                   seq(t,[72,76,79,84].slice(0,n+1),{type:'square',dur:0.3,vol:0.15,step:0.05});
                                   noise(t,{dur:0.35+n*0.05,vol:0.09,filter:'bandpass',fc:900,fc1:7000,q:1.2}); } },

  // ── PUZZLE / QUIZ ──
  flip:      { gap: 30,  fn:(t)=>{ tone(t,{type:'triangle',f0:700,f1:980,dur:0.06,vol:0.10}); } },
  match:     { gap: 60,  fn:(t,o)=>{ const s=o.semi||0; seq(t,[76+s,83+s],{type:'sine',dur:0.3,vol:0.15,step:0.075}); } },
  correct:   { gap: 50,  fn:(t)=>{ seq(t,[79,86],{type:'square',dur:0.2,vol:0.14,step:0.06}); } },
  wrong:     { gap: 60,  fn:(t)=>{ tone(t,{type:'sawtooth',f0:220,f1:130,dur:0.22,vol:0.13,filter:'lowpass',fc:1100}); } },
  // Node Hacker pitches its 16 keys up a minor-pentatonic ladder, so a correct
  // replay is literally the melody you were just played back.
  node:      { gap: 20,  fn:(t,o)=>{ const scale=[0,3,5,7,10];
                                   const i=Math.max(0,o.semi||0);
                                   const m=57 + scale[i%5] + 12*Math.floor(i/5);
                                   tone(t,{type:'triangle',f0:mtof(m),dur:0.26,vol:0.16});
                                   tone(t,{type:'sine',f0:mtof(m+12),dur:0.2,vol:0.06}); } },
  alarm:     { gap: 500, fn:(t)=>{ tone(t,{type:'square',f0:880,dur:0.16,vol:0.13,hold:0.06});
                                   tone(t+0.2,{type:'square',f0:660,dur:0.2,vol:0.13,hold:0.06}); } },
  tick:      { gap: 200, fn:(t)=>{ tone(t,{type:'square',f0:1200,dur:0.04,vol:0.08}); } }
};

// ── PLAYBACK ──────────────────────────────────────────────────────────
const lastAt = Object.create(null);

function play(name, opts){
  if(mode === 'mute') return;
  const def = BANK[name];
  if(!def) return;
  const now = performance.now();
  if(now - (lastAt[name] || -1e9) < def.gap) return;
  lastAt[name] = now;
  const c = ensureCtx();
  if(!c || c.state !== 'running') return;
  try{ def.fn(c.currentTime + 0.001, opts || {}); }
  catch(e){ /* one bad effect must never take a game frame down with it */ }
}

// ══════════════════════════════════════════════════════════════════════
//  🎵 MUSIC — a step sequencer, not a file
// ══════════════════════════════════════════════════════════════════════
// Same four-chord synthwave loop underneath both tracks (Am–F–C–G); the hub
// plays it as a slow pad-and-arp, a round plays it at nearly 1.5× with a kick,
// a hat and a driving sixteenth arpeggio. Notes are scheduled ahead of the
// clock in a lookahead window, because setInterval is far too jittery to place
// a downbeat on its own.
// ── PROGRESSIONS ──
// One set per Music Drive. The sequencer never learns which drive is playing;
// it reads whatever `CHORDS` currently points at, so a new drive is a new entry
// here and a row in SHOP_ITEMS.drives — never a change to musicStep().
const CHORD_SETS = {
  classic: [                                        // Am–F–C–G · the house sound
    { root: 45, notes: [45, 48, 52, 57, 60, 64] },  // Am
    { root: 41, notes: [41, 45, 48, 53, 57, 60] },  // F
    { root: 48, notes: [48, 52, 55, 60, 64, 67] },  // C
    { root: 43, notes: [43, 47, 50, 55, 59, 62] }   // G
  ],
  dark: [                                           // Dm–Bb–Gm–A · minor, heavier
    { root: 38, notes: [38, 41, 45, 50, 53, 57] },  // Dm
    { root: 34, notes: [34, 38, 41, 46, 50, 53] },  // Bb
    { root: 43, notes: [43, 46, 50, 55, 58, 62] },  // Gm
    { root: 45, notes: [45, 49, 52, 57, 61, 64] }   // A (major third — the sting)
  ],
  bright: [                                         // C–G–Am–F · the lift
    { root: 48, notes: [48, 52, 55, 60, 64, 67] },  // C
    { root: 43, notes: [43, 47, 50, 55, 59, 62] },  // G
    { root: 45, notes: [45, 48, 52, 57, 60, 64] },  // Am
    { root: 41, notes: [41, 45, 48, 53, 57, 60] }   // F
  ],
  vapor: [                                          // Fmaj7–Em7–Dm7–Cmaj7 · drift
    { root: 41, notes: [41, 45, 48, 52, 57, 60] },
    { root: 40, notes: [40, 43, 47, 50, 55, 59] },
    { root: 38, notes: [38, 41, 45, 48, 53, 57] },
    { root: 36, notes: [36, 40, 43, 47, 52, 55] }
  ]
};

// The live progression and voicing. Swapped by setDrive(); the defaults ARE the
// Synthwave Retro drive, so an account that never opens the market sounds
// exactly as it always has.
let CHORDS = CHORD_SETS.classic;
let VOICE  = { pad:'sawtooth', lead:'square', bass:'sawtooth' };

const TRACKS = {
  hub:  { bpm: 92,  gain: 0.30, baseBpm: 92  },
  game: { bpm: 136, gain: 0.26, baseBpm: 136 }
};

// ── ⏱️ TENSION ──
// A round whose clock has dropped under five seconds gets the whole loop lifted
// 25% — tempo AND pitch together, which is what makes it read as panic rather
// than as a tempo change. One multiplier drives both, so they can never drift
// apart. `tension` is the target; `tensionNow` is what the scheduler has
// actually reached, ramped over a few steps so the lift arrives as a surge
// instead of a jump cut.
const TENSION_MUL = 1.25;
let tension = 1, tensionNow = 1;

let curTrack = null, pendingTrack = null, schedTimer = null;
let nextStepTime = 0, stepIdx = 0;
const LOOKAHEAD = 0.15, TICK_MS = 25;

function kick(t, vol){
  tone(t, { type:'sine', f0:170, f1:44, dur:0.20, vol:vol, attack:0.002, bus:musicBus });
  noise(t, { dur:0.045, vol:vol*0.5, filter:'lowpass', fc:1600, fc1:300, bus:musicBus });
}
function hat(t, vol, open){
  noise(t, { dur: open?0.14:0.035, vol:vol, filter:'highpass', fc:7000, bus:musicBus });
}
function snare(t, vol){
  noise(t, { dur:0.16, vol:vol, filter:'bandpass', fc:1900, q:0.8, bus:musicBus });
  tone(t, { type:'triangle', f0:330, f1:180, dur:0.12, vol:vol*0.5, bus:musicBus });
}

function musicStep(i, t){
  const track = TRACKS[curTrack];
  const g = track.gain;
  const bar = Math.floor(i / 16) % 4;
  const s = i % 16;
  const ch = CHORDS[bar];
  // Every frequency in the loop goes through here, so the tension lift is a
  // genuine pitch shift of the whole arrangement rather than a filter tweak on
  // one voice. `p` is 1 in the ordinary case and costs a multiply.
  const p = tensionNow;
  const f = n => mtof(n) * p;

  if(curTrack === 'hub'){
    // Pad: a slow-attack triad held across the whole bar, plus a bass root.
    if(s === 0){
      ch.notes.slice(0,3).forEach((n,k)=>{
        tone(t, { type:VOICE.pad, f0:f(n+12), dur:2.4, vol:g*0.07, attack:0.5,
                  filter:'lowpass', fc:700, fc1:1400, q:1, detune:(k-1)*7, bus:musicBus });
      });
      tone(t, { type:'triangle', f0:f(ch.root-12), dur:0.9, vol:g*0.30, bus:musicBus });
    }
    if(s === 8) tone(t, { type:'triangle', f0:f(ch.root-12), dur:0.7, vol:g*0.22, bus:musicBus });
    // Sparse arpeggio into the delay — this is the line you actually hum.
    if(s % 4 === 2){
      const n = ch.notes[(Math.floor(i/4) * 2) % ch.notes.length] + 12;
      tone(t, { type:VOICE.lead, f0:f(n), dur:0.34, vol:g*0.10,
                filter:'lowpass', fc:2600, bus:musicBus, send:musicDelay });
    }
    if(s % 8 === 4) hat(t, g*0.06);
  } else {
    // Round music: constant sixteenth arp, four-on-the-floor, offbeat bass.
    if(s % 4 === 0) kick(t, g*0.55);
    if(s === 4 || s === 12) snare(t, g*0.20);
    if(s % 2 === 1) hat(t, g*0.055, s % 8 === 7);

    const bassPat = [1,0,0,1,0,0,1,0,1,0,0,1,0,1,0,0];
    if(bassPat[s]){
      tone(t, { type:VOICE.bass, f0:f(ch.root-12), dur:0.13, vol:g*0.34,
                filter:'lowpass', fc:420, fc1:180, q:4, bus:musicBus });
    }
    const arpSeq = [0,2,4,5,4,2,3,1];
    const n = ch.notes[arpSeq[s % 8] % ch.notes.length] + 12;
    tone(t, { type:VOICE.lead, f0:f(n), dur:0.11, vol:g*0.075,
              filter:'lowpass', fc:3200, bus:musicBus, send:musicDelay });
    if(s === 0){
      tone(t, { type:VOICE.pad, f0:f(ch.notes[0]+12), dur:1.6, vol:g*0.05, attack:0.3,
                filter:'lowpass', fc:900, detune:6, bus:musicBus });
    }
  }
}

function scheduler(){
  if(!ctx || !curTrack) return;
  // Chase the tension target rather than snapping to it: the scheduler runs
  // every 25ms, so this reaches the full 1.25 in roughly a fifth of a second —
  // fast enough to feel like the music reacted, slow enough not to click.
  tensionNow += (tension - tensionNow) * 0.18;
  if(Math.abs(tension - tensionNow) < 0.002) tensionNow = tension;
  const stepDur = 60 / (TRACKS[curTrack].bpm * tensionNow) / 4;   // sixteenth notes
  // A backgrounded tab throttles this interval to once a second or worse. Left
  // alone the catch-up loop would then dump forty steps into the same instant.
  if(nextStepTime < ctx.currentTime) nextStepTime = ctx.currentTime + 0.05;
  while(nextStepTime < ctx.currentTime + LOOKAHEAD){
    try{ musicStep(stepIdx, nextStepTime); }catch(e){}
    nextStepTime += stepDur;
    stepIdx = (stepIdx + 1) % 64;                  // four bars, then round again
  }
}

function music(track){
  if(track !== null && !TRACKS[track]) return;
  // `pendingTrack` is what the game WANTS playing; `curTrack` is what actually
  // is. They diverge whenever the context is still locked or the music is
  // muted, and every path back in (unlock, un-mute) reads the wanted one.
  pendingTrack = track;
  if(track === curTrack && schedTimer) return;     // already running: don't restart
  stopScheduler();
  curTrack = null;
  if(!track || mode !== 'full') return;
  const c = ensureCtx();
  if(!c || c.state !== 'running') return;          // retried from unlock()
  curTrack = track;

  // ── TEMPO-SYNC THE DELAY ──
  // Everything else in the sequencer derives its timing from bpm; the delay was
  // the one exception, pinned at a flat 300ms. Against the hub's 326ms eighth
  // that lands every echo 26ms early, and against the round's 220ms eighth it
  // lines up with nothing at all — so each repeat fell between the sixteenths
  // of the arp it was echoing, and 0.34 feedback stacked that error up until
  // the groove smeared. A dotted eighth (45/bpm) is the synthwave staple: the
  // echo syncopates ACROSS the sixteenths and lands back on the beat every
  // three, which is what makes an arpeggio cascade instead of blur.
  const dotted8 = 45 / TRACKS[track].bpm;            // 0.489s @ 92 · 0.331s @ 136
  musicDelay.delayTime.setTargetAtTime(dotted8, c.currentTime, 0.02);

  stepIdx = 0;
  nextStepTime = c.currentTime + 0.08;
  schedTimer = setInterval(scheduler, TICK_MS);
  scheduler();
}
function stopScheduler(){
  if(schedTimer){ clearInterval(schedTimer); schedTimer = null; }
}
function resumeMusic(){ if(pendingTrack && !schedTimer) music(pendingTrack); }

// ── 🎵 DRIVE CONTROL ──
// Re-voices the sequencer in place. The loop is restarted only when something
// that affects TIMING changed, because the delay line is tuned per-bpm at the
// top of music() — a chord swap alone can take effect on the next bar with no
// audible seam at all.
function setDrive(cfg){
  cfg = cfg || {};
  const set = CHORD_SETS[cfg.chords] || CHORD_SETS.classic;
  const voice = cfg.voice === 'square'   ? { pad:'square',   lead:'square',   bass:'square'   }
              : cfg.voice === 'triangle' ? { pad:'triangle', lead:'triangle', bass:'sine'     }
              :                            { pad:'sawtooth', lead:'square',   bass:'sawtooth' };
  const bpm = cfg.bpm || {};
  const retimed = (bpm.hub  && bpm.hub  !== TRACKS.hub.bpm) ||
                  (bpm.game && bpm.game !== TRACKS.game.bpm);

  CHORDS = set;
  VOICE  = voice;
  TRACKS.hub.bpm  = TRACKS.hub.baseBpm  = bpm.hub  || 92;
  TRACKS.game.bpm = TRACKS.game.baseBpm = bpm.game || 136;

  if(retimed && curTrack){
    const want = curTrack;
    curTrack = null;          // force music() past its "already running" guard
    music(want);
  }
}

// Called by the games' clocks. `on` is simply "is the round inside its last few
// seconds" — the engine owns what that sounds like.
function setTension(on){
  const want = on ? TENSION_MUL : 1;
  if(want === tension) return;
  tension = want;
}

// ── MODE CONTROL ──────────────────────────────────────────────────────
function applyMode(){
  saveMode(mode);
  if(ctx){
    const t = ctx.currentTime;
    // Ramped, not switched: a hard gain jump on a running pad is an audible pop.
    sfxBus.gain.cancelScheduledValues(t);
    sfxBus.gain.setTargetAtTime(mode === 'mute' ? 0 : 1, t, 0.02);
    musicBus.gain.cancelScheduledValues(t);
    musicBus.gain.setTargetAtTime(mode === 'full' ? 1 : 0, t, 0.05);
  }
  if(mode === 'full'){
    if(ctx && ctx.state === 'suspended') ctx.resume().then(resumeMusic).catch(()=>{});
    else resumeMusic();
  }else{
    // Keep the desired track on file so un-muting resumes the right one.
    const want = curTrack || pendingTrack;
    stopScheduler();
    curTrack = null;
    pendingTrack = want;
  }
  buttons.forEach(paintButton);
}

const MODE_UI = {
  full: { icon:'🔊', label:'Audio: effects + music',  toast:'🔊 AUDIO ONLINE — effects + music' },
  sfx:  { icon:'🔈', label:'Audio: effects only',     toast:'🔈 MUSIC MUTED — effects only' },
  mute: { icon:'🔇', label:'Audio: muted',            toast:'🔇 AUDIO OFFLINE' }
};

const buttons = [];
function paintButton(el){
  const ui = MODE_UI[mode];
  el.textContent = ui.icon;
  el.title = ui.label + ' (click to change)';
  el.setAttribute('aria-label', ui.label);
  el.classList.toggle('snd-off', mode === 'mute');
  el.classList.toggle('snd-partial', mode === 'sfx');
}
function bindToggle(el){
  if(!el || buttons.includes(el)) return;
  buttons.push(el);
  paintButton(el);
  el.addEventListener('click', e => { e.stopPropagation(); cycleMode(); });
}
// Same registry as bindToggle, but the caller owns the click — used by the
// audio popover, which sets modes directly instead of blind-cycling.
function bindIndicator(el){
  if(!el || buttons.includes(el)) return;
  buttons.push(el);
  paintButton(el);
}
function repaintAll(){ buttons.forEach(paintButton); }
function cycleMode(){
  mode = MODES[(MODES.indexOf(mode) + 1) % MODES.length];
  applyMode();
  unlock();
  play('toggle');
  return mode;
}
function setMode(m){
  if(!MODES.includes(m) || m === mode) return;
  mode = m; applyMode();
}

return {
  play, music, unlock, bindToggle, bindIndicator, repaintAll, cycleMode, setMode, setVolume,
  setDrive, setTension,
  get tense(){ return tension > 1; },
  // 🎵 The round track's tempo, which a Music Drive retunes. Published because
  // PULSE SYNC charts its beats against it: the mission's notes land on the
  // music the player chose rather than on a number of its own, and a drive
  // bought in the market genuinely changes how that mission feels to play.
  get bpm(){ return TRACKS.game.bpm; },
  get mode(){ return mode; },
  get volume(){ return volume; },
  modeToast(){ return MODE_UI[mode].toast; },
  get supported(){ return SUPPORTED; }
};
})();

// ══════════════════════════════════════════════════════════════════════
//  🔥 FIREBASE ENGINE SETUP — REALTIME PROTOCOLS (SAFE CONFIG)
// ══════════════════════════════════════════════════════════════════════
const FB = {
  apiKey:            "AIzaSyC1NZy2ZzNLutYAiE_QjPZGH5CymvGCnDs",
  authDomain:        "neal-with-roblox.firebaseapp.com",
  databaseURL:       "https://neal-with-roblox-default-rtdb.asia-southeast1.firebasedatabase.app",
  projectId:         "neal-with-roblox",
  storageBucket:     "neal-with-roblox.firebasestorage.app",
  messagingSenderId: "984878364213",
  appId:             "1:984878364213:web:fb1147a1a5ff0b02d2a37c"
};

var auth = null;
var db = null;

try { 
  firebase.initializeApp(FB); 
  auth = firebase.auth(); 
  db = firebase.database(); 
} catch(e) { 
  console.warn('Firebase connection context offline:', e.message); 
}

// ════════════════════════════════════════════
//  📴 OFFLINE MODE
// ══════════════════════════════════════════════════════════════════════
// Firebase Auth persists its session locally, so a returning player still HAS
// an identity with no connection. The profile is the problem: it lives in the
// Realtime Database, and RTDB on the web keeps no on-disk cache, so
// once('value') never settles offline — it does not reject, it simply waits.
// That await is what strands a player on the auth screen forever.
//
// So the profile is mirrored into localStorage on every read and write, and
// the boot path races the database against a clock. Miss the deadline and the
// mirror takes over: the arcade opens, solo missions play, and finished runs
// are banked until the network comes back.

const LS_PROFILE = 'pi_profile_v1';
const LS_QUEUE   = 'pi_pending_v1';
const NET_WAIT   = 6000;

let offlineMode = false;

const lsGet = (k, fb) => { try{ const v = localStorage.getItem(k); return v ? JSON.parse(v) : fb; }catch(e){ return fb } };
const lsSet = (k, v)  => { try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} };

// The timeout IS the offline signal — see the note above about RTDB never
// rejecting on its own.
function withTimeout(p, ms){
  return Promise.race([
    Promise.resolve(p),
    new Promise((_, rej) => setTimeout(() => {
      // Tagged, because this error reaches the auth screen's error mapper. An
      // untagged Error has no .code, falls off the end of fErrMap, and gets
      // reported as "Matrix validation anomaly." — which tells a player with no
      // wifi absolutely nothing about what went wrong.
      const e = new Error('offline-timeout');
      e.code = 'app/offline';
      e.isOffline = true;
      rej(e);
    }, ms))
  ]);
}

function cacheProfile(u){
  if(!u || !u.uid) return;
  lsSet(LS_PROFILE, { uid: u.uid, at: Date.now(), data: u });
}
function readCachedProfile(uid){
  const rec = lsGet(LS_PROFILE, null);
  return rec && rec.uid === uid ? rec.data : null;
}
const pendingRuns = () => { const q = lsGet(LS_QUEUE, []); return Array.isArray(q) ? q : [] };

function paintOfflineBanner(){
  let el = document.getElementById('offline-bar');
  if(!el){
    el = document.createElement('div');
    el.id = 'offline-bar';
    document.body.appendChild(el);
  }
  const n = pendingRuns().length;
  el.style.display = offlineMode ? 'block' : 'none';
  if(offlineMode){
    el.innerHTML = '📴 <b>OFFLINE</b> — solo missions only. ' +
      (n ? n + ' run' + (n > 1 ? 's' : '') + ' banked, syncing when you reconnect.'
         : 'Scores are saved on this device.');
  }
}

function setOfflineMode(on){
  if(offlineMode === on){ paintOfflineBanner(); return; }
  offlineMode = on;
  document.documentElement.classList.toggle('is-offline', on);
  paintOfflineBanner();
  if(!on) flushPendingRuns();
}

// Network-only doors, gated in one place. The listener sits on `document` in
// the capture phase deliberately: these buttons' own handlers are bound later
// in this file, and at the target element listeners fire in registration order
// regardless of the capture flag — so a guard bound to the button itself would
// run second and be too late to stop anything.
document.addEventListener('click', e => {
  if(!offlineMode || !e.target || !e.target.closest) return;
  const el = e.target.closest('#btn-mp-open, #btn-market, #btn-save-acct, #btn-boss-rush');
  if(!el) return;
  e.stopImmediatePropagation();
  e.preventDefault();
  snd('deny');
  // For a local player the Save button is the one they will press the moment
  // wifi returns — tell them that, not the generic line.
  if(el.id === 'btn-save-acct' && isLocalSession()){
    if(navigator.onLine && auth && db){ claimLocalAccount(); return; }
    toast('📴 Connect to wifi, then press Save to keep your progress.');
    return;
  }
  toast('📴 That needs a connection. Solo missions still work.');
}, true);

// Browser-level signals are instant but only report whether the radio is on,
// so they prompt a re-check rather than being trusted outright. A local session
// must NOT flip online here: its uid is device-made, the server would reject
// every write under it, and going "online" is claimLocalAccount()'s job — so
// for local sessions these only repaint the Save button.
addEventListener('online',  () => {
  if(isLocalSession()){ refreshClaimUi(); toast('📡 Back online — open ⚙️ Settings and press 💾 Save to keep your progress.', 5000); return; }
  if(db && user) setOfflineMode(false);
});
addEventListener('offline', () => {
  if(isLocalSession()){ refreshClaimUi(); return; }
  if(user) setOfflineMode(true);
});

// ── THE CACHED LOGIN ──
// The mirror IS the saved login: it holds the uid and everything the hub needs
// to draw itself. Firebase cannot mint OR restore a session without a network
// in every case, and entering the hub used to be possible only through
// onAuthStateChanged — so a player with no wifi sat on the auth screen even
// though their profile was sitting in localStorage the whole time.
//
// This opens the arcade straight from that mirror. It grants no new authority:
// every write still goes through the queue and is replayed under the real
// Firebase session once the network is back, and the rules still check
// auth.uid on the server. It is a local reader of local data.
const hasMirror = () => { const r = lsGet(LS_PROFILE, null); return !!(r && r.uid && r.data) };

function offlineResume(){
  const rec = lsGet(LS_PROFILE, null);
  if(!rec || !rec.uid || !rec.data) return false;
  user = { uid: rec.uid, ...ensureUserDefaults(rec.data) };
  user.isGuest = !!rec.data.isGuest;
  setOfflineMode(true);
  applyEquippedCosmetics();
  snd('login');
  enterHub();
  return true;
}

// Offered rather than forced whenever the network is merely doubtful — the
// player can still wait and sign in properly if they know they have signal.
function showResumeOffer(){
  if(user || !hasMirror()) return false;
  const anchor = document.getElementById('btn-guest');
  if(!anchor) return false;
  const host = anchor.parentElement;

  let btn = document.getElementById('btn-offline-resume');
  if(!btn){
    btn = document.createElement('button');
    btn.id = 'btn-offline-resume';
    btn.className = 'btn btn-guest btn-full btn-lg';
    btn.onclick = offlineResume;
    const note = document.createElement('div');
    note.className = 'guest-note';
    note.id = 'offline-resume-note';
    note.textContent = 'Saved on this device. Scores bank locally and sync when you reconnect.';
    host.appendChild(btn);
    host.appendChild(note);
  }
  const rec = lsGet(LS_PROFILE, null);
  const who = (rec && rec.data && rec.data.username) || 'Player';
  // Two spans rather than one string. A username can be 20 characters and the
  // button is only as wide as the auth card, so something has to give; the CSS
  // pins the static half and clips only the name to an ellipsis. Written as one
  // label, the browser had no seam to cut at and the whole thing overflowed.
  btn.textContent = '';
  const lbl = document.createElement('span');
  lbl.className = 'ofr-label';
  lbl.textContent = '📴 Continue Offline as';
  const nameEl = document.createElement('span');
  nameEl.className = 'ofr-name';
  nameEl.textContent = who;
  btn.append(lbl, nameEl);
  btn.title = `Continue offline as ${who}`;   // clipped names stay readable on hover
  btn.style.display = '';
  const n = document.getElementById('offline-resume-note');
  if(n) n.style.display = '';
  return true;
}

// ── PLAYING WITH NO ACCOUNT AT ALL ──
// A first-time player with no wifi has nothing cached and no way to reach
// Firebase, so there is no identity to restore and none can be minted. Rather
// than turn them away, this mints a purely LOCAL one: no network, no Firebase,
// just a uid in localStorage. They play immediately, and every finished round
// banks into the same queue the offline path already uses.
//
// Nothing here is a security boundary. A local session can write only to this
// device; claimLocalAccount() is what later exchanges it for a real Firebase
// identity, and only then does any of it reach the leaderboard.
const LS_LOCAL = 'pi_local_v1';
const isLocalSession = () => !!(user && user.isLocal);

function startLocalPlay(){
  const uid = 'local-' + Math.random().toString(36).slice(2, 10);
  user = { uid, ...ensureUserDefaults({ username: 'Player', isLocal: true, isGuest: true }) };
  user.isLocal = true;
  user.isGuest = true;
  lsSet(LS_LOCAL, 1);
  cacheProfile(user);
  setOfflineMode(true);
  applyEquippedCosmetics();
  snd('login');
  enterHub();
  refreshClaimUi();
  toast('🎮 Playing locally. Back on wifi, save your progress from ⚙️ Settings.', 5000);
  return true;
}

// Turns a local session into a real anonymous guest and replays everything it
// banked. The queue is what carries the progress across: each run is re-sent
// through the normal write path, so the server validates every point rather
// than trusting a total this device made up.
async function claimLocalAccount(){
  if(!isLocalSession()) return false;
  if(!auth || !db){ toast('📴 Still no connection.'); return false; }

  const btn = document.getElementById('btn-save-acct');
  const label = btn && btn.textContent;
  if(btn){ btn.disabled = true; btn.textContent = '⏳ Saving…'; }

  try{
    toast('📡 Claiming your account…');
    const c   = await withTimeout(auth.signInAnonymously(), NET_WAIT);
    const uid = c.user.uid;
    // signInAnonymously() REUSES a persisted anonymous session when one exists
    // — and set() on an existing node would wipe that guest's real totals, so
    // only a genuinely new node is written. (Banked runs then ADD to whatever
    // the reclaimed account already had, which is the right outcome.)
    const snap = await withTimeout(db.ref('players/' + uid).once('value'), NET_WAIT);
    if(!snap.exists()){
      await withTimeout(db.ref('players/' + uid).set({
        username: guestTag(uid),
        totalPoints: 0, gamesPlayed: 0, credits: 0, isGuest: true,
        createdAt: firebase.database.ServerValue.TIMESTAMP
      }), NET_WAIT);
    }

    // Re-point the session at the real identity. The local totals stay on
    // screen meanwhile — the flush recomputes them from the server and the
    // final resync repaints, so the player never watches them fall to zero.
    user.uid      = uid;
    user.isLocal  = false;
    user.isGuest  = true;
    user.username = guestTag(uid);
    lsSet(LS_LOCAL, 0);
    cacheProfile(user);

    setOfflineMode(false);      // drains the banked queue into the new account
    refreshClaimUi();
    return true;
  }catch(e){
    console.warn('Account claim failed:', e);
    toast(e && e.isOffline ? '📴 Still no connection — your progress is safe on this device.'
                           : '⚠️ Could not claim the account.');
    return false;
  }finally{
    // Only a claim that FAILED gets its old label back. A successful one has
    // already been repainted by refreshClaimUi() as the ordinary guest upgrade,
    // and restoring "Save Progress Online" over that would label the button
    // with a claim it no longer runs.
    if(btn){ btn.disabled = false; if(label && isLocalSession()) btn.textContent = label; }
  }
}

// The hub's Save Account button does double duty. Normally it opens the
// email/password upgrade modal (a handler assigned inside a closure far below —
// unreachable by name from here, so it is captured off the element rather than
// referenced). For a local session it becomes the claim; once the claim lands,
// the captured handler goes back and the button is the ordinary guest upgrade.
function refreshClaimUi(){
  const btn = document.getElementById('btn-save-acct');
  if(!btn) return;
  if(!isLocalSession()){
    if(btn._upgradeHandler){ btn.onclick = btn._upgradeHandler; btn._upgradeHandler = null; }
    btn.textContent = '💾 Save Account';
    btn.classList.remove('claim-ready');
  }else{
    const online = navigator.onLine && !!auth && !!db;
    if(!btn._upgradeHandler) btn._upgradeHandler = btn.onclick;
    btn.style.display = '';
    btn.textContent = online ? '💾 Save Progress Online' : '💾 Save (needs wifi)';
    // Lifts the offline greying while the claim can actually run — see style.css.
    btn.classList.toggle('claim-ready', online);
    btn.onclick = () => {
      if(navigator.onLine && auth && db) claimLocalAccount();
      else toast('📴 Connect to wifi, then press this to save your progress.');
    };
  }
  // ⚙️ The button lives in the Settings panel now. The panel describes the same
  // state in words, and the gear on the hub bar carries the "not saved yet"
  // dot, so both repaint whenever the button does.
  if(typeof paintSettings === 'function') paintSettings();
}

// Offered whenever there is no connection and no saved profile — the case that
// used to be a dead end.
function showLocalPlayOffer(){
  if(user) return false;
  const anchor = document.getElementById('btn-guest');
  if(!anchor) return false;

  let btn = document.getElementById('btn-local-play');
  if(!btn){
    btn = document.createElement('button');
    btn.id = 'btn-local-play';
    btn.className = 'btn btn-guest btn-full btn-lg';
    btn.textContent = '🎮 Play Without Signing In';
    btn.onclick = startLocalPlay;
    const note = document.createElement('div');
    note.className = 'guest-note';
    note.id = 'local-play-note';
    note.textContent = 'No wifi needed. Your scores are kept on this device and can be saved to an account once you are back online.';
    anchor.parentElement.appendChild(btn);
    anchor.parentElement.appendChild(note);
  }
  btn.style.display = '';
  const n = document.getElementById('local-play-note');
  if(n) n.style.display = '';
  return true;
}

// Boot fallback. onAuthStateChanged only fires when Firebase manages to restore
// a session, and offline it may never fire at all — leaving the auth screen up
// with no explanation. If nothing has claimed the screen shortly after load and
// the device is plainly offline, the mirror opens by itself; if the network is
// only doubtful, the button is offered instead.
addEventListener('load', () => setTimeout(() => {
  if(user) return;
  if(hasMirror()){
    if(!navigator.onLine || !auth) offlineResume();
    else showResumeOffer();
    return;
  }
  // No saved profile. If the network is plainly down, sitting on a login screen
  // that cannot possibly succeed helps nobody — offer local play instead.
  if(!navigator.onLine || !auth){
    showLocalPlayOffer();
    const el = document.getElementById('auth-err');
    if(el && !el.textContent){
      el.textContent = '📴 No connection. You can play now and save your progress later.';
      el.style.display = 'block';
    }
  }
}, 2500));

// ════════════════════════════════════════════
//  👁️ VISUAL COMFORT PREFERENCES
// ════════════════════════════════════════════
// Reduced motion follows the OS preference until the player chooses; the
// colorblind-safe palette is opt-in. Both live as classes on <html> so CSS
// carries most of the work, plus VFX.shake() for the canvas games.
const VFX = (function(){
  const LS_RM = 'pi_reduced_motion', LS_CB = 'pi_cb_safe';
  const sysRM = () => { try{ return matchMedia('(prefers-reduced-motion: reduce)').matches; }catch(e){ return false; } };
  const load = (key, fallback) => {
    try{ const v = localStorage.getItem(key); return v === null ? fallback : v === '1'; }
    catch(e){ return fallback; }
  };
  const save = (key, v) => { try{ localStorage.setItem(key, v ? '1' : '0'); }catch(e){} };
  let rm = load(LS_RM, sysRM());
  let cb = load(LS_CB, false);
  function apply(){
    document.documentElement.classList.toggle('reduced-motion', rm);
    document.documentElement.classList.toggle('cb-safe', cb);
  }
  apply();
  return {
    get reducedMotion(){ return rm; },
    get cbSafe(){ return cb; },
    setReducedMotion(v){ rm = !!v; save(LS_RM, rm); apply(); },
    setCbSafe(v){ cb = !!v; save(LS_CB, cb); apply(); },
    shake(v){ return rm ? 0 : v; }
  };
})();

// ════════════════════════════════════════════
//  🌌 ARCADE HUB HUB AMBIENT BACKGROUND
// ════════════════════════════════════════════
(function(){
  const c = document.getElementById('bg-canvas');
  const x = c.getContext('2d');
  let p=[], W=0, H=0, lastD=0;
  // The backing store is sized in DEVICE pixels and the context scaled to match.
  // Sized in CSS pixels — which is what `c.width = innerWidth` does — the whole
  // field was drawn at 1/dpr of the display and stretched back up by the
  // compositor, so every star was a soft blob rather than the crisp point it is
  // meant to be. This canvas is behind EVERY screen in the arcade and it is the
  // first thing on the page, so that one line made the product read as soft
  // before a single game had started. A star is 0.2–1.5px across: it is exactly
  // the kind of mark that has nothing left after a 1.5× or 3× upscale.
  //
  // The style size has to be written too. #bg-canvas is position:fixed with
  // inset:0, and an absolutely positioned REPLACED element takes its intrinsic
  // size — the width/height attributes — not the space between the offsets. So
  // the attribute alone used to be the layout size; now that it is in device
  // pixels, CSS has to be told the box is still one viewport.
  const resize=()=>{
    // A window with no layout yet -- a restored background tab, a collapsed
    // pane -- reports 0, and writing that through leaves a 0x0 canvas that
    // nothing ever resizes back. Keep what we have and let the next resize or
    // the first real frame do it. (fitCanvas() refuses the same value for the
    // same reason.)
    if(innerWidth < 2 || innerHeight < 2) return;
    const d = Math.min(window.devicePixelRatio || 1, 3);
    W = innerWidth; H = innerHeight; lastD = d;
    c.width = Math.round(W * d); c.height = Math.round(H * d);
    c.style.width = W + 'px'; c.style.height = H + 'px';
    x.setTransform(d, 0, 0, d, 0, 0);          // draw in CSS units, land on device pixels
  };
  const init=()=>{p=Array.from({length:110},()=>({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.3+.2,a:Math.random(),da:(Math.random()*.012+.003)*(Math.random()<.5?1:-1),s:Math.random()*.35+.05}))};
  const draw=()=>{
    // Two things this catches that the resize listener cannot. A page that was
    // laid out only AFTER first paint (a restored background tab) never got a
    // size at all; and dpr is not a constant -- it changes when the window
    // moves to another monitor or the browser zooms, and neither reliably
    // fires `resize`. One comparison a frame, and the field follows the display
    // instead of staying soft until something happens to resize the window.
    const d = Math.min(window.devicePixelRatio || 1, 3);
    if(innerWidth > 1 && (!W || d !== lastD || W !== innerWidth || H !== innerHeight)){
      const reshaped = (!W || W !== innerWidth || H !== innerHeight);
      resize();
      if(reshaped) init();                 // a dpr change alone must not reshuffle the sky
    }
    x.clearRect(0,0,W,H);const still=VFX.reducedMotion;p.forEach(pt=>{if(!still){pt.a+=pt.da;if(pt.a>1||pt.a<0)pt.da*=-1;pt.y-=pt.s;if(pt.y<-2){pt.y=H+2;pt.x=Math.random()*W}}x.beginPath();x.arc(pt.x,pt.y,pt.r,0,Math.PI*2);x.fillStyle=`rgba(255,255,255,${Math.max(0,Math.min(.65,pt.a))})`;x.fill()});requestAnimationFrame(draw)};
  resize();init();draw();
  // The listener is still the fast path for an ordinary window drag; the check
  // in draw() is what covers the cases that never fire one.
  window.addEventListener('resize',()=>{resize();init()});
})();

// ════════════════════════════════════════════
//  📦 ENGINE GLOBAL COMPLIANCE ENVIRONMENT
// ════════════════════════════════════════════
let user=null, curGame=null, gTimer=null, gameLoopId=null;
let onQuitGame=null; // optional per-game quit handler
// Optional per-round teardown. A Network Arena round owns things stopGame()
// can't see — database listeners, send throttles, the versus HUD — and they
// have to come down whichever way the round ends (quit, timeout, dropped link).
let onStopGame=null;

// ══════════════════════════════════════════════
//  ⏸️ ROUND TIME — the clock a held round stops
// ══════════════════════════════════════════════
// performance.now() with every pause taken out of it. 📸 Photo mode freezes the
// frame loop by handing it dt = 0, and that is enough for any mission that
// steps its world by dt — but a mission that reads the WALL clock never sees
// the freeze. Battle Bots kept landing waves and firing turrets, Pulse Sync's
// chart kept scrolling notes past the gate as misses, the Frequency Modulator's
// target kept drifting, and the pace ghost kept running while the player could
// not. Anything that means "how long has this round been PLAYED" reads gNow():
// identical to performance.now() minus a constant until the round is held, and
// standing still while it is.
const gPause = { on: false, at: 0, total: 0 };
function gNow(){ return (gPause.on ? gPause.at : performance.now()) - gPause.total; }

// Deferred callbacks belonging to the running game. Every game paints into the
// same shared DOM, so a timeout that outlives its round lands on the round you
// started next — Reaction Time's re-arm would repaint #g-reaction green under a
// fresh round that hadn't armed its own timer. Anything a game schedules goes
// through gLater() and dies with the game in stopGame().
//
// It HOLDS with the game, too. A timeout knows nothing about frames, so a
// frozen round's timers used to carry on without it: Node Hacker broadcast its
// whole key into a paused room, a mismatched Memory Match pair used up its
// reveal, and Reaction Time turned green behind the camera. Each entry keeps
// its due time in ROUND time; gHold() lifts every pending timer, gRelease()
// re-arms each with exactly what it had left, and one that is set or comes due
// while the round is held simply waits for the release.
//
// ⚠️ A held timer comes back under a NEW native id, so cancel with gCancel(),
// never clearTimeout(). The id gLater() returns stays valid for gCancel()
// however many times the round has been paused.
const gTimeouts = new Map();          // first native id → { fn, due, tid }
function gLater(fn, ms){
  const e = { fn, due: gNow() + ms, tid: 0 };
  const id = e.tid = setTimeout(() => gFire(id), ms);
  gTimeouts.set(id, e);
  return id;
}
function gFire(id){
  const e = gTimeouts.get(id);
  if(!e) return;
  if(gPause.on){ e.tid = 0; return; }        // parked — gRelease() re-arms it
  gTimeouts.delete(id);
  e.fn();
}
function gCancel(id){
  const e = gTimeouts.get(id);
  if(e){ clearTimeout(e.tid); gTimeouts.delete(id); }
  else clearTimeout(id);
}
function gHold(){
  if(gPause.on) return;
  gPause.on = true;
  gPause.at = performance.now();
  gTimeouts.forEach(e => { clearTimeout(e.tid); e.tid = 0; });
}
function gRelease(){
  if(!gPause.on) return;
  gPause.total += performance.now() - gPause.at;
  gPause.on = false;
  const now = gNow();
  gTimeouts.forEach((e, id) => {
    clearTimeout(e.tid);
    e.tid = setTimeout(() => gFire(id), Math.max(0, e.due - now));
  });
}

// ══════════════════════════════════════════════
//  ⏳ THE ROUND CLOCK — what a Time Dilator adds to
// ══════════════════════════════════════════════
// Every countdown in the arcade is a PRIVATE variable that overwrites #g-time
// once a second. The Time Dilator wrote three seconds into that element and the
// mission's own next tick erased it — so a consumable the player pays five
// credits for did nothing, on any mission, in either renderer. It looked like
// it worked for slightly under one second, which is why it survived this long.
//
// There are two ways to give the seconds back, and the arcade needs both:
//
//   · roundClockAdd — a mission HANDS OVER a function that adds seconds to its
//     own counter. Exact, and the readout jumps the way the player expects.
//     Every § 9 mission registers one, in both builds.
//
//   · _clockSkip — the universal fallback, for the twenty-one missions that
//     predate the seam. runMissionStart() wraps setInterval for the duration of
//     the mission's own start() call (the same trick DOUBLE SPEED uses) and
//     wraps each candidate clock in a shim that can be told to SKIP a tick.
//     Skipping three ticks IS "+3 seconds of play", and the clock visibly holds
//     instead of counting, which reads as a dilation rather than as a freeze.
//     The shim checks gTimer === id, so only the round's own clock is ever
//     suppressed — a spawn timer on a similar period keeps running.
let roundClockAdd = null;
let _clockSkip = 0;
function registerRoundClock(fn){ roundClockAdd = typeof fn === 'function' ? fn : null; }

// Runs a mission's start() with the clock capture installed. Every path that
// starts a mission goes through here: prepGame (so solo rounds, Boss Rush and
// the Endless lane), the Daily Hack, and a Network Arena score race.
function runMissionStart(fn){
  roundClockAdd = null;
  _clockSkip = 0;
  const real = window.setInterval;
  window.setInterval = function(f, ms, ...rest){
    // Only intervals in the clock band are candidates. Anything faster is a
    // simulation tick, and anything slower is not a countdown anybody reads.
    if(typeof f !== 'function' || typeof ms !== 'number' || ms < 250 || ms > 2000){
      return real.call(window, f, ms, ...rest);
    }
    let id;
    const shim = function(){
      // 📸 A paused round's clock must not tick. Same shim, same test, and the
      // same reason it only ever touches gTimer: a spawn timer on a similar
      // period is not the round's countdown.
      if(gTimer === id && typeof photoActive === 'function' && photoActive()) return;
      if(_clockSkip > 0 && gTimer === id){ _clockSkip--; return; }
      return f.apply(this, arguments);
    };
    id = real.call(window, shim, ms, ...rest);
    return id;
  };
  try{ fn(); }
  finally{ window.setInterval = real; }
}

function stopGame(){
  roundClockAdd = null;
  _clockSkip = 0;
  // 📸 A paused camera belongs to the round that was paused. Left armed it
  // would swallow the next round's input and hold its HUD hidden.
  if(typeof photoAbort === 'function') photoAbort();
  // Cleared BEFORE the handler runs, so a teardown that ends up calling

  // stopGame() again (a network round finishing as it's quit) can't recurse.
  if(onStopGame){
    const fn=onStopGame; onStopGame=null;
    try{ fn(); }catch(e){ console.warn('Round teardown failed:', e); }
  }
  clearInterval(gTimer); gTimer=null;
  cancelAnimationFrame(gameLoopId); gameLoopId=null;
  gTimeouts.forEach(e => clearTimeout(e.tid)); gTimeouts.clear();
  window.onkeydown=window.onkeyup=null;
  // The round's chaos modifier, its tension lift and its power-up dock are all
  // round-scoped. They come down HERE rather than in each ending, for the same
  // reason the timers do: there are a dozen ways out of a round and only one of
  // them is the clock running out.
  if(typeof chaosClear === 'function') chaosClear();
  musicTension(false);
  if(typeof hidePowerDock === 'function') hidePowerDock();
  if(aCanvas){
    aCanvas.onmousemove=null; aCanvas.onclick=null;
    aCanvas.ontouchmove=null; aCanvas.ontouchstart=null;
    clearCanvasDrag();
  }
  hideTouchHint();
  const rbox=document.getElementById('g-reaction');
  if(rbox){ rbox.onpointerdown=null; rbox.onclick=null; }
  // Battle Bots builds its deploy cards fresh each round, so emptying the deck
  // drops that round's click handlers along with the nodes carrying them —
  // quitting mid-siege can't leave a live "Deploy Tank" behind. Hidden here as
  // well as in prepGame() so the teardown is complete on its own rather than
  // relying on whatever game happens to mount next to tidy up after it.
  const deck=document.getElementById('bb-deck');
  if(deck){ deck.innerHTML=''; deck.style.display='none'; }
  const ramPill=document.getElementById('bb-ram-pill');
  if(ramPill) ramPill.style.display='none';
  // The versus strip and link-quality pill belong to a Network Arena round and
  // must never survive into the solo game that mounts next.
  const mpHudEl=document.getElementById('mp-hud');
  if(mpHudEl) mpHudEl.style.display='none';
  const mpPing=document.getElementById('mp-ping-pill');
  if(mpPing) mpPing.style.display='none';
  const mpOv=document.getElementById('mp-overlay');
  if(mpOv){ mpOv.classList.remove('show','warn'); }
  const cl=document.getElementById('ctrl-left');
  const cr=document.getElementById('ctrl-right');
  const ca=document.getElementById('ctrl-action');
  const cd=document.getElementById('ctrl-drop');
  clearHold(cl); clearHold(cr); clearHold(ca); clearHold(cd);
  [cl,cr,ca,cd].forEach(el=>{ if(el) el.onclick=null; });
}
