// One place that knows how to start each mission. prepGame() runs them behind a
// countdown; a Network Arena score race runs the very same function behind a
// SHARED countdown, which is the whole trick — a duel is the solo game with two
// scoreboards, not a second implementation of it.
const SOLO_START = {
  click: startClick,   nebula: startNebula, tetris: startTetris,   dodge: startDodge,
  memory: startMemory, math: startMath,     reaction: startReaction, pong: startPong,
  snake: startSnake,   flappy: startFlappy, breaker: startBreaker, arena: startArena,
  runner: startRunner, hacker: startHacker, meteor: startMeteor,   battlebots: startBattleBots,
  path: startOverclockPath, freq: startFrequencyModulator,
  rhythm: startPulseSync, merge: startCoreMerge, uplink: startOrbitalUplink,
  cutter: startIceCutter, sorter: startPacketSort, trace: startSignalTrace,
  defrag: startDefrag,    coolant: startCoolant
};

// ══════════════════════════════════════════════
//  ⚙️ SYSTEM STABILITY — GLOBAL DIFFICULTY ENGINE
// ══════════════════════════════════════════════
// Three operational tiers. `pointMult` scales final awarded score.
// `speedMult` scales hazard/spawn/object velocities (>1 = more intense).
// `timeMult` scales countdown clocks (<1 = less time on the clock).
const DIFFICULTY_TIERS = {
  stable:      { key:'stable',      label:'STABLE CORE',      icon:'🟢', pointMult:1.0, speedMult:1.0, timeMult:1.0 },
  overclocked: { key:'overclocked', label:'OVERCLOCKED',      icon:'🟡', pointMult:1.5, speedMult:1.5, timeMult:0.75 },
  meltdown:    { key:'meltdown',    label:'CRITICAL MELTDOWN',icon:'🔴', pointMult:2.0, speedMult:2.0, timeMult:0.5 }
};

let currentDifficultyTier = 'stable';
let gameDifficultyMultiplier = 1.0; // tracks the active tier's point multiplier

// Speed/hazard modifier for the active tier (>1 = harder/faster).
// ⏩ DOUBLE SPEED rides this multiplier rather than reaching into eighteen game
// loops. It is deliberately NOT the full ×2 the modifier's clocks run at: the
// interval halving in chaosRun() already doubles every timer and every
// tick-driven behaviour, and stacking a second ×2 on hazard VELOCITIES on top
// of that made the canvas games unreadable rather than fast. ×1.5 here is what
// makes a Nebula swarm visibly quicken while its clock genuinely doubles.
let chaosSpeedMul = 1;
function getDifficultyModifier(){
  // ♾️ ENDLESS PROTOCOL rides the SAME multiplier every hazard in the arcade
  // already scales by, which is what lets one lane ramp twenty-six missions in
  // two renderers without any of them opting in. endlessSpeedMul() is 1 outside
  // an endless run.
  return DIFFICULTY_TIERS[currentDifficultyTier].speedMult * chaosSpeedMul * endlessSpeedMul();
}
// Countdown/timer modifier for the active tier (<1 = less time)
function getTimeModifier(){
  // ♾️ And the clock, for the same reason: "no clock" in an endless lane is a
  // clock long enough that it is not what ends the run. A mission that reads
  // this gets a generous stage; one that runs on infinity is unaffected.
  return DIFFICULTY_TIERS[currentDifficultyTier].timeMult * endlessTimeMul();
}

// There is more than one of these panels on screen now — the hub's and the
// Network Arena's — so painting one by id would leave the other lying about the
// active tier. Everything below works off the CLASS, which is what makes the
// arena's copy the same control rather than a second implementation of it.
function paintDiffPanels(tierKey){
  const tier = DIFFICULTY_TIERS[tierKey];
  if(!tier) return;
  document.querySelectorAll('.diff-btn').forEach(b=>b.classList.toggle('active', b.dataset.tier===tierKey));
  document.querySelectorAll('.diff-mult').forEach(el=>el.textContent = `×${tier.pointMult.toFixed(1)} PTS`);
  // Recolor the ambient glow behind the panel to match the newly active tier,
  // and give it a brief brighter flash so the change reads as an event, not just a state.
  document.querySelectorAll('.diff-selector').forEach(sel=>{
    sel.classList.remove('tier-stable','tier-overclocked','tier-meltdown');
    sel.classList.add(`tier-${tierKey}`);
    sel.classList.remove('flash');
    void sel.offsetWidth; // restart the animation/transition even if the same tier is clicked again
    sel.classList.add('flash');
    clearTimeout(sel._flashTimer);
    sel._flashTimer = setTimeout(()=>sel.classList.remove('flash'), 350);
  });
}

function setDifficultyTier(tierKey){
  const tier = DIFFICULTY_TIERS[tierKey];
  if(!tier) return;
  currentDifficultyTier = tierKey;
  gameDifficultyMultiplier = tier.pointMult;
  paintDiffPanels(tierKey);
  updateGameCardMaxPoints();
  updateHubDiffDisplay();
  // The arena's panel can be showing the HOST'S tier instead of ours, and its
  // duel cards quote point caps that scale with the dial — both are its own
  // business, so it gets the last word on its own panel.
  if(typeof mpPaintDiff === 'function') mpPaintDiff();
  // 🌀 The chaos note quotes what a roll will DO, and Meltdown is the tier that
  // stacks two of them — so the note has to move when the dial does.
  if(typeof paintChaosToggle === 'function') paintChaosToggle();
}

function lockDifficultySelector(){
  document.querySelectorAll('.diff-selector').forEach(sel=>{
    sel.classList.add('locked');
    sel.querySelectorAll('.diff-btn').forEach(b=>b.disabled = true);
  });
}
function unlockDifficultySelector(){
  document.querySelectorAll('.diff-selector').forEach(sel=>{
    sel.classList.remove('locked');
    sel.querySelectorAll('.diff-btn').forEach(b=>b.disabled = false);
  });
}

// Delegated rather than bound per button. There are two panels' worth of these
// now, and one listener at the document covers every tier button that exists —
// including any panel added later — instead of a bind pass that has to be
// remembered each time.
document.addEventListener('click', e=>{
  const btn = e.target.closest?.('.diff-btn');
  if(!btn || btn.disabled) return;
  const tierKey = btn.dataset.tier;
  const tier = DIFFICULTY_TIERS[tierKey];
  if(!tier) return;
  setDifficultyTier(tierKey);
  // Hosting an open room? It takes the new tier immediately, so the guest's
  // panel — and the round they are both about to play — follows the dial rather
  // than whatever happened to be set when the room was opened.
  if(typeof mpSyncTier === 'function') mpSyncTier();
  // The tier's own pitch: Stable settles, Overclock lifts, Meltdown alarms.
  snd(tierKey==='meltdown' ? 'alarm' : 'score', { semi: tierKey==='stable' ? -5 : 2 });
  toast(`${tier.icon} SYSTEM STABILITY: ${tier.label} (×${tier.pointMult.toFixed(1)} PTS)`, 2500, `toast-${tierKey}`);
});

function initGameCardBasePoints() {
  document.querySelectorAll('.gc-pts').forEach(el => {
    const txt = el.textContent.match(/UP TO (\d+) PTS/);
    if (txt) {
      const base = parseInt(txt[1],10);
      el.dataset.basePts = base;
    }
  });
}
function updateGameCardMaxPoints() {
  const diff = gameDifficultyMultiplier;
  document.querySelectorAll('.gc-pts').forEach(el => {
    // Cyber Arena is uncapped, so its label never matched the "UP TO n PTS"
    // pattern and initGameCardBasePoints() recorded no base for it. Rewriting
    // it anyway printed "UP TO NaN PTS"; cards without a numeric cap keep
    // whatever label they shipped with.
    const base = parseInt(el.dataset.basePts, 10);
    if (!Number.isFinite(base)) return;
    el.textContent = `UP TO ${Math.floor(base * diff)} PTS`;
  });
}
function updateHubDiffDisplay() {
  const diff = gameDifficultyMultiplier;
  const hubPtsEl = document.getElementById('h-pts');
  let diffEl = document.getElementById('hub-diff');
  if (!diffEl) {
    diffEl = document.createElement('span');
    diffEl.id = 'hub-diff';
    diffEl.style.fontSize = '0.8rem';
    diffEl.style.marginLeft = '6px';
    diffEl.style.color = 'var(--dim)';
    // Append after existing content
    hubPtsEl.appendChild(diffEl);
  }
  diffEl.textContent = `(x${diff})`;
}

// Initialize
initGameCardBasePoints();
updateGameCardMaxPoints();
updateHubDiffDisplay();
const multEl = document.getElementById('diff-mult');
if(multEl) multEl.textContent = `×${gameDifficultyMultiplier.toFixed(1)} PTS`;
document.getElementById('diff-selector')?.classList.add(`tier-${currentDifficultyTier}`);

const aCanvas = document.getElementById('arcade-canvas');
const aCtx = aCanvas?.getContext('2d');

// The play field is a fixed coordinate space and every game draws in those
// units. How big the canvas actually is on screen is a separate concern
// handled by fitCanvas(), which installs a base transform to convert — so the
// board can fill a desktop without a single game knowing about it.
//
// The field was 400×500. Widening it to 560 is a real change to the play
// space, not a stretch: cells and sprites keep their proportions and the games
// get 160 more units of room, which is why each one re-lays-out around it
// (Tetris runs a 14-column well instead of 10, Breaker a wider brick wall,
// Nebula wider invader formations, and so on).
const BOARD_W = 560, BOARD_H = 500;

// A screen is hidden with opacity + pointer-events, never display:none, so the
// buttons on the screen you just LEFT stay in the keyboard focus order. Clicking
// "Play Again" therefore left #btn-again focused for the whole of the next round,
// and the first Space or Enter of that round re-fired it and restarted the game —
// which only ever bit the games you can play without touching the mouse, because
// everywhere else the first click moved focus off the button.
// `inert` takes the outgoing screen out of the focus order and drops focus along
// with it; the explicit blur is the fallback where inert isn't supported.
const showScreen=id=>{
  const next=document.getElementById(id);
  document.querySelectorAll('.screen').forEach(s=>{
    s.classList.remove('active');
    s.inert = s!==next;
  });
  const a=document.activeElement;
  if(a?.closest && a.closest('.screen') && a.closest('.screen')!==next) a.blur?.();
  setTimeout(()=>next?.classList.add('active'),40);
};

let _tt;
const toast=(msg,ms=2500,tintClass=null)=>{const el=document.getElementById('toast');el.textContent=msg;el.classList.remove('toast-stable','toast-overclocked','toast-meltdown');if(tintClass)el.classList.add(tintClass);el.classList.add('show');clearTimeout(_tt);_tt=setTimeout(()=>el.classList.remove('show'),ms)};

// ══════════════════════════════════════════════════════════════════════
//  🔊 AUDIO — hookup to the synth engine at the top of this file
// ══════════════════════════════════════════════════════════════════════
// Everything routes through these two shims rather than touching SFX directly,
// so audio that failed to initialise (no Web Audio, or a browser that blocked
// it) degrades to a silent arcade instead of a ReferenceError in a game loop. They're called from hot paths (per shot,
// per brick), so they stay as cheap as a property lookup — the rate limiting
// and the "is audio even unlocked yet" question live inside the engine.
// 📳 HAPTICS ride HERE, on the one call every mission in the arcade already
// makes for every event it has. Twenty-six missions times two renderers is
// fifty-two implementations; none of them has to learn that vibration exists,
// and a mission written tomorrow buzzes correctly without its author knowing.
// hapticFor() maps a small set of sound ids to patterns and returns null for
// everything else, so the cost on a hot path is one object lookup.
const snd   = (name, opts) => { if(window.SFX) SFX.play(name, opts); haptic(name); };
const music = track        => { if(window.SFX) SFX.music(track); };
// "The clock is nearly out." Driven from one MutationObserver on #g-time rather
// than from eighteen game loops — see watchGameClock().
const musicTension = on    => { if(window.SFX) SFX.setTension(on); };

// The 🔊 button appears in both the hub bar and the game header; they're two
// views of one setting. Clicking either opens one shared popover — mode chips
// plus a master volume slider — anchored to whichever button was clicked.
const audioPop = (function(){
  let pop = null;

  function build(){
    pop = document.createElement('div');
    pop.id = 'audio-pop';
    pop.innerHTML = `
      <div class="ap-sec">AUDIO</div>
      <div class="ap-modes">
        <button class="ap-mode" data-mode="full">🔊 All</button>
        <button class="ap-mode" data-mode="sfx">🔈 SFX</button>
        <button class="ap-mode" data-mode="mute">🔇 Off</button>
      </div>
      <div class="ap-vol-row">
        <input type="range" id="ap-vol" min="0" max="100" step="1" aria-label="Master volume">
        <span class="ap-vol-num" id="ap-vol-num">100</span>
      </div>
      <div class="ap-divider"></div>
      <div class="ap-sec">VISUAL COMFORT</div>
      <div class="ap-toggle" id="ap-rm" role="switch" tabindex="0">
        <span class="ap-toggle-lbl">🌊 Reduce motion</span><span class="ap-switch"></span>
      </div>
      <div class="ap-toggle" id="ap-cb" role="switch" tabindex="0">
        <span class="ap-toggle-lbl">🎨 Colorblind-safe</span><span class="ap-switch"></span>
      </div>`;
    document.body.appendChild(pop);

    const wireToggle = (id, get, set, onLabel) => {
      const el = pop.querySelector(id);
      const flip = e => {
        e.stopPropagation();
        set(!get());
        paint();
        snd('toggle');
        toast(`${onLabel}: ${get() ? 'ON' : 'OFF'}`, 1600);
      };
      el.addEventListener('click', flip);
      el.addEventListener('keydown', e => { if(e.key === 'Enter' || e.key === ' ') flip(e); });
    };
    wireToggle('#ap-rm', ()=>VFX.reducedMotion, v=>VFX.setReducedMotion(v), '🌊 Reduced motion');
    wireToggle('#ap-cb', ()=>VFX.cbSafe,        v=>VFX.setCbSafe(v),        '🎨 Colorblind-safe');

    pop.querySelectorAll('.ap-mode').forEach(b=>{
      b.addEventListener('click', e=>{
        e.stopPropagation();
        SFX.setMode(b.dataset.mode);
        SFX.unlock();
        snd('toggle');
        toast(SFX.modeToast(), 1800);
        paint();
      });
    });

    const vol = pop.querySelector('#ap-vol');
    vol.addEventListener('input', ()=>{
      SFX.setVolume(+vol.value);
      pop.querySelector('#ap-vol-num').textContent = vol.value;
    });
    // Preview blip on release, so dragging isn't a machine-gun of clicks.
    vol.addEventListener('change', ()=>{ SFX.unlock(); snd('toggle'); });

    document.addEventListener('click', e=>{
      // The anchor buttons run their own open/close toggle — closing here too
      // would make the button reopen the popover it just closed.
      if(e.target.closest?.('.btn-sound')) return;
      if(pop.classList.contains('open') && !pop.contains(e.target)) hide();
    }, true);
    document.addEventListener('keydown', e=>{ if(e.key==='Escape') hide(); });
  }

  function paint(){
    if(!pop) return;
    pop.querySelectorAll('.ap-mode').forEach(b=>{
      b.classList.toggle('active', b.dataset.mode === SFX.mode);
    });
    pop.querySelector('#ap-vol').value = SFX.volume;
    pop.querySelector('#ap-vol-num').textContent = SFX.volume;
    const rm = pop.querySelector('#ap-rm'), cb = pop.querySelector('#ap-cb');
    rm.classList.toggle('on', VFX.reducedMotion);
    rm.setAttribute('aria-checked', VFX.reducedMotion);
    cb.classList.toggle('on', VFX.cbSafe);
    cb.setAttribute('aria-checked', VFX.cbSafe);
  }

  function show(anchor){
    if(!pop) build();
    paint();
    pop.classList.add('open');
    const r = anchor.getBoundingClientRect();
    const w = pop.offsetWidth || 230;
    // Below the button, right-aligned to it, clamped to the viewport.
    pop.style.top  = Math.min(r.bottom + 8, innerHeight - pop.offsetHeight - 8) + 'px';
    pop.style.left = Math.max(8, Math.min(r.right - w, innerWidth - w - 8)) + 'px';
  }

  function hide(){ pop && pop.classList.remove('open'); }

  return { show, hide, get open(){ return !!(pop && pop.classList.contains('open')); } };
})();

if(window.SFX){
  ['btn-sound-hub','btn-sound-game'].forEach(id=>{
    const el = document.getElementById(id);
    if(!el) return;
    SFX.bindIndicator(el);
    el.addEventListener('click', e=>{
      e.stopPropagation();
      SFX.unlock();
      audioPop.open ? audioPop.hide() : audioPop.show(el);
    });
  });
}

// Generic interface feedback, delegated once at the document instead of bolted
// onto ~40 individual handlers. Anything that navigates BACKWARDS gets the
// descending blip, so the hub always sounds like the place you return to.
// Only `.btn`-classed controls are caught here. The game pad, Click Frenzy's
// button, the difficulty tiers, the mission cards and Memory Match's tiles
// deliberately sit outside it — each of those has a sound of its own that says
// something the generic blip can't.
const BACK_BTNS = new Set(['btn-quit','btn-hub','btn-market-back','btn-logout']);
document.addEventListener('click', e=>{
  const el = e.target.closest?.('.btn, .market-tab, .auth-tab, .fb-close');
  if(!el || el.disabled) return;
  // The audio toggle demos the mode it just switched to, and the shop answers
  // with a purchase/equip cue — neither wants a blip on top.
  if(el.classList.contains('btn-sound') || el.classList.contains('shop-btn')) return;
  if(el.classList.contains('market-tab') || el.classList.contains('auth-tab')) { snd('tab'); return; }
  snd(BACK_BTNS.has(el.id) || el.classList.contains('fb-close') ? 'uiBack' : 'ui');
}, true);

// Browsers keep audio suspended until the page has been interacted with, so
// the sign-in screen can't have a soundtrack on arrival — it gets one on the
// first touch instead. music() is a no-op when the track is already playing,
// so signing in and walking into the hub never restarts the loop.
window.addEventListener('pointerdown', ()=>music('hub'), { once:true });

// ── FULLSCREEN TOGGLE ──
// iOS Safari exposes NO Fullscreen API on ordinary elements, and older
// Android/Safari builds only expose the webkit-prefixed one. The previous
// version called the unprefixed method unconditionally, which throws a
// TypeError on iOS before any promise exists — so .catch() never ran and
// the button silently did nothing. Probe for what's actually there.
const FS = (function(){
  const d = document.documentElement;
  const req  = d.requestFullscreen || d.webkitRequestFullscreen || d.webkitRequestFullScreen || d.msRequestFullscreen;
  const exit = document.exitFullscreen || document.webkitExitFullscreen || document.webkitCancelFullScreen || document.msExitFullscreen;
  return (req && exit) ? { req, exit } : null;
})();
const fsElement = () => document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement || null;
const fsSupported = () => !!FS;

function toggleFullscreen(){
  if(!FS) return;
  try{
    const p = fsElement() ? FS.exit.call(document) : FS.req.call(document.documentElement);
    if(p && p.catch) p.catch(e => console.warn('Fullscreen request refused:', e));
  }catch(e){ console.warn('Fullscreen unavailable:', e); }
}
function updateFsButtons(){
  const isFs=!!fsElement();
  const icon=isFs?'⛉':'⛶';
  const tip=isFs?'Exit Fullscreen':'Enter Fullscreen';
  ['btn-fs-hub','btn-fs-game'].forEach(id=>{
    const el=document.getElementById(id);
    if(!el)return;
    // No API at all (iPhone Safari): hide rather than leave a dead button
    if(!FS){ el.style.display='none'; return; }
    el.textContent=icon;el.title=tip;
  });
}
['fullscreenchange','webkitfullscreenchange','msfullscreenchange']
  .forEach(ev => document.addEventListener(ev, updateFsButtons));
document.getElementById('btn-fs-hub').onclick=toggleFullscreen;
document.getElementById('btn-fs-game').onclick=toggleFullscreen;
updateFsButtons();   // hides the buttons up front where unsupported

// ── TOUCH-SAFE HOLD BUTTONS ──
// Mobile browsers only synthesise mousedown AFTER the finger lifts, so
// hold-to-move never worked with plain onmousedown/onmouseup. Pointer
// events cover mouse, touch and stylus in one path. Pointer capture keeps
// the release bound to the button even when the finger slides off it, and
// pointercancel stops a direction sticking "on" when the browser or an
// interruption steals the touch mid-hold.
function bindHold(el, onDown, onUp){
  if(!el) return;
  clearHold(el);
  let held = false;
  const press = e => { if(held) return; if(e && e.cancelable) e.preventDefault(); held = true; onDown(); };
  const release = () => { if(!held) return; held = false; onUp(); };

  const bound = [];
  const on = (target, type, fn, opts) => { target.addEventListener(type, fn, opts); bound.push([target, type, fn, opts]); };

  // Touch events, not Pointer Events — same reason as bindCanvasDrag. Mobile
  // browsers cancel the pointer stream out from under a held button the moment
  // they suspect a scroll, so hold-to-move died a few frames in. That left
  // Pong and Nebula, whose only controls were these buttons, unplayable on a
  // phone while onclick-driven games looked fine.
  if('ontouchstart' in window){
    on(el, 'touchstart',  press,   { passive:false });
    on(el, 'touchend',    release, { passive:false });
    on(el, 'touchcancel', release, { passive:false });
  }
  on(el, 'mousedown', press);
  on(el, 'mouseleave', release);
  on(window, 'mouseup', release);   // releasing off the button still counts

  el._holdCleanup = () => bound.forEach(([t, type, fn, opts]) => t.removeEventListener(type, fn, opts));
  // 🔄 The press/release pair, kept on the element. The listeners themselves are
  // closed over inside `bound` and cannot be read back out, so INVERSE CONTROLS
  // needs this to re-bind ◀ and ▶ to each other's behaviour — see chaosRun().
  el._holdPair = { down: onDown, up: onUp };
}
function clearHold(el){
  if(!el) return;
  if(el._holdCleanup){ el._holdCleanup(); el._holdCleanup = null; }
  el._holdPair = null;
  el.onpointerdown = el.onpointerup = el.onpointercancel = el.onlostpointercapture = null;
  el.onmousedown = el.onmouseup = el.onmouseleave = null;
  el.ontouchstart = el.ontouchend = el.ontouchcancel = null;
}

// ══════════════════════════════════════════════════════════════════════
//  📱 TOUCH ENGINE — canvas gestures, board fitting, control pad layout
// ══════════════════════════════════════════════════════════════════════

// Phones and tablets get the finger-first control scheme (drag to move, hold
// to fire, tap to strike); anything with a mouse keeps keyboard + pointer.
const isTouchDevice = (window.matchMedia && matchMedia('(pointer: coarse)').matches) || ('ontouchstart' in window);

// The board is CSS-scaled to fit the screen, so a raw `clientX - rect.left`
// reads short by the scale factor — a finger on the far right of a 340px-wide
// board reported x≈340 into a 560-wide play field, and every game silently lost
// the last chunk of its width. Everything that turns a pointer into game
// coordinates goes through here.
//
// It measures the CONTENT box, not getBoundingClientRect(). The rect spans the
// border box, but the bitmap only fills the content box — and under the global
// `box-sizing:border-box` the canvas's 2px border eats INTO the width fitCanvas
// assigned rather than adding to it. Measuring the rect therefore reports a
// board 4px wider than the one being drawn and offset 2px left of it, which
// pulled every tap ~3 board units toward the centre at either edge: worst
// exactly where you're threading a gap. clientLeft/clientWidth are the content
// box exactly.
function boardPos(clientX, clientY){
  const rect = aCanvas.getBoundingClientRect();
  const w = aCanvas.clientWidth  || rect.width  || 1;
  const h = aCanvas.clientHeight || rect.height || 1;
  let p;
  // 🌀 AXIS DRIFT tilts the board with a CSS rotation, and getBoundingClientRect
  // knows nothing about rotations: it reports the axis-aligned box the rotated
  // canvas now OCCUPIES, which is wider and taller than the board and whose
  // left/top corner is not a corner of the board at all. Measuring off it lands
  // the finger progressively further from the thing it is pointing at the closer
  // you get to a corner — so under drift the mapping is done from the CENTRE,
  // which a rotation about the board's own middle leaves exactly where it was.
  //
  // clientWidth/clientHeight are layout values and are untouched by the
  // transform, so they stay the right divisor either way.
  if(chaosDrift){
    const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
    const c = Math.cos(-chaosDrift), s = Math.sin(-chaosDrift);
    const ox = clientX - cx, oy = clientY - cy;
    const ux = ox * c - oy * s, uy = ox * s + oy * c;   // un-rotated screen offset
    p = { x: BOARD_W / 2 + ux * (BOARD_W / w), y: BOARD_H / 2 + uy * (BOARD_H / h) };
  }else{
    p = {
      x: (clientX - rect.left - aCanvas.clientLeft) * (BOARD_W / w),
      y: (clientY - rect.top  - aCanvas.clientTop ) * (BOARD_H / h)
    };
  }
  // 🔄 INVERSE CONTROLS mirrors the board here rather than in each game: this is
  // the one funnel every drag, swipe and tap passes through on its way to
  // becoming a coordinate, so one flip covers all of them and none of them has
  // to know a modifier exists. Vertical is mirrored too — Flappy is a vertical
  // game, and "reversed direction inputs" that left it untouched would be a
  // modifier half the arcade ignored.
  //
  // AFTER the drift correction, never before: the un-rotation is a fact about
  // where the finger physically is, and the flip is a fact about what that
  // position should MEAN. Doing them the other way round mirrors the tilt too
  // and the two modifiers stop composing.
  if(chaosInverse){ p.x = BOARD_W - p.x; p.y = BOARD_H - p.y; }
  return p;
}

// Drag binding for the play surface.
//
// This deliberately does NOT use Pointer Events. Pointer capture on a canvas
// is fragile on real phones: mobile Safari and Android Chrome fire
// pointercancel the moment they suspect the gesture might be a scroll, an
// edge swipe or a browser gesture, which kills the drag a few frames in — the
// game looks frozen even though its loop is running fine. Desktop Chromium
// never reproduces it, which is exactly why it shipped.
//
// Touch Events with a non-passive preventDefault hold the gesture properly,
// and mouse events are bound alongside them so hybrid touch laptops work with
// either input. preventDefault on touchstart also suppresses the synthesised
// mouse events, so a tap can't fire both paths.
// Every position handed to a game carries `.touch`, saying which input actually
// produced it — NOT what the device is capable of. `isTouchDevice` is true on
// any machine that merely HAS a touchscreen, so a Windows laptop with both was
// handed the finger scheme for its mouse too: absolute cursor-following was
// switched off and steering degraded to a relative hold-and-drag. Deciding per
// event lets one machine run both schemes, whichever hand you reach with.
const _drag = { touch: [], mouse: [] };
function bindCanvasDrag(handlers){
  clearCanvasDrag();
  if(!aCanvas) return;

  const pos = (t, touch) => {
    const p = boardPos(t.clientX, t.clientY);
    p.touch = !!touch;
    return p;
  };
  // 📸 PHOTO MODE suspends every input path into the round. It is suspended
  // HERE rather than by tearing the binding down, because a mission's handlers
  // are closures inside its own start() and there would be no way to put them
  // back. One guard, fifty-two builds, and the binding survives the pause
  // intact — which is what makes "resume exactly where you were" possible.
  //
  // This is also the half of the never-yaw rule that makes the other half safe:
  // the camera may orbit only while nothing can steer.
  const frozen = () => (typeof photoActive === 'function') && photoActive();
  const on = (target, type, fn, bucket) => {
    target.addEventListener(type, fn, { passive: false });
    _drag[bucket].push([target, type, fn]);
  };

  // ── TOUCH ──
  if('ontouchstart' in window){
    let id = null;
    const mine = list => { for(let i=0;i<list.length;i++) if(list[i].identifier === id) return list[i]; return null; };
    on(aCanvas, 'touchstart', e => {
      if(frozen()) return;
      if(id !== null) return;                    // one finger drives; ignore extras
      const t = e.changedTouches[0];
      if(!t) return;
      e.preventDefault();
      id = t.identifier;
      handlers.onDown && handlers.onDown(pos(t, true), e);
    }, 'touch');
    on(aCanvas, 'touchmove', e => {
      if(frozen()) return;
      const t = mine(e.changedTouches);
      if(!t) return;
      e.preventDefault();
      handlers.onMove && handlers.onMove(pos(t, true), e);
    }, 'touch');
    const endTouch = e => {
      const t = mine(e.changedTouches);
      if(!t) return;
      e.preventDefault();
      id = null;
      handlers.onUp && handlers.onUp(pos(t, true), e);
    };
    on(aCanvas, 'touchend', endTouch, 'touch');
    on(aCanvas, 'touchcancel', endTouch, 'touch');
  }

  // ── MOUSE ──
  // move/up live on window so a drag survives the cursor leaving the canvas,
  // which is what pointer capture used to buy us.
  let down = false;
  on(aCanvas, 'mousedown', e => {
    if(frozen()) return;
    e.preventDefault();
    down = true;
    handlers.onDown && handlers.onDown(pos(e, false), e);
  }, 'mouse');
  on(aCanvas, 'mousemove', e => {
    if(frozen()) return;
    if(!down) handlers.onHover && handlers.onHover(pos(e, false), e);
  }, 'mouse');
  on(window, 'mousemove', e => {
    if(frozen()) return;
    if(down) handlers.onMove && handlers.onMove(pos(e, false), e);
  }, 'mouse');
  on(window, 'mouseup', e => {
    if(!down) return;
    down = false;
    handlers.onUp && handlers.onUp(pos(e, false), e);
  }, 'mouse');
}
function clearCanvasDrag(){
  ['touch','mouse'].forEach(k => {
    _drag[k].forEach(([target, type, fn]) => target.removeEventListener(type, fn));
    _drag[k] = [];
  });
  if(!aCanvas) return;
  // Legacy inline handlers from the pre-gesture code, in case anything set them.
  aCanvas.onpointerdown = aCanvas.onpointermove = null;
  aCanvas.onpointerup = aCanvas.onpointercancel = aCanvas.onlostpointercapture = null;
}

// ── BOARD FITTING ──
// 400×500 is taller than most phone viewports once the header, progress bar
// and control pad have taken their cut, so the bottom of the play field ended
// up below the fold. Measure what's actually left and scale the canvas to it,
// preserving aspect ratio.
//
// The scale runs both ways: it used to be capped at 1×, which kept the board
// at a postage-stamp 400×500 on a desktop with most of the window sitting
// empty around it. It now grows into whatever space the layout leaves over,
// and the canvas's backing store grows with it, so a bigger board is drawn at
// full resolution rather than being a stretched-up 400×500 bitmap.
function fitCanvas(){
  // Before the guard below: Memory Match, Math Blitz and Reaction Time hide the
  // canvas holder entirely and would otherwise never fit their header.
  fitHud();
  const holder = document.getElementById('g-canvas-holder');
  if(!holder || holder.style.display === 'none' || !aCanvas) return;
  const area = document.querySelector('.g-area');
  if(!area) return;

  const controls = document.getElementById('arcade-controls');
  const ctrlVisible = controls && getComputedStyle(controls).display !== 'none';
  // Landscape parks the pad beside the board instead of beneath it, so it eats
  // width there and height everywhere else.
  const beside = ctrlVisible && getComputedStyle(holder).display === 'flex';
  const ctrlBox = ctrlVisible ? controls.getBoundingClientRect() : null;
  const ctrlH = (ctrlVisible && !beside) ? ctrlBox.height + 10 : 0;   // + #arcade-controls margin-top
  const ctrlW = beside ? ctrlBox.width + 12 : 0;

  // Consoles that sit UNDER the board cost it height exactly the way the control
  // pad does, so they have to be measured too — otherwise the board sizes
  // itself into them and they run off the bottom of the screen. Three of them
  // can be up: Battle Bots' deploy deck, the Frequency Modulator's two sliders,
  // and — in 3D mode, where the sum itself is rendered in the world — Math
  // Blitz's answer field. All are siblings of the holder inside .g-area, and
  // all carry a 10px top margin.
  let deckH = 0;
  for(const id of ['bb-deck', 'g-freq-ctl', 'g-math', 'g-sort-rule']){
    const el = document.getElementById(id);
    if(el && getComputedStyle(el).display !== 'none'){
      deckH += el.getBoundingClientRect().height + 10;
    }
  }

  const availW = area.clientWidth - ctrlW;
  // The header is measured, never assumed, so its exact height (title line,
  // stat pills, hint caption) costs the board only what it actually uses.
  // holder.top is independent of the canvas's own height, so measuring it
  // before resizing doesn't feed back on itself. The 24px covers the screen's
  // bottom padding and the home-indicator safe area.
  const availH = window.innerHeight - holder.getBoundingClientRect().top - ctrlH - deckH - 24;

  // Floor is deliberately low: on a landscape phone there genuinely isn't much
  // height, and a small board beats one whose bottom half is off-screen. In
  // practice .g-area's 700px cap binds first (1.75×), keeping the board no
  // wider than the header and progress bar above it; the 1.9× ceiling is a
  // backstop for if that ever widens.
  const scale = Math.min(availW / BOARD_W, Math.max(130, availH) / BOARD_H, 1.9);
  const cssW = Math.round(BOARD_W * scale), cssH = Math.round(BOARD_H * scale);
  // A round can start while the page has no layout at all — a tab restored in
  // the background, a pane the window manager has collapsed, a start that lands
  // between the screen switch and the first layout pass. availW is 0 there, and
  // writing that through collapses the canvas to nothing. That state is
  // SELF-PERPETUATING: a zero canvas gives .g-area zero width, which gives the
  // next fit zero again, so the board never comes back and the round plays out
  // on an invisible field. Refusing to write it and asking for another frame
  // costs nothing and cannot get stuck.
  if(cssW <= 0 || cssH <= 0){ scheduleFit(); return; }
  aCanvas.style.width  = cssW + 'px';
  aCanvas.style.height = cssH + 'px';

  // Let the header and progress bar track the board's width, so the three read
  // as one unit rather than a narrow field under a full-width bar. The CSS
  // floors it, so a small board can't squeeze the header into wrapping (which
  // would change its height and feed back into the measurement above).
  area.closest('.screen')?.style.setProperty('--board-w', cssW + 'px');

  // Match the backing store to the on-screen size (retina included) and let a
  // base transform map the 560×500 game units onto it. Assigning width/height
  // wipes the canvas and resets context state, so only touch it when the size
  // genuinely changed — every game redraws on its next animation frame.
  //
  // The content box is read back rather than reusing cssW/cssH: the 2px border
  // sits inside them under box-sizing:border-box, so the bitmap has to match
  // what the element actually paints. Trusting cssW squeezed the board by
  // 4/cssW horizontally and 4/cssH vertically — a different factor on each
  // axis, since the board isn't square — which skewed it very slightly.
  // Capped at 3, not 2. Every current phone reports a dpr of 2.6–3.5, so a cap
  // of 2 drew the board at two thirds of the panel and let the compositor
  // stretch it — a permanent softness on exactly the device the arcade is most
  // played on, and one no setting could recover. A 2D board costs fills and
  // strokes rather than per-pixel shading, so the extra pixels are cheap here
  // in a way they are not in the 3D layer (which has its own governor for it).
  // 3 is the ceiling because nothing ships above it and an uncapped dpr would
  // let a browser-zoom quirk ask for a 30-megapixel bitmap.
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  const dispW = aCanvas.clientWidth || cssW, dispH = aCanvas.clientHeight || cssH;
  const pxW = Math.round(dispW * dpr), pxH = Math.round(dispH * dpr);
  if(aCanvas.width !== pxW || aCanvas.height !== pxH){
    aCanvas.width  = pxW;
    aCanvas.height = pxH;
  }
  aCtx?.setTransform(pxW / BOARD_W, 0, 0, pxH / BOARD_H, 0, 0);

  // 🧊 The 3D surface is layered on this one and must land on exactly the same
  // rectangle, or taps would map to the wrong world position. Sizing it here
  // rather than on its own resize listener means one measurement drives both.
  if(window.PI3D) PI3D.syncSize();
}
let _fitRaf = 0;
function scheduleFit(){ cancelAnimationFrame(_fitRaf); _fitRaf = requestAnimationFrame(() => { fitHud(); fitCanvas(); }); }

// ══ 📐 ONE LINE, WHATEVER IS IN THE ROW ══
// The header carries a variable-length list of readouts — the clock and the
// score always, plus LEVEL in Tetris, ping in a duel, integrity in Boss Rush,
// WAVE in Endless, and the pace ghost on any mission with a personal best — and
// it is capped at the BOARD's width, whose floor is 560px. Below about 600px of
// header the row cannot hold all of it and wraps to a second line.
//
// Widening the header is not available: it tracks the board on purpose, so the
// header, the progress bar and the play field read as one column. So the row
// gives up presentation instead, in the order a player misses least, and only
// as far as it has to. Almost always that is tier 1 alone — a few px of padding
// nobody will notice — and the tiers that actually drop something are reserved
// for a genuinely full row on a genuinely narrow board.
//
// ⚠️ Hidden pills report a zero rect, so they have to be filtered out before
// comparing tops — otherwise a display:none LEVEL pill sits at top 0, never
// matches its siblings, and the row looks permanently wrapped.
const HUD_TIERS = ['hud-t1', 'hud-t2', 'hud-t3'];
function fitHud(){
  const hdr = document.querySelector('.g-hdr');
  const stats = document.querySelector('.g-stats');
  if(!hdr || !stats) return;
  HUD_TIERS.forEach(c => hdr.classList.remove(c));
  // Wrapped == the row is taller than its tallest item. Comparing the items'
  // TOPS instead looks equivalent and is not: the pace ghost is a couple of px
  // taller than a stat pill, so centring puts it ~1px above its neighbours on a
  // perfectly unwrapped row, and any tolerance tight enough to catch a real
  // wrap is loose enough to be tripped by that. Height has no such ambiguity.
  const wrapped = () => {
    const k = [...stats.children].filter(c => getComputedStyle(c).display !== 'none');
    if(k.length < 2) return false;
    const tallest = Math.max(...k.map(c => c.getBoundingClientRect().height));
    return stats.getBoundingClientRect().height > tallest + 2;
  };
  for(const c of HUD_TIERS){
    if(!wrapped()) return;
    hdr.classList.add(c);
  }
}
let _hudRaf = 0;
function scheduleHudFit(){ cancelAnimationFrame(_hudRaf); _hudRaf = requestAnimationFrame(fitHud); }
window.addEventListener('resize', scheduleFit);
// Orientation flips report the old viewport for a beat on iOS, so re-measure late.
window.addEventListener('orientationchange', () => setTimeout(fitCanvas, 260));
if(window.visualViewport) visualViewport.addEventListener('resize', scheduleFit);

// ── CONTROL PAD LAYOUT ──
// Every game declares which buttons it wants and what they say; anything not
// named is hidden. Keeps the pad from carrying a stale ROTATE label into the
// next game and sizes the row for however many buttons survive.
function setControls(cfg){
  const bar = document.getElementById('arcade-controls');
  if(!bar) return;
  bar.style.display = cfg ? 'flex' : 'none';
  bar.classList.remove('four-up','solo-action');

  let shown = 0;
  [['left','ctrl-left'],['action','ctrl-action'],['drop','ctrl-drop'],['right','ctrl-right']]
    .forEach(([key, id]) => {
      const el = document.getElementById(id);
      if(!el) return;
      const label = cfg && cfg[key];
      if(label == null){ el.style.display = 'none'; return; }
      el.style.display = '';
      el.textContent = label;
      // A bare glyph (◀, ↑, ⟳) reads tiny at the label font size — scale those
      // up without stretching worded buttons like "⬇⬇ DROP".
      el.classList.toggle('glyph', [...label].length <= 2);
      shown++;
    });
  if(shown >= 4) bar.classList.add('four-up');
  if(shown === 1) bar.classList.add('solo-action');
  // The purple treatment marks a committing action (Tetris's hard drop), so
  // it's opt-in — Snake's ↓ is just another arrow and shouldn't stand out.
  document.getElementById('ctrl-drop')?.classList.toggle('accent', !!(cfg && cfg.accentDrop));
}

// ── TOUCH TUTORIAL ──
// A finger-driven scheme is invisible until someone tries it, so each touch
// game states its gesture once over the board and clears on first contact.
let _hintTimer = null;
function showTouchHint(text, ms = 3600){
  const el = document.getElementById('touch-hint');
  if(!el) return;
  clearTimeout(_hintTimer);
  if(!isTouchDevice || !text){ el.classList.remove('show'); return; }
  el.textContent = text;
  el.classList.add('show');
  _hintTimer = setTimeout(hideTouchHint, ms);
}
function hideTouchHint(){
  clearTimeout(_hintTimer);
  document.getElementById('touch-hint')?.classList.remove('show');
}

// Header hint line: touch players need the gesture, mouse players the keys.
// A machine with BOTH (a touchscreen laptop, a tablet with a trackpad) can play
// either way now that the control scheme is chosen per event, so it's told
// both rather than being guessed at. The hint has a full-width row of its own,
// so the longer line costs the header nothing.
const hasFinePointer = !!(window.matchMedia && matchMedia('(any-pointer: fine)').matches);
function setControlHint(touchText, keyText){
  const el = document.getElementById('g-controls');
  if(!el) return;
  const parts = [];
  if(isTouchDevice && touchText) parts.push(touchText);
  if((!isTouchDevice || hasFinePointer) && keyText) parts.push(keyText);
  el.textContent = parts.join('  ·  ');
  // Every mission calls this on the way in, which makes it the one hook that
  // catches the canvas-less ones too. Deferred by a frame so the round's pills
  // are painted before the row is measured.
  scheduleHudFit();
}

const countdown=cb=>{
  const ov=document.getElementById('cd-ov'),nm=document.getElementById('cd-num');
  ov.classList.add('show');let n=3;
  const tick=()=>{nm.className='';nm.textContent=n>0?n:'GO!';void nm.offsetWidth;nm.className='cd-pop';snd(n>0?'countdown':'go');if(n<=0)setTimeout(()=>{ov.classList.remove('show');cb()},700);else{n--;setTimeout(tick,1000)}};
  tick();
};

// ════════════════════════════════════════════
//  🔐 GATEWAY VALIDATION INTERFACE KEYS
// ════════════════════════════════════════════
// Only the failures make a noise — setErr('') is also how every screen CLEARS
// the line, and that must stay silent.
const setErr=msg=>{if(msg)snd('error');document.getElementById('auth-err').textContent=msg};

// True while an explicit sign-in flow is still seeding its player node.
// Keeps onAuthStateChanged from racing ahead and loading a half-written profile.
let authPending=false;

document.getElementById('tab-login').onclick=()=>{
  document.getElementById('tab-login').classList.add('active');
  document.getElementById('tab-signup').classList.remove('active');
  document.getElementById('form-login').style.display='';
  document.getElementById('form-signup').style.display='none';
  setErr('');
};
document.getElementById('tab-signup').onclick=()=>{
  document.getElementById('tab-signup').classList.add('active');
  document.getElementById('tab-login').classList.remove('active');
  document.getElementById('form-signup').style.display='';
  document.getElementById('form-login').style.display='none';
  setErr('');
};

document.getElementById('btn-login').onclick=async()=>{
  if(!auth){ showAuthOfflineNotice(); return }
  const email=document.getElementById('l-email').value.trim();
  const pass=document.getElementById('l-pass').value;
  if(!email||!pass){setErr('Fields cannot remain unassigned.');return}
  try{
    // Timed, or a dead network leaves this awaiting a promise Firebase will
    // never settle and the button simply stops responding.
    const c=await withTimeout(auth.signInWithEmailAndPassword(email,pass), NET_WAIT);
    await loadUser(c.user.uid);
  }
  catch(e){
    console.error('Sign-in failed:',e);
    if(e && e.isOffline) showAuthOfflineNotice();
    else setErrCode(e,'email');
  }
};

document.getElementById('btn-signup').onclick=async()=>{
  if(!auth||!db){ showAuthOfflineNotice(); return }
  const name=document.getElementById('s-name').value.trim();
  const email=document.getElementById('s-email').value.trim();
  const pass=document.getElementById('s-pass').value;
  if(!name||!email||!pass){setErr('Fields cannot remain unassigned.');return}
  if(!/^[a-zA-Z0-9_-]{2,20}$/.test(name)){setErr('Format error inside username syntax.');return}
  authPending=true;
  try{
    const c=await withTimeout(auth.createUserWithEmailAndPassword(email,pass), NET_WAIT);
    await db.ref('players/' + c.user.uid).set({ username: name, totalPoints: 0, gamesPlayed: 0 });
    await loadUser(c.user.uid);
  }catch(e){
    console.error('Sign-up failed:',e);
    if(e && e.isOffline) showAuthOfflineNotice();
    else setErrCode(e,'email');
  }
  finally{authPending=false}
};

const fErrMap={'auth/email-already-in-use':'Target email node already claimed.','auth/wrong-password':'Input encryption key mismatch.','auth/user-not-found':'Identity node missing.','auth/weak-password':'Minimum signature length unfulfilled.','auth/invalid-email':'Malformed structural routing email.','auth/credential-already-in-use':'That email is already bound to another identity node.','auth/provider-already-linked':'This session already holds a permanent identity.','auth/requires-recent-login':'Session too old to re-key. Exit and sign in again.','auth/email-already-exists':'Target email node already claimed.'};

// 'operation-not-allowed' / 'admin-restricted-operation' usually mean "the
// provider this call needs is switched off" — WHICH provider depends on the
// call, so every site passes its own context.
const fErrProviderOff={
  guest:'Guest protocol offline — enable Anonymous sign-in in the Firebase Console.',
  email:'Email protocol offline — enable Email/Password sign-in in the Firebase Console.'
};

// …except Identity Platform also reuses OPERATION_NOT_ALLOWED for something
// unrelated: with email enumeration protection ON, an address cannot be attached
// to an account until it has been verified, and linking a guest counts as
// "changing email". Same code, completely different fix — the server's own text
// is the only thing that separates them, so read it before deciding.
const fErrRaw=e=>{
  const sr=e&&e.customData&&e.customData.serverResponse;
  return String((sr&&sr.error&&sr.error.message)||(e&&e.message)||'');
};
const fErrVerifyFirst='Identity re-key blocked — turn OFF “Email enumeration protection” '+
                      '(Firebase Console → Authentication → Settings → User actions).';

const fErr=(e,ctx)=>{
  const c=e&&e.code;
  // Our own timeout, not a Firebase rejection — it carries no meaningful code
  // and must never reach fErrMap's catch-all.
  if(e&&e.isOffline) return '📴 No connection to the mainframe.';
  if(c==='auth/operation-not-allowed'||c==='auth/admin-restricted-operation'){
    if(/verify.*email|email.*verif/i.test(fErrRaw(e))) return fErrVerifyFirst;
    return fErrProviderOff[ctx]||fErrProviderOff.email;
  }
  return fErrMap[c]||'Matrix validation anomaly.';
};

// Prints the raw Firebase code under the friendly line. The code is the only
// thing that actually identifies the failure, and several distinct causes share
// one message — on a phone there is no console to read it out of, so it goes
// on screen.
function showAuthErr(el, e, ctx){
  if(!el) return;
  snd('error');
  el.textContent = fErr(e, ctx);
  if(e && e.code){
    const tag = document.createElement('div');
    tag.textContent = e.code;
    tag.style.cssText = 'margin-top:6px;font-family:var(--fd),monospace;font-size:.52rem;' +
                        'letter-spacing:.1em;color:var(--dimmer);text-transform:none';
    el.appendChild(tag);
  }
}
const setErrCode = (e, ctx) => showAuthErr(document.getElementById('auth-err'), e, ctx);

// ── 🎮 GUEST ACCESS — FIREBASE ANONYMOUS AUTH ──
// Derives a stable display handle from the anonymous UID, e.g. "Guest_A1B2C".
const guestTag = uid => 'Guest_' + String(uid).replace(/[^a-zA-Z0-9]/g,'').slice(0,5).toUpperCase();

async function signInAsGuest(){
  if(!auth||!db){ showAuthOfflineNotice(); return }
  const btn=document.getElementById('btn-guest');
  const label=btn.textContent;
  btn.disabled=true;btn.textContent='⏳ Booting guest node...';
  setErr('');
  authPending=true; // hold off onAuthStateChanged until the profile node exists
  try{
    // Timed, or a dead network leaves the button spinning on "Booting guest
    // node..." with nothing ever resolving.
    const c=await withTimeout(auth.signInAnonymously(), NET_WAIT);
    const ref=db.ref('players/' + c.user.uid);
    const snap=await withTimeout(ref.once('value'), NET_WAIT);
    if(!snap.exists()){
      await ref.set({
        username: guestTag(c.user.uid),
        totalPoints: 0,
        gamesPlayed: 0,
        credits: 0,
        isGuest: true,
        createdAt: firebase.database.ServerValue.TIMESTAMP
      });
    }
    await loadUser(c.user.uid);
    toast('🎮 Guest access granted — progress lives in this browser only.',4000);
  }catch(e){
    console.error('Guest sign-in failed:',e);
    // A dead network is not a credential problem: a new anonymous identity
    // simply cannot be minted offline, so point at the saved profile instead.
    if(e && e.isOffline) showAuthOfflineNotice();
    else setErrCode(e,'guest');
  }finally{
    authPending=false;
    btn.disabled=false;btn.textContent=label;
  }
}

document.getElementById('btn-guest').onclick=signInAsGuest;

// initializeApp() threw, which on a first visit means the SDK itself could not
// be fetched. Without this the auth screen just sits there with three buttons
// that quietly do nothing.
if(!auth) showAuthOfflineNotice();

function ensureUserDefaults(raw){
  raw = raw || {};
  const defaults = {
    username: 'Player', totalPoints: 0, gamesPlayed: 0, credits: 0,
    // Levelling. `xp` is the lifetime total; the level and the points it has
    // paid out are DERIVED from it by xpLevel(), and stored only so a level-up
    // can be detected between two rounds rather than recomputed from scratch.
    xp: 0, level: 1, perkSpent: 0,
    owned: { colors: [], cursors: [], skins: [], drives: [], exits: [] },
    equipped: {
      colors: 'col-cyan', cursors: 'cur-default', skins: 'skin-default',
      drives: 'drv-synthwave', exits: 'exit-default'
    }
  };
  return {
    ...defaults, ...raw,
    owned: {
      colors: [...(raw.owned && raw.owned.colors || [])],
      cursors: [...(raw.owned && raw.owned.cursors || [])],
      skins: [...(raw.owned && raw.owned.skins || [])],
      drives: [...(raw.owned && raw.owned.drives || [])],
      exits: [...(raw.owned && raw.owned.exits || [])]
    },
    equipped: { ...defaults.equipped, ...(raw.equipped || {}) },
    // Progression state. Firebase drops empty objects, so an established player
    // and a brand-new one both arrive here missing these.
    achievements: { ...(raw.achievements || {}) },
    history:      { ...(raw.history || {}) },
    streak:       { count: 0, lastDay: null, best: 0, ...(raw.streak || {}) },
    // ⚠️ EXACTLY {season, pts}. The database's rules validate this record's shape
    // and refuse a write that adds a child to it — and because a refusal takes
    // down the entire update() it rides in, an extra key here silently stopped
    // the streak, the achievements and the credit payout from persisting too.
    // How many season tiers have been paid is DERIVED from `pts` instead (see
    // seasonTiersFor), which is better anyway: the total only ever rises within
    // a season, so a counter beside it was a second source of truth that could
    // disagree with the first.
    weekly:       { season: null, pts: 0, ...(raw.weekly || {}) },
    // 📁 THE DOSSIER's three ledgers. None of these can be derived from what
    // was already stored: `history` keeps only the last twelve runs per mission,
    // so the lifetime best and the lifetime count are both lost the moment a
    // thirteenth round is played.
    best:         { ...(raw.best || {}) },      // gid → best single run, lifetime
    runs:         { ...(raw.runs || {}) },      // gid → rounds finished, lifetime
    days:         { ...(raw.days || {}) },      // UTC day → rounds finished that day
    // ⚔️ The player's STANDING CHALLENGE — one per profile, posted from a results
    // card and discovered by everyone else through the player list the
    // leaderboard already reads. See postChallenge().
    challenge:    raw.challenge || null,
    friends:      { ...(raw.friends || {}) },
    // Perks bought from the tree, keyed by perk id → true. Separate from
    // `achievements` because these are SPENT for, not earned.
    perks:        { ...(raw.perks || {}) },
    // The UTC day ⏳ Chrono Reserve last paid out on. Null on every profile that
    // has never owned the perk, which reads correctly as "not collected today".
    perkDay:      raw.perkDay || null,
    // Consumables, keyed by shop id → count remaining. A number rather than a
    // list: two Time Dilators are not distinguishable from each other.
    powerups:     { ...(raw.powerups || {}) },
    // The player's own best on today's seeded run. `day` is the UTC key it was
    // set on, which is the whole reset mechanism — a stale key reads as no run.
    daily:        { day: null, pts: 0, gid: null, ...(raw.daily || {}) }
  };
}

async function loadUser(uid){
  let data = null, live = false, existed = false;

  if(db){
    try{
      const snapshot = await withTimeout(db.ref('players/' + uid).once('value'), NET_WAIT);
      existed = snapshot.exists();
      data = existed ? snapshot.val() : {};
      live = true;
    }catch(e){
      console.warn('Profile fetch did not answer — opening offline:', e.message);
    }
  }

  if(!live){
    // Nothing live and nothing mirrored means this device has never once
    // loaded this profile, so there is genuinely nothing to open.
    data = readCachedProfile(uid);
    if(!data){ showAuthOfflineNotice(); return; }
  }

  user = { uid, ...ensureUserDefaults(data) };
  // Anonymous sessions are the source of truth for guest status, not the DB flag.
  user.isGuest = !!(auth && auth.currentUser && auth.currentUser.isAnonymous);
  if(user.isGuest && live && !existed) user.username = guestTag(uid);

  setOfflineMode(!live);
  if(live) cacheProfile(user);
  applyEquippedCosmetics();
  snd('login');
  enterHub();
  if(live) flushPendingRuns();
}

// Shown when there is no connection AND no mirrored profile — the one case
// offline genuinely cannot serve, because a Firebase identity cannot be minted
// without a network.
function showAuthOfflineNotice(){
  // With a mirror on this device there is nothing to apologise for — offer the
  // way in instead of an error.
  if(showResumeOffer()){
    const el = document.getElementById('auth-err');
    if(el){
      el.textContent = '📴 No connection — but this device has your progress saved.';
      el.style.display = 'block';
    }
    return;
  }
  // No saved profile either: offer play-now instead of an apology.
  showLocalPlayOffer();
  const el = document.getElementById('auth-err');
  if(el){
    el.textContent = '📴 No connection. You can play now without an account and save your progress once you are back online.';
    el.style.display = 'block';
  }
  setOfflineMode(true);
}

// Restores an existing session on reload — including anonymous guests, whose
// UID persists in browser storage until they sign out or clear site data.
if(auth)auth.onAuthStateChanged(async u=>{
  if(!u||user||authPending)return;
  try{await loadUser(u.uid)}catch(e){console.error('Session restore failed:',e)}
});

// Wipes an unclaimed guest: removes their leaderboard node AND deletes the
// anonymous identity, so abandoned guests don't pile up in Auth or the DB.
// Only ever runs on an account still flagged isAnonymous — once a guest has
// upgraded via linkWithCredential() this is a no-op and their data is safe.
async function purgeGuestAccount(){
  const cu = auth && auth.currentUser;
  if(!cu || !cu.isAnonymous) return false;
  const uid = cu.uid;
  try{ if(db) await db.ref('players/' + uid).remove(); }
  catch(e){ console.warn('Guest data purge failed:', e); }
  try{ await cu.delete(); }            // delete() also ends the session
  catch(e){ console.warn('Guest identity purge failed:', e); if(auth) auth.signOut(); }
  return true;
}

document.getElementById('btn-logout').onclick=async()=>{
  // Signing out while holding a room would leave it on the grid until the tab
  // closed, so the seat goes back first whatever the player decides below.
  await mpLeaveRoom();
  // The grid terminal is the one thing that keeps ticking with nobody in the
  // hub, and its listener is bound to this account's session.
  stopChatTerminal();
  if(user && user.isGuest){
    const pts = (user.totalPoints||0).toLocaleString();
    const warn = (user.totalPoints>0)
      ? `Exiting deletes this guest profile and its ${pts} PTS permanently.\n\nWant to keep them? Cancel, then open ⚙️ Settings → “💾 Save Account”.\n\nExit and delete anyway?`
      : 'Exiting deletes this guest profile permanently. Exit anyway?';
    if(!confirm(warn)) return;
    if(isLocalSession()){
      // A local profile lives in this browser, not in Firebase — wiping it
      // means clearing the mirror and the banked queue, or the next boot's
      // resume path would cheerfully resurrect what was just deleted.
      try{
        localStorage.removeItem(LS_PROFILE);
        localStorage.removeItem(LS_QUEUE);
        localStorage.removeItem(LS_LOCAL);
      }catch(e){}
    } else if(offlineMode){
      // A real guest's purge is two server deletes; offline they never settle
      // and the button would simply freeze. Refuse honestly instead.
      toast('📴 Deleting a guest profile needs a connection. Reconnect and try again.');
      return;
    } else {
      await purgeGuestAccount();
    }
    snd('logout');
    setOfflineMode(false);
    user=null;showScreen('auth-screen');setErr('');toast('🗑️ Guest profile wiped from the grid.');
    return;
  }
  if(auth)auth.signOut();
  snd('logout');
  user=null;showScreen('auth-screen');setErr('');toast('👋 Terminal connection closed.');
};

// ════════════════════════════════════════════
//  🏠 CENTRAL HUB CONTROLLER
// ════════════════════════════════════════════
function enterHub(){
  // Standing in the hub means you are not in a Network Arena room — this is the
  // one place every "I'm done with multiplayer" path passes through, so the
  // room is released here rather than in each of them. A no-op when there is
  // no room, which is the common case.
  if(typeof mpLeaveRoom === 'function') mpLeaveRoom();
  // Same reasoning for a chained run and for a watched room: reaching the hub
  // ends both, and a spectator that kept its listeners would leak them.
  if(typeof abortBossRush === 'function') abortBossRush();
  if(typeof abortEndless === 'function') abortEndless();
  if(typeof abortAnomaly === 'function') abortAnomaly();
  if(typeof abortChallenge === 'function') abortChallenge();
  if(typeof mpStopSpectating === 'function') mpStopSpectating();
  // 📈 The pace ghost deliberately OUTLIVES stopGame() — the results card is
  // written after the round is torn down and it is the thing that reads the
  // curve. So the round that ends by walking away instead has to be closed
  // here, or its frame loop keeps running against a hidden readout.
  Ghost.endPace();
  // ⏳ Chrono Reserve pays out on arrival rather than on a timer — see
  // perkDailyGrant(). A no-op for every profile that does not own it.
  if(typeof perkDailyGrant === 'function') perkDailyGrant();
  // A Daily Hack that was walked away from mid-round still holds the fixed
  // tier. Released here for the same reason the room and the chain are: this is
  // the one door every "I'm done" path goes through.
  if(typeof abortDailyRun === 'function') abortDailyRun();
  document.getElementById('h-uname').textContent=user.username;
  let guestTagEl=document.getElementById('h-guest-tag');
  if(user.isGuest){
    if(!guestTagEl){
      guestTagEl=document.createElement('div');
      guestTagEl.id='h-guest-tag';guestTagEl.className='hub-guest-tag';guestTagEl.textContent='GUEST';
      const un=document.getElementById('h-uname');un.parentNode.insertBefore(guestTagEl,un.nextSibling);
    }
    guestTagEl.style.display='';
  }else if(guestTagEl){guestTagEl.style.display='none'}
  // "Save Account" is only meaningful while the session is still anonymous
  const saveBtn=document.getElementById('btn-save-acct');
  if(saveBtn)saveBtn.style.display=user.isGuest?'':'none';
  // For a local session the button reads as the claim; every hub repaint goes
  // through here, so this keeps its text and handler current either way.
  refreshClaimUi();
  document.getElementById('h-pts').textContent=`🏆 ${(user.totalPoints||0).toLocaleString()} PTS`;
  document.getElementById('h-credits').textContent=`💎 ${(user.credits||0).toLocaleString()} CR`;
  showScreen('hub-screen');
  music('hub');
  loadLeaderboard();
  refreshHubProgression();
  unlockDifficultySelector();
  // The line above rewrites #h-pts wholesale, and the "(x1.5)" tag lives INSIDE
  // it — so the tag has to be put back, or the hub silently stops showing which
  // tier it is paying out at.
  updateHubDiffDisplay();
  // Everything the hub gained: the level rail, today's seeded challenge and its
  // board, the grid terminal and the consumable kit. Guarded as one block —
  // these are hub furniture, and a single one of them throwing must not leave
  // the player looking at a half-painted hub.
  try{
    paintXpRail();
    paintDailyBanner();
    loadDailyBoard();
    startChatTerminal();
    paintPowerKit();
    applyMusicDrive();
    // ♾️ 🌒 The two lanes added beside the Daily Hack, and the loadout rail.
    paintEndlessBanner();
    paintAnomalyBanner();
    loadLaneBoards();
    paintLoadoutRail();
    maybeOnboard();
  }catch(e){ console.warn('Hub panels failed to paint:', e); }
}

// Optional-chained: this file is one long top-level script, so a single missing
// element here would throw and abandon every statement below it — including the
// SHOP_ITEMS/META tables and all sixteen game registrations. That is exactly
// what a browser serving a cached older index.html against a newer app.js
// produces, and it should degrade to "one dead button", not a dead arcade.
document.getElementById('btn-boss-rush')?.addEventListener('click',()=>startBossRush());
document.getElementById('btn-market')?.addEventListener('click',()=>openMarket());
document.getElementById('btn-market-back')?.addEventListener('click',()=>enterHub());
// 🎒 The market's loadout door. It opens the same overlay the hub rail does —
// one shelf, two ways in, because a saved kit is relevant in both places.
document.getElementById('btn-market-loadouts')?.addEventListener('click',
  () => openOverlay('loadout-overlay', renderLoadouts));

document.querySelectorAll('.game-card').forEach(card=>{
  // Desktop only: on a phone every "hover" is really the start of a tap, so
  // the card would blip twice for one press.
  if(!isTouchDevice) card.addEventListener('mouseenter',()=>snd('hover'));
  card.addEventListener('click',()=>{
    const gid=card.dataset.game;
    // 🔒 Checked here as well as painted on the card: the class is the polite
    // refusal, this is the real one.
    if(!missionUnlocked(gid)){
      snd('deny');
      const need = missionClearance(gid);
      toast(`🔒 ${META[gid].name} needs CLEARANCE ${need} — you are level ${xpLevel(user.xp || 0).level}.`, 3200);
      return;
    }
    curGame=gid;
    snd('success');
    document.getElementById('g-title').textContent=META[gid].name;
    showScreen('game-screen');
    prepGame(gid);
  });
});

document.getElementById('btn-quit').onclick=()=>{
  if(onQuitGame){const fn=onQuitGame;onQuitGame=null;fn();return;}
  stopGame();
  setControls(null);
  document.getElementById('game-screen').classList.remove('canvas-game');
  enterHub();
};

// ════════════════════════════════════════════
//  🎮 ROUTING & SCHEDULING INTERFACE
// ════════════════════════════════════════════
// Wipes the shared game screen back to a known state and shows whichever panel
// `gid` plays in. Split out of prepGame() because a Network Arena round needs
// exactly this reset but drives its own start (a shared countdown off the
// server clock, not a local one).
function resetGameStage(gid){
  stopGame();
  onQuitGame=null;
  // 🌀 The record the results card reads about "what was this round played
  // under". chaosClear() deliberately will not overwrite it with nothing — it
  // has to survive a second stopGame() — so the place it gets forgotten is the
  // START of the next round, which is here. Every round passes through this
  // function, including the Daily Hack and a Network Arena round, neither of
  // which would otherwise clear a modifier the previous mission had left behind
  // and would pay the player for it.
  chaos.last = null;
  chaos.lastStack = [];
  // 🌳 Signal Filter's per-round allowance. Zeroed here and restocked by
  // prepGame(), so a round that does NOT go through prepGame — a duel, the
  // Daily Hack — cannot inherit a reroll the last mission left unspent.
  chaosRerollLeft = 0;
  music('game');
  lockDifficultySelector();
  document.getElementById('g-click').style.display='none';
  document.getElementById('g-canvas-holder').style.display='none';
  document.getElementById('g-memory').style.display='none';
  document.getElementById('g-math').style.display='none';
  document.getElementById('g-reaction').style.display='none';
  document.getElementById('g-hacker').style.display='none';
  document.getElementById('g-path').style.display='none';
  document.getElementById('g-freq-ctl').style.display='none';
  document.getElementById('g-sort-rule').style.display='none';
  document.getElementById('tetris-next-wrap').style.display='none';
  document.getElementById('tetris-lvl-pill').style.display='none';
  document.getElementById('bb-deck').style.display='none';
  document.getElementById('bb-ram-pill').style.display='none';
  setControls(null);                 // every game re-declares its own pad
  document.getElementById('g-controls').textContent='';   // and its own hint
  // 🧊 A 3D round always plays on the board, including the missions whose 2D
  // build is pure DOM — so the landscape layout that parks the pad beside the
  // board has to know about them too.
  const canvasGame = ['nebula','tetris','dodge','pong','snake','flappy','breaker','arena','runner','meteor','battlebots','freq',
                      'rhythm','merge','uplink','cutter','sorter','trace','defrag','coolant'].includes(gid)
                  || !!(window.PI3D && PI3D.has(gid));
  document.getElementById('game-screen').classList.toggle('canvas-game', canvasGame);
  // Whatever the last round left up comes down here, before the next one
  // decides whether it wants the GL surface at all.
  if(window.PI3D) PI3D.unmount();

  // ⚙️ A chip is spent on ONE round. Cleared here rather than at the results
  // card because the card is the thing that reads it — clearing it there would
  // be clearing it before the read on the very next line.
  runOverclock = 0;
  document.querySelector('.g-area')?.classList.remove('overclocked-run');
  document.getElementById('g-pts').textContent='0';
  document.getElementById('g-time').textContent='—';
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='var(--cyan)';
  window.onkeydown = window.onkeyup = null;
  if(aCanvas) { aCanvas.onmousemove = null; }
}

// `mod` is an already-rolled chaos modifier, or null for an ordinary round.
// Passed in rather than rolled here because who rolls it is the caller's
// business: Boss Rush rolls one per stage, the Network Arena rolls one per room
// and publishes it so both sides get the SAME one, and a plain mission gets
// none at all.
function prepGame(gid, mod){
  resetGameStage(gid);
  const start = SOLO_START[gid];
  if(!start) return;
  // 🌀 An ordinary mission rolls its own, but only when the player has armed
  // CHAOS PROTOCOL. Rolled HERE rather than at the game card so that Play Again
  // rerolls too — a modifier you could out-wait by pressing the same button is
  // not a modifier, it is a loading screen. Boss Rush and the Network Arena
  // still pass their own in, and passing one always wins: those two have
  // reasons of their own for which modifier this round gets.
  if(mod === undefined && chaosOptIn && !mp && !bossRush){
    const rolled = chaosRollStack();
    mod = rolled.length ? rolled : null;
  }
  chaos.pending = !mod ? [] : (Array.isArray(mod) ? mod : [mod]);
  // 🌳 Signal Filter. One reroll per ROUND, restocked here, because the perk
  // is about the hand you were dealt rather than about a budget to manage.
  chaosRerollLeft = hasPerk('perk-filter') ? 1 : 0;
  chaosAnnounce(chaos.pending);
  countdown(()=>{
    chaosArm(chaos.pending);
    // 🧊 3D MODE. The 3D missions are the same rounds behind a different
    // renderer, so they run through chaosRun() exactly as the 2D ones do —
    // that is what keeps the setInterval doubling and the inverted-key wrapper
    // working in both. startFor() returns false when the player is in 2D mode,
    // when the mission has no 3D build yet, or when the GL round threw on
    // startup; each of those falls through to the 2D implementation, which is
    // always present.
    let ran = false;
    // 📈 Started BEFORE the round so its clock begins on the same frame the
    // game does. Started after chaosArm() so the tier and modifier the personal
    // best is keyed against are the ones actually running.
    Ghost.beginPace(gid, chalRival());
    chaosRun(() => runMissionStart(() => {
      ran = !!(window.PI3D && PI3D.startFor(gid));
      if(!ran) start();
    }));
    if(Ghost.pacing){
      const rv = Ghost.paceRival;
      toast(rv
        ? `⚔️ Racing ${String(rv.name || 'RIVAL').slice(0, 14)} — ${Ghost.paceTarget.toLocaleString()} to beat`
        : `👀 Pacing your best run — ${Ghost.paceTarget.toLocaleString()} to beat`, 2600);
    }
    showPowerDock();
  });
}

// ════════════════════════════════════════════
//  👻 GHOST REPLAY — race your own best run
// ════════════════════════════════════════════
// There are TWO ghosts, and the split is worth understanding before touching
// either. This one is a POSITION trail: begin() at start, sample() once per
// frame, finish() at the end, with playback indexed by FRAME rather than time —
// which is why sample() must be called exactly once per frame, in the same
// rhythm the recording was made at. It only means anything in a mission where
// the player is a moving dot, so four missions use it.
//
// The other is the PACE ghost, further down this module: a score-over-time
// curve that rides setLive() and therefore covers all twenty-one missions
// without any of them opting in. See beginPace().
//
// Ghosts live in localStorage, not Firebase: a timeline is thousands of numbers,
// it is only meaningful against your OWN run, and it must not cost a round trip
// mid-game. Keyed by tier too, since a Meltdown run is not the same race.
const Ghost = (function(){
  const PREFIX = 'pi_ghost_';
  const MAX_FRAMES = 5000;          // ~80s at 60fps, then recording simply stops
  let rec = null, play = null;

  const key = gid => `${PREFIX}${gid}:${currentDifficultyTier}`;

  function begin(gid){
    rec = null; play = null;
    // A duel or a Boss Rush stage is not a solo run — no ghost either way.
    if(mp || bossRush) return;
    rec = { gid, frames: [] };
    try{
      const raw = localStorage.getItem(key(gid));
      const best = raw ? JSON.parse(raw) : null;
      if(best && Array.isArray(best.frames) && best.frames.length) play = best;
    }catch(e){ play = null; }
  }

  // Values are rounded to a tenth — a ghost is a visual pace car, and full
  // float precision would multiply the stored size for no visible gain.
  //
  // 📸 A frame drawn while photo mode holds the round is not a frame of the
  // run. Recording it padded the trail with copies of one position — a new
  // best saved that way stalls on the spot, in every later race, for as long
  // as the camera was up — and spent the ~80s recording budget on nothing.
  function sample(a, b){
    if(!rec || rec.frames.length >= MAX_FRAMES) return;
    if(gPause.on) return;
    rec.frames.push(b == null ? Math.round(a * 10) / 10
                              : [Math.round(a * 10) / 10, Math.round(b * 10) / 10]);
  }

  function at(i){
    if(!play) return null;
    return i < play.frames.length ? play.frames[i] : null;
  }

  function finish(score){
    if(!rec) return;
    const beat = !play || score > play.score;
    if(beat && rec.frames.length){
      try{ localStorage.setItem(key(rec.gid), JSON.stringify({ score, frames: rec.frames })); }
      catch(e){ /* quota or private mode — a missing ghost is not an error */ }
    }
    rec = null;
    return beat;
  }

  function cancel(){ rec = null; play = null; }

  // ══════════════════════════════════════════════════════════════════════
  //  📈 THE PACE GHOST — the other kind of ghost, for the other seventeen
  // ══════════════════════════════════════════════════════════════════════
  // The ghost above is a POSITION trail, and a position trail only means
  // anything in a game where the player is a moving dot: dodge, snake, flappy
  // and runner. That left fourteen missions — every grid, every puzzle, every
  // wave shooter — ending against a bare number with nothing to push against.
  //
  // A pace ghost races the one thing every mission in the arcade genuinely has:
  // a SCORE OVER TIME. It records (elapsed, score) whenever the live counter
  // moves, replays the best run's curve alongside the live one, and says how
  // far ahead or behind you are right now. That works for a mission whose score
  // arrives in one lump at the end as well as one that ticks up continuously —
  // it just says nothing useful until the lump lands, which is honest.
  //
  // It hangs off setLive(), which is the single funnel every mission already
  // writes its live score through. No mission opts in and none can forget to.
  const PACE_PREFIX = 'pi_pace_';
  const PACE_MAX = 400;             // samples; a round that scores more often than
                                    // this is sampled coarsely rather than truncated
  const paceKey = gid => `${PACE_PREFIX}${gid}:${currentDifficultyTier}`;

  let pace = null;                  // { gid, t0, pts:[[ms,score]], best, last, beat }
  let paceRaf = 0;

  // `rival` is an accepted ⚔️ RIVAL CHALLENGE — someone else's curve, raced
  // instead of your own. Two curves are tracked rather than one because they
  // answer different questions: `best` is what the HUD races, `mine` is what a
  // new personal best is measured against. Conflating them meant a run that
  // beat a rival but not your own record overwrote your record with a worse
  // curve, and a run that beat your record while chasing a better rival never
  // saved at all.
  function beginPace(gid, rival){
    endPace();
    // The same three exclusions the position ghost makes, for the same reason:
    // a duel board, a Boss Rush stage and a seeded Daily Hack are not the run
    // this personal best describes.
    if(mp || bossRush || dailyActive) return;
    let mine = null;
    try{
      const raw = localStorage.getItem(paceKey(gid));
      const p = raw ? JSON.parse(raw) : null;
      if(p && Array.isArray(p.pts) && p.pts.length) mine = p;
    }catch(e){ mine = null; }
    const best = (rival && Array.isArray(rival.pts) && rival.pts.length) ? rival : mine;
    // ⏸️ ROUND time, not wall time. The curve is score against time PLAYED:
    // on performance.now() the ghost kept running while photo mode held the
    // round, so a player came back from a photo behind a ghost that had raced
    // on without them — and a best run recorded that way stretched the pause
    // into its curve for every race after it.
    pace = { gid, t0: gNow(), pts: [[0, 0]], best, mine,
             rival: best === rival ? rival : null, last: 0, beat: false };
    paintPace();
    // The widest readout in the row, and it only shows up once a mission has a
    // personal best — so a row that fitted on the first run can stop fitting on
    // the second. Re-measure whenever it appears or disappears.
    scheduleHudFit();
    // Ticks on its own as well as on every score change, because the GHOST
    // moves while you are stuck: a pace readout that only updated when you
    // scored would freeze at "+40" through the ten seconds it took your best
    // run to overtake you, which is the exact stretch you wanted to see.
    const tick = () => {
      if(!pace) return;
      paintPace();
      paceRaf = requestAnimationFrame(tick);
    };
    paceRaf = requestAnimationFrame(tick);
  }

  // Called from setLive(). Cheap by construction: one array push, and only when
  // the number actually moved.
  function samplePace(score){
    if(!pace) return;
    const n = +score;
    if(!Number.isFinite(n) || n === pace.last) return;
    pace.last = n;
    const ms = Math.round(gNow() - pace.t0);
    // Thinning keeps a long round's curve inside the storage budget without
    // losing its shape: once the list is full, every second sample is dropped
    // and the sampling interval doubles. The curve stays the same curve.
    if(pace.pts.length >= PACE_MAX){
      pace.pts = pace.pts.filter((_, i) => i % 2 === 0);
    }
    pace.pts.push([ms, n]);
  }

  // The best run's score at `ms`, interpolated between the two samples that
  // straddle it — a step function would make the ghost lurch.
  function paceAt(ms){
    const b = pace && pace.best;
    if(!b || !b.pts.length) return null;
    const pts = b.pts;
    if(ms <= pts[0][0]) return pts[0][1];
    // The curve ends when the best run did. After that the ghost simply holds
    // its final score, which is exactly what it scored.
    if(ms >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
    let lo = 0, hi = pts.length - 1;
    while(hi - lo > 1){
      const mid = (lo + hi) >> 1;
      if(pts[mid][0] <= ms) lo = mid; else hi = mid;
    }
    const [t0, s0] = pts[lo], [t1, s1] = pts[hi];
    const k = t1 === t0 ? 0 : (ms - t0) / (t1 - t0);
    return s0 + (s1 - s0) * k;
  }

  function paintPace(){
    const el = document.getElementById('ghost-pace');
    if(!el) return;
    if(!pace || !pace.best){ el.style.display = 'none'; return; }
    const ms = gNow() - pace.t0;
    const ghost = Math.round(paceAt(ms) || 0);
    const diff = pace.last - ghost;
    el.style.display = 'flex';
    el.classList.toggle('ahead', diff >= 0);
    el.classList.toggle('behind', diff < 0);
    const rival = pace.rival;
    el.classList.toggle('vs-rival', !!rival);
    el.innerHTML =
      `<span class="gp-ico">${rival ? '⚔️' : '👻'}</span>` +
      `<span class="gp-delta">${diff >= 0 ? '▲ +' : '▼ −'}${Math.abs(diff).toLocaleString()}</span>` +
      `<span class="gp-target">${rival ? esc(String(rival.name || 'RIVAL')).slice(0, 10).toUpperCase() : 'PB'} ` +
      `${pace.best.score.toLocaleString()}</span>`;
  }

  // Saves only on an improvement, and reports whether this run was one — which
  // is what 🌳 Echo Trace pays for.
  function finishPace(score){
    if(!pace) return false;
    const ms = Math.round(gNow() - pace.t0);
    const curve = pace.pts.concat([[score === pace.last ? ms : ms, score]]);
    // Saved against YOUR record, whoever you were racing.
    if((!pace.mine || score > pace.mine.score) && pace.pts.length > 1){
      try{ localStorage.setItem(paceKey(pace.gid), JSON.stringify({ score, pts: curve })); }
      catch(e){ /* quota or private mode — a missing ghost is not an error */ }
    }
    const hadGhost = !!pace.best;
    const target = pace.best ? pace.best.score : 0;
    const rival = pace.rival;
    endPace();
    // `curve` travels out so a finished run can be POSTED as a challenge
    // without the results card having to reconstruct it.
    return hadGhost
      ? { beat: score > target, target, rival: rival ? (rival.name || 'RIVAL') : null, curve }
      : { beat: false, target: 0, rival: null, curve, none: true };
  }

  function endPace(){
    if(paceRaf) cancelAnimationFrame(paceRaf);
    paceRaf = 0;
    pace = null;
    const el = document.getElementById('ghost-pace');
    // Emptied as well as hidden: a hidden element that still holds the last
    // mission's numbers is a trap for anything that reads it back, and it
    // flashes the wrong personal best for a frame if the next round shows it.
    if(el){ el.style.display = 'none'; el.className = 'ghost-pace'; el.innerHTML = ''; }
    scheduleHudFit();
  }

  return {
    begin, sample, at, finish, cancel,
    beginPace, samplePace, finishPace, endPace,
    get racing(){ return !!play; },
    get target(){ return play ? play.score : 0; },
    // True while a pace ghost is live AND has a best run to race. Read by the
    // round-start toast, which should not promise a race that is not happening.
    get pacing(){ return !!(pace && pace.best); },
    get paceTarget(){ return pace && pace.best ? pace.best.score : 0; },
    get paceRival(){ return pace && pace.rival ? pace.rival : null; }
  };
})();

// Shared look for every ghost: the player's own colour, ghosted back.
function ghostStyle(alpha = 0.28){
  aCtx.globalAlpha = alpha;
  aCtx.shadowBlur = 0;
  aCtx.strokeStyle = getEquippedColorHex();
  aCtx.fillStyle = 'rgba(255,255,255,0.08)';
  aCtx.lineWidth = 2;
  aCtx.setLineDash([5, 4]);
}

// ════════════════════════════════════════════
//  🔥 BOSS RUSH — five missions, one score
// ════════════════════════════════════════════
// Rides the same vsResultTap seam a duel uses: each stage's results card is
// intercepted, its RAW score banked, and the next stage started. Only the
// combined total reaches showResults(), so the tier multiplier and the score
// write both happen exactly once.
const BOSS_RUSH_LEN = 5;
// 🔥 The chain's ceiling is DERIVED from the cap table rather than written into
// META, because a number written down beside a table that grows goes stale
// silently: it sat at 6200 — the top-five sum from before PULSE SYNC (1400) and
// CORE MERGE (1300) existed — and clamped every good chain a little low with
// nothing on screen to say so. Cyber Arena is excluded for the same reason it
// is excluded from the pool: a mission that never ends cannot be a stage.
META.bossrush.maxPts = Object.keys(SOLO_START)
  .filter(g => g !== 'arena' && META[g])
  .map(g => META[g].maxPts)
  .sort((a, b) => b - a)
  .slice(0, BOSS_RUSH_LEN)
  .reduce((a, b) => a + b, 0);
// 🩸 CHAIN INTEGRITY. Five independent stages whose scores are added up is a
// playlist, not a chain: a disaster on stage two costs you those points and
// nothing else, and stage three plays exactly as it would have. Carrying a
// single integrity bar across all five is what makes it one run — a bad leg
// now threatens the legs after it, so the decision on stage four is different
// depending on how stage two went.
//
// A stage that takes BR_SAFE of its cap costs nothing at all. Below that the
// damage scales, up to BR_MAX_DMG for a zero — so three genuinely bad stages
// end the chain, two do not, and one is free to be a write-off.
const BR_INTEGRITY = 100, BR_SAFE = 0.6, BR_MAX_DMG = 34;
let bossRush = null;

function startBossRush(){
  // Cyber Arena never ends on its own, so it can't be a stage in a fixed chain.
  // 🔒 And a chain must not deal a mission the player has never been allowed to
  // see: a rush is a test of missions you know, not an ambush. Falls back to the
  // full pool if the ladder ever leaves too few to fill a chain.
  let pool = Object.keys(SOLO_START).filter(g => g !== 'arena' && missionUnlocked(g));
  if(pool.length < BOSS_RUSH_LEN) pool = Object.keys(SOLO_START).filter(g => g !== 'arena');
  const queue = pool
    .map(g => ({ g, k: Math.random() }))
    .sort((a, b) => a.k - b.k)
    .slice(0, BOSS_RUSH_LEN)
    .map(x => x.g);
  bossRush = { queue, idx: 0, total: 0, bd: {}, mods: [], integrity: BR_INTEGRITY, worst: null };
  vsResultTap = bossRushTap;
  snd('success');
  toast(`🔥 BOSS RUSH — ${queue.length} missions, one score, one integrity bar.`, 3600);
  bossRushNext();
}

// The pill that carries the bar into every stage. Built here rather than in
// index.html for the same reason the Battle Bots deck is: it belongs to a mode,
// not to the game screen, and a stale cached page should degrade to "no pill"
// rather than to a broken layout.
function paintBossIntegrity(){
  const stats = document.querySelector('.g-stats');
  let pill = document.getElementById('br-int-pill');
  if(!bossRush){ if(pill) pill.remove(); return; }
  if(!pill && stats){
    pill = document.createElement('div');
    pill.id = 'br-int-pill';
    pill.className = 'stat-pill br-int-pill';
    stats.insertBefore(pill, stats.firstChild);
  }
  if(!pill) return;
  const v = Math.max(0, Math.round(bossRush.integrity));
  pill.innerHTML = `🩸 <em>${v}%</em><span class="br-int-bar"><span style="width:${v}%"></span></span>`;
  pill.classList.toggle('low', v <= 34);
  pill.classList.toggle('mid', v > 34 && v <= 67);
  scheduleHudFit();
}

function bossRushNext(){
  if(!bossRush) return;
  if(bossRush.idx >= bossRush.queue.length){ bossRushFinish(); return; }
  const gid = bossRush.queue[bossRush.idx];
  curGame = gid;
  document.getElementById('g-title').textContent =
    `🔥 ${bossRush.idx + 1}/${bossRush.queue.length} · ${META[gid].name}`;
  showScreen('game-screen');
  // 🌀 A fresh roll per STAGE, not per run: the point of a rush is that you
  // never settle in, and five stages under one modifier is just a long round
  // with a handicap. Recorded so the final card can list what it threw at you.
  //
  // ESCALATING, and not on the ordinary odds. A rush whose modifiers were rolled
  // at 55% could hand out five clean stages or five loaded ones, so the shape of
  // the run was luck rather than design. The first stage is always clean — it is
  // the one that sets the pace and it should be readable — then one modifier,
  // then two. That ramp is the same every run, which is what lets a player plan
  // for it: spend integrity early, because the end is where it gets expensive.
  const step = bossRush.idx;
  const forced = step === 0 ? 0 : step <= 2 ? 1 : 2;
  const rolled = chaosForce(forced);
  if(rolled.length) bossRush.mods.push(`${step + 1}: ${chaosLabel(rolled)}`);
  prepGame(gid, rolled.length ? rolled : null);
  // After prepGame, which calls resetGameStage and wipes the stat strip.
  paintBossIntegrity();
}

function bossRushTap(gid, pts, bd){
  if(!bossRush) return false;
  // The tap short-circuits showResults(), so the finished stage is still
  // running its loop — stop it here rather than waiting for the next prep.
  stopGame();
  // 🌀 Each stage is paid for its OWN modifier, here, because each stage rolled
  // its own. Doing it on the final card instead would multiply five stages by
  // whatever the fifth one happened to draw — which is why bossRushFinish()
  // passes noChaosPay and this line exists.
  const mult = chaosPayMult();
  const paid = Math.round(pts * mult);
  bossRush.total += paid;

  // 🩸 What this stage cost the chain. Measured against the mission's own cap so
  // a 300 in Reaction Time (a 400 cap) and a 1,000 in Cyberpunk Tetris (1,500)
  // are read as the same quality of run — anything else would make the chain a
  // lottery on which missions it drew.
  const cap = (META[gid] && META[gid].maxPts) || 1;
  const frac = Math.min(1, pts / cap);
  const dmg = Math.round(Math.max(0, 1 - frac / BR_SAFE) * BR_MAX_DMG);
  bossRush.integrity -= dmg;
  if(dmg > 0 && (!bossRush.worst || dmg > bossRush.worst.dmg)){
    bossRush.worst = { gid, dmg, frac };
  }

  bossRush.bd[`${META[gid].emoji} ${META[gid].name}`] =
    `${paid} PTS · ${Math.round(frac * 100)}% of cap` + (dmg ? ` · −${dmg}% integrity` : ' · clean');
  bossRush.idx++;
  const left = bossRush.queue.length - bossRush.idx;
  paintBossIntegrity();

  if(bossRush.integrity <= 0){
    // The chain COLLAPSES rather than being forfeit. Quitting still forfeits
    // (see abortBossRush) because that is a choice; running out of integrity is
    // the chain's own ending, and an ending banks.
    snd('gameOver');
    toast('🩸 CHAIN INTEGRITY LOST — banking what you carried', 2800);
    setTimeout(() => bossRushFinish(true), 1400);
    return true;
  }

  snd(dmg ? 'hurt' : 'score');
  toast(
    left > 0
      ? `✅ +${paid} PTS · ${dmg ? `−${dmg}% integrity · ` : ''}${left} to go`
      : `✅ +${paid} PTS · final stage clear`,
    1800);
  setTimeout(bossRushNext, 1100);
  return true;
}

function bossRushFinish(collapsed){
  const total = bossRush.total, bd = { ...bossRush.bd };
  const cleared = bossRush.idx;
  const planned = bossRush.queue.length;
  const mods = bossRush.mods.slice();
  const integrity = Math.max(0, Math.round(bossRush.integrity));
  const worst = bossRush.worst;
  bossRush = null;
  vsResultTap = null;
  paintBossIntegrity();
  bd['🔥 Stages Cleared'] = `${cleared}/${planned}`;
  bd['🩸 Chain Integrity'] = collapsed ? 'LOST' : `${integrity}%`;
  if(worst) bd['💥 Weakest Leg'] = `${META[worst.gid].emoji} ${META[worst.gid].name} · −${worst.dmg}%`;
  if(mods.length) bd['🌀 Modifiers Survived'] = mods.join(' · ');
  // An intact bar is worth points on the way out, so playing the back half
  // carefully beats throwing a stage away for nothing — the same shape as Ice
  // Breaker paying for shields you never spent.
  const bonus = collapsed ? 0 : Math.round(integrity * 4);
  if(bonus) bd['🩸 Integrity Bonus'] = `+${bonus}`;
  showResults('bossrush', total + bonus, bd, {
    emoji: collapsed ? '🩸' : '🔥',
    name: collapsed ? 'BOSS RUSH — CHAIN LOST' : 'BOSS RUSH',
    noChaosPay: true,
    ...(collapsed ? { sound: 'gameOver' } : {}),
    again: { label: 'Run It Again', fn: () => startBossRush() }
  });
}

// Quitting mid-chain abandons the whole run — the banked total is forfeit,
// which is the point of a rush.
function abortBossRush(){
  if(!bossRush) return;
  bossRush = null;
  vsResultTap = null;
  paintBossIntegrity();
}

// ── SCORE TAPS ────────────────────────────────────────────────────────
// Every game in the arcade already announces itself twice: setLive() while it
// runs, showResults() when it ends. A Network Arena SCORE RACE needs exactly
// those two facts from a game it otherwise doesn't touch, so it listens here
// instead of each of the sixteen games learning what a duel is.
//
// Null outside a race, which is the ordinary case and costs one branch.
let vsLiveTap = null;      // (n) => void            — the on-screen number changed
let vsResultTap = null;    // (gid, pts, bd) => bool — true means "I've taken it"

const setLive=n=>{
  document.getElementById('g-pts').textContent=n;
  // 📈 The pace ghost rides here because this is the one line every mission in
  // the arcade already calls to publish its live score. Nothing opts in, nothing
  // can forget to, and a mission added tomorrow gets a personal best to race
  // without its author knowing the feature exists.
  Ghost.samplePace(n);
  if(vsLiveTap) vsLiveTap(n);
};

// `opts` is how a Network Arena round borrows this card without the solo
// assumptions baked into it:
//   noBonus   — skip the difficulty multiplier entirely (pay the raw score)
//   tier      — pay out at THIS tier instead of the live dial. A duel needs it
//               because both boards ran on the room's tier, and that tier has
//               already been handed back by the time this card is written.
//   badge     — {text, cls} replacing the tier bonus badge
//   emoji / name — override the headline
//   again     — {label, fn} for the left button; hub — {label, fn} for the right
function showResults(gid,pts,bd,opts){
  opts = opts || {};
  // A game finishing inside a score race hasn't finished the ROUND — the rival
  // may still be playing. The race takes the score and puts up its own card
  // once both boards are done. `internal` is how the race shows that card
  // without the tap swallowing it in turn.
  if(vsResultTap && !opts.internal && vsResultTap(gid, pts, bd)) return;
  stopGame();
  // 💀 The equipped EXIT STATE plays over the board that just died, and the card
  // lands when it clears. Split here rather than inside the card so the exit
  // covers the same moment the old code spent doing nothing — the beat between
  // the last frame of the game and the first frame of the readout.
  playExitFx(gid, pts, opts, () => showResultsCard(gid, pts, bd, opts));
}

function showResultsCard(gid,pts,bd,opts){
  opts = opts || {};
  music('hub');
  const tier = DIFFICULTY_TIERS[opts.tier] || DIFFICULTY_TIERS[currentDifficultyTier];
  // 🌳 Perk A rides here rather than inside each game, for the same reason the
  // tier multiplier does: this is the one place a raw score becomes an award.
  const perkMult = perkScoreMult(gid, opts);
  // 🌀 What the modifiers the round was played under are worth. Rides the same
  // seam as the tier and the perk for the same reason: this is the one place a
  // raw score becomes an award, and a multiplier applied anywhere else would
  // have to be applied in twenty-one places.
  //
  // noChaosPay is Boss Rush's flag. That chain rolls a FRESH modifier per stage
  // and banks each stage's score as it lands, so it has already paid for every
  // one of them — letting the final card multiply the total by whatever the
  // fifth stage happened to roll would pay the last modifier five times.
  const chaosMult = (opts.noBonus || opts.noChaosPay) ? 1 : chaosPayMult();
  // ⚙️ The chip is the player's own money, so it pays even on the paths that
  // refuse the tier bonus — a duel board where both sides could have bought one
  // is still a fair board.
  const chipMult = (opts.internal || !runOverclock) ? 1 : runOverclock;
  // 📈 Closed here, not in stopGame(), because this is the last moment the run
  // exists: the curve has to survive the teardown to be compared against and
  // saved. Returns false when there was no personal best to race.
  const paceRes = opts.internal ? false : Ghost.finishPace(pts);
  // 🌳 Echo Trace pays for beating the ghost rather than for having one, so it
  // is worth exactly as much as the run you are proud of and nothing on the
  // ones you are not.
  const echoMult = (paceRes && paceRes.beat && hasPerk('perk-echo')) ? 1.1 : 1;
  // ⚔️ Settled here for the same reason everything else is: it is a fact about
  // what this round PAYS. Stands the challenge down either way — a challenge is
  // taken once, win or lose — and hands back the tier it borrowed.
  const chalRes = opts.internal ? null : settleChallenge(gid, pts);
  const chalMult = chalRes ? chalRes.mult : 1;
  const finalPts = Math.round(pts * (opts.noBonus ? 1 : tier.pointMult) * perkMult * chaosMult * chipMult * echoMult * chalMult);
  // ♾️ The cap a run is measured against. Ordinarily the mission's own, but an
  // ENDLESS run has no finish line to be a fraction of — it rides the same
  // uncapped lane CYBER ARENA has always used, generalised into one option
  // rather than a second scoring path. Only the fanfare threshold and the
  // dossier's percentage read it; the award itself is never clamped here.
  const m=META[gid], cap=opts.cap || m.maxPts, pct=finalPts/cap;
  // A three-quarter run earns the fanfare; anything less gets the neutral
  // readout chime, so the sound is honest about how the round actually went.
  // Held back a beat: the screen itself cross-fades over ~340ms, and the games
  // that end in a crash are still playing their death sting right now — this
  // lands the flourish on the card appearing rather than under the explosion.
  // A plain timeout, not gLater(), because stopGame() has already run.
  setTimeout(()=>snd(opts.sound || (pct>.75 ? 'victory' : 'results')), 300);
  document.getElementById('res-emoji').textContent=opts.emoji||(pct>.75?'🎉':'💪');
  document.getElementById('res-gname').textContent=opts.name||m.name;

  // Bonus badge — shows the active tier's point multiplier (×1.0 / ×1.5 / ×2.0), colored to match
  const gnameEl = document.getElementById('res-gname');
  let bonusEl = document.getElementById('res-bonus');
  if(!bonusEl){
    bonusEl = document.createElement('div');
    bonusEl.id = 'res-bonus';
    gnameEl.parentNode.insertBefore(bonusEl, gnameEl.nextSibling);
  }
  bonusEl.className = `res-bonus ${opts.badge ? opts.badge.cls : 'res-bonus-'+tier.key}`;
  bonusEl.textContent = opts.badge ? opts.badge.text
                                   : `${tier.icon} ${tier.label} · ×${tier.pointMult.toFixed(1)} BONUS`;

  document.getElementById('res-pts').textContent=finalPts;
  // 📳 One buzz for a run worth having, a different one for a washout. Here
  // rather than in each mission's end(), for the same reason everything else
  // in this function is here.
  haptic(pct > 0.5 ? 'hx-score' : 'hx-fail');
  // 📁 THE RUN LEDGER. The dossier could already say what your BEST run was;
  // it could not say anything about where a typical run ENDS, because nothing
  // wrote that down. One append here covers all twenty-six missions and both
  // renderers — the same argument as setLive() and the pace ghost.
  if(!opts.internal) logRunEnd(gid, finalPts, cap, paceRes);
  // Rows the round itself can't know about: the perk cut it just paid, the
  // modifier it was played under, and the seed if it was the Daily Hack.
  bd = { ...bd };
  if(perkMult > 1) bd['🌳 Perk · Arcade Boost'] = `+${Math.round((perkMult-1)*100)}%`;
  if(chipMult > 1) bd['⚙️ Overclock Chip'] = `+${Math.round((chipMult-1)*100)}%`;
  // `none` means there was a pace ghost RECORDING but nothing to race, which is
  // every first run on a mission — a row saying "0 vs 0" there is noise.
  if(paceRes && !paceRes.none){
    bd[paceRes.rival ? '⚔️ Rival Pace' : '👀 Pace Ghost'] = paceRes.beat
      ? `AHEAD · beat ${paceRes.target.toLocaleString()}`
      : `${(pts - paceRes.target).toLocaleString()} vs ${paceRes.target.toLocaleString()}`;
    if(echoMult > 1) bd['🌳 Perk · Echo Trace'] = `+${Math.round((echoMult-1)*100)}%`;
  }
  if(chalRes){
    Object.assign(bd, chalRes.rows);
    if(chalMult > 1) bd['⚔️ Takedown Bonus'] = `+${Math.round((chalMult-1)*100)}%`;
  }
  if(chaos.lastStack && chaos.lastStack.length){
    bd['🌀 Chaos Modifier'] = chaosLabel(chaos.lastStack);
    if(chaosMult > 1) bd['🌀 Chaos Payout'] = `×${chaosMult.toFixed(2)}`;
  }else if(chaos.last){
    bd['🌀 Chaos Modifier'] = `${chaos.last.icon} ${chaos.last.name}`;
  }
  // 📦 SUPPLY DROP settles here rather than at the moment it was rolled: the
  // boon is "finish the round and the grid pays out", and a consumable handed
  // over at the countdown would be one a player could quit to keep.
  if(!opts.internal && (chaos.lastStack || []).some(c => c.id === 'surplus')){
    const won = grantRandomConsumable();
    if(won) bd['📦 Supply Drop'] = `${won.emoji} ${won.name}`;
  }
  if(dailyActive)  bd['📅 Daily Seed'] = dailySeedLabel() + (dailyRun ? '' : ' · PRACTICE');
  if(anomalyActive) bd['🌒 Weekly Anomaly'] = anomalyOf().icon + ' ' + anomalyOf().name +
                                              ' · ' + seasonKey() + (anomalyRun ? '' : ' · PRACTICE');
  document.getElementById('res-bd').innerHTML=Object.entries(bd).map(([k,v])=>`<div class="res-row"><span>${k}</span><span class="rv">${v}</span></div>`).join('');
  showScreen('results-screen');
  // 📋 The run, encoded. Built before saveScore() so it describes what was
  // played rather than what the profile looks like afterwards.
  stampReplay(gid, finalPts, tier.key);
  // recordRun() lands one database round trip later, by which time the round's
  // own state has been torn down — so every fact it needs about THIS run is
  // captured here and travels with it rather than being read back.
  saveScore(gid, finalPts, {
    tier: tier.key,
    duelWin: !!opts.duelWin,
    botLevel: opts.botLevel || null,
    perfect: !!opts.perfect,
    maxed: !!opts.maxed,
    chaos: chaos.last ? chaos.last.id : null,
    daily: dailyRun,
    teamSize: (mp && mp.teamSize) || 1
  });
  // 📅 A Daily Hack round posts to its own board and then stands down — which
  // also hands the player's stability dial back. It runs on `dailyActive`, not
  // on `dailyRun`: a practice replay has nothing to post but still has a tier
  // to release.
  if(dailyActive) settleDailyRun(gid, finalPts);
  // 🌒 The same shape, one bucket up: the week's one slot, claimed by the first
  // run that banks something, and handed the player's own stability dial back
  // whichever way the round ended.
  if(anomalyActive) settleAnomalyRun(gid, finalPts);

  // ⚔️ POST AS CHALLENGE. Offered only for a run that can actually be raced:
  // a solo mission (a duel, a Boss Rush total and the Daily Hack are all runs
  // nobody could reproduce from a mission id and a tier), a score above zero,
  // and a pace curve worth posting. The curve comes out of finishPace() rather
  // than being rebuilt here — the round's state is already gone by now.
  const postBtn = document.getElementById('btn-post-chal');
  if(postBtn){
    const curve = paceRes && paceRes.curve;
    const postable = !opts.internal && !!SOLO_START[gid] && pts > 0 && !dailyActive &&
                     Array.isArray(curve) && curve.length > 1 && !!db && !offlineMode;
    postBtn.style.display = postable ? '' : 'none';
    postBtn.disabled = false;
    postBtn.textContent = '⚔️ Post As Challenge';
    if(postable){
      postBtn.onclick = async () => {
        postBtn.disabled = true;
        const ok = await postChallenge(gid, pts, tier.key, curve);
        postBtn.textContent = ok ? '⚔️ Challenge Posted' : '⚔️ Post As Challenge';
        postBtn.disabled = ok;
      };
    }else{
      postBtn.onclick = null;
    }
  }

  const againBtn=document.getElementById('btn-again');
  const hubBtn=document.getElementById('btn-hub');
  againBtn.textContent = opts.again ? opts.again.label : 'Play Again';
  hubBtn.textContent   = opts.hub   ? opts.hub.label   : 'Hub';
  againBtn.onclick = opts.again ? opts.again.fn
                                : ()=>{showScreen('game-screen');prepGame(gid)};
  hubBtn.onclick = opts.hub ? opts.hub.fn : ()=>{
    document.getElementById('h-pts').textContent=`🏆 ${(user?.totalPoints||0).toLocaleString()} PTS`;
    document.getElementById('h-credits').textContent=`💎 ${(user?.credits||0).toLocaleString()} CR`;
    enterHub();
  };
}

// The highest single award a mission can legitimately pay: its cap times the
// best tier multiplier. Anything above that never came from a played round.
const MAX_TIER_MULT = Math.max(...Object.values(DIFFICULTY_TIERS).map(t => t.pointMult));
function maxAwardFor(gid){
  return Math.ceil((META[gid] ? META[gid].maxPts : 2000) * MAX_TIER_MULT);
}

async function saveScore(gid,pts,ctx){
  if(!user) return;
  ctx = ctx || {};
  const award = Math.max(0, Math.min(parseInt(pts || 0) || 0, maxAwardFor(gid)));

  // 📈 XP is earned by PLAYING, so it is granted here — the one call every
  // finished round makes — rather than inside recordRun(), which never runs on
  // the offline path and would quietly stop the profile levelling with no wifi.
  awardXp(award);

  if(!db || offlineMode){ bankRunOffline(gid, award, ctx); return; }

  try{
    await pushRun({ gid, award, ctx });
    snd('coin');
    toast(`✅ Matrix Sync: +${award} PTS`);
  }catch(e){
    // The write did not land. Banking it beats losing the round — the player
    // earned those points whether or not the mainframe was reachable.
    console.warn('Score write failed, banking locally:', e);
    setOfflineMode(true);
    bankRunOffline(gid, award, ctx);
  }
}

// The single server write for a finished round. Split out of saveScore() so the
// offline flush replays banked runs through exactly the same path, rather than
// a parallel copy that could drift away from it.
function pushRun({ gid, award, ctx }){
  const playerRef = db.ref('players/' + user.uid);
  return withTimeout(playerRef.once('value'), NET_WAIT).then(snapshot => {
    const d  = snapshot.val() || { totalPoints: 0, gamesPlayed: 0, highScores: {} };
    const hs = d.highScores || {};
    const newPoints     = parseInt(d.totalPoints || 0) + award;
    const newGames      = parseInt(d.gamesPlayed || 0) + 1;
    const newHighScores = { ...hs, [gid]: Math.max(parseInt(hs[gid] || 0), award) };

    return withTimeout(playerRef.update({
      username: user.username,
      totalPoints: newPoints,
      gamesPlayed: newGames,
      highScores: newHighScores,
      // Server clock, not the client's — the rate-limit rule compares it to `now`.
      lastScoreAt: firebase.database.ServerValue.TIMESTAMP
    }), NET_WAIT).then(() => {
      if(!user) return;
      user.totalPoints = newPoints;
      user.gamesPlayed = newGames;
      user.highScores  = newHighScores;
      // Runs after the score lands, so achievement thresholds test against the
      // totals the player actually has rather than the ones they had a moment ago.
      recordRun(gid, award, ctx);
      cacheProfile(user);
      loadLeaderboard();
    });
  });
}

// An offline round is banked, not lost. Local totals move immediately so the hub
// stays honest about what was just earned; they are optimistic only in that the
// server recomputes from its own state on flush and loadUser() then resyncs, so
// a replayed run can never double-count.
function bankRunOffline(gid, award, ctx){
  const q = pendingRuns();
  q.push({ gid, award, ctx, at: Date.now() });
  lsSet(LS_QUEUE, q);

  user.totalPoints = (user.totalPoints || 0) + award;
  user.gamesPlayed = (user.gamesPlayed || 0) + 1;
  user.highScores  = user.highScores || {};
  user.highScores[gid] = Math.max(parseInt(user.highScores[gid] || 0), award);
  cacheProfile(user);

  const hp = document.getElementById('h-pts');
  if(hp) hp.textContent = `🏆 ${(user.totalPoints || 0).toLocaleString()} PTS`;
  if(typeof updateHubDiffDisplay === 'function') updateHubDiffDisplay();
  paintOfflineBanner();

  snd('coin');
  toast(`📴 +${award} PTS banked — syncs when you reconnect`);
}

// Replayed one at a time with a deliberate gap: the database rules refuse a
// second score write inside 2.5s, so a burst flush would have most of the queue
// rejected as rate-limited.
async function flushPendingRuns(){
  // A local session's queue must only ever drain through claimLocalAccount(),
  // which first swaps in a uid the server will actually accept writes for.
  if(isLocalSession()) return;
  if(!db || !user || offlineMode || flushPendingRuns.busy) return;
  const q = pendingRuns();
  if(!q.length) return;

  flushPendingRuns.busy = true;
  toast(`📡 Syncing ${q.length} banked run${q.length > 1 ? 's' : ''}…`);
  const left = q.slice();
  try{
    for(const run of q){
      try{
        await new Promise(r => setTimeout(r, 2600));
        await pushRun(run);
        left.shift();
        lsSet(LS_QUEUE, left);   // persisted per run, so a mid-flush reload resumes
      }catch(e){
        // Still unreachable — keep whatever is left for the next reconnect.
        console.warn('Banked run not accepted, keeping it queued:', e);
        setOfflineMode(true);
        break;
      }
    }
    if(!left.length){
      // Server state is the truth once the queue drains: the optimistic local
      // totals get replaced rather than added to.
      try{
        const snap = await withTimeout(db.ref('players/' + user.uid).once('value'), NET_WAIT);
        user = { uid: user.uid, ...ensureUserDefaults(snap.val() || {}) };
        user.isGuest = !!(auth && auth.currentUser && auth.currentUser.isAnonymous);
        cacheProfile(user);
        enterHub();
      }catch(e){ console.warn('Post-sync refresh failed:', e); }
      toast('✅ Banked runs synced.');
    }
  } finally {
    flushPendingRuns.busy = false;
    paintOfflineBanner();
  }
}

// ════════════════════════════════════════════
//  🏅 ACHIEVEMENTS · STREAKS · RUN HISTORY
// ════════════════════════════════════════════
// One evaluation point: recordRun() is called by saveScore() after every round,
// solo or duel, and is the only thing that writes progression state. Each
// achievement is a pure predicate over the run plus the player record, so
// adding one never means touching a game.

const HISTORY_LEN = 12; // runs kept per mission for the sparkline

const ACHIEVEMENTS = [
  { id:'first-blood',  icon:'🎯', name:'First Contact',    desc:'Finish your first mission.',                 cr:1,  test:(c)=>c.gamesPlayed >= 1 },
  { id:'decade',       icon:'🔟', name:'Ten Deep',         desc:'Finish 10 missions.',                        cr:2,  test:(c)=>c.gamesPlayed >= 10 },
  { id:'century',      icon:'💯', name:'Centurion',        desc:'Finish 100 missions.',                       cr:10, test:(c)=>c.gamesPlayed >= 100 },
  { id:'pts-5k',       icon:'⭐', name:'Five Thousand',     desc:'Bank 5,000 lifetime points.',                cr:3,  test:(c)=>c.totalPoints >= 5000 },
  { id:'pts-25k',      icon:'🌟', name:'Twenty-Five K',    desc:'Bank 25,000 lifetime points.',               cr:8,  test:(c)=>c.totalPoints >= 25000 },
  { id:'pts-100k',     icon:'✨', name:'Six Figures Soon', desc:'Bank 100,000 lifetime points.',              cr:25, test:(c)=>c.totalPoints >= 100000 },
  { id:'overclocked',  icon:'🟡', name:'Overclocker',      desc:'Score on the Overclock tier.',               cr:2,  test:(c)=>c.tier === 'overclocked' && c.pts > 0 },
  { id:'meltdown',     icon:'🔴', name:'Meltdown Survivor',desc:'Score on the Meltdown tier.',                cr:5,  test:(c)=>c.tier === 'meltdown' && c.pts > 0 },
  { id:'meltdown-ace', icon:'☢️', name:'Critical Mastery', desc:'Take 75% of a mission cap on Meltdown.',     cr:12, test:(c)=>c.tier === 'meltdown' && c.pct >= 0.75 },
  { id:'maxed',        icon:'🏆', name:'Cap Breaker',      desc:'Hit a mission\'s full point cap.',           cr:15, test:(c)=>c.pct >= 1 },
  { id:'duelist',      icon:'⚔️', name:'Duelist',          desc:'Win a Network Arena duel.',                  cr:4,  test:(c)=>c.duelWin },
  { id:'droid-elite',  icon:'🤖', name:'Droid Slayer',     desc:'Beat an Elite droid.',                       cr:10, test:(c)=>c.duelWin && c.botLevel === 'elite' },
  { id:'streak-3',     icon:'🔥', name:'Three-Day Burn',   desc:'Play three days running.',                   cr:3,  test:(c)=>c.streak >= 3 },
  { id:'streak-7',     icon:'🔆', name:'Week Locked In',   desc:'Play seven days running.',                   cr:10, test:(c)=>c.streak >= 7 },
  { id:'streak-30',    icon:'💠', name:'Thirty Straight',  desc:'Play thirty days running.',                  cr:50, test:(c)=>c.streak >= 30 },
  { id:'explorer',     icon:'🗺️', name:'Grid Explorer',    desc:'Score at least once in 8 different missions.',cr:6, test:(c)=>c.missionsPlayed >= 8 },
  { id:'completionist',icon:'👑', name:'Full Sweep',       desc:'Score at least once in every mission.',      cr:30, test:(c)=>c.missionsPlayed >= Object.keys(SOLO_START).length },
  { id:'rush-clear',   icon:'🔥', name:'Rush Hour',        desc:'Finish a Boss Rush chain.',                  cr:8,  test:(c)=>c.gid === 'bossrush' },
  // ── MATRIX ADDITIONS ──
  // Both are facts only the GAME can know, so each one sets a flag on the
  // results options rather than being inferred from the score here: a 950 in
  // Frequency Modulator says nothing about whether the first lock was clean.
  { id:'perfect-sync', icon:'🎯', name:'Perfect Sync',     desc:'Lock the first Frequency Modulator stage without a miss.', cr:12,
    test:(c)=>c.gid === 'freq' && c.perfect },
  { id:'max-overclock',icon:'⚡', name:'Overclocked',      desc:'Hit the maximum possible score in Click Frenzy.',          cr:15,
    test:(c)=>c.gid === 'click' && c.maxed },
  { id:'chaos-rider',  icon:'🌀', name:'Chaos Rider',      desc:'Finish a run under a chaos modifier.',       cr:5,  test:(c)=>!!c.chaos },
  { id:'daily-hacker', icon:'📅', name:'Daily Hacker',     desc:'Post a score on the Daily Hack.',            cr:4,  test:(c)=>!!c.daily },
  { id:'squad',        icon:'👥', name:'Squad Tactics',    desc:'Win a 2v2 co-op grid round.',                cr:8,  test:(c)=>c.duelWin && c.teamSize === 2 },
  { id:'level-10',     icon:'🌳', name:'Tenth Tier',       desc:'Reach profile level 10.',                    cr:10, test:(c)=>c.level >= 10 }
];

const achById = id => ACHIEVEMENTS.find(a => a.id === id);

// UTC day key, so a streak can't be farmed by changing timezone.
const dayKey = (t = Date.now()) => new Date(t).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);

// ISO-ish week key — the bucket the weekly leaderboard sorts on.
function seasonKey(t = Date.now()){
  const d = new Date(t);
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7)); // nearest Thursday
  const year = d.getUTCFullYear();
  const week = Math.ceil(((d - Date.UTC(year, 0, 1)) / 86400000 + 1) / 7);
  return `${year}-W${String(week).padStart(2, '0')}`;
}

// Rolls the daily streak forward. Returns the patch to write, or null when the
// player has already been counted today.
// 🌳 Cold Storage widens the gap a streak survives from one day to two. Read
// live rather than baked into the record, so buying the perk protects the
// streak you are ALREADY on rather than only future ones.
const streakGapAllowed = () => hasPerk('perk-cold') ? 2 : 1;

function rollStreak(streak){
  const today = dayKey();
  if(streak.lastDay === today) return null;
  const gap = streak.lastDay ? daysBetween(streak.lastDay, today) : null;
  const count = (gap !== null && gap >= 1 && gap <= streakGapAllowed())
    ? (streak.count || 0) + 1 : 1;
  return { count, lastDay: today, best: Math.max(count, streak.best || 0) };
}

// Escalating drip, capped so a long streak stays a bonus rather than an income.
const streakReward = n => Math.min(1 + Math.floor(n / 3), 8);

// ══════════════════════════════════════════════════════════════════════
//  🎖️ THE SEASON TRACK — ten tiers a week
// ══════════════════════════════════════════════════════════════════════
// The weekly bucket already existed and did exactly one thing: rank the board,
// and hand a crown to whoever topped it. That is a reward for being the single
// best player on the grid, which is nobody — so for everyone else the weekly
// number was a statistic rather than a goal.
//
// A track fixes that without touching the ranking: it pays for YOUR OWN total,
// on thresholds nobody else can take from you. The board still decides who is
// best; the track decides whether the week was worth playing.
//
// Tiers are claimed AUTOMATICALLY the moment the threshold is crossed. A claim
// button would be a second thing to remember and a way to lose a reward by
// forgetting it — and there is no decision to make, so there is nothing for the
// button to ask.
const SEASON_TIERS = [
  { at:    500, cr:  1 },
  { at:   1500, cr:  2 },
  { at:   3000, cr:  3 },
  { at:   5000, cr:  4 },
  { at:   7500, cr:  6 },
  { at:  11000, cr:  8 },
  { at:  15000, cr: 10 },
  { at:  20000, cr: 12 },
  { at:  27000, cr: 15 },
  // The crown was previously reachable only by topping the weekly board. It
  // stays the top prize, but grinding a full season is now a second way in —
  // grantSeasonCrown() is idempotent, so a player who does both keeps one.
  { at:  35000, cr: 20, crown: true }
];

const seasonPts = () => (user && user.weekly && user.weekly.season === seasonKey()) ? (user.weekly.pts || 0) : 0;
// How many tiers a total has earned. A pure function of the points, which is
// the whole trick: nothing is stored, nothing can drift, and a profile opened
// on a second device computes the same answer from the same number.
const seasonTiersFor = pts => SEASON_TIERS.filter(t => pts >= t.at).length;
const seasonClaimed  = () => seasonTiersFor(seasonPts());
// The next unearned tier, or null once the track is finished.
const seasonNext     = () => SEASON_TIERS[seasonClaimed()] || null;

// Milliseconds until the season key rolls over, so the overlay can say how long
// is left rather than making the player work out which Thursday it means.
function seasonResetIn(){
  const now = Date.now();
  // Walk forward a day at a time rather than doing calendar arithmetic against
  // seasonKey()'s nearest-Thursday rule — eight iterations at most, and it can
  // never disagree with the function that actually decides the bucket.
  for(let d = 1; d <= 8; d++){
    const t = now + d * 86400000;
    if(seasonKey(t) !== seasonKey(now)){
      return Date.parse(new Date(t).toISOString().slice(0, 10) + 'T00:00:00Z') - now;
    }
  }
  return 0;
}
function seasonResetLabel(){
  const ms = seasonResetIn();
  const h = Math.floor(ms / 3600000);
  return h >= 24 ? `${Math.floor(h / 24)}d ${h % 24}h` : `${h}h`;
}

// Pays for every tier the round just crossed. Takes the total BEFORE and AFTER
// rather than reading a stored counter: the difference between the two tier
// counts is exactly what this round earned, needs no state of its own, and
// cannot pay twice for the same tier even if the write that recorded the points
// is later refused.
function settleSeasonTrack(before, after){
  if(!user) return 0;
  const from = seasonTiersFor(before), to = seasonTiersFor(after);
  if(to <= from) return 0;
  let cr = 0, crown = false;
  const hit = [];
  for(let i = from; i < to; i++){
    cr += SEASON_TIERS[i].cr;
    if(SEASON_TIERS[i].crown) crown = true;
    hit.push(i + 1);
  }
  // Held back so it lands after the results card rather than under the round's
  // own death sting — the same reason awardXp() delays its level-up toast.
  setTimeout(() => {
    snd('levelUp');
    toast(hit.length === 1
      ? `🎖️ SEASON TIER ${hit[0]} CLEARED — +${cr} CR`
      : `🎖️ SEASON TIERS ${hit[0]}–${hit[hit.length - 1]} CLEARED — +${cr} CR`, 3600);
    paintSeasonRail();
  }, 1800);
  if(crown) setTimeout(grantSeasonCrown, 2600);
  return cr;
}

function paintSeasonRail(){
  const btn = document.getElementById('btn-season');
  if(!btn) return;
  const next = seasonNext();
  const done = seasonClaimed();
  btn.textContent = next
    ? `🎖️ SEASON ${done}/${SEASON_TIERS.length}`
    : `🎖️ SEASON COMPLETE`;
  // Lit only when there is a tier within reach, so the button is a nudge when
  // it is worth one and furniture the rest of the time.
  const close = next && seasonPts() >= next.at * 0.6;
  btn.classList.toggle('btn-primary', !!close);
  btn.classList.toggle('btn-secondary', !close);
}


// ══════════════════════════════════════════════════════════════════════
//  ⚔️ RIVAL CHALLENGES — the asynchronous half of the arena
// ══════════════════════════════════════════════════════════════════════
// Every head-to-head thing in this arcade needed both people online at the same
// moment. The Network Arena is a live socket: two clients, one simulation, a
// shared countdown — which is the best version of playing someone, and also the
// reason almost nobody ever does. Two people who play at different times of day
// had no way to compete at all.
//
// A challenge is a POSTED RUN. You finish a mission, you publish the score and
// the pace curve, and it sits there. Someone else picks it up hours later, plays
// the same mission at the same stability tier, and races your curve on the same
// HUD the personal-best ghost uses. Nobody waits for anybody.
//
// 🔥 THE STORAGE IS THE INTERESTING PART. A new top-level node would be refused
// outright — the database's rules name the nodes they allow and `players` is one
// of them — so a challenge lives at `players/<uid>/challenge`, inside the record
// its author already owns and already writes. That is not a workaround: it is
// also the only shape that needs no directory, because the leaderboard ALREADY
// reads the player list, so every challenge is discovered by the query that was
// being made anyway.
//
// One standing challenge per profile. A list per player would need pagination,
// expiry and moderation; one slot means posting is always "replace mine", which
// is a decision anyone can make in a second.
const CHAL_CURVE_MAX = 26;          // samples kept in a posted curve
const CHAL_BONUS = 0.15;            // +15% for taking someone's challenge down
let chalActive = null;              // the challenge THIS round is racing
let chalBoard = [];                 // what the last player-list read turned up

// A posted curve is thinned hard. A full pace curve is up to 400 pairs and this
// one rides inside a record the leaderboard fetches for every player on the
// grid — so it is resampled to 26 evenly spaced points, which is more than
// enough to draw a pace line and about three hundred bytes.
function thinCurve(pts){
  if(!Array.isArray(pts) || pts.length <= CHAL_CURVE_MAX) return (pts || []).map(p => [p[0], p[1]]);
  const out = [];
  for(let i = 0; i < CHAL_CURVE_MAX; i++){
    const src = pts[Math.round(i * (pts.length - 1) / (CHAL_CURVE_MAX - 1))];
    out.push([src[0], src[1]]);
  }
  return out;
}

async function postChallenge(gid, pts, tier, curve){
  if(!user) return false;
  if(!db || offlineMode){
    snd('deny');
    toast('📴 Offline — a challenge needs a connection to post.', 2800);
    return false;
  }
  const rec = {
    gid, tier: tier || 'stable', pts: Math.max(0, Math.round(pts)),
    name: user.username || 'OPERATIVE',
    at: Date.now(),
    curve: thinCurve(curve)
  };
  try{
    await db.ref(`players/${user.uid}/challenge`).set(rec);
    user.challenge = rec;
    snd('purchase');
    toast(`⚔️ CHALLENGE POSTED — ${META[gid].emoji} ${META[gid].name} · ${rec.pts.toLocaleString()} to beat`, 3600);
    loadChallenges();
    return true;
  }catch(e){
    // The rules refusing this is the one failure worth naming precisely, because
    // it looks exactly like a code bug from the outside.
    console.warn('Challenge post failed:', e);
    snd('deny');
    toast('⚠️ The grid refused the challenge — it was not posted.', 3200);
    return false;
  }
}

async function withdrawChallenge(){
  if(!user || !db) return;
  try{
    await db.ref(`players/${user.uid}/challenge`).remove();
    user.challenge = null;
    snd('uiBack');
    toast('⚔️ Challenge withdrawn.', 2200);
    loadChallenges();
  }catch(e){ console.warn('Challenge withdraw failed:', e); }
}

// Reads the same player list the leaderboard reads. Ordered by totalPoints so
// the sample skews toward players who actually play, which is also who posts.
function loadChallenges(){
  const panel = document.getElementById('chal-panel');
  if(!panel) return;
  if(!db || offlineMode){
    panel.innerHTML = '<div class="lb-empty">📴 Offline — challenges need a connection.</div>';
    return;
  }
  db.ref('players').orderByChild('totalPoints').limitToLast(60).once('value', snap => {
    const list = [];
    snap.forEach(c => {
      const d = c.val() || {};
      const ch = d.challenge;
      if(!ch || !ch.gid || !META[ch.gid] || !(ch.pts > 0)) return;
      if(c.key === user?.uid) return;                  // yours is shown separately
      list.push({ uid: c.key, ...ch });
    });
    // Freshest first: a challenge from this morning is a better invitation than
    // a record someone set in March.
    list.sort((a, b) => (b.at || 0) - (a.at || 0));
    chalBoard = list.slice(0, 8);
    renderChallenges();
  }, err => {
    console.warn('Challenge read failed:', err);
    panel.innerHTML = '<div class="lb-empty">⚠️ Could not read the challenge board.</div>';
  });
}

function renderChallenges(){
  const panel = document.getElementById('chal-panel');
  if(!panel) return;
  const mine = user && user.challenge;
  let html = '';
  if(mine && META[mine.gid]){
    html += `<div class="chal-mine">` +
      `<div class="chal-mine-lbl">⚔️ YOUR STANDING CHALLENGE</div>` +
      `<div class="chal-row own">` +
        `<span class="chal-ico">${META[mine.gid].emoji}</span>` +
        `<div class="chal-txt"><div class="chal-name">${esc(META[mine.gid].name)}</div>` +
        `<div class="chal-meta">${(mine.pts || 0).toLocaleString()} PTS · ${esc((DIFFICULTY_TIERS[mine.tier] || {}).label || mine.tier)}</div></div>` +
        `<button class="btn btn-secondary btn-sm" id="chal-withdraw">WITHDRAW</button>` +
      `</div></div>`;
  }
  if(!chalBoard.length){
    html += `<div class="lb-empty">No open challenges on the grid. Post one from a results card and it waits here for someone.</div>`;
  }else{
    html += chalBoard.map(c => {
      const m = META[c.gid];
      const tier = DIFFICULTY_TIERS[c.tier] || DIFFICULTY_TIERS.stable;
      const mineBest = (user && user.best && user.best[c.gid]) || 0;
      // Says whether you have ALREADY beaten the number, because that changes
      // whether the row is an invitation or a formality.
      const edge = mineBest > c.pts ? `your best ${mineBest.toLocaleString()}` : null;
      const locked = !missionUnlocked(c.gid);
      return `<div class="chal-row${locked ? ' locked' : ''}">` +
        `<span class="chal-ico">${m.emoji}</span>` +
        `<div class="chal-txt">` +
          `<div class="chal-name">${esc(m.name)}</div>` +
          `<div class="chal-meta">${esc(String(c.name || 'OPERATIVE')).slice(0, 14)} · ` +
          `<strong>${(c.pts || 0).toLocaleString()}</strong> PTS · ${tier.icon} ${esc(tier.label)}` +
          (edge ? ` · <em>${edge}</em>` : '') + `</div>` +
        `</div>` +
        (locked
          ? `<span class="chal-locked">🔒 CLEARANCE ${missionClearance(c.gid)}</span>`
          : `<button class="btn btn-primary btn-sm chal-take" data-uid="${esc(c.uid)}">TAKE IT →</button>`) +
        `</div>`;
    }).join('');
  }
  panel.innerHTML = html;
  document.getElementById('chal-withdraw')?.addEventListener('click', withdrawChallenge);
  panel.querySelectorAll('.chal-take').forEach(b => {
    b.onclick = () => acceptChallenge(b.dataset.uid);
  });
}

function acceptChallenge(uid){
  const c = chalBoard.find(x => x.uid === uid);
  if(!c) return;
  if(!missionUnlocked(c.gid)) return;
  chalActive = c;
  // The tier is part of the challenge, not a preference: racing someone's
  // Meltdown run on Stable Core would be racing a different game. Borrowed for
  // the round and handed back by settleChallenge().
  chalPrevTier = currentDifficultyTier;
  if(DIFFICULTY_TIERS[c.tier]) setDifficultyTier(c.tier);
  lockDifficultySelector();
  curGame = c.gid;
  document.getElementById('g-title').textContent =
    `⚔️ ${META[c.gid].name} · vs ${String(c.name || 'RIVAL').slice(0, 12)}`;
  showScreen('game-screen');
  snd('success');
  toast(`⚔️ CHALLENGE ACCEPTED — beat ${(c.pts || 0).toLocaleString()} on ${(DIFFICULTY_TIERS[c.tier] || {}).label || c.tier}`, 3600);
  prepGame(c.gid);
}
let chalPrevTier = null;

// The curve the pace ghost should race this round, or null for your own record.
function chalRival(){
  if(!chalActive || !Array.isArray(chalActive.curve) || !chalActive.curve.length) return null;
  return { score: chalActive.pts, pts: chalActive.curve, name: chalActive.name };
}

// Settled on the results card. Returns the breakdown rows it wants added and
// the multiplier it earned, then stands the challenge down — win or lose, a
// challenge is taken once.
function settleChallenge(gid, pts){
  if(!chalActive) return null;
  const c = chalActive;
  chalActive = null;
  if(chalPrevTier){ setDifficultyTier(chalPrevTier); chalPrevTier = null; }
  unlockDifficultySelector();
  if(c.gid !== gid) return null;                 // not the round that was accepted
  const won = pts > (c.pts || 0);
  setTimeout(() => {
    snd(won ? 'victory' : 'results');
    toast(won
      ? `⚔️ CHALLENGE TAKEN DOWN — beat ${String(c.name || 'RIVAL').slice(0, 14)} by ${(pts - c.pts).toLocaleString()}`
      : `⚔️ CHALLENGE HELD — ${String(c.name || 'RIVAL').slice(0, 14)} keeps it by ${((c.pts || 0) - pts).toLocaleString()}`,
      3600);
  }, 1600);
  return {
    won,
    mult: won ? 1 + CHAL_BONUS : 1,
    rows: {
      '⚔️ Rival Challenge': `${String(c.name || 'RIVAL').slice(0, 14)} · ${(c.pts || 0).toLocaleString()} PTS`,
      '⚔️ Outcome': won ? 'TAKEN DOWN' : 'HELD'
    }
  };
}

// Walking away from an accepted challenge must hand the borrowed tier back, or
// the dial stays locked on someone else's setting for the rest of the session.
function abortChallenge(){
  if(!chalActive) return;
  chalActive = null;
  if(chalPrevTier){ setDifficultyTier(chalPrevTier); chalPrevTier = null; }
  unlockDifficultySelector();
}

// ══════════════════════════════════════════════════════════════════════
//  📁 THE OPERATIVE DOSSIER
// ══════════════════════════════════════════════════════════════════════
// Everything the profile already knew and had nowhere to say. The arcade
// recorded a lifetime point total, a run history per mission and a streak, and
// showed the player exactly one of those three — a number in the hub bar. So a
// hundred rounds of play left no readable trace, and the one question a
// returning player actually has ("which of these have I got good at?") had no
// answer anywhere in the interface.
//
// It is a READ-ONLY view by design. Nothing here awards anything, nothing here
// can be spent, and that is what lets it show everything at once without
// becoming a second economy to manage.
const HEAT_WEEKS = 18;                     // ~4 months, which fits the width

// 📅 THE ACTIVITY LOG lives in localStorage rather than on the profile. It is a
// private record of when you played, nothing else in the arcade reads it, and
// nobody is ever ranked on it — the same reasoning that keeps the ghost curves
// local. The honest cost is that it is per-device: play on a phone and a laptop
// and each keeps its own half of the picture.
const DAYS_KEY = 'pi_days';
function activityDays(){
  try{
    const raw = localStorage.getItem(DAYS_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return (o && typeof o === 'object') ? o : {};
  }catch(e){ return {}; }
}
function bumpActivityDay(){
  try{
    const o = activityDays();
    const k = dayKey();
    o[k] = (o[k] || 0) + 1;
    // Pruned to a little more than the window the heatmap draws, so the record
    // cannot grow without bound on a profile that is years old.
    const keep = Object.keys(o).sort().slice(-(HEAT_WEEKS * 7 + 14));
    const out = {};
    keep.forEach(d => { out[d] = o[d]; });
    localStorage.setItem(DAYS_KEY, JSON.stringify(out));
    if(user) user.days = out;
  }catch(e){ /* private mode — a missing heatmap is not an error */ }
}

// 📁 Best and run count, derived when the database has not been taught to store
// them. `history` keeps the last twelve runs, so the derived best is the best of
// those twelve and the derived count saturates at twelve — which is why the
// dossier marks a saturated count with a '+' rather than pretending to know.
const dosBest = gid => (user.best && user.best[gid]) || Math.max(0, ...(user.history[gid] || [0]));
const dosRuns = gid => (user.runs && user.runs[gid]) || (user.history[gid] || []).length;
const dosRunsExact = gid => !!(user.runs && user.runs[gid]);

// Sundays back to the start of the window, so the grid's columns are weeks and
// its rows are weekdays — the shape everyone already reads as a calendar.
function heatDays(){
  const out = [];
  const today = new Date(dayKey() + 'T00:00:00Z');
  // Walk back to the most recent Sunday so the final column is the current week.
  const end = new Date(today);
  end.setUTCDate(end.getUTCDate() + (6 - end.getUTCDay()));
  for(let i = HEAT_WEEKS * 7 - 1; i >= 0; i--){
    const d = new Date(end);
    d.setUTCDate(d.getUTCDate() - i);
    out.push(d.toISOString().slice(0, 10));
  }
  return out;
}

function renderDossier(){
  const wrap = document.getElementById('dossier-body');
  const sub  = document.getElementById('dossier-sub');
  if(!wrap || !user) return;

  const st = xpLevel(user.xp || 0);
  const gids = Object.keys(SOLO_START);
  // Read from localStorage each time it is opened rather than trusting the copy
  // on the profile: the log is written by bumpActivityDay() and a session that
  // was open when the day rolled over would otherwise draw a stale calendar.
  user.days = activityDays();
  const played = gids.filter(g => dosRuns(g) > 0);
  const bestRun = Math.max(0, ...gids.map(g => dosBest(g)));
  const totalRuns = gids.reduce((a, g) => a + dosRuns(g), 0);
  const achGot = ACHIEVEMENTS.filter(a => user.achievements[a.id]).length;

  if(sub) sub.textContent =
    `${esc(user.username || 'OPERATIVE')} · level ${st.level} · ${played.length} of ${gids.length} missions on record`;

  const tile = (icon, label, value, note) =>
    `<div class="dos-tile"><span class="dos-ico">${icon}</span>` +
    `<div class="dos-val">${value}</div><div class="dos-lbl">${esc(label)}</div>` +
    (note ? `<div class="dos-note">${esc(note)}</div>` : '') + `</div>`;

  // ── LIFETIME ──
  let html = `<div class="dos-sec">⭐ LIFETIME</div><div class="dos-tiles">` +
    tile('🏆', 'Points banked', (user.totalPoints || 0).toLocaleString()) +
    tile('🎮', 'Rounds finished', (user.gamesPlayed || 0).toLocaleString()) +
    tile('💎', 'Credits held', (user.credits || 0).toLocaleString()) +
    tile('📈', 'Best single run', bestRun ? bestRun.toLocaleString() : '—') +
    tile('🔥', 'Streak', `${user.streak.count || 0}`, `best ${user.streak.best || 0} days`) +
    tile('🏅', 'Achievements', `${achGot}/${ACHIEVEMENTS.length}`) +
    tile('🎖️', 'Season points', seasonPts().toLocaleString(), `tier ${seasonClaimed()}/${SEASON_TIERS.length}`) +
    tile('🌳', 'Perks owned', `${PERKS.filter(p => hasPerk(p.id)).length}/${PERKS.length}`) +
    `</div>`;

  // ── ACTIVITY ──
  // A day with one round and a day with thirty should not look the same, so the
  // ramp is on the COUNT — but capped at 6, because past that the difference
  // stops being information and starts being a gradient nobody can read.
  const days = heatDays();
  const todayKey = dayKey();
  const activeDays = days.filter(d => (user.days[d] || 0) > 0).length;
  html += `<div class="dos-sec">📅 ACTIVITY <em>${activeDays} active days in the last ${HEAT_WEEKS} weeks</em></div>`;
  html += `<div class="dos-heat">`;
  for(let w = 0; w < HEAT_WEEKS; w++){
    html += `<div class="dos-heat-col">`;
    for(let d = 0; d < 7; d++){
      const key = days[w * 7 + d];
      const n = user.days[key] || 0;
      const lvl = n === 0 ? 0 : Math.min(4, Math.ceil(n / 1.5));
      const future = key > todayKey;
      html += `<span class="dos-cell l${lvl}${future ? ' fut' : ''}${key === todayKey ? ' today' : ''}"` +
              ` title="${key} · ${n} round${n === 1 ? '' : 's'}"></span>`;
    }
    html += `</div>`;
  }
  html += `</div><div class="dos-heat-key"><span>quiet</span>` +
          `<span class="dos-cell l0"></span><span class="dos-cell l1"></span><span class="dos-cell l2"></span>` +
          `<span class="dos-cell l3"></span><span class="dos-cell l4"></span><span>busy</span></div>`;

  // ── PER-MISSION ──
  // Ranked by how close the best run got to the mission's CAP, not by the raw
  // score: a 1,400 in Pulse Sync and a 400 in Reaction Time are the same
  // achievement, and ranking by points would bury every short mission.
  const rows = played.map(g => {
    const m = META[g], hist = user.history[g] || [];
    const best = dosBest(g);
    const runs = dosRuns(g);
    const exact = dosRunsExact(g);
    const avg = hist.length ? Math.round(hist.reduce((a, b) => a + b, 0) / hist.length) : 0;
    // Cyber Arena is uncapped (99999), so a percentage of its cap is
    // meaningless — it is ranked on its own best instead and shows no bar.
    const capped = m.maxPts < 90000;
    return { g, m, best, runs, avg, hist, capped, exact, pct: capped ? Math.min(1, best / m.maxPts) : 0 };
  }).sort((a, b) => (b.capped ? b.pct : 0) - (a.capped ? a.pct : 0) || b.best - a.best);

  html += `<div class="dos-sec">🎯 MISSION RECORD <em>ranked by how close your best run came to the cap</em></div>`;
  if(!rows.length){
    html += `<div class="dos-empty">Nothing on record yet — finish a mission and it appears here.</div>`;
  }else{
    html += `<div class="dos-missions">`;
    for(const r of rows){
      // Sparkline of the last twelve, drawn as bars rather than a polyline: at
      // twelve points a line is mostly interpolation and a bar is a fact.
      const top = Math.max(1, ...r.hist);
      const spark = r.hist.map(v =>
        `<span style="height:${Math.max(6, (v / top) * 100)}%"></span>`).join('');
      html += `<div class="dos-mission" data-dos="${r.g}" tabindex="0" role="button" aria-label="Open the ${esc(r.m.name)} dossier">` +
        `<span class="dm-ico">${r.m.emoji}</span>` +
        `<div class="dm-name">${esc(r.m.name)}</div>` +
        `<div class="dm-stats">` +
          `<span class="dm-best">${r.best.toLocaleString()}</span>` +
          `<span class="dm-cap">${r.capped ? `${Math.round(r.pct * 100)}% of cap` : 'uncapped'}</span>` +
        `</div>` +
        (r.capped ? `<div class="dm-bar"><span style="width:${r.pct * 100}%"></span></div>` : `<div class="dm-bar dm-bar-none"></div>`) +
        `<div class="dm-foot"><span>${r.runs}${!r.exact && r.runs >= HISTORY_LEN ? '+' : ''} run${r.runs === 1 ? '' : 's'}</span>` +
        `<span>avg ${r.avg.toLocaleString()} (last ${r.hist.length})</span></div>` +
        `<div class="dm-spark">${spark}</div>` +
        `</div>`;
    }
    html += `</div>`;
  }

  // Missions with nothing on record are named rather than omitted: "you have
  // never played these three" is the most actionable line on the page.
  const missing = gids.filter(g => !played.includes(g));
  if(missing.length){
    html += `<div class="dos-sec">🕳️ NO RECORD <em>never finished</em></div><div class="dos-missing">` +
      missing.map(g => `<span class="dos-chip" data-jump="${g}">${META[g].emoji} ${esc(META[g].name)}</span>`).join('') +
      `</div>`;
  }

  wrap.innerHTML = html;
  // The chips are a door, not a label: tapping one closes the dossier and
  // scrolls the mission it names into view.
  // A row is a DOOR now, not a summary. Everything the arcade already recorded
  // per mission — the pace curve, the run ledger, the endless best — lives one
  // tap in, where there is room to read it.
  wrap.querySelectorAll('.dos-mission[data-dos]').forEach(el => {
    const open = () => renderMissionDossier(el.dataset.dos);
    el.onclick = open;
    el.onkeydown = e => { if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); open(); } };
  });
  wrap.querySelectorAll('.dos-chip[data-jump]').forEach(el => {
    el.onclick = () => {
      closeOverlay('dossier-overlay');
      const card = document.querySelector(`.game-card[data-game="${el.dataset.jump}"]`);
      if(card){
        card.scrollIntoView({ block: 'center', behavior: 'smooth' });
        card.classList.add('gc-flash');
        setTimeout(() => card.classList.remove('gc-flash'), 1600);
      }
    };
  });
}

function renderSeasonTrack(){
  const wrap = document.getElementById('season-track');
  const sub  = document.getElementById('season-sub');
  if(!wrap || !user) return;
  const pts = seasonPts(), done = seasonClaimed();
  const next = seasonNext();
  if(sub){
    sub.textContent = next
      ? `${pts.toLocaleString()} pts this season · ${(next.at - pts).toLocaleString()} to tier ${done + 1} · resets in ${seasonResetLabel()}`
      : `${pts.toLocaleString()} pts this season · track complete · resets in ${seasonResetLabel()}`;
  }
  const top = SEASON_TIERS[SEASON_TIERS.length - 1].at;
  wrap.innerHTML =
    `<div class="season-bar"><div class="season-bar-fill" style="width:${Math.min(100, pts / top * 100)}%"></div></div>` +
    `<div class="season-tiers">` +
    SEASON_TIERS.map((t, i) => {
      const state = i < done ? 'paid' : pts >= t.at ? 'ready' : 'locked';
      const pct = Math.min(1, pts / t.at);
      return `<div class="season-tier ${state}">` +
             `<div class="st-num">${i + 1}</div>` +
             `<div class="st-at">${t.at.toLocaleString()}</div>` +
             `<div class="st-reward">${t.crown ? '👑 CROWN + ' : ''}${t.cr} CR</div>` +
             `<div class="st-meter"><span style="width:${pct * 100}%"></span></div>` +
             `<div class="st-state">${state === 'paid' ? '✔ PAID' : state === 'ready' ? 'CLAIMING…' : `${Math.round(pct * 100)}%`}</div>` +
             `</div>`;
    }).join('') +
    `</div>`;
}

// The whole progression write for one finished round, batched into a single
// update() so it costs one round trip and can't half-apply.
function recordRun(gid, pts, ctx){
  if(!db || !user) return;
  const m = META[gid];
  const patch = {}, unlocked = [];

  // ── run history (client-trimmed; the DB keeps only what the sparkline draws)
  const hist = [...(user.history[gid] || []), pts].slice(-HISTORY_LEN);
  user.history[gid] = hist;
  patch['history/' + gid] = hist;

  // ── 📁 the dossier's ledgers.
  //
  // ⚠️ DELIBERATELY NOT IN `patch`. The database's rules enumerate the child keys
  // they allow under a player record, and a single update() carrying ONE key
  // they do not name is refused ENTIRELY — so adding these three to the
  // progression patch silently stopped the streak, the achievements, the weekly
  // bucket and the credit payout from persisting at all. The symptom was a
  // console warning and four unrelated systems quietly going read-only.
  //
  // So they go out as their own write, after the one that matters, and that
  // write is allowed to fail. Until the Console rules name `best` and `runs`,
  // the dossier derives them from `history` instead (see dosBest/dosRuns) and
  // is fully readable either way; once they are named it gains a lifetime run
  // count and a best that survives a thirteenth round.
  if(pts > (user.best[gid] || 0)) user.best[gid] = pts;
  user.runs[gid] = (user.runs[gid] || 0) + 1;
  const ledger = { ['best/' + gid]: user.best[gid], ['runs/' + gid]: user.runs[gid] };
  // 📅 The activity log is LOCAL on purpose, not just for want of a rule. It is
  // a private record of when you played, it is never compared against anyone,
  // and nothing else in the arcade needs to read it — the same reasoning that
  // keeps the ghost curves in localStorage. The cost is that it is per-device.
  bumpActivityDay();

  // ── weekly bucket, reset when the season key rolls over
  const season = seasonKey();
  const weeklyBefore = (user.weekly.season === season) ? (user.weekly.pts || 0) : 0;
  const weekly = { season, pts: weeklyBefore + pts };
  user.weekly = weekly;
  patch.weekly = weekly;

  // ── daily streak
  const roll = rollStreak(user.streak);
  let streakBonus = 0;
  if(roll){
    user.streak = roll;
    patch.streak = roll;
    streakBonus = streakReward(roll.count);
  }

  // ── achievements
  const cond = {
    gid, pts,
    tier: ctx.tier || currentDifficultyTier,
    pct: m ? pts / m.maxPts : 0,
    duelWin: !!ctx.duelWin,
    botLevel: ctx.botLevel || null,
    // Facts only the round itself could report, forwarded from showResultsCard.
    perfect: !!ctx.perfect,
    maxed: !!ctx.maxed,
    chaos: ctx.chaos || null,
    daily: !!ctx.daily,
    teamSize: +ctx.teamSize || 1,
    level: xpLevel(user.xp || 0).level,
    totalPoints: user.totalPoints || 0,
    gamesPlayed: user.gamesPlayed || 0,
    streak: user.streak.count || 0,
    // Boss Rush banks under its own key but isn't a mission — counting it
    // would let Full Sweep unlock one mission short.
    missionsPlayed: Object.keys(user.history)
      .filter(k => SOLO_START[k] && (user.history[k] || []).length).length
  };
  // 🎖️ The season track pays for whatever tiers this round's points crossed,
  // folded into the same payout the streak and the achievements use. It stores
  // nothing of its own — the tier count is derived from the weekly total, which
  // is the only reason it needs no key the rules would have to be taught.
  let creditGain = streakBonus + settleSeasonTrack(weeklyBefore, weekly.pts);
  // ♻️ Salvage Routine. Sixty percent of a mission's cap is a good run rather
  // than a lucky one, and Cyber Arena's uncapped 99999 can never reach it —
  // which is correct: a perk that paid per point would pay that mission alone.
  let salvage = 0;
  if(hasPerk('perk-salvage') && cond.pct >= 0.6){
    salvage = 1;
    creditGain += salvage;
  }
  ACHIEVEMENTS.forEach(a => {
    if(user.achievements[a.id]) return;
    let hit = false;
    try{ hit = !!a.test(cond); }catch(e){ hit = false; }
    if(!hit) return;
    user.achievements[a.id] = Date.now();
    patch['achievements/' + a.id] = firebase.database.ServerValue.TIMESTAMP;
    creditGain += a.cr;
    unlocked.push(a);
  });

  if(creditGain > 0){
    user.credits = (user.credits || 0) + creditGain;
    patch.credits = user.credits;
  }

  db.ref('players/' + user.uid).update(patch)
    .catch(e => console.warn('Progression write failed:', e));
  // Fired and forgotten, separately, so a rule that has not been taught about
  // these keys costs the dossier a little precision and costs the progression
  // write nothing at all.
  db.ref('players/' + user.uid).update(ledger)
    .catch(() => { /* not yet allowed by the rules — the dossier derives instead */ });

  if(salvage > 0) toast(`♻️ SALVAGE ROUTINE · +${salvage} CR`, 2400);
  if(streakBonus > 0) announceStreak(user.streak.count, streakBonus);
  if(unlocked.length) announceUnlocks(unlocked);
  refreshHubProgression();
}

// Unlocks queue rather than stacking — three at once would otherwise overwrite
// each other in the single shared toast element.
let _unlockQueue = [], _unlockTimer = null;
function announceUnlocks(list){
  _unlockQueue.push(...list);
  if(_unlockTimer) return;
  const nextOne = () => {
    const a = _unlockQueue.shift();
    if(!a){ _unlockTimer = null; return; }
    snd('victory');
    toast(`${a.icon} ACHIEVEMENT — ${a.name}  ·  +${a.cr} CR`, 3200);
    _unlockTimer = setTimeout(nextOne, 3400);
  };
  nextOne();
}

function announceStreak(count, bonus){
  setTimeout(() => toast(`🔥 ${count}-DAY STREAK  ·  +${bonus} CR`, 2800), 900);
}

// ── HUB PROGRESSION UI ──
// Streak chip in the hub bar, plus the badge shelf under the leaderboard.
// ══════════════════════════════════════════════════════════════════════
//  🔒 CLEARANCE LEVELS — the mission ladder
// ══════════════════════════════════════════════════════════════════════
// Twenty-one missions were open on the first visit, which is not generosity —
// it is twenty-one identical-looking cards and no reason to pick any of them.
// A new player's first decision was the hardest one the arcade ever asks, and
// they made it with no information at all.
//
// The ladder is deliberately SHALLOW. Six missions are open immediately, the
// rest arrive over the first handful of rounds, and everything is open by level
// seven — which at a tenth of a point per XP is about six thousand lifetime
// points, a single evening. It exists to stagger the introduction, not to gate
// content: a player who wants Battle Bots on day one waits ten minutes, not a
// week.
//
// Grouped by how much a mission has to EXPLAIN, not by difficulty. Click Frenzy
// and Reaction Time need one sentence; Battle Bots needs a deck, an economy and
// three lanes, and meeting it first is how a new player decides this arcade is
// not for them.
const MISSION_CLEARANCE = {
  // 1 — one rule each, readable in a single sentence.
  click: 1, reaction: 1, memory: 1, math: 1, dodge: 1, nebula: 1,
  // 2 — one rule plus a control scheme to learn.
  pong: 2, snake: 2, flappy: 2, coolant: 2,
  // 3 — a board that has state you have to plan against.
  tetris: 3, breaker: 3, merge: 3, trace: 3,
  // 4 — a puzzle with a rule you have to be told.
  hacker: 4, path: 4, rhythm: 4, defrag: 4,
  // 5 — sustained runs with a resource to manage.
  runner: 5, meteor: 5, uplink: 5, cutter: 5, sorter: 5,
  // 6–7 — a console, an ability bar, an economy.
  freq: 6, arena: 6,
  battlebots: 7
};
const MISSION_MAX_CLEARANCE = Math.max(...Object.values(MISSION_CLEARANCE));

// A mission the player has ALREADY scored in is never taken away. This is the
// whole reason the ladder is safe to add to a live arcade: an established
// profile lands on it with every mission it has ever played already open, so
// the feature is invisible to everyone except the people it is for.
const missionScored = gid => !!(user && ((user.runs && user.runs[gid] > 0) ||
                                         (user.history && (user.history[gid] || []).length)));

function missionClearance(gid){ return MISSION_CLEARANCE[gid] || 1; }
function missionUnlocked(gid){
  if(!user) return true;                       // pre-login: nothing to gate
  if(missionScored(gid)) return true;
  return xpLevel(user.xp || 0).level >= missionClearance(gid);
}

// Paints the grid. Called from enterHub and from refreshHubProgression, so a
// level gained mid-session opens its cards without a reload.
function paintMissionLocks(){
  if(!user) return;
  const lvl = xpLevel(user.xp || 0).level;
  document.querySelectorAll('.game-card').forEach(card => {
    const gid = card.dataset.game;
    const need = missionClearance(gid);
    const open = missionUnlocked(gid);
    card.classList.toggle('locked', !open);
    card.setAttribute('aria-disabled', String(!open));
    let tag = card.querySelector('.gc-lock');
    if(open){ if(tag) tag.remove(); return; }
    if(!tag){
      tag = document.createElement('span');
      tag.className = 'gc-lock';
      card.appendChild(tag);
    }
    // Says how far away it is, not just that it is shut. "CLEARANCE 3" is a
    // locked door; "2 LEVELS AWAY" is a thing you are on your way to.
    const gap = need - lvl;
    tag.innerHTML = `<span class="gcl-ico">🔒</span>` +
      `<span class="gcl-txt">CLEARANCE ${need}<em>${gap === 1 ? 'one level away' : `${gap} levels away`}</em></span>`;
  });
  // The sub-line under the grid label carries the summary, so a player can see
  // at a glance whether anything is still shut without scanning the cards.
  const lab = document.getElementById('mission-clearance');
  if(lab){
    const shut = Object.keys(SOLO_START).filter(g => !missionUnlocked(g)).length;
    lab.textContent = shut
      ? `LVL ${lvl} · ${shut} mission${shut === 1 ? '' : 's'} still classified`
      : `LVL ${lvl} · full clearance`;
    lab.classList.toggle('all-clear', !shut);
  }
}

function refreshHubProgression(){
  if(!user) return;
  const bar = document.getElementById('h-credits');
  if(bar) bar.textContent = `💎 ${(user.credits || 0).toLocaleString()} CR`;

  let chip = document.getElementById('h-streak');
  const n = user.streak.count || 0;
  if(!chip && bar){
    chip = document.createElement('div');
    chip.id = 'h-streak';
    chip.className = 'hub-streak';
    bar.parentNode.insertBefore(chip, bar.nextSibling);
  }
  paintMissionLocks();
  if(typeof loadChallenges === 'function') loadChallenges();
  if(chip){
    chip.style.display = n > 0 ? '' : 'none';
    chip.textContent = `🔥 ${n}`;
    chip.title = `${n}-day streak · best ${user.streak.best || n}`;
  }
  renderBadgeShelf();
  renderCardSparklines();
}

function renderBadgeShelf(){
  const panel = document.getElementById('lb-panel');
  if(!panel || !panel.parentNode) return;
  let shelf = document.getElementById('badge-shelf');
  if(!shelf){
    const label = document.createElement('div');
    label.className = 'sec-label badge-label';
    // The shelf is the WORDED way into the matrix. The hub bar's 🏆 is
    // icon-only — the bar has no room for a label — so this is where the
    // feature is actually named, and clicking either lands in the same place.
    label.innerHTML = '🏅 ACHIEVEMENTS <em class="badge-open">VIEW MATRIX →</em>';
    shelf = document.createElement('div');
    shelf.id = 'badge-shelf';
    label.style.cursor = shelf.style.cursor = 'pointer';
    const open = () => openOverlay('ach-overlay', renderAchievementMatrix);
    label.onclick = open;
    shelf.onclick = open;
    panel.parentNode.appendChild(label);
    panel.parentNode.appendChild(shelf);
  }
  const owned = user.achievements || {};
  const got = ACHIEVEMENTS.filter(a => owned[a.id]).length;
  shelf.innerHTML =
    `<div class="badge-count">${got} / ${ACHIEVEMENTS.length} UNLOCKED</div>` +
    `<div class="badge-grid">` +
    ACHIEVEMENTS.map(a => {
      const has = !!owned[a.id];
      return `<div class="badge${has ? ' has' : ''}" title="${esc(a.name)} — ${esc(a.desc)}${has ? '' : ' (locked)'}">
                <span class="badge-ico">${a.icon}</span>
              </div>`;
    }).join('') +
    `</div>`;
}

// Inline SVG trend line on each mission card — last dozen runs, best marked.
function sparklineSVG(runs, color){
  if(!runs || runs.length < 2) return '';
  const w = 100, h = 22, max = Math.max(...runs, 1), min = Math.min(...runs, 0);
  const span = (max - min) || 1;
  const pts = runs.map((v, i) => {
    const x = (i / (runs.length - 1)) * w;
    const y = h - ((v - min) / span) * (h - 3) - 1.5;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const bestI = runs.indexOf(max);
  const bx = (bestI / (runs.length - 1)) * w;
  const by = h - ((max - min) / span) * (h - 3) - 1.5;
  return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true">
            <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.6"
                      stroke-linejoin="round" stroke-linecap="round" opacity=".85"/>
            <circle cx="${bx.toFixed(1)}" cy="${by.toFixed(1)}" r="2" fill="${color}"/>
          </svg>`;
}

function renderCardSparklines(){
  if(!user) return;
  document.querySelectorAll('.game-card').forEach(card => {
    const gid = card.dataset.game;
    const runs = (user.history && user.history[gid]) || [];
    let box = card.querySelector('.gc-spark');
    if(runs.length < 2){ if(box) box.remove(); return; }
    if(!box){
      box = document.createElement('div');
      box.className = 'gc-spark';
      card.appendChild(box);
    }
    const color = CARD_COLORS[card.dataset.c] || 'var(--cyan)';
    const best = Math.max(...runs);
    box.innerHTML = sparklineSVG(runs, color) +
      `<span class="spark-best">PB ${best.toLocaleString()}</span>`;
  });
}

