function findItem(cat, id){ return (SHOP_ITEMS[cat]||[]).find(i=>i.id===id); }

// ── ⏳ DAILY FEATURED ROTATION ──
// Derived from the UTC day rather than stored anywhere, so every client picks
// the same items with no server state and no scheduled job. The discount is the
// reason to come back and look.
const FEATURE_PER_CAT = 2;
const FEATURE_DISCOUNT = 0.3;

// Small deterministic string hash — same day + same category = same shortlist.
function hashStr(s){
  let h = 2166136261;
  for(let i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

function featuredIds(cat, day = dayKey()){
  // Consumables are excluded. The rotation exists to nudge a player toward a
  // cosmetic they do not own yet — a one-off purchase — and a repeatable one
  // behaves differently under it: the discount stops being a nudge and becomes
  // the correct day to stock up, and the advertised 5 CR / 10 CR stop being
  // what a Time Dilator costs.
  const pool = (SHOP_ITEMS[cat] || []).filter(i => !i.default && !i.earned && !i.consumable);
  if(pool.length <= FEATURE_PER_CAT) return pool.map(i => i.id);
  // Deterministic shuffle: sort by a per-item hash of the day, take the top N.
  return pool
    .map(i => ({ id: i.id, k: hashStr(day + ':' + cat + ':' + i.id) }))
    .sort((a, b) => a.k - b.k)
    .slice(0, FEATURE_PER_CAT)
    .map(x => x.id);
}

const isFeatured = (cat, id) => featuredIds(cat).includes(id);
// The price actually charged — one function so the card and the till agree.
function priceOf(cat, item){
  return isFeatured(cat, item.id)
    ? Math.max(1, Math.round(item.price * (1 - FEATURE_DISCOUNT)))
    : item.price;
}

function msToRotation(){
  const now = new Date();
  const next = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
  return next - now.getTime();
}
function rotationLabel(){
  const ms = msToRotation();
  const h = Math.floor(ms / 3600000), m = Math.floor((ms % 3600000) / 60000);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

// Rarity is computed relative to the other paid items in the same category,
// so the priciest items automatically get the flashiest shop-card treatment.
function getRarity(cat, item){
  // A consumable's price says how strong one use is, not how rare the item is —
  // banding them would print "LEGENDARY" on a 10 CR shield you can buy nine of.
  if(item.consumable) return null;
  if(item.default || item.earned || !item.price) return null;
  // Earned items carry price 0 and would drag `min` down, re-banding every
  // paid item in the category.
  const prices = (SHOP_ITEMS[cat]||[]).filter(i=>!i.default && !i.earned).map(i=>i.price);
  const max = Math.max(...prices), min = Math.min(...prices);
  if(item.price===max) return 'legendary';
  if(item.price >= min + (max-min)*0.5) return 'epic';
  return 'rare';
}

function hexToRgba(hex, alpha){
  const h = hex.replace('#','');
  const full = h.length===3 ? h.split('').map(c=>c+c).join('') : h;
  const n = parseInt(full,16);
  return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${alpha})`;
}

// Rotates a hex colour's hue, keeping its saturation and lightness. Lets a game
// build a multi-colour palette out of the one equipped colour without any of the
// derived shades coming out duller than the colour the player actually bought.
function shiftHue(hex, deg){
  const h = hex.replace('#','');
  const full = h.length===3 ? h.split('').map(c=>c+c).join('') : h;
  const n = parseInt(full,16);
  const r=((n>>16)&255)/255, g=((n>>8)&255)/255, b=(n&255)/255;
  const max=Math.max(r,g,b), min=Math.min(r,g,b), d=max-min;
  const l=(max+min)/2;
  let hue=0, s=0;
  if(d){
    s = d/(1-Math.abs(2*l-1));
    if(max===r)      hue=((g-b)/d)%6;
    else if(max===g) hue=(b-r)/d+2;
    else             hue=(r-g)/d+4;
    hue=(hue*60+360)%360;
  }
  hue=(hue+deg%360+360)%360;
  const c=(1-Math.abs(2*l-1))*s, x=c*(1-Math.abs((hue/60)%2-1)), m=l-c/2;
  const seg = hue<60?[c,x,0] : hue<120?[x,c,0] : hue<180?[0,c,x]
            : hue<240?[0,x,c] : hue<300?[x,0,c] : [c,0,x];
  const hx = v => Math.round((v+m)*255).toString(16).padStart(2,'0');
  return `#${hx(seg[0])}${hx(seg[1])}${hx(seg[2])}`;
}

function getEquippedColorHex(){
  const item = user && findItem('colors', user.equipped && user.equipped.colors);
  return item ? item.color : '#00f5ff';
}
function getEquippedSkinEmoji(){
  const item = user && findItem('skins', user.equipped && user.equipped.skins);
  return item ? item.emoji : null;
}
function drawSkinBadge(x, y, size=13){
  const emoji = getEquippedSkinEmoji();
  if(!emoji) return;
  aCtx.save();
  aCtx.font = `${size}px sans-serif`;
  aCtx.textAlign = 'center';
  aCtx.textBaseline = 'middle';
  aCtx.shadowBlur = 0;
  aCtx.fillText(emoji, x, y);
  aCtx.restore();
}

let customCursorEl = null;
let codeCursorTimer = null;

function ensureCustomCursorEl(){
  if(customCursorEl) return customCursorEl;
  customCursorEl = document.createElement('div');
  customCursorEl.id = 'custom-cursor-fx';
  document.body.appendChild(customCursorEl);
  document.addEventListener('mousemove', e=>{
    customCursorEl.style.left = e.clientX + 'px';
    customCursorEl.style.top = e.clientY + 'px';
  });
  return customCursorEl;
}

function stopCodeCursorAnim(){
  if(codeCursorTimer){ clearInterval(codeCursorTimer); codeCursorTimer = null; }
}

function applyEquippedCosmetics(){
  if(!user) return;
  const colorItem = findItem('colors', user.equipped && user.equipped.colors) || SHOP_ITEMS.colors[0];
  document.documentElement.style.setProperty('--cyan', colorItem.color);

  const cursorItem = findItem('cursors', user.equipped && user.equipped.cursors) || SHOP_ITEMS.cursors[0];
  const cursorRarity = getRarity('cursors', cursorItem);
  let cursorStyleTag = document.getElementById('custom-cursor-style');
  if(!cursorStyleTag){
    cursorStyleTag = document.createElement('style');
    cursorStyleTag.id = 'custom-cursor-style';
    document.head.appendChild(cursorStyleTag);
  }

  stopCodeCursorAnim();
  const fx = ensureCustomCursorEl();

  if(cursorItem.default){
    cursorStyleTag.textContent = '';
    document.body.style.cursor = '';
    fx.style.display = 'none';
    fx.className = '';
  } else if(cursorRarity==='epic' || cursorRarity==='legendary'){
    // Epic/legendary cursors swap the real OS pointer for an animated element that tracks the mouse.
    cursorStyleTag.textContent = `*{cursor:none !important;}`;
    document.body.style.cursor = 'none';
    fx.style.display = 'block';
    if(cursorRarity==='legendary'){
      fx.className = 'ccur ccur-legendary';
      const chars = '01';
      const randomCode = () => Array.from({length:6}, () => chars[Math.floor(Math.random()*chars.length)]).join('');
      fx.innerHTML = `<span class="ccur-code">${randomCode()}</span>`;
      const codeEl = fx.querySelector('.ccur-code');
      codeCursorTimer = setInterval(() => { codeEl.textContent = randomCode(); }, 130);
    } else {
      fx.className = 'ccur ccur-epic';
      fx.innerHTML = `<span class="ccur-inner">${cursorItem.emoji}</span>`;
    }
  } else {
    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32'><text x='0' y='24' font-size='26'>${cursorItem.emoji}</text></svg>`;
    const cursorCss = `url("data:image/svg+xml,${encodeURIComponent(svg)}") 4 4, auto`;
    // !important beats element-level cursor:pointer rules on buttons, cards, canvas, etc.
    cursorStyleTag.textContent = `*{cursor:${cursorCss} !important;}`;
    document.body.style.cursor = cursorCss;
    fx.style.display = 'none';
    fx.className = '';
  }

  // The soundtrack is a cosmetic like any other, so it is re-applied on the same
  // pass that repaints the colour and the pointer.
  applyMusicDrive();
}

function openMarket(){
  showScreen('market-screen');
  refreshMarketBalances();
  ['powerups','colors','cursors','skins','drives','exits'].forEach(renderShop);
  paintPowerKit();
  switchMarketTab('convert');
  startRotationTicker();
}

// Countdown under the market tabs. Ticks only while the market is open — the
// interval is cleared the moment the player leaves.
let _rotTicker = null;
function startRotationTicker(){
  const tabs = document.querySelector('.market-tabs');
  if(!tabs) return;
  let el = document.getElementById('shop-rotation');
  if(!el){
    el = document.createElement('div');
    el.id = 'shop-rotation';
    tabs.parentNode.insertBefore(el, tabs.nextSibling);
  }
  const paint = () => {
    if(!document.getElementById('market-screen').classList.contains('active')){
      clearInterval(_rotTicker); _rotTicker = null; return;
    }
    el.innerHTML = `⏳ FEATURED STOCK ROTATES IN <em>${rotationLabel()}</em>`;
  };
  paint();
  clearInterval(_rotTicker);
  _rotTicker = setInterval(paint, 30000);
}

function refreshMarketBalances(){
  const ptsTxt = `🏆 ${(user?.totalPoints||0).toLocaleString()} PTS`;
  const crTxt = `💎 ${(user?.credits||0).toLocaleString()} CR`;
  document.getElementById('m-pts').textContent = ptsTxt;
  document.getElementById('m-credits').textContent = crTxt;
  document.getElementById('h-pts').textContent = ptsTxt;
  document.getElementById('h-credits').textContent = crTxt;
  // 💱 The headline rate is a fact about YOUR profile now that Data Broker can
  // change it, so it is painted rather than written into the markup.
  const rateEl = document.getElementById('conv-rate-buy');
  if(rateEl){
    const r = buyRate();
    rateEl.textContent = `${r} PTS = 1 CR`;
    rateEl.classList.toggle('perked', r !== CONV_RATE);
    rateEl.title = r !== CONV_RATE ? '🌳 Data Broker — discounted from 100' : '';
  }
}

document.querySelectorAll('.market-tab').forEach(tab=>{
  tab.addEventListener('click',()=>switchMarketTab(tab.dataset.tab));
});
function switchMarketTab(tab){
  document.querySelectorAll('.market-tab').forEach(t=>t.classList.toggle('active', t.dataset.tab===tab));
  document.querySelectorAll('.market-panel').forEach(p=>p.classList.toggle('active', p.id==='panel-'+tab));
}

// ── CONVERSION LOGIC ──
const convPtsInput = document.getElementById('conv-pts-input');
const convCreditsInput = document.getElementById('conv-credits-input');

convPtsInput.addEventListener('input',()=>{
  const v = Math.max(0, parseInt(convPtsInput.value)||0);
  document.getElementById('conv-pts-preview').textContent = `= ${Math.floor(v/buyRate())} CR`;
});
convCreditsInput.addEventListener('input',()=>{
  const v = Math.max(0, parseInt(convCreditsInput.value)||0);
  document.getElementById('conv-credits-preview').textContent = `= ${v*CONV_RATE} PTS`;
});

document.getElementById('btn-conv-to-credits').onclick = async ()=>{
  if(!user || !db){ toast('⚠️ Connection state unconfigured'); return }
  const v = Math.max(0, parseInt(convPtsInput.value)||0);
  const credits = Math.floor(v/buyRate());
  if(credits<=0){ snd('deny'); toast(`⚠️ Enter at least ${buyRate()} points.`); return }
  if(v>(user.totalPoints||0)){ snd('deny'); toast('⚠️ Insufficient points.'); return }
  const spentPts = credits*buyRate();
  user.totalPoints -= spentPts;
  user.credits = (user.credits||0) + credits;
  await db.ref('players/'+user.uid).update({ totalPoints:user.totalPoints, credits:user.credits });
  convPtsInput.value=''; document.getElementById('conv-pts-preview').textContent='= 0 CR';
  refreshMarketBalances(); loadLeaderboard();
  snd('convert');
  toast(`✅ Converted ${spentPts} PTS → ${credits} CR`);
};

document.getElementById('btn-conv-to-points').onclick = async ()=>{
  if(!user || !db){ toast('⚠️ Connection state unconfigured'); return }
  const v = Math.max(0, parseInt(convCreditsInput.value)||0);
  if(v<=0){ snd('deny'); toast('⚠️ Enter at least 1 credit.'); return }
  if(v>(user.credits||0)){ snd('deny'); toast('⚠️ Insufficient credits.'); return }
  const gainedPts = v*CONV_RATE;
  user.credits -= v;
  user.totalPoints = (user.totalPoints||0) + gainedPts;
  // Any write that raises totalPoints has to carry the server stamp, or the
  // rate-limit rule in database.rules.json rejects it — this is a points
  // increase just as much as a finished round is.
  await db.ref('players/'+user.uid).update({
    totalPoints:user.totalPoints,
    credits:user.credits,
    lastScoreAt: firebase.database.ServerValue.TIMESTAMP
  });
  convCreditsInput.value=''; document.getElementById('conv-credits-preview').textContent='= 0 PTS';
  refreshMarketBalances(); loadLeaderboard();
  snd('convert');
  toast(`✅ Converted ${v} CR → ${gainedPts} PTS`);
};

// ── SHOP RENDERING ──
function renderShop(cat){
  const grid = document.getElementById('shop-'+cat);
  if(!grid) return;
  grid.innerHTML = '';
  SHOP_ITEMS[cat].forEach(item=>{
    const owned = item.default || (user?.owned?.[cat]||[]).includes(item.id);
    const equipped = user?.equipped?.[cat]===item.id;
    const rarity = getRarity(cat, item);
    const card = document.createElement('div');
    card.className = 'shop-card' + (rarity ? ` rarity-${rarity}` : '') + (equipped ? ' equipped' : '');
    const preview = cat==='colors'
      ? (item.id==='col-matrix'
          ? `<div class="shop-swatch matrix-swatch"></div>`
          : `<div class="shop-swatch" style="background:${item.color};box-shadow:0 0 20px ${item.color}"></div>`)
      : `<div class="shop-emoji">${item.emoji}</div>`;
    const badge = rarity ? `<div class="rarity-badge ${rarity}">${rarity}</div>` : '';
    const p = priceOf(cat, item);
    const cut = p < item.price ? `<s class="shop-was">💎${item.price}</s> ` : '';
    let btnHtml;
    if(item.consumable){
      // Consumables are never "owned" or "equipped" — they are stocked. The card
      // keeps offering the buy until the stack is full, and says how many are in
      // the kit right now.
      const held = powerHeld(item.id);
      card.classList.add('consumable');
      btnHtml = held >= (item.stack || 9)
        ? `<button class="btn btn-secondary btn-sm shop-btn" disabled>KIT FULL · ${held}</button>`
        : `<button class="btn btn-primary btn-sm shop-btn" data-act="buy" data-cat="${cat}" data-id="${item.id}">Buy · ${cut}💎${p}</button>`;
    } else if(equipped){
      btnHtml = `<button class="btn btn-secondary btn-sm shop-btn" data-act="unequip" data-cat="${cat}" data-id="${item.id}">Unequip</button>`;
    } else if(owned){
      btnHtml = `<button class="btn btn-primary btn-sm shop-btn" data-act="equip" data-cat="${cat}" data-id="${item.id}">Equip</button>`;
    } else if(item.earned){
      // No price — the only way in is the achievement that grants it.
      btnHtml = `<button class="btn btn-secondary btn-sm shop-btn" disabled>🔒 Earned Only</button>`;
    } else {
      btnHtml = `<button class="btn btn-primary btn-sm shop-btn" data-act="buy" data-cat="${cat}" data-id="${item.id}">Buy · ${cut}💎${p}</button>`;
    }
    const feat = (!owned && !item.earned && isFeatured(cat, item.id))
      ? `<div class="shop-feat">⏳ ${Math.round(FEATURE_DISCOUNT*100)}% OFF</div>` : '';
    if(feat) card.classList.add('featured');
    // A drive, an exit state and a consumable all need a sentence to be worth
    // anything — a colour swatch explains itself, "Darksynth Terminal" does not.
    const desc = item.desc ? `<div class="shop-desc">${esc(item.desc)}</div>` : '';
    const held = item.consumable ? `<div class="shop-held">IN KIT · <em>${powerHeld(item.id)}</em></div>` : '';
    card.innerHTML = `${preview}${badge}${feat}<div class="shop-name">${esc(item.name)}</div>${desc}${held}` +
                     `${equipped?'<div class="shop-tag">EQUIPPED</div>':''}${btnHtml}`;
    // A drive is only judgeable by ear, so equipping one auditions it: the hub
    // loop restarts on the new voicing the moment the button lands.
    grid.appendChild(card);
  });
  grid.querySelectorAll('.shop-btn').forEach(btn=>{
    btn.onclick = () => handleShopAction(btn.dataset.act, btn.dataset.cat, btn.dataset.id);
  });
}

async function handleShopAction(act, cat, id){
  // A guest with no link still has a wallet — it is mirrored in localStorage
  // like everything else — so the market stays open and the write is banked
  // through saveProfilePatch() instead of being refused outright.
  if(!user){ toast('⚠️ Connection state unconfigured'); return }
  const item = findItem(cat, id);
  if(!item) return;

  if(act==='buy'){
    if(item.earned){ snd('deny'); toast('🔒 That one has to be earned.'); return }
    const price = priceOf(cat, item);
    if((user.credits||0) < price){ snd('deny'); toast('⚠️ Insufficient credits.'); return }

    if(item.consumable){
      const held = powerHeld(id);
      if(held >= stackCapFor(item)){ snd('deny'); toast('⚠️ Kit is full.'); return }
      user.credits -= price;
      user.powerups[id] = held + 1;
      await saveProfilePatch({ credits:user.credits, ['powerups/'+id]: user.powerups[id] });
      snd('purchase');
      toast(`✅ ${item.emoji} ${item.name} stocked — ${user.powerups[id]} in kit`);
      paintPowerKit();
      paintPowerDock();
    } else {
      user.credits -= price;
      user.owned[cat] = [...(user.owned[cat]||[]), id];
      await saveProfilePatch({ credits:user.credits, ['owned/'+cat]: user.owned[cat] });
      snd('purchase');
      toast(price < item.price
        ? `✅ Purchased ${item.name} — saved 💎${item.price - price}`
        : `✅ Purchased ${item.name}`);
    }
  } else if(act==='equip'){
    user.equipped[cat] = id;
    await saveProfilePatch({ ['equipped/'+cat]: id });
    snd('equip');
    toast(`⚡ Equipped ${item.name}`);
    applyEquippedCosmetics();
  } else if(act==='unequip'){
    const defItem = SHOP_ITEMS[cat].find(i=>i.default);
    user.equipped[cat] = defItem.id;
    await saveProfilePatch({ ['equipped/'+cat]: defItem.id });
    snd('uiBack');
    toast(`Unequipped ${item.name}`);
    applyEquippedCosmetics();
  }
  refreshMarketBalances();
  renderShop(cat);
}

// ════════════════════════════════════════════
//  🖱️ GAME 1: CLICK FRENZY
// ════════════════════════════════════════════
function startClick(){
  document.getElementById('g-click').style.display='flex';
  let clicks=0,t=10,ended=false;
  document.getElementById('click-count').textContent='0';
  document.getElementById('g-time').textContent='10';
  const btn=document.getElementById('click-btn');
  btn.disabled=false;
  // The blip climbs an octave over eight clicks and wraps, so a fast streak
  // sounds like it's accelerating even though the button is doing one thing.
  btn.onclick=()=>{if(!ended){clicks++;snd('bounce',{semi:(clicks%8)*2});document.getElementById('click-count').textContent=clicks;setLive(Math.min(500,clicks*8))}};
  gTimer=setInterval(()=>{
    t--;document.getElementById('g-time').textContent=t;
    document.getElementById('prog-fill').style.width=`${t/10*100}%`;
    if(t<=3&&t>0) snd('tick');
    if(t<=0){
      clearInterval(gTimer);ended=true;btn.disabled=true;btn.onclick=null;
      const pts=Math.min(500,clicks*8);
      // ⚡ OVERCLOCKED wants the ceiling itself, not "close to it": 500 is the
      // cap and 63 clicks is what reaches it, so the flag is the clamp firing.
      const maxed=pts>=500;
      setTimeout(()=>showResults('click',pts,{
        '🖱️ Structural Actions':clicks,
        ...(maxed?{'⚡ Threshold':'MAXIMUM SCORE REACHED'}:{}),
        '🏆 Final Score':`${pts} PTS`
      },{ maxed }),400);
    }
  },1000);
}

// ════════════════════════════════════════════
//  🚀 GAME 2: NEON NEBULA (OVERDRIVE ENGINE)
// ════════════════════════════════════════════
function startNebula(){
  document.getElementById('g-canvas-holder').style.display='block';
  // Drag-to-fly is the good way to play, but the D-pad stays put so the game
  // is never dead if a browser refuses the gesture.
  setControls({ left:'◀', action: isTouchDevice ? '⚡ FIRE / ABILITY' : 'SHOOT / ABILITY', right:'▶' });
  setControlHint('HOLD TO FIRE · DRAG TO FLY · OR USE ◀ ▶',
                 '← → / A D = MOVE · SPACE = FIRE · Q/E = ABILITY');
  showTouchHint('HOLD ANYWHERE TO FIRE · DRAG TO FLY');
  fitCanvas();
  const diffMod = getDifficultyModifier();
  let score = 0, gameTime = 60, shield = 100, screenShake = 0;
  // plasmaOrbs: total orbs collected (levels 1-3 = weapon, 4+ = special abilities)
  let plasmaOrbs = 0;
  // Special ability charges earned beyond level 3
  let specialAbilities = []; // queue of ability types earned
  let activeAbility = null;  // currently deployed ability with timer/state
  // Enemy attack arrays
  let projectiles = [], enemyProjectiles = [], enemies = [], powerups = [], particles = [], floatingTexts = [], backgroundStars = [];
  let enemySpawnTimer = 0, enemySpawnInterval = 1000, lastTime = performance.now();
  let shieldFlashTimer = 0; // red flash when hit
  // 🛡️ The absorb path. Nebula's death is a DEPLETED BAR rather than a single
  // fatal hit, so putting the player back at 1% would be a shield that bought
  // one more projectile — this restores the bar and grants the same three second
  // bubble a repair pickup does, which is what makes the save survivable.
  function survivedNebulaHit(){
    if(!survivedFatal()) return false;
    shield = 60;
    shieldBubbleActive = true;
    shieldBubbleTimer = 180;
    document.getElementById('prog-fill').style.width = `${shield}%`;
    return true;
  }
  let timeWarpActive = false, timeWarpTimer = 0;
  let shieldBubbleActive = false, shieldBubbleTimer = 0;

  document.getElementById('g-time').textContent = gameTime;
  document.getElementById('prog-fill').style.width = '100%';
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg, #ff0844, #ff4e50)';

  for (let i = 0; i < 30; i++) backgroundStars.push({ x: Math.random() * BOARD_W, y: Math.random() * BOARD_H, size: 1, speed: 0.5, alpha: 0.4 });
  for (let i = 0; i < 15; i++) backgroundStars.push({ x: Math.random() * BOARD_W, y: Math.random() * BOARD_H, size: 1.6, speed: 1.4, alpha: 0.8 });

  let keys = {}, moveLeft = false, moveRight = false;
  // ── TOUCH FLIGHT STATE ──
  // touchFiring: a finger is down anywhere on the board → hold-to-fire.
  // touchFlying: that finger has taken over steering, so update() stops
  //   integrating velocity and lets the drag drive position directly.
  // grabDX/grabDY: the ship-to-finger offset captured on touch-down, so
  //   grabbing the board never teleports the ship under your thumb.
  let touchFiring = false, touchFlying = false, grabDX = 0, grabDY = 0;
  const FLY_Y_MIN = 300, FLY_Y_MAX = 466;   // ship stays in the lower band

  window.onkeydown = e => {
    if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyA','KeyD','KeyW','KeyS','KeyQ'].includes(e.code)) e.preventDefault();
    keys[e.code] = true;
    // Q or E to deploy special ability
    if ((e.code === 'KeyQ' || e.code === 'KeyE') && specialAbilities.length > 0 && !activeAbility) deployAbility();

    // Show ability hint briefly when abilities are available
    if (specialAbilities.length > 0 && !activeAbility && (e.code === 'KeyQ' || e.code === 'KeyE')) {
      // Flash the action button to indicate it's usable
      const actionBtn = document.getElementById('ctrl-action');
      actionBtn.style.transform = 'scale(1.2)';
      setTimeout(() => actionBtn.style.transform = '', 200);

      // Show toast with ability hint
      const nextAbility = specialAbilities[0];
      toast(`Press [ACTION] or [Q]/[E] to use ${nextAbility.label}`, 1500);
    }
  };
  window.onkeyup = e => { if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyA','KeyD','KeyW','KeyS'].includes(e.code)) e.preventDefault(); keys[e.code] = false; };

  // Pressing a direction also drops any stale drag claim, so a gesture the
  // browser cut off mid-flight can't leave the buttons inert.
  // The impulse gives a tap a visible shove; holding still accelerates as before.
  const KICK = 4;
  bindHold(document.getElementById('ctrl-left'),
           ()=>{ touchFlying=false; touchFiring=false; player.vx -= KICK; moveLeft=true; },  ()=>moveLeft=false);
  bindHold(document.getElementById('ctrl-right'),
           ()=>{ touchFlying=false; touchFiring=false; player.vx += KICK; moveRight=true; }, ()=>moveRight=false);
  // ACTION button: shoot if no special ready, else deploy special
  document.getElementById('ctrl-action').onclick = () => {
    if (specialAbilities.length > 0 && !activeAbility) deployAbility();
    else player.shoot();
  };

  // ── HOLD TO FIRE · DRAG TO FLY ──
  // One gesture does both: putting a finger on the board opens fire and
  // grabs the ship, moving it steers, lifting it stops. Firing is driven by
  // the `touchFiring` flag inside player.update() so it respects the same
  // weapon cooldown as holding Space — no tap-spam advantage.
  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      touchFiring = true; touchFlying = true;
      grabDX = (player.x + player.w / 2) - p.x;
      grabDY = (player.y + player.h / 2) - p.y;
    },
    onMove(p){
      const prevX = player.x;
      player.x = p.x + grabDX - player.w / 2;
      player.y = p.y + grabDY - player.h / 2;
      player.x = Math.max(5, Math.min(BOARD_W - player.w - 5, player.x));
      player.y = Math.max(FLY_Y_MIN, Math.min(FLY_Y_MAX, player.y));
      player.vx = (player.x - prevX) * 0.55;   // feeds the hull's banking tilt
    },
    onUp(){ touchFiring = false; touchFlying = false; }
  });

  // ── SPECIAL ABILITY DEFINITIONS (unlocked at plasma orb 4, 5, 6, 7+) ──
  const ABILITY_DEFS = [
    { id:'SMART_MISSILE', label:'🎯 SMART MISSILE', color:'#00f5ff', desc:'MISSILES LOCK ON!' },
    { id:'SHIELD_BURST',  label:'🛡️ SHIELD BURST',  color:'#a855f7', desc:'SHIELD RESTORED!' },
    { id:'TIME_WARP',     label:'⏳ TIME WARP',     color:'#ffd700', desc:'TIME SLOWED!' },
    { id:'NOVA_BOMB',     label:'💥 NOVA BOMB',     color:'#ff0090', desc:'SCREEN NUKE!' },
  ];
  // Cycle through abilities for each extra orb
  function getAbilityForOrb(orbIndex) {
    // orbIndex = (plasmaOrbs - 3), 1-based → pick from cycle
    return ABILITY_DEFS[(orbIndex - 1) % ABILITY_DEFS.length];
  }

  function deployAbility() {
    if (specialAbilities.length === 0) return;
    const abil = specialAbilities.shift();
    updateAbilityHUD();
    activeAbility = abil;

    snd('ability');

    if (abil.id === 'SMART_MISSILE') {
      // Fire 3 homing missiles that launch FROM the ship nose and track nearest enemies
      popText(BOARD_W / 2, player.y - 24, '🎯 SMART MISSILES!', '#00f5ff');
      screenShake = 6;
      const shipNoseX = player.x + player.w/2;
      const shipNoseY = player.y;
      // Stagger missile launches for visual effect
      [0, 1, 2].forEach(i => {
        setTimeout(() => {
          if (!enemies.length) return;
          // Find target (different enemy for each missile if possible)
          const sortedEnemies = [...enemies].sort((a,b)=>Math.hypot(a.x-shipNoseX,a.y-shipNoseY)-Math.hypot(b.x-shipNoseX,b.y-shipNoseY));
          const target = sortedEnemies[i % sortedEnemies.length];
          projectiles.push({
            x: shipNoseX + (i-1)*6,
            y: shipNoseY,
            vx: (i-1)*1.5,
            vy: -9,
            smart: true,
            lockedTarget: target, // lock to a specific enemy
            smartTimer: 0
          });
          // launch flash
          explode(shipNoseX, shipNoseY, '#00f5ff', 5);
          snd('missile');
        }, i * 120);
      });
      setTimeout(() => { activeAbility = null; }, 2500);

    } else if (abil.id === 'SHIELD_BURST') {
      // Restore shield to 100% — pure healing, no damage component
      snd('shield');
      shield = 100;
      document.getElementById('prog-fill').style.width = '100%';
      shieldBubbleActive = true;
      shieldBubbleTimer = 180; // 3 seconds of invincibility bubble
      enemyProjectiles = []; // clear all incoming fire
      screenShake = 12;
      // Big purple burst from the ship
      for (let i = 0; i < 40; i++) {
        const ang = (i/40)*Math.PI*2, v = Math.random()*5+2;
        particles.push({ x: player.x+player.w/2, y: player.y+player.h/2, vx: Math.cos(ang)*v, vy: Math.sin(ang)*v, alpha: 1, decay: 0.025, color: '#a855f7', size: Math.random()*3+1 });
      }
      popText(BOARD_W / 2, player.y - 24, '🛡️ SHIELD RESTORED!', '#a855f7');
      setTimeout(() => {
        shieldBubbleActive = false;
        activeAbility = null;
      }, 3000);

    } else if (abil.id === 'TIME_WARP') {
      // Slow all enemies and their projectiles to 50% speed for 3 seconds
      timeWarpActive = true;
      timeWarpTimer = 180; // 3 seconds at 60fps
      screenShake = 8;
      popText(BOARD_W / 2, 200, '⏳ TIME WARP!', '#ffd700');
      // Radial particle ring
      for (let i = 0; i < 36; i++) {
        const ang = (i/36)*Math.PI*2;
        particles.push({
          x: BOARD_W / 2 + Math.cos(ang)*120, y: 250 + Math.sin(ang)*100,
          vx: -Math.cos(ang)*0.8, vy: -Math.sin(ang)*0.8,
          alpha: 0.9, decay: 0.008, color: '#ffd700', size: 2.5
        });
      }
      // Auto-end when timer reaches 0 (handled in render loop)

    } else if (abil.id === 'NOVA_BOMB') {
      // Destroy ALL enemies on screen with massive expanding shockwave
      snd('bigExplode');
      screenShake = 30;
      popText(BOARD_W / 2, 200, '💥 NOVA BOMB!', '#ff0090');
      // Award points for all enemies destroyed
      const enemyCount = enemies.length;
      enemies.forEach(e => {
        score += e.pts;
        popText(e.x + e.w/2, e.y, `+${e.pts}`, e.color);
        explode(e.x + e.w/2, e.y + e.h/2, e.color, 20);
      });
      setLive(score);
      enemies = [];
      enemyProjectiles = [];
      // Expanding shockwave rings
      for (let ring = 0; ring < 3; ring++) {
        setTimeout(() => {
          for (let i = 0; i < 60; i++) {
            const ang = (i/60)*Math.PI*2, v = (Math.random()*3+2)*(ring+1)*0.6;
            particles.push({
              x: BOARD_W / 2, y: 250,
              vx: Math.cos(ang)*v, vy: Math.sin(ang)*v,
              alpha: 1, decay: 0.018,
              color: ['#ff0090','#ff6600','#ffd700','#fff','#a855f7'][i%5],
              size: Math.random()*3+1.5
            });
          }
        }, ring * 200);
      }
      setTimeout(() => { activeAbility = null; }, 2000);
    }
  }

  function updateAbilityHUD() {
    // Called after consuming an ability from the queue — no extra DOM needed,
    // the canvas draw handles it. This is a no-op placeholder kept for call-site clarity.
  }

  // ── ABILITY HUD OVERLAY (bottom of canvas) ──
  let abilPulse = 0;
  function drawAbilityHUD() {
    abilPulse += 0.08;
    if (specialAbilities.length === 0 && !activeAbility) return;
    aCtx.save();

    if (specialAbilities.length > 0 && !activeAbility) {
      const next = specialAbilities[0];
      const pulse = Math.sin(abilPulse) * 0.4 + 0.7;
      aCtx.fillStyle = 'rgba(0,0,0,0.7)';
      aCtx.strokeStyle = next.color;
      aCtx.lineWidth = 2;
      aCtx.shadowBlur = 12 * pulse; aCtx.shadowColor = next.color;
      aCtx.beginPath(); aCtx.roundRect(6, 448, BOARD_W - 12, 46, 8); aCtx.fill(); aCtx.stroke();
      aCtx.shadowBlur = 8 * pulse; aCtx.shadowColor = next.color;
      aCtx.fillStyle = next.color;
      // A phone has no Q/E key, and 8.5px Orbitron on a board scaled to ~0.6×
      // renders around 5px — unreadable. Say what the player can actually press.
      aCtx.font = 'bold 10px Orbitron';
      aCtx.fillText(isTouchDevice ? 'TAP  ⚡ FIRE / ABILITY  TO DEPLOY:'
                                  : 'PRESS [ACTION] BUTTON  OR  [Q]/[E] KEY TO DEPLOY:', 14, 462);
      aCtx.fillStyle = '#fff';
      aCtx.font = 'bold 12px Orbitron';
      aCtx.shadowBlur = 10; aCtx.shadowColor = next.color;
      aCtx.fillText(next.label, 14, 487);
      if (specialAbilities.length > 1) {
        aCtx.fillStyle = 'rgba(255,255,255,0.55)';
        aCtx.font = 'bold 9px Orbitron';
        aCtx.fillText('(+' + (specialAbilities.length - 1) + ' more queued)', BOARD_W / 2, 487);
      }
    } else if (activeAbility) {
      aCtx.fillStyle = 'rgba(0,0,0,0.65)';
      aCtx.strokeStyle = activeAbility.color;
      aCtx.lineWidth = 1.5;
      aCtx.beginPath(); aCtx.roundRect(6, 448, BOARD_W - 12, 46, 8); aCtx.fill(); aCtx.stroke();
      aCtx.fillStyle = activeAbility.color;
      aCtx.font = 'bold 10px Orbitron';
      aCtx.shadowBlur = 12; aCtx.shadowColor = activeAbility.color;
      aCtx.textAlign = 'center';
      aCtx.fillText('ACTIVE: ' + activeAbility.desc, BOARD_W / 2, 475);
      aCtx.textAlign = 'left';
    }

    aCtx.restore();
  }

  // ── PLASMA ORB LEVEL DISPLAY ──
  function drawPlasmaLevel() {
    const wl = Math.min(3, plasmaOrbs + 1); // visual weapon tier 1-3
    const extra = Math.max(0, plasmaOrbs - 2); // extra orbs beyond max weapon
    aCtx.save();
    aCtx.fillStyle = 'rgba(0,0,0,0.5)'; aCtx.strokeStyle = '#39ff14'; aCtx.lineWidth = 1;
    aCtx.beginPath(); aCtx.roundRect(8, 10, 110, 24, 5); aCtx.fill(); aCtx.stroke();
    aCtx.fillStyle = '#39ff14'; aCtx.font = 'bold 8px Orbitron'; aCtx.shadowBlur = 6; aCtx.shadowColor = '#39ff14';
    const label = plasmaOrbs < 3 ? `PLASMA LV${wl}` : `PLASMA MAX +${extra}`;
    aCtx.fillText(label, 14, 25);
    // Pip bars
    for (let i = 0; i < Math.min(5, plasmaOrbs + 1); i++) {
      aCtx.fillStyle = i < 3 ? '#39ff14' : ['#00f5ff','#ffd700','#ff0090','#a855f7'][i-3];
      aCtx.shadowColor = aCtx.fillStyle; aCtx.shadowBlur = 8;
      aCtx.fillRect(82 + i * 7, 14, 5, 14);
    }
    aCtx.restore();
  }

  const player = {
    x: (BOARD_W - 34) / 2, y: 430, w: 34, h: 26, vx: 0, vy: 0, friction: 0.85, accel: 1.2, cooldown: 0, angle: 0,
    get weaponLevel() { return Math.min(3, plasmaOrbs + 1); },
    update(dt) {
      if (touchFlying) {
        // The finger owns position this frame — only decay the velocity so
        // the hull keeps banking into the turn it was just thrown through.
        this.vx *= this.friction; this.vy = 0;
        this.angle = this.vx * 0.05;
      } else {
        if (keys['ArrowLeft']  || keys['KeyA'] || moveLeft)  this.vx -= this.accel;
        if (keys['ArrowRight'] || keys['KeyD'] || moveRight) this.vx += this.accel;
        // Vertical thrust keeps keyboard play in step with what a drag can do.
        if (keys['ArrowUp']    || keys['KeyW']) this.vy -= this.accel;
        if (keys['ArrowDown']  || keys['KeyS']) this.vy += this.accel;
        this.vx *= this.friction; this.vy *= this.friction;
        this.x += this.vx; this.y += this.vy;
        this.angle = this.vx * 0.05;
      }
      if (this.x < 5) { this.x = 5; this.vx = 0; }
      if (this.x > BOARD_W - this.w - 5) { this.x = BOARD_W - this.w - 5; this.vx = 0; }
      if (this.y < FLY_Y_MIN) { this.y = FLY_Y_MIN; this.vy = 0; }
      if (this.y > FLY_Y_MAX) { this.y = FLY_Y_MAX; this.vy = 0; }
      if (this.cooldown > 0) this.cooldown -= dt;
      // Holding a finger on the board fires on the same cooldown as Space,
      // so touch gets no tap-spam edge over keyboard.
      if ((keys['Space'] || touchFiring) && this.cooldown <= 0) { this.shoot(); this.cooldown = 150; }
    },
    shoot() {
      const wl = this.weaponLevel;
      // The gun drops a semitone per weapon level and switches to the fatter
      // plasma sample once the spread bolts unlock — the upgrade is audible
      // before you've had time to notice the extra bullets on screen.
      snd(plasmaOrbs >= 3 ? 'plasma' : 'shoot', { semi: -(wl - 1) * 2 });
      if (wl === 1) {
        projectiles.push({ x: this.x + this.w/2, y: this.y, vx: 0, vy: -10 });
      } else if (wl === 2) {
        projectiles.push({ x: this.x + 6, y: this.y + 5, vx: -1.5, vy: -10 });
        projectiles.push({ x: this.x + this.w - 6, y: this.y + 5, vx: 1.5, vy: -10 });
      } else {
        projectiles.push({ x: this.x + 5, y: this.y + 5, vx: -2, vy: -10 });
        projectiles.push({ x: this.x + this.w/2, y: this.y, vx: 0, vy: -12 });
        projectiles.push({ x: this.x + this.w - 5, y: this.y + 5, vx: 2, vy: -10 });
        // Extra orbs beyond lv3: add spread plasma bolts
        if (plasmaOrbs >= 3) {
          projectiles.push({ x: this.x + this.w/2, y: this.y + 5, vx: -3.5, vy: -8, plasma: true });
          projectiles.push({ x: this.x + this.w/2, y: this.y + 5, vx: 3.5, vy: -8, plasma: true });
        }
        if (plasmaOrbs >= 5) {
          projectiles.push({ x: this.x + this.w/2, y: this.y + 8, vx: -5, vy: -6, plasma: true });
          projectiles.push({ x: this.x + this.w/2, y: this.y + 8, vx: 5, vy: -6, plasma: true });
        }
      }
    },
    draw() {
      aCtx.save(); aCtx.translate(this.x + this.w/2, this.y + this.h/2); aCtx.rotate(this.angle);
      // Shield bubble visual
      if (shieldBubbleActive) {
        aCtx.strokeStyle = `rgba(168,85,247,${0.4 + Math.sin(shieldBubbleTimer*0.3)*0.3})`;
        aCtx.lineWidth = 3; aCtx.shadowBlur = 20; aCtx.shadowColor = '#a855f7';
        aCtx.beginPath(); aCtx.arc(0, 0, 30, 0, Math.PI*2); aCtx.stroke();
      }
      const glowColor = plasmaOrbs >= 3 ? '#a855f7' : getEquippedColorHex();
      aCtx.shadowBlur = plasmaOrbs >= 3 ? 25 : 15; aCtx.shadowColor = glowColor; aCtx.fillStyle = glowColor;
      aCtx.beginPath(); aCtx.moveTo(0, -this.h/2); aCtx.lineTo(-this.w/2, this.h/2); aCtx.lineTo(-this.w/4, this.h/4);
      aCtx.lineTo(this.w/4, this.h/4); aCtx.lineTo(this.w/2, this.h/2); aCtx.closePath(); aCtx.fill();
      aCtx.shadowBlur = 5; aCtx.shadowColor = '#fff'; aCtx.fillStyle = '#fff';
      aCtx.beginPath(); aCtx.moveTo(0, -this.h/3); aCtx.lineTo(-3, 3); aCtx.lineTo(3, 3); aCtx.closePath(); aCtx.fill();
      aCtx.fillStyle = Math.random() > 0.5 ? '#ff0844' : '#ff6600'; aCtx.fillRect(-3, this.h/2 - 2, 6, Math.random()*6+3);
      aCtx.restore();
      drawSkinBadge(this.x + this.w/2, this.y - 10);
    }
  };

  // ── ENEMY CLASS (with attack behaviours) ──
  class Enemy {
    constructor(type) {
      this.type = type; this.x = Math.random() * (BOARD_W - 60) + 10; this.y = -30; this.offset = Math.random() * 100;
      this.attackTimer = 0;
      if (type === 'SCOUT') {
        // PINK — dives straight down fast, accelerates over time
        this.w = 20; this.h = 20; this.speed = 3.5; this.hp = 1; this.color = '#ff0090'; this.pts = 15;
        this.dive = false; this.diveSpeed = 0;
      } else if (type === 'BOMBER') {
        // ORANGE — moves slowly, drops bombs periodically
        this.w = 36; this.h = 28; this.speed = 1.2; this.hp = 3; this.color = '#ff6600'; this.pts = 40;
        this.attackCooldown = 120; // frames between bombs (2s at 60fps)
      } else {
        // PURPLE FIGHTER — weaves, shoots lasers at player
        this.w = 26; this.h = 22; this.speed = 2.2; this.hp = 2; this.color = '#a855f7'; this.pts = 25;
        this.attackCooldown = 90; // frames between laser shots
        this.laserFlash = 0;
      }
    }

    update(frame) {
      const warpMult = timeWarpActive ? 0.5 : 1.0;

      if (this.type === 'SCOUT') {
        // Pink scout: dive behaviour — after entering screen, occasionally
        // locks onto player X and dives diagonally
        if (!this.dive && this.y > 50 && Math.random() < 0.004) {
          this.dive = true; this.diveSpeed = 6 + Math.random() * 3;
          this.diveVx = (player.x - this.x) * 0.04;
        }
        if (this.dive) {
          this.y += this.diveSpeed * warpMult;
          this.x += this.diveVx * warpMult;
          this.diveSpeed = Math.min(12, this.diveSpeed + 0.12); // accelerate
        } else {
          this.y += this.speed * warpMult;
        }

      } else if (this.type === 'BOMBER') {
        this.y += this.speed * warpMult;
        this.attackTimer++;
        if (this.attackTimer >= this.attackCooldown / warpMult) {
          this.attackTimer = 0;
          snd('enemyShot', { semi: -5 });
          // Drop a bomb straight down from the enemy center
          enemyProjectiles.push({
            type: 'BOMB', x: this.x + this.w/2, y: this.y + this.h,
            vx: (Math.random() - 0.5) * 1.2, vy: 3.5,
            r: 7, alpha: 1, trail: [], fuseTimer: 0
          });
        }

      } else {
        // Purple FIGHTER — sine wave + laser shots
        this.y += this.speed * warpMult;
        this.x += Math.sin(this.y * 0.03 + this.offset) * 1.5 * warpMult;
        this.attackTimer++;
        if (this.laserFlash > 0) this.laserFlash--;
        if (this.attackTimer >= this.attackCooldown / warpMult) {
          this.attackTimer = 0; this.laserFlash = 8;
          snd('enemyShot');
          // Shoot laser aimed at player
          const dx = player.x + player.w/2 - (this.x + this.w/2);
          const dy = player.y + player.h/2 - (this.y + this.h/2);
          const dist = Math.sqrt(dx*dx + dy*dy) || 1;
          const speed = 5.5;
          enemyProjectiles.push({
            type: 'LASER', x: this.x + this.w/2, y: this.y + this.h,
            vx: (dx/dist)*speed, vy: (dy/dist)*speed,
            len: 18, alpha: 1
          });
        }
      }
    }

    draw() {
      aCtx.save(); aCtx.shadowBlur = 12; aCtx.shadowColor = this.color;

      if (this.type === 'BOMBER') {
        // Orange chunky diamond-ish shape
        aCtx.fillStyle = this.dive ? '#ffaa00' : this.color;
        aCtx.beginPath();
        aCtx.moveTo(this.x + this.w/2, this.y + this.h);
        aCtx.lineTo(this.x, this.y + this.h*0.4);
        aCtx.lineTo(this.x + this.w*0.2, this.y);
        aCtx.lineTo(this.x + this.w*0.8, this.y);
        aCtx.lineTo(this.x + this.w, this.y + this.h*0.4);
        aCtx.closePath(); aCtx.fill();
        // Warning glow when about to bomb
        if (this.attackTimer > this.attackCooldown * 0.7) {
          const glow = Math.sin(this.attackTimer * 0.4) * 0.5 + 0.5;
          aCtx.strokeStyle = `rgba(255,255,0,${glow})`; aCtx.lineWidth = 2;
          aCtx.stroke();
        }

      } else if (this.type === 'FIGHTER') {
        // Purple fighter — arrow with laser charge glow
        aCtx.fillStyle = this.laserFlash > 0 ? '#ffffff' : this.color;
        aCtx.shadowBlur = this.laserFlash > 0 ? 25 : 12;
        aCtx.beginPath();
        aCtx.moveTo(this.x + this.w/2, this.y + this.h);
        aCtx.lineTo(this.x, this.y);
        aCtx.lineTo(this.x + this.w*0.35, this.y + this.h*0.4);
        aCtx.lineTo(this.x + this.w/2, this.y + this.h*0.2);
        aCtx.lineTo(this.x + this.w*0.65, this.y + this.h*0.4);
        aCtx.lineTo(this.x + this.w, this.y);
        aCtx.closePath(); aCtx.fill();

      } else {
        // Pink scout — sleek triangle, red-hot when diving
        aCtx.fillStyle = this.dive ? '#ff4444' : this.color;
        aCtx.shadowBlur = this.dive ? 22 : 12;
        aCtx.shadowColor = this.dive ? '#ff0000' : this.color;
        aCtx.beginPath();
        aCtx.moveTo(this.x + this.w/2, this.y + this.h);
        aCtx.lineTo(this.x, this.y);
        aCtx.lineTo(this.x + this.w, this.y);
        aCtx.closePath(); aCtx.fill();
        // Dive trail
        if (this.dive) {
          aCtx.strokeStyle = 'rgba(255,68,68,0.4)'; aCtx.lineWidth = 1;
          aCtx.beginPath(); aCtx.moveTo(this.x+this.w/2, this.y); aCtx.lineTo(this.x+this.w/2, this.y-18); aCtx.stroke();
        }
      }

      // HP bar (only for multi-HP enemies)
      if ((this.type === 'BOMBER' && this.hp < 3) || (this.type === 'FIGHTER' && this.hp < 2)) {
        const maxHp = this.type === 'BOMBER' ? 3 : 2;
        aCtx.fillStyle = 'rgba(0,0,0,0.6)'; aCtx.fillRect(this.x, this.y - 7, this.w, 4);
        aCtx.fillStyle = '#39ff14'; aCtx.fillRect(this.x, this.y - 7, this.w * (this.hp/maxHp), 4);
      }

      aCtx.restore();
    }
  }

  // ── ENEMY PROJECTILE DRAWING & UPDATE ──
  function updateEnemyProjectiles(dt) {
    const warpMult = timeWarpActive ? 0.5 : 1.0;
    for (let i = enemyProjectiles.length - 1; i >= 0; i--) {
      const ep = enemyProjectiles[i];
      ep.x += ep.vx * warpMult; ep.y += ep.vy * warpMult;

      if (ep.type === 'BOMB') {
        ep.fuseTimer++;
        // Trail
        ep.trail.push({ x: ep.x, y: ep.y, alpha: 0.7 });
        if (ep.trail.length > 10) ep.trail.shift();
        // Draw trail
        ep.trail.forEach((t, ti) => {
          aCtx.save(); aCtx.globalAlpha = t.alpha * (ti/ep.trail.length) * 0.5;
          aCtx.fillStyle = '#ff6600';
          aCtx.beginPath(); aCtx.arc(t.x, t.y, 3, 0, Math.PI*2); aCtx.fill(); aCtx.restore();
        });
        // Draw bomb
        aCtx.save();
        aCtx.shadowBlur = 14; aCtx.shadowColor = '#ff6600';
        // Pulsing fuse glow
        const fuseGlow = Math.sin(ep.fuseTimer * 0.3) * 0.4 + 0.6;
        aCtx.fillStyle = `rgba(255,100,0,${fuseGlow})`;
        aCtx.beginPath(); aCtx.arc(ep.x, ep.y, ep.r, 0, Math.PI*2); aCtx.fill();
        aCtx.strokeStyle = '#ffcc00'; aCtx.lineWidth = 1.5; aCtx.stroke();
        // Fuse spark
        aCtx.fillStyle = '#ffff00';
        aCtx.beginPath(); aCtx.arc(ep.x + Math.sin(ep.fuseTimer*0.8)*3, ep.y - ep.r - 3, 2, 0, Math.PI*2); aCtx.fill();
        aCtx.restore();

        // Shield collision — immune if bubble active
        if (!shieldBubbleActive &&
            Math.hypot(ep.x - (player.x+player.w/2), ep.y - (player.y+player.h/2)) < ep.r + 14) {
          explode(ep.x, ep.y, '#ff6600', 18);
          snd('hurt');
          shield -= 20; screenShake = 16; shieldFlashTimer = 15;
          document.getElementById('prog-fill').style.width = `${Math.max(0,shield)}%`;
          enemyProjectiles.splice(i,1); if (shield <= 0 && !survivedNebulaHit()) end(); continue;
        }
        if (ep.y > BOARD_H + 20) { enemyProjectiles.splice(i,1); continue; }

      } else if (ep.type === 'LASER') {
        // Draw laser bolt
        aCtx.save();
        aCtx.shadowBlur = 12; aCtx.shadowColor = '#a855f7';
        aCtx.strokeStyle = '#a855f7'; aCtx.lineWidth = 2.5;
        aCtx.beginPath();
        aCtx.moveTo(ep.x, ep.y);
        aCtx.lineTo(ep.x - ep.vx * (ep.len/5), ep.y - ep.vy * (ep.len/5));
        aCtx.stroke();
        aCtx.strokeStyle = 'rgba(255,255,255,0.7)'; aCtx.lineWidth = 1;
        aCtx.beginPath();
        aCtx.moveTo(ep.x, ep.y);
        aCtx.lineTo(ep.x - ep.vx*2, ep.y - ep.vy*2);
        aCtx.stroke();
        aCtx.restore();

        // Player collision
        if (!shieldBubbleActive &&
            collide({ x: ep.x - 4, y: ep.y - 4, w: 8, h: 8 }, { x: player.x, y: player.y, w: player.w, h: player.h })) {
          explode(ep.x, ep.y, '#a855f7', 8);
          snd('shieldHit');
          shield -= 12; screenShake = 10; shieldFlashTimer = 10;
          document.getElementById('prog-fill').style.width = `${Math.max(0,shield)}%`;
          enemyProjectiles.splice(i,1); if (shield <= 0 && !survivedNebulaHit()) end(); continue;
        }
        // Same stale bound as the player's bullets: enemy lasers evaporated
        // over the right quarter of the board instead of reaching you.
        if (ep.y > BOARD_H + 20 || ep.y < -20 || ep.x < -20 || ep.x > BOARD_W + 20) { enemyProjectiles.splice(i,1); continue; }
      }
    }
  }

  function explode(x, y, color, qty = 10) {
    for (let i = 0; i < qty; i++) {
      let ang = Math.random() * Math.PI * 2, v = Math.random() * 4 + 1;
      particles.push({ x, y, vx: Math.cos(ang)*v, vy: Math.sin(ang)*v, alpha: 1, decay: Math.random()*0.03+0.02, color, size: Math.random()*2+1 });
    }
  }
  function popText(x, y, txt, color) { floatingTexts.push({ x, y, txt, color, alpha: 1, vy: -0.8 }); }
  const collide = (r1, r2) => r1.x < r2.x + r2.w && r1.x + r1.w > r2.x && r1.y < r2.y + r2.h && r1.y + r1.h > r2.y;

  gTimer = setInterval(() => { gameTime--; document.getElementById('g-time').textContent = gameTime; if (gameTime <= 0) end(); }, 1000);

  let frame = 0;

  function pipeline(now) {
    if (isOver) return;
    let dt = now - lastTime; lastTime = now;
    frame++;
    aCtx.clearRect(0, 0, BOARD_W, BOARD_H);

    aCtx.save();
    if (screenShake > 0.5) { const sh = VFX.shake(screenShake); aCtx.translate((Math.random()-0.5)*sh, (Math.random()-0.5)*sh); screenShake *= 0.88; }

    // Shield flash overlay
    if (shieldFlashTimer > 0) {
      shieldFlashTimer--;
      aCtx.fillStyle = `rgba(255,0,0,${shieldFlashTimer/15*0.25})`;
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    }

    // Time warp visual (blue tint + slowdown label)
    if (timeWarpActive) {
      if (timeWarpTimer > 0) {
        timeWarpTimer--;
      } else {
        // Time warp has ended
        timeWarpActive = false;
        activeAbility = null;
      }
      aCtx.fillStyle = 'rgba(255,215,0,0.04)';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
      // Pulsing border
      aCtx.strokeStyle = `rgba(255,215,0,${0.3 + Math.sin(frame*0.2)*0.2})`;
      aCtx.lineWidth = 3;
      aCtx.strokeRect(2, 2, BOARD_W - 4, BOARD_H - 4);
    }

    backgroundStars.forEach(s => {
      s.y += s.speed * (timeWarpActive ? 0.35 : 1);
      if (s.y > BOARD_H) s.y = 0;
      aCtx.fillStyle = `rgba(255,255,255,${s.alpha})`; aCtx.fillRect(s.x, s.y, s.size, s.size);
    });

    player.update(dt); player.draw();

    // Shield bubble countdown
    if (shieldBubbleActive && shieldBubbleTimer > 0) shieldBubbleTimer--;

    enemySpawnTimer += dt;
    if (enemySpawnTimer >= enemySpawnInterval) {
      let r = Math.random(), type = 'SCOUT';
      if (score > 150 && r > 0.75) type = 'BOMBER';
      else if (score > 60 && r > 0.4) type = 'FIGHTER';
      enemies.push(new Enemy(type)); enemySpawnTimer = 0;
      enemySpawnInterval = Math.max(300 / diffMod, 1100 / diffMod - score * 0.5 * diffMod);
    }

    // ── Player projectiles ──
    for (let pi = projectiles.length - 1; pi >= 0; pi--) {
      const p = projectiles[pi];
      // Smart missile homing — lock onto assigned target or nearest if target gone
      if (p.smart) {
        let target = null;
        // Use locked target if it's still alive
        if (p.lockedTarget && enemies.includes(p.lockedTarget)) {
          target = p.lockedTarget;
        } else if (enemies.length > 0) {
          // Re-lock to nearest enemy
          let bestD = Infinity;
          enemies.forEach(e => {
            const d = Math.hypot(e.x - p.x, e.y - p.y);
            if (d < bestD) { bestD = d; target = e; }
          });
          p.lockedTarget = target;
        }
        if (target) {
          const tx = (target.x + target.w/2) - p.x;
          const ty = (target.y + target.h/2) - p.y;
          const dist = Math.hypot(tx, ty) || 1;
          p.vx += (tx/dist) * 1.1;
          p.vy += (ty/dist) * 1.1;
          // Cap speed
          const spd = Math.hypot(p.vx, p.vy);
          if (spd > 12) { p.vx = p.vx/spd*12; p.vy = p.vy/spd*12; }
        }
        // Cyan homing trail
        particles.push({ x:p.x, y:p.y, vx:(Math.random()-0.5)*0.5, vy:0.5, alpha:0.8, decay:0.07, color:'#00f5ff', size:2 });
      }
      p.x += p.vx; p.y += p.vy;
      // Draw
      aCtx.save();
      if (p.smart) {
        aCtx.shadowBlur = 15; aCtx.shadowColor = '#00f5ff';
        aCtx.fillStyle = '#fff';
        aCtx.beginPath(); aCtx.arc(p.x, p.y, 4, 0, Math.PI*2); aCtx.fill();
        aCtx.fillStyle = '#00f5ff';
        aCtx.beginPath(); aCtx.arc(p.x, p.y, 2, 0, Math.PI*2); aCtx.fill();
      } else if (p.plasma) {
        // Extra wide plasma bolt from max+ level
        aCtx.shadowBlur = 14; aCtx.shadowColor = '#a855f7';
        aCtx.fillStyle = '#a855f7';
        aCtx.beginPath(); aCtx.arc(p.x, p.y, 3, 0, Math.PI*2); aCtx.fill();
        aCtx.fillStyle = '#ff0090';
        aCtx.beginPath(); aCtx.arc(p.x, p.y, 1.5, 0, Math.PI*2); aCtx.fill();
      } else {
        aCtx.shadowBlur = 10; aCtx.shadowColor = '#00f5ff'; aCtx.fillStyle = '#00f5ff';
        aCtx.fillRect(p.x - 1.5, p.y, 3, 10);
      }
      aCtx.restore();
      // Off-board cull. These bounds are BOARD-relative on purpose: hardcoded
      // to the old 400-wide field, the x>420 test deleted every shot fired from
      // the right quarter of the 560-wide board on the same frame it spawned —
      // the ship's own muzzle sits past 420 once it's right of x≈403, so the
      // gun was simply dead over there.
      if (p.y < -20 || p.y > BOARD_H + 20 || p.x < -20 || p.x > BOARD_W + 20) { projectiles.splice(pi, 1); }
    }

    // ── Power-ups (plasma orbs) ──
    for (let pui = powerups.length - 1; pui >= 0; pui--) {
      const pu = powerups[pui];
      pu.y += 1.8; pu.pulse += 0.1;
      // Colour shifts based on how many orbs already collected
      const orbColor = ['#39ff14','#00f5ff','#ffd700','#ff0090','#a855f7'][Math.min(4, plasmaOrbs)];
      aCtx.save();
      aCtx.shadowBlur = 14; aCtx.shadowColor = orbColor; aCtx.fillStyle = orbColor;
      aCtx.translate(pu.x, pu.y); aCtx.rotate(pu.pulse * 0.2);
      // Octagon shape for max+ orbs
      if (plasmaOrbs >= 3) {
        aCtx.beginPath();
        for (let s=0;s<8;s++) { const a=(s/8)*Math.PI*2; aCtx.lineTo(Math.cos(a)*8, Math.sin(a)*8); }
        aCtx.closePath(); aCtx.fill();
      } else {
        aCtx.fillRect(-6, -6, 12, 12);
      }
      aCtx.restore();

      if (collide({ x: player.x, y: player.y, w: player.w, h: player.h }, { x: pu.x-8, y: pu.y-8, w: 16, h: 16 })) {
        plasmaOrbs++;
        powerups.splice(pui, 1);
        explode(pu.x, pu.y, orbColor, 18);
        if (plasmaOrbs <= 3) {
          snd('powerup');
          popText(player.x, player.y - 10, `PLASMA LV${plasmaOrbs}!`, '#39ff14');
        } else {
          const abilIndex = plasmaOrbs - 3;
          const abil = getAbilityForOrb(abilIndex);
          specialAbilities.push(abil);
          snd('charge');
          popText(player.x, player.y - 10, abil.label + ' CHARGED!', abil.color);
          // Big particle burst for bonus orbs
          for (let k=0;k<6;k++) {
            setTimeout(()=>explode(pu.x + (Math.random()-0.5)*40, pu.y + (Math.random()-0.5)*30, abil.color, 12), k*80);
          }
        }
      } else if (pu.y > BOARD_H + 20) powerups.splice(pui, 1);
    }

    // ── Enemies ──
    for (let ei = enemies.length - 1; ei >= 0; ei--) {
      const e = enemies[ei];
      e.update(frame); e.draw();

      if (e.y > 510) {
        snd('shieldHit');
        enemies.splice(ei, 1); shield -= 15 * diffMod; screenShake = 10; shieldFlashTimer = 12;
        document.getElementById('prog-fill').style.width = `${Math.max(0,shield)}%`;
        if (shield <= 0 && !survivedNebulaHit()) end(); continue;
      }
      if (!shieldBubbleActive && collide({ x: player.x, y: player.y, w: player.w, h: player.h }, { x: e.x, y: e.y, w: e.w, h: e.h })) {
        explode(e.x + e.w/2, e.y + e.h/2, e.color, 20);
        snd('hurt');
        enemies.splice(ei, 1); shield -= 25 * diffMod; screenShake = 18; shieldFlashTimer = 18;
        document.getElementById('prog-fill').style.width = `${Math.max(0,shield)}%`;
        if (shield <= 0 && !survivedNebulaHit()) end(); continue;
      }
      // Check player projectile hits
      let destroyed = false;
      for (let pi = projectiles.length - 1; pi >= 0; pi--) {
        const p = projectiles[pi];
        const pBox = p.smart
          ? { x: p.x-5, y: p.y-5, w: 10, h: 10 }
          : { x: p.x-2, y: p.y, w: 4, h: 12 };
        if (collide(pBox, { x: e.x, y: e.y, w: e.w, h: e.h })) {
          projectiles.splice(pi, 1);
          e.hp -= p.plasma ? 2 : 1; // plasma bolts do double damage
          explode(p.x, p.y, p.plasma ? '#a855f7' : '#00f5ff', p.plasma ? 6 : 3);
          snd('hit');
          if (e.hp <= 0) {
            explode(e.x + e.w/2, e.y + e.h/2, e.color, 15);
            snd('explode');
            popText(e.x, e.y, `+${e.pts}`, e.color);
            if (Math.random() < 0.18 / diffMod) powerups.push({ x: e.x + e.w/2, y: e.y + e.h/2, pulse: 0 });
            score += e.pts; setLive(score); enemies.splice(ei, 1); destroyed = true; break;
          }
        }
      }
      if (destroyed) continue;
    }

    // ── Enemy projectiles ──
    updateEnemyProjectiles(dt);

    // ── Particles ──
    for (let pi = particles.length - 1; pi >= 0; pi--) {
      const p = particles[pi];
      p.x += p.vx; p.y += p.vy; p.alpha -= p.decay;
      if (p.alpha <= 0) { particles.splice(pi, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = p.alpha; aCtx.fillStyle = p.color;
      const sz = p.size || 2;
      aCtx.fillRect(p.x, p.y, sz, sz); aCtx.restore();
    }

    // ── Floating texts ──
    for (let fti = floatingTexts.length - 1; fti >= 0; fti--) {
      const ft = floatingTexts[fti];
      ft.y += ft.vy || -0.8; ft.alpha -= 0.018;
      if (ft.alpha <= 0) { floatingTexts.splice(fti, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = ft.alpha;
      // Bigger font for ability announcements (longer strings)
      const isAbility = ft.txt.length > 8;
      const fontSize = isAbility ? 13 : 11;
      aCtx.shadowBlur = isAbility ? 14 : 8; aCtx.shadowColor = ft.color;
      aCtx.font = `bold ${fontSize}px Orbitron`; aCtx.fillStyle = ft.color;
      aCtx.textAlign = 'center';
      // Clamp x so text stays within canvas — board-relative, or every popup
      // from the right half snapped back to 340 and read as the wrong kill.
      const clampedX = Math.max(60, Math.min(BOARD_W - 60, ft.x));
      aCtx.fillText(ft.txt, clampedX, ft.y); aCtx.restore();
    }

    drawPlasmaLevel();
    drawAbilityHUD();

    aCtx.restore();
    gameLoopId = requestAnimationFrame(pipeline);
  }

  let isOver = false;
  function end() {
    if (isOver) return; isOver = true;
    snd('gameOver');
    const finalPts = Math.min(1000, score);
    showResults('nebula', finalPts, {
      '👾 Alien Matrices Purged': Math.floor(score / 20),
      '⚡ Plasma Orbs Absorbed': plasmaOrbs,
      '🛡️ Shield Grid Status': `${Math.max(0, shield)}%`,
      '🏆 Final Earnings': `${finalPts} PTS`
    });
  }

  gameLoopId = requestAnimationFrame(pipeline);
}

// ══════════════════════════════════════════════════════════════════════
//  🧱 GAME 3: CYBERPUNK TETRIS (PREMIUM STANDALONE ENGINE INTEGRATED)
// ══════════════════════════════════════════════════════════════════════
function startTetris(){
  document.getElementById('g-canvas-holder').style.display='block';
  document.getElementById('tetris-next-wrap').style.display='block';
  document.getElementById('tetris-lvl-pill').style.display='block';
  setControls({ left:'◀', action:'⟳', drop:'⬇⬇ DROP', right:'▶', accentDrop:true });
  setControlHint('DRAG = SLIDE · TAP = ROTATE · ⬇⬇ = SLAM IT DOWN',
                 '← → = MOVE · ↑ = ROTATE · ↓ = SOFT DROP · SPACE = HARD DROP');
  showTouchHint('DRAG TO SLIDE · TAP TO ROTATE · ⬇⬇ TO SLAM');
  fitCanvas();
  const diffMod = getDifficultyModifier();

  const nCanvas = document.getElementById('nextCanvas');
  const nCtx = nCanvas.getContext('2d');
  // The NEXT box draws in an 80x80 space and its backing store was 80x80 flat,
  // so on any display finer than 1x the browser stretched it -- the one panel
  // on the board with visibly softer edges than the board behind it. Backing
  // store in device pixels, context scaled back to the 80x80 the drawing code
  // uses, so nothing below this line has to know.
  (() => {
    const d = Math.min(window.devicePixelRatio || 1, 3);
    const px = Math.round(80 * d);
    if(nCanvas.width !== px){ nCanvas.width = px; nCanvas.height = px; }
    nCtx.setTransform(d, 0, 0, d, 0, 0);
  })();

  let tetrisOver=false;
  // The clock is shortened by the tier, so the bar has to be measured against
  // the clock this run actually started with — against a hardcoded 60 it opened
  // two-thirds full on Overclock and half full on Meltdown.
  const startTime = 60 / diffMod;
  let score=0, level=1, linesCleared=0, time=startTime;
  const TET_COLS = Math.floor(BOARD_W / 40);   // 40 = cell width, so cells keep their shape
  let arena=createMatrix(TET_COLS,20), player={pos:{x:0,y:0}, matrix:null}, nextPiece=null;
  let dropCounter=0, dropInterval=600 * diffMod, lastTime=performance.now(), screenShake=0;
  let particles = [];
  
  document.getElementById('g-time').textContent=time;
  document.getElementById('tetris-lvl').textContent=level;

  // Exact Standardized Shape Definitions
  const PIECES = {
    'T': [[0,1,0],[1,1,1],[0,0,0]],
    'I': [[0,2,0,0],[0,2,0,0],[0,2,0,0],[0,2,0,0]],
    'O': [[3,3],[3,3]],
    'Z': [[4,4,0],[0,4,4],[0,0,0]],
    'S': [[0,5,5],[5,5,0],[0,0,0]],
    'J': [[0,6,0],[0,6,0],[6,6,0]],
    'L': [[0,7,0],[0,7,0],[0,7,7]]
  };
  
  // Cyberpunk Color Palette
  const COLORS = [null, '#ff007f', '#00f0ff', '#ffbc00', '#9d4edd', '#39ff14', '#ff5e00', '#001eff'];

  function createMatrix(w, h){ const matrix=[]; while(h--) matrix.push(new Array(w).fill(0)); return matrix; }
  
  function getPiece(){ const p='TILJOSZ'; return PIECES[p[p.length*Math.random()|0]]; }
  
  function resetPlayer(){
    if(!nextPiece) { player.matrix = getPiece(); nextPiece = getPiece(); }
    else { player.matrix = nextPiece; nextPiece = getPiece(); }
    player.pos.y = 0; player.pos.x = (arena[0].length/2|0) - (player.matrix[0].length/2|0);
    if(collide(arena, player)){
      // 🛡️ A top-out is absorbed by deleting the top five rows of the STACK
      // — not the top five rows of the well, which are the empty air above it.
      // Finding the highest occupied row first is what makes this give real
      // headroom instead of quietly doing nothing.
      if(survivedFatal()){
        const rows = arena.length, wdt = arena[0].length;
        let top = arena.findIndex(row => row.some(c => c !== 0));
        if(top < 0) top = 0;
        arena.splice(top, 5);
        while(arena.length < rows) arena.unshift(new Array(wdt).fill(0));
        player.pos.y = 0;
        player.pos.x = (wdt/2|0) - (player.matrix[0].length/2|0);
      }
      else end();
    }
  }
  
  function collide(a, p){
    const m=p.matrix, o=p.pos;
    for(let y=0; y<m.length; ++y) for(let x=0; x<m[y].length; ++x) {
      if(m[y][x]!==0 && (a[y+o.y] && a[y+o.y][x+o.x])!==0) return true;
    } return false;
  }
  
  function merge(a, p){
    p.matrix.forEach((row,y)=>{ row.forEach((val,x)=>{ if(val!==0) a[y+p.pos.y][x+p.pos.x]=val; }); });
  }

  function rotate(m, dir){
    for(let y=0; y<m.length; ++y) for(let x=0; x<y; ++x) [m[x][y], m[y][x]] = [m[y][x], m[x][y]];
    if(dir>0) m.forEach(row=>row.reverse()); else m.reverse();
  }

  function playerMove(dir){ player.pos.x+=dir; if(collide(arena,player)) player.pos.x-=dir; else snd('move'); }
  function playerRotate(dir){
    snd('rotate');
    const pos=player.pos.x; let offset=1; rotate(player.matrix, dir);
    while(collide(arena,player)){ player.pos.x+=offset; offset=-(offset+(offset>0?1:-1)); if(offset>player.matrix[0].length) { rotate(player.matrix, -dir); player.pos.x=pos; return; } }
  }
  
  function playerDrop(){
    player.pos.y++;
    if(collide(arena,player)){
      player.pos.y--; merge(arena,player); snd('land'); resetPlayer(); arenaSweep();
    } dropCounter=0;
  }

  // Included Hard Drop standard logic
  function playerHardDrop(){
    while(!collide(arena, player)) player.pos.y++;
    player.pos.y--; merge(arena, player); snd('hardDrop'); screenShake=8; resetPlayer(); arenaSweep();
    dropCounter=0;
  }

  function explodeLine(y, width) {
    for(let x=0; x<width; x++) {
      for(let i=0; i<3; i++) {
        let ang = Math.random()*Math.PI*2, v=Math.random()*3+1;
        particles.push({x: x*40+20, y: y*25+12, vx: Math.cos(ang)*v, vy: Math.sin(ang)*v, alpha: 1, color: COLORS[Math.floor(Math.random()*7)+1]});
      }
    }
  }

  function arenaSweep(){
    let rowCount=1;
    // How many rows went in ONE sweep, which is not what rowCount tracks —
    // that doubles per row as a score multiplier. The clear chime gets longer
    // and higher with the size of the clear, so a quad is unmistakable.
    let sweptRows=0, leveled=false;
    outer: for(let y=arena.length-1; y>0; --y){
      for(let x=0; x<arena[y].length; ++x) if(arena[y][x]===0) continue outer;
      const row = arena.splice(y,1)[0].fill(0); arena.unshift(row);
      explodeLine(y, arena[0].length);
      ++y; score += rowCount*10; linesCleared++; rowCount*=2; sweptRows++;
      setLive(score); screenShake=12;

      // Included progressive drop speed calculation logic
      if(linesCleared%10===0 && level<50) {
        level++; document.getElementById('tetris-lvl').textContent=level;
        dropInterval = Math.max(50, (600 * Math.pow(0.85, level - 1)) / diffMod);
        leveled=true;
      }
    }
    if(sweptRows) snd('lineClear',{semi:sweptRows});
    if(leveled) snd('levelUp');
  }

  function drawMatrix(matrix, offset, ctx, isGhost=false){
    matrix.forEach((row,y)=>{
      row.forEach((value,x)=>{
        if(value!==0){
          if(isGhost) {
            ctx.fillStyle = COLORS[value]; ctx.globalAlpha = 0.2;
            ctx.fillRect((x+offset.x)*40, (y+offset.y)*25, 38, 23);
            ctx.globalAlpha = 1;
          } else {
            ctx.shadowBlur = 10; ctx.shadowColor = COLORS[value];
            ctx.fillStyle = COLORS[value];
            if(ctx===nCtx) ctx.fillRect((x+offset.x)*20, (y+offset.y)*20, 18, 18);
            else ctx.fillRect((x+offset.x)*40, (y+offset.y)*25, 38, 23);
            ctx.shadowBlur = 0;
          }
        }
      });
    });
  }

  window.onkeydown=e=>{
    if(e.code==='ArrowLeft') { playerMove(-1); e.preventDefault(); }
    if(e.code==='ArrowRight') { playerMove(1); e.preventDefault(); }
    if(e.code==='ArrowDown') { playerDrop(); e.preventDefault(); }
    if(e.code==='ArrowUp') { playerRotate(1); e.preventDefault(); }
    if(e.code==='Space') { playerHardDrop(); e.preventDefault(); } // Space bar hard drop
  };
  // ── CONTROL PAD ──
  // Tapping ◀ nine times to cross the board is miserable on a phone, so the
  // arrows auto-repeat on hold after the usual delayed-auto-shift pause.
  const repeatStoppers = [];
  function bindRepeat(el, fn){
    let delay = null, rep = null;
    const stop = () => { clearTimeout(delay); clearInterval(rep); delay = rep = null; };
    const tick = () => { if(tetrisOver){ stop(); return; } fn(); };
    bindHold(el, () => { tick(); delay = setTimeout(() => { rep = setInterval(tick, 60); }, 220); }, stop);
    repeatStoppers.push(stop);
  }
  bindRepeat(document.getElementById('ctrl-left'),  ()=>playerMove(-1));
  bindRepeat(document.getElementById('ctrl-right'), ()=>playerMove(1));
  document.getElementById('ctrl-action').onclick = ()=>{ if(!tetrisOver) playerRotate(1); };
  // Slam the active piece straight to the stack — the mobile stand-in for
  // holding Space, and the only way to keep pace once the drop speed climbs.
  document.getElementById('ctrl-drop').onclick = ()=>{ if(!tetrisOver) playerHardDrop(); };

  // ── BOARD GESTURES ──
  // Drag sideways to slide a column at a time, pull down to soft drop, flick
  // down to slam, tap to rotate. The pad below does the same jobs for anyone
  // who'd rather press buttons.
  const COL_PX = 40, ROW_PX = 25;          // one cell of the 10×20 board
  let gStartX=0, gStartY=0, gAccX=0, gAccY=0, gStartT=0, gMoved=false;
  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      gStartX = gAccX = p.x; gStartY = gAccY = p.y;
      gStartT = performance.now(); gMoved = false;
    },
    onMove(p){
      if(tetrisOver) return;
      while(p.x - gAccX >= COL_PX){ playerMove(1);  gAccX += COL_PX; gMoved = true; }
      while(gAccX - p.x >= COL_PX){ playerMove(-1); gAccX -= COL_PX; gMoved = true; }
      // Soft drop only once the gesture has settled into a slow pull-down. A
      // fast flick skips this entirely so it can't sink the piece, lock it,
      // and then hard-drop the *next* one on release.
      if(performance.now() - gStartT > 260){
        while(p.y - gAccY >= ROW_PX){ playerDrop(); gAccY += ROW_PX; gMoved = true; }
      }
      if(p.y < gAccY) gAccY = p.y;         // pulling back up re-arms the drop
    },
    onUp(p){
      if(tetrisOver) return;
      const held = performance.now() - gStartT;
      const dy = p.y - gStartY, dx = Math.abs(p.x - gStartX);
      if(held < 260 && dy > 55 && dy > dx * 1.6) playerHardDrop();   // flick down
      else if(!gMoved && held < 260 && dy < 20 && dx < 20) playerRotate(1);  // tap
    }
  });

  gTimer=setInterval(()=>{
    time--; document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${Math.max(0,time/startTime)*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0) end();
  },1000);

  resetPlayer();

  function loop(now){
    if(tetrisOver)return;
    const dt = now - lastTime; lastTime = now;
    aCtx.clearRect(0,0,BOARD_W,BOARD_H); nCtx.clearRect(0,0,80,80);
    
    dropCounter += dt; if(dropCounter > dropInterval) playerDrop();
    
    aCtx.save();
    if(screenShake>0.5) { const sh = VFX.shake(screenShake); aCtx.translate((Math.random()-0.5)*sh, (Math.random()-0.5)*sh); screenShake*=0.8; }
    
    // Calculate Ghost Piece position
    let ghost = { matrix: player.matrix, pos: {x: player.pos.x, y: player.pos.y} };
    while(!collide(arena, ghost)) ghost.pos.y++;
    ghost.pos.y--;
    
    // Draw Environment
    aCtx.strokeStyle='rgba(255,255,255,0.05)';
    for(let i=0; i<=TET_COLS; i++) { aCtx.beginPath(); aCtx.moveTo(i*40,0); aCtx.lineTo(i*40,BOARD_H); aCtx.stroke(); }
    for(let i=0; i<20; i++) { aCtx.beginPath(); aCtx.moveTo(0,i*25); aCtx.lineTo(BOARD_W,i*25); aCtx.stroke(); }
    
    drawMatrix(ghost.matrix, ghost.pos, aCtx, true);
    drawMatrix(arena, {x:0, y:0}, aCtx);
    drawMatrix(player.matrix, player.pos, aCtx);
    
    // Draw Next Piece preview canvas
    if(nextPiece){
      const offsetX = (4 - nextPiece[0].length) / 2;
      const offsetY = (4 - nextPiece.length) / 2;
      drawMatrix(nextPiece, {x: offsetX, y: offsetY}, nCtx);
    }
    
    // Process Particles. Walked backwards, not with forEach: splicing during a
    // forEach shifts the tail down and skips the next entry, so roughly half
    // the line-clear debris was never faded out and sat on the board.
    for (let pi = particles.length - 1; pi >= 0; pi--) {
      const p = particles[pi];
      p.x += p.vx; p.y += p.vy; p.alpha -= 0.03;
      if (p.alpha <= 0) { particles.splice(pi, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = p.alpha; aCtx.fillStyle = p.color; aCtx.fillRect(p.x, p.y, 4, 4); aCtx.restore();
    }

    aCtx.restore();
    gameLoopId=requestAnimationFrame(loop);
  }
  
  function end(){
    if(tetrisOver)return;tetrisOver=true;
    // Only a top-out is a death; running the clock out is a finished round.
    snd(time<=0 ? 'results' : 'gameOver');
    repeatStoppers.forEach(stop=>stop());   // don't leave a held arrow ticking
    showResults('tetris',Math.min(1500,score),{'🧱 Base Core Lines Resolved':linesCleared, '🏆 Final Output Score':`${score} PTS`});
  }
  
  gameLoopId=requestAnimationFrame(loop);
}

// ══════════════════════════════════════════════════════════════════════
//  💥 GAME 4: DODGE CORES (STABILIZED SMOOTH MOUSE TRAIL TRACKING)
// ══════════════════════════════════════════════════════════════════════
function startDodge(){
  document.getElementById('g-canvas-holder').style.display='block';
  setControls(null);   // pure drag control — no pad to steal board height
  setControlHint('DRAG ANYWHERE TO STEER YOUR CORE', 'MOVE THE MOUSE TO STEER YOUR CORE');
  showTouchHint('DRAG ANYWHERE TO STEER');
  fitCanvas();
  let score=0, time=30, isGameOver=false, player={x:BOARD_W/2,y:BOARD_H/2,r:8}, obstacles=[];
  document.getElementById('g-time').textContent=time;

  Ghost.begin('dodge');
  if(Ghost.racing) toast(`👻 Racing your best run — ${Ghost.target} to beat`, 2600);

  const place = (x, y) => {
    player.x = Math.max(player.r, Math.min(BOARD_W - player.r, x));
    player.y = Math.max(player.r, Math.min(BOARD_H - player.r, y));
  };

  // ── STEERING ──
  // Mouse keeps the cursor-is-the-dot feel: the dot follows the pointer the
  // moment it's over the board, with no button held. Touch uses a *relative*
  // drag: the dot tracks how far the finger travels rather than snapping under
  // it, so your thumb never covers the one pixel you're trying to thread
  // between cores. Grab anywhere on the board and steer from there.
  //
  // The choice is per event (p.touch), not per device — a laptop with a
  // touchscreen gets cursor-following from its mouse AND relative drag from its
  // screen, instead of one scheme forced on both.
  let lastP = null;
  bindCanvasDrag({
    onHover(p){ if(!p.touch) place(p.x, p.y); },
    onDown(p){
      hideTouchHint();
      lastP = p;
      if(!p.touch) place(p.x, p.y);
    },
    onMove(p){
      if(p.touch && lastP) place(player.x + (p.x - lastP.x), player.y + (p.y - lastP.y));
      else place(p.x, p.y);
      lastP = p;
    },
    onUp(){ lastP = null; }
  });

  gTimer=setInterval(()=>{
    if(isGameOver) return;
    time--;document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/30*100}%`;
    score+=25;setLive(score);
    // Surviving another second IS the scoring event here, so it gets a beat.
    snd(time<=5&&time>0 ? 'tick' : 'score', {semi:-7});
    if(time<=0) end();
  },1000);

  let obstacleColors = ['#ff6600','#ff2442','#ffd700','#ff0090','#a855f7'];
  let frame = 0;

  function loop(){
    if(isGameOver) return;
    frame++;
    Ghost.sample(player.x, player.y);

    // Solid dark background so nothing blends into page
    aCtx.fillStyle = '#0a0a1a';
    aCtx.fillRect(0,0,BOARD_W,BOARD_H);

    // Subtle grid lines for depth
    aCtx.strokeStyle = 'rgba(255,255,255,0.04)';
    aCtx.lineWidth = 1;
    for(let gx=0;gx<=BOARD_W;gx+=40){ aCtx.beginPath();aCtx.moveTo(gx,0);aCtx.lineTo(gx,BOARD_H);aCtx.stroke(); }
    for(let gy=0;gy<=BOARD_H;gy+=40){ aCtx.beginPath();aCtx.moveTo(0,gy);aCtx.lineTo(BOARD_W,gy);aCtx.stroke(); }

    // Ghost dot — drawn before the live one so it can never mask it.
    const gp = Ghost.at(frame);
    if(gp){
      aCtx.save();
      ghostStyle();
      aCtx.beginPath();
      aCtx.arc(gp[0], gp[1], player.r, 0, Math.PI*2);
      aCtx.fill(); aCtx.stroke();
      aCtx.restore();
    }

    // Player dot — equipped color with glow
    aCtx.save();
    const dodgeColor = getEquippedColorHex();
    aCtx.shadowBlur = 24; aCtx.shadowColor = dodgeColor;
    aCtx.beginPath(); aCtx.arc(player.x, player.y, player.r, 0, Math.PI*2);
    aCtx.fillStyle = dodgeColor; aCtx.fill();
    aCtx.shadowBlur = 6; aCtx.shadowColor = '#fff';
    aCtx.strokeStyle = '#fff'; aCtx.lineWidth = 2; aCtx.stroke();
    aCtx.restore();
    drawSkinBadge(player.x, player.y - player.r - 10);

    // Spawn obstacles
    if(Math.random() < .08 * (BOARD_W / 400)) {
      const col = obstacleColors[Math.floor(Math.random()*obstacleColors.length)];
      obstacles.push({
        x: Math.random()*(BOARD_W-20)+10, y: -10,
        vx: (Math.random()-0.5)*4, vy: Math.random()*3+3,
        r: Math.random()*6+8,
        color: col
      });
    }

    // Draw & move obstacles
    for(let i=obstacles.length-1; i>=0; i--){
      let o = obstacles[i];
      o.x += o.vx; o.y += o.vy;

      // Glowing obstacle
      aCtx.save();
      aCtx.shadowBlur = 18; aCtx.shadowColor = o.color;
      aCtx.beginPath(); aCtx.arc(o.x, o.y, o.r, 0, Math.PI*2);
      aCtx.fillStyle = o.color; aCtx.fill();
      // Bright core highlight
      aCtx.shadowBlur = 0;
      aCtx.beginPath(); aCtx.arc(o.x - o.r*0.28, o.y - o.r*0.28, o.r*0.3, 0, Math.PI*2);
      aCtx.fillStyle = 'rgba(255,255,255,0.35)'; aCtx.fill();
      aCtx.restore();

      const dx = o.x - player.x, dy = o.y - player.y;
      if(Math.sqrt(dx*dx + dy*dy) < o.r + player.r){
        // 🛡️ Absorbing the hit sweeps the whole field. Clearing only the core
        // that struck leaves its neighbours a frame away from killing you
        // anyway, and a shield that buys one frame reads as a broken shield.
        if(survivedFatal()){ obstacles.length = 0; break; }
        isGameOver=true; snd('bigExplode'); end(); return;
      }
      if(o.y > BOARD_H + 20) obstacles.splice(i,1);
    }

    gameLoopId = requestAnimationFrame(loop);
  }
  
  function end(){
    clearCanvasDrag();
    const earned=Math.min(800,score);
    const wasRacing=Ghost.racing, target=Ghost.target;
    const beat=Ghost.finish(earned);
    showResults('dodge',earned,{
      '⏱️ Operational Lifespan':score/25+'s',
      ...(wasRacing?{'👻 Ghost To Beat':`${target} PTS`}:{}),
      ...(wasRacing&&beat?{'👻 Result':'GHOST BEATEN'}:{}),
      '🏆 Score Accumulation':`${earned} PTS`
    });
  }
  gameLoopId=requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🧠 GAME 5: MEMORY MATCH
// ════════════════════════════════════════════
function startMemory(){
  const wrap = document.getElementById('g-memory');wrap.style.display='grid';wrap.innerHTML='';
  let icons=['🚀','🚀','🧱','🧱','🖱️','🖱️','💥','💥','🧠','🧠','🔢','🔢','⚡','⚡','🏆','🏆'], flipped=[], matched=0, score=0, time=25;
  document.getElementById('g-time').textContent=time;
  icons.sort(()=>Math.random()-.5);

  gTimer=setInterval(()=>{
    time--;document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/25*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0) end();
  },1000);

  icons.forEach((icon,idx)=>{
    const card=document.createElement('div');card.className='mem-card';card.dataset.val=icon;card.textContent='?';
    card.onclick=()=>{
      if(flipped.length<2&&!card.classList.contains('flipped')){
        card.classList.add('flipped');card.textContent=icon;flipped.push(card);snd('flip');
        if(flipped.length===2){
          // Each pair rings a step higher than the last, so the board sings its
          // way up as it empties.
          if(flipped[0].dataset.val===flipped[1].dataset.val){score+=75;setLive(score);matched++;snd('match',{semi:matched*2});flipped=[];if(matched===8)end()}
          else{snd('wrong');setTimeout(()=>{flipped[0].classList.remove('flipped');flipped[0].textContent='?';flipped[1].classList.remove('flipped');flipped[1].textContent='?';flipped=[]},700)}
        }
      }
    };
    wrap.appendChild(card);
  });
  let memEnded=false;
  function end(){if(memEnded)return;memEnded=true;showResults('memory',Math.min(600,score),{'🧩 Clusters Unified':matched,'🏆 Score Accumulation':`${score} PTS`})}
}

// ════════════════════════════════════════════
//  🔢 GAME 6: MATH BLITZ
// ════════════════════════════════════════════
function startMath(){
  document.getElementById('g-math').style.display='block';
  let score=0, time=20, curAns=0;
  document.getElementById('g-time').textContent=time;

  function gen(){
    // 📅 dailyRand() is an ordinary Math.random() outside a Daily Hack. Inside
    // one it is the day's seeded stream, which is what makes every operative on
    // the grid answer the SAME twenty questions in the same order.
    let a=Math.floor(dailyRand()*12)+2, b=Math.floor(dailyRand()*12)+2, ops=['+','-','*'], op=ops[Math.floor(dailyRand()*3)];
    document.getElementById('math-question').textContent=`${a} ${op} ${b}`;
    curAns=op==='+'?a+b:op==='-'?a-b:a*b;
    document.getElementById('math-answer').value='';document.getElementById('math-answer').focus();
  }
  gen();

  const check=()=>{
    let input=parseInt(document.getElementById('math-answer').value);
    if(input===curAns){score+=50;setLive(score);snd('correct')}else{snd('wrong')}gen();
  };
  document.getElementById('math-submit').onclick=check;
  document.getElementById('math-answer').onkeydown=e=>{if(e.code==='Enter')check()};

  let mathEnded=false;
  gTimer=setInterval(()=>{
    time--;document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/20*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0&&!mathEnded){mathEnded=true;document.getElementById('math-answer').onkeydown=null;document.getElementById('math-submit').onclick=null;showResults('math',Math.min(750,score),{'🔢 Nodes Resolved':score/50,'🏆 Score Accumulation':`${score} PTS`})}
  },1000);
}

// ════════════════════════════════════════════
//  ⚡ GAME 7: REACTION TIME
// ════════════════════════════════════════════
function startReaction(){
  // --rx-* resolve through the cb-safe palette, where "go" is bright yellow —
  // red→green is exactly the switch a deutan player can't see.
  const goWord = VFX.cbSafe ? 'YELLOW' : 'GREEN';
  const box=document.getElementById('g-reaction');box.style.display='flex';box.style.background='var(--rx-wait)';
  const txt=document.getElementById('reaction-text');txt.textContent=`WAIT FOR ${goWord}...`;
  let state='wait', startT=0, time=15, score=0, reactionEnded=false;
  document.getElementById('g-time').textContent=time;

  // Re-arms go through the shared registry so stopGame() kills them on a quit,
  // plus a local guard for the clock-expiry path. Left running, one of these
  // repainted the box green under the NEXT round without arming that round's
  // startT — the replay showed GO while its own state still said WAIT, so the
  // tap scored "TOO FAST" and the round never became playable.
  const later=(fn,ms)=>gLater(()=>{ if(!reactionEnded) fn(); },ms);

  gTimer=setInterval(()=>{
    time--;document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/15*100}%`;
    if(time<=0) end();
  },1000);

  setControlHint('TAP THE INSTANT IT TURNS GREEN','CLICK THE INSTANT IT TURNS GREEN');
  const goLabel = isTouchDevice ? 'TAP NOW!' : 'CLICK NOW!';

  let trigger=later(()=>{if(state==='wait'){state='go';box.style.background='var(--rx-go)';txt.textContent=goLabel;snd('go');startT=performance.now()}},Math.random()*2500+1500);

  // Timed on pointerdown, not click. A synthesised click doesn't land until
  // the finger lifts, which was quietly adding its own latency to every
  // reading — this game's whole score is that number.
  box.onpointerdown=e=>{
    e.preventDefault();
    if(state==='wait'){gCancel(trigger);snd('wrong');txt.textContent='TOO FAST! RESETTING...';box.style.background='var(--rx-early)';state='hold';later(()=>{if(time>0){state='wait';box.style.background='var(--rx-wait)';txt.textContent='WAIT...';trigger=later(()=>{state='go';box.style.background='var(--rx-go)';txt.textContent=goLabel;snd('go');startT=performance.now()},Math.random()*2000+1000)}},1200)}
    else if(state==='go'){
      let diff=Math.round(performance.now()-startT);
      let earned=Math.max(10,400-diff);score+=earned;setLive(score);
      // Faster reflex, higher chime — a 150ms tap is audibly better than 320ms.
      snd('score',{semi:Math.max(0,Math.round((400-diff)/40))});
      txt.textContent=`${diff}ms! REBOOTING...`;box.style.background='var(--rx-hit)';state='hold';
      later(()=>{if(time>0){state='wait';box.style.background='var(--rx-wait)';txt.textContent='WAIT...';trigger=later(()=>{state='go';box.style.background='var(--rx-go)';txt.textContent=goLabel;snd('go');startT=performance.now()},Math.random()*2000+1000)}},1500);
    }
  };
  function end(){if(reactionEnded)return;reactionEnded=true;gCancel(trigger);box.onpointerdown=null;showResults('reaction',Math.min(400,score),{'🏆 Final Sync Score':score})}
}

// ════════════════════════════════════════════
//  🏆 SYNCED DATA MATRIX LEADERBOARD BUILDER
// ════════════════════════════════════════════
// Three views of one board. All-time sorts on totalPoints; Weekly sorts on the
// weekly bucket and shows only rows from the CURRENT season, so last week's
// numbers vanish on rollover without anyone having to reset anything; Friends
// re-sorts the all-time pull down to the people you've added.
const LB_SCOPES = {
  alltime: { label:'🏆 ALL-TIME',  title:'🏆 TOP PLAYERS' },
  weekly:  { label:'📅 THIS WEEK', title:'📅 WEEKLY SEASON' },
  friends: { label:'👥 FRIENDS',   title:'👥 YOUR RIVALS' }
};
let lbScope = 'alltime';

function renderLbTabs(){
  const panel = document.getElementById('lb-panel');
  if(!panel || !panel.parentNode) return;
  let tabs = document.getElementById('lb-tabs');
  if(!tabs){
    tabs = document.createElement('div');
    tabs.id = 'lb-tabs';
    panel.parentNode.insertBefore(tabs, panel);
    tabs.addEventListener('click', e => {
      const b = e.target.closest('.lb-tab');
      if(!b) return;
      lbScope = b.dataset.scope;
      snd('tab');
      renderLbTabs();
      loadLeaderboard();
    });
  }
  tabs.innerHTML = Object.entries(LB_SCOPES).map(([k, v]) =>
    `<button class="lb-tab${k === lbScope ? ' on' : ''}" data-scope="${k}">${v.label}</button>`
  ).join('');
}

function lbRows(panel, players, scoreOf){
  const medals = ['🥇','🥈','🥉'];
  players.forEach((d, i) => {
    // Podium place and "this is you" are independent: a logged-in player
    // sitting 2nd keeps the silver row and gets the blue marker too.
    const isMe = user && d.uid === user.uid;
    const cls = [i < 3 ? `r${i+1}` : '', isMe ? 'me' : ''].filter(Boolean).join(' ');
    const row = document.createElement('div');
    row.className = `lb-row ${cls}`.trim();
    const isFriend = !!(user && user.friends && user.friends[d.uid]);
    const canAdd = user && !isMe && !d.isGuest;
    row.innerHTML =
      `<div class="lb-rank">${medals[i] || '#' + (i+1)}</div>` +
      `<div class="lb-name">${esc(d.username)}${isMe ? ' ← You' : ''}</div>` +
      (canAdd ? `<button class="lb-fr${isFriend ? ' on' : ''}" data-uid="${esc(d.uid)}" data-name="${esc(d.username)}"
                   title="${isFriend ? 'Remove rival' : 'Add as rival'}">${isFriend ? '★' : '☆'}</button>` : '') +
      `<div class="lb-score">${(parseInt(scoreOf(d)) || 0).toLocaleString()} PTS</div>`;
    panel.appendChild(row);
  });
}

async function loadLeaderboard(){
  const panel = document.getElementById('lb-panel');
  if(!db){ panel.innerHTML = '<div class="lb-empty">⚠️ Connecting Live Registry...</div>'; return; }
  // Offline the query below never calls back, so the panel would sit on
  // "Loading scores..." indefinitely. Say what is actually happening instead.
  if(offlineMode){
    renderLbTabs();
    panel.innerHTML = '<div class="lb-empty">📴 Offline — the live registry needs a connection.</div>';
    return;
  }
  renderLbTabs();
  const scope = lbScope, meta = LB_SCOPES[scope];
  const season = seasonKey();
  const scoreOf = d => scope === 'weekly'
    ? ((d.weekly && d.weekly.season === season) ? d.weekly.pts : 0)
    : d.totalPoints;

  try{
    const q = scope === 'weekly'
      ? db.ref('players').orderByChild('weekly/pts').limitToLast(20)
      : db.ref('players').orderByChild('totalPoints').limitToLast(scope === 'friends' ? 200 : 20);

    q.once('value', snapshot => {
      if(!snapshot.exists()){ panel.innerHTML = '<div class="lb-empty">No logged scores inside network nodes.</div>'; return; }
      let players = [];
      snapshot.forEach(c => { players.push({ uid:c.key, ...c.val() }); });
      players.reverse();

      if(scope === 'weekly'){
        players = players.filter(d => d.weekly && d.weekly.season === season && d.weekly.pts > 0);
      }else if(scope === 'friends'){
        const fr = (user && user.friends) || {};
        players = players.filter(d => fr[d.uid] || (user && d.uid === user.uid)).slice(0, 20);
      }

      panel.innerHTML = `<div class="lb-title">${meta.title}</div>`;
      if(!players.length){
        panel.innerHTML += scope === 'friends'
          ? '<div class="lb-empty">No rivals yet — tap ☆ beside a player to track them.</div>'
          : '<div class="lb-empty">Nothing logged for this season yet.</div>';
        return;
      }
      lbRows(panel, players, scoreOf);

      // Top of a finished-enough season gets the crown cosmetic, granted once.
      if(scope === 'weekly' && user && players[0] && players[0].uid === user.uid) grantSeasonCrown();
    });
  }catch(e){ console.error(e); }
}

// Star toggle, delegated so it survives every re-render of the board.
document.addEventListener('click', async e => {
  const b = e.target.closest?.('.lb-fr');
  if(!b || !user || !db) return;
  e.stopPropagation();
  const uid = b.dataset.uid, name = b.dataset.name;
  const had = !!user.friends[uid];
  if(had) delete user.friends[uid]; else user.friends[uid] = true;
  b.classList.toggle('on', !had);
  b.textContent = had ? '☆' : '★';
  snd(had ? 'uiBack' : 'success');
  toast(had ? `☆ ${name} removed from rivals` : `★ ${name} added to rivals`, 2000);
  try{
    await db.ref(`players/${user.uid}/friends/${uid}`).set(had ? null : true);
  }catch(err){ console.warn('Rival write failed:', err); }
}, true);

// One-off cosmetic for topping a weekly season. Uses the normal owned/equipped
// shape so it shows up in the Black Market like anything else.
async function grantSeasonCrown(){
  if(!user || !db) return;
  const id = 'skin-crown';
  if((user.owned.skins || []).includes(id)) return;
  user.owned.skins = [...(user.owned.skins || []), id];
  try{
    await db.ref(`players/${user.uid}/owned/skins`).set(user.owned.skins);
    snd('victory');
    toast('👑 SEASON CROWN UNLOCKED — top of the weekly board!', 4000);
  }catch(e){ console.warn('Crown grant failed:', e); }
}
const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ════════════════════════════════════════════
//  🏓 GAME 8: CYBER PONG
// ════════════════════════════════════════════
function startPong(){
  document.getElementById('g-canvas-holder').style.display='block';
  // Drag is the natural way to rally, but the buttons stay so the game still
  // plays if a browser refuses the gesture.
  setControls({ left:'▲ UP', right:'▼ DOWN' });
  setControlHint('DRAG TO RALLY · OR USE ▲ ▼', '↑ ↓ OR MOUSE TO MOVE YOUR PADDLE');
  showTouchHint('DRAG UP AND DOWN TO MOVE YOUR PADDLE');
  fitCanvas();

  const W=BOARD_W, H=BOARD_H, PAD_W=10, PAD_H=70, BALL_R=7;
  const X_SCALE = W / 400;   // keeps a rally the same length in seconds
  let userScore=0, cpuScore=0, time=45, isOver=false;
  let playerY=H/2-PAD_H/2, aiY=H/2-PAD_H/2;
  let ballX=W/2, ballY=H/2, ballVX=4*X_SCALE*(Math.random()<0.5?1:-1), ballVY=3*(Math.random()<0.5?1:-1);
  let aiSpeed=2.8;
  let rallyCount = 0; // Track current rally length
  const updateScore = () => {
    const raw = (userScore - cpuScore) * 50;
    const displayScore = Math.max(0, raw);
    setLive(displayScore);
  };
  updateScore();
  document.getElementById('g-time').textContent=Math.ceil(time);
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--cyan),var(--purple))';

  // Mouse / touch control. The mouse steers on hover — no button held, the
  // paddle simply is where the cursor is. Touch needs contact by definition,
  // and a rally pulls your finger past the top and bottom edges constantly, so
  // the drag is bound on the window rather than the canvas to keep it alive.
  const trackPaddle = p => {
    playerY = Math.max(0, Math.min(H-PAD_H, p.y - PAD_H/2));
  };
  bindCanvasDrag({
    onHover: trackPaddle,
    onDown(p){ hideTouchHint(); trackPaddle(p); },
    onMove: trackPaddle
  });

  // Mobile buttons. Each press nudges immediately as well as starting the
  // glide — hold-to-move alone meant a quick tap moved the paddle by a couple
  // of pixels and read as a dead button.
  let moveUp=false,moveDown=false;
  const NUDGE=34;
  bindHold(document.getElementById('ctrl-left'),
           ()=>{ playerY=Math.max(0,playerY-NUDGE); moveUp=true; },   ()=>moveUp=false);
  bindHold(document.getElementById('ctrl-right'),
           ()=>{ playerY=Math.min(H-PAD_H,playerY+NUDGE); moveDown=true; }, ()=>moveDown=false);

  // Keyboard
  let keys={};
  window.onkeydown=e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown'].includes(e.code))e.preventDefault()};
  window.onkeyup=e=>{keys[e.code]=false};

  gTimer=setInterval(()=>{
    if(isOver)return;
    time--;document.getElementById('g-time').textContent=Math.ceil(time);
    document.getElementById('prog-fill').style.width=`${time/45*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0)end();
  },1000);

  function end(){
    if(isOver)return; isOver=true;
    const pts = Math.min(900, Math.max(0, (userScore - cpuScore) * 50));
    showResults('pong', pts, {'🏓 Your Goals': userScore, '🤖 CPU Goals': cpuScore, '🏆 Final Score': `${pts} PTS`});
  }

  function drawGlow(color,alpha=0.18){
    aCtx.save();aCtx.shadowBlur=18;aCtx.shadowColor=color;aCtx.globalAlpha=alpha;aCtx.restore();
  }

  function loop(){
    if(isOver)return;

    // Keyboard / button paddle movement
    const SPEED=6;
    if(keys['ArrowUp']||moveUp) playerY=Math.max(0,playerY-SPEED);
    if(keys['ArrowDown']||moveDown) playerY=Math.min(H-PAD_H,playerY+SPEED);

    // AI paddle — tracks ball with slight lag
    const aiCenter=aiY+PAD_H/2;
    const diff=ballY-aiCenter;
    aiY+=Math.sign(diff)*Math.min(aiSpeed,Math.abs(diff));
    aiY=Math.max(0,Math.min(H-PAD_H,aiY));

    // Ball movement
    const prevX=ballX;
    ballX+=ballVX; ballY+=ballVY;

    // Top/bottom wall bounce
    if(ballY-BALL_R<0){ballY=BALL_R;ballVY=Math.abs(ballVY);snd('bounceWall');}
    if(ballY+BALL_R>H){ballY=H-BALL_R;ballVY=-Math.abs(ballVY);snd('bounceWall');}

    // Paddle hits are SWEPT — they ask whether the ball crossed the paddle's
    // face this frame, not whether it happens to be sitting inside the 10-unit
    // slab right now. The rally speeds the ball up 4% per hit from an opening
    // 5.6, so past ~10 units/frame it stepped clean over the slab and scored
    // against you through a paddle that was in exactly the right place.
    const pFace=20+PAD_W;                       // player paddle's inner face
    const aFace=W-20-PAD_W;                     // AI paddle's inner face

    // Player paddle (left, x=20..20+PAD_W)
    if(ballVX<0 && prevX-BALL_R>=pFace && ballX-BALL_R<=pFace && ballY>playerY && ballY<playerY+PAD_H){
      // Player hit the ball - increase rally count
      rallyCount++;
      // The rally climbs in pitch as the ball speeds up — you can hear a long
      // rally getting dangerous without taking your eyes off the paddle.
      snd('bounce',{semi:Math.min(14,rallyCount)});
      ballVX=Math.abs(ballVX)*1.04;
      ballVY=((ballY-(playerY+PAD_H/2))/(PAD_H/2))*6;
      ballX=20+PAD_W+BALL_R;
    }

    // AI paddle (right, x=W-20-PAD_W..W-20)
    if(ballVX>0 && prevX+BALL_R<=aFace && ballX+BALL_R>=aFace && ballY>aiY && ballY<aiY+PAD_H){
      // AI hit the ball - rally continues
      rallyCount++;
      snd('bounce',{semi:Math.min(14,rallyCount)-12});
      ballVX=-Math.abs(ballVX)*1.02;
      ballVY=((ballY-(aiY+PAD_H/2))/(PAD_H/2))*5;
      ballX=W-20-PAD_W-BALL_R;
    }

    // Ball misses — reset and award points
    if(ballX<0||ballX>W){
      if(ballX < 0) {
        // Ball passed LEFT wall — player missed — CPU scores
        cpuScore++;
        snd('hurt');
        updateScore();
      } else {
        // Ball passed RIGHT wall — CPU missed — player scores
        userScore++;
        snd('score');
        updateScore();
      }

      // Reset for next point — random side, at the same pace as the opening
      // serve. X_SCALE has to be here too: without it every rally after the
      // first crossed the wider board at the old 400-wide speed, so the game
      // got conspicuously sluggish the moment anyone scored.
      rallyCount = 0;
      ballX=W/2; ballY=H/2;
      ballVX=4*X_SCALE*(Math.random()<0.5?1:-1);
      ballVY=3*(Math.random()<0.5?1:-1);
      aiSpeed=Math.min(5,2.8+userScore*0.002);
    }

    // ── DRAW ──
    aCtx.clearRect(0,0,W,H);

    // Centre dashed line
    aCtx.setLineDash([8,12]);aCtx.strokeStyle='rgba(255,255,255,0.08)';aCtx.lineWidth=2;
    aCtx.beginPath();aCtx.moveTo(W/2,0);aCtx.lineTo(W/2,H);aCtx.stroke();
    aCtx.setLineDash([]);

    // Player paddle (equipped color)
    const pongColor = getEquippedColorHex();
    aCtx.save();aCtx.shadowBlur=20;aCtx.shadowColor=pongColor;
    aCtx.fillStyle=pongColor;aCtx.beginPath();
    aCtx.roundRect(20,playerY,PAD_W,PAD_H,4);aCtx.fill();aCtx.restore();
    drawSkinBadge(20+PAD_W/2, playerY-12);

    // AI paddle (pink)
    aCtx.save();aCtx.shadowBlur=20;aCtx.shadowColor='#ff0090';
    aCtx.fillStyle='#ff0090';aCtx.beginPath();
    aCtx.roundRect(W-20-PAD_W,aiY,PAD_W,PAD_H,4);aCtx.fill();aCtx.restore();

    // Ball (white glow)
    aCtx.save();aCtx.shadowBlur=22;aCtx.shadowColor='#fff';
    aCtx.fillStyle='#ffffff';aCtx.beginPath();aCtx.arc(ballX,ballY,BALL_R,0,Math.PI*2);aCtx.fill();aCtx.restore();

    // Labels
    aCtx.font='bold 0.65rem Orbitron,monospace';aCtx.fillStyle='rgba(255,255,255,0.25)';
    aCtx.textAlign='center';
    aCtx.fillText('YOU',W/4,22);aCtx.fillText('CPU',3*W/4,22);

    gameLoopId=requestAnimationFrame(loop);
  }
  loop();
}

// ════════════════════════════════════════════
//  🐍 GAME 9: GRID SNAKE
// ════════════════════════════════════════════
function startSnake(){
  document.getElementById('g-canvas-holder').style.display='block';
  // Four absolute arrows. The old pad was two relative turns plus a cycle
  // button, which meant working out "which way is left of me right now" while
  // the snake was already moving — arrows say where you're going outright.
  setControls({ left:'←', action:'↑', drop:'↓', right:'→' });
  setControlHint('SWIPE OR TAP AN ARROW TO STEER', 'ARROW KEYS TO STEER');
  showTouchHint('SWIPE ANY DIRECTION TO STEER');
  fitCanvas();

  const diffMod = getDifficultyModifier();
  const baseTime = 60;
  const adjustedTime = baseTime / diffMod;

  const W=BOARD_W,H=BOARD_H,CELL=20,COLS=W/CELL,ROWS=H/CELL;
  let score=0,time=adjustedTime,isOver=false;
  let dir={x:1,y:0},nextDir={x:1,y:0};
  let snake=[{x:10,y:12},{x:9,y:12},{x:8,y:12}];
  let food=spawnFood(),speed=160 / diffMod,lastMoveTime=0,particles=[];
  let gTick=0;

  Ghost.begin('snake');
  if(Ghost.racing) toast(`👻 Racing your best run — ${Ghost.target} to beat`, 2600);

  document.getElementById('g-time').textContent=Math.ceil(time);
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--lime),var(--cyan))';
  document.getElementById('prog-fill').style.width='100%';

  function spawnFood(){
    let pos;
    do{pos={x:Math.floor(Math.random()*COLS),y:Math.floor(Math.random()*ROWS)}}
    while(snake.some(s=>s.x===pos.x&&s.y===pos.y));
    return pos;
  }

  // Keyboard
  window.onkeydown=e=>{
    if(e.code==='ArrowLeft'&&dir.x!==1) {nextDir={x:-1,y:0};e.preventDefault();}
    if(e.code==='ArrowRight'&&dir.x!==-1){nextDir={x:1,y:0};e.preventDefault();}
    if(e.code==='ArrowUp'&&dir.y!==1)   {nextDir={x:0,y:-1};e.preventDefault();}
    if(e.code==='ArrowDown'&&dir.y!==-1){nextDir={x:0,y:1};e.preventDefault();}
  };

  // Turning onto your own neck is a no-op, exactly as pressing the opposite
  // arrow key already was.
  const steer=(x,y)=>{ if(x!==-dir.x||y!==-dir.y) nextDir={x,y}; };

  // Four absolute arrows, matching the arrow keys one for one.
  document.getElementById('ctrl-left').onclick  = ()=>steer(-1, 0);
  document.getElementById('ctrl-action').onclick= ()=>steer( 0,-1);
  document.getElementById('ctrl-drop').onclick  = ()=>steer( 0, 1);
  document.getElementById('ctrl-right').onclick = ()=>steer( 1, 0);

  // ── SWIPE STEERING ──
  // Flick the way you want to go — the same four directions as the arrows.
  let swStartX=0, swStartY=0, swDone=false;
  bindCanvasDrag({
    onDown(p){ hideTouchHint(); swStartX=p.x; swStartY=p.y; swDone=false; },
    onMove(p){
      if(swDone) return;
      const dx=p.x-swStartX, dy=p.y-swStartY;
      if(Math.max(Math.abs(dx),Math.abs(dy))<26) return;   // ignore jitter
      if(Math.abs(dx)>Math.abs(dy)) steer(dx>0?1:-1,0); else steer(0,dy>0?1:-1);
      // One turn per swipe, then re-arm from here so a long S-curve drag can
      // chain turns without lifting your finger.
      swStartX=p.x; swStartY=p.y;
    },
    onUp(){ swDone=true; }
  });

  gTimer=setInterval(()=>{
    if(isOver)return;
    time--;document.getElementById('g-time').textContent=Math.ceil(time);
    document.getElementById('prog-fill').style.width=`${time/adjustedTime*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0)end('timeout');
  },1000);

  function end(reason){
    if(isOver)return;isOver=true;
    if(reason!=='timeout') snd('gameOver');
    const earned=Math.min(1200,score);
    const wasRacing=Ghost.racing, target=Ghost.target;
    const beat=Ghost.finish(earned);
    showResults('snake',earned,{
      '🐍 Nodes Consumed':Math.floor(score/30),
      '📏 Max Length':snake.length,
      ...(wasRacing?{'👻 Ghost To Beat':`${target} PTS`}:{}),
      ...(wasRacing&&beat?{'👻 Result':'GHOST BEATEN'}:{}),
      '🏆 Score Accumulation':`${earned} PTS`
    });
  }

  function loop(now){
    if(isOver)return;
    gameLoopId=requestAnimationFrame(loop);

    // Move snake at fixed interval
    if(now-lastMoveTime>=speed){
      lastMoveTime=now;
      dir={...nextDir};
      const head={x:snake[0].x+dir.x,y:snake[0].y+dir.y};

      // Wall collision
      const hitWall = head.x<0||head.x>=COLS||head.y<0||head.y>=ROWS;
      // Self collision
      const hitSelf = !hitWall && snake.some(s=>s.x===head.x&&s.y===head.y);
      if(hitWall || hitSelf){
        // 🛡️ SHIELD OVERLAY absorbs the crash. The chain doesn't advance into
        // whatever it hit — it reverses instead, which is the only outcome that
        // leaves a survivable board: a wall bounce that kept going would be a
        // second crash next tick, and a self-hit has nowhere else to go.
        if(survivedFatal()){
          nextDir={x:-dir.x,y:-dir.y};
          snake.reverse();
          return;
        }
        snd('bigExplode'); end(hitWall?'wall':'self'); return;
      }

      snake.unshift(head);
      // Indexed by MOVE, not by animation frame: the snake steps on a fixed
      // interval, so a tick-indexed ghost replays at the same pace on any
      // refresh rate. `speed` shortens as you grow, and the ghost carries its
      // own run's pacing with it.
      gTick++;
      Ghost.sample(head.x, head.y);

      if(head.x===food.x&&head.y===food.y){
        score+=30;setLive(score);
        // Pitch tracks length, so the chain you've built is something you hear.
        snd('eat',{semi:Math.min(19,snake.length-3)});
        // Particle burst on food eat
        for(let i=0;i<8;i++){
          const ang=Math.random()*Math.PI*2,v=Math.random()*3+1;
          particles.push({x:food.x*CELL+CELL/2,y:food.y*CELL+CELL/2,vx:Math.cos(ang)*v,vy:Math.sin(ang)*v,alpha:1,color:'#39ff14'});
        }
        food=spawnFood();
        speed=Math.max(70,speed-3); // speed up as snake grows
      } else {
        snake.pop();
      }
    }

    // ── DRAW ──
    aCtx.clearRect(0,0,W,H);

    // Grid
    aCtx.strokeStyle='rgba(57,255,20,0.05)';aCtx.lineWidth=1;
    for(let i=0;i<=COLS;i++){aCtx.beginPath();aCtx.moveTo(i*CELL,0);aCtx.lineTo(i*CELL,H);aCtx.stroke();}
    for(let i=0;i<=ROWS;i++){aCtx.beginPath();aCtx.moveTo(0,i*CELL);aCtx.lineTo(W,i*CELL);aCtx.stroke();}

    // Ghost head from your best run, under the live snake.
    const gh = Ghost.at(gTick);
    if(gh){
      aCtx.save();
      ghostStyle();
      aCtx.fillRect(gh[0]*CELL+1, gh[1]*CELL+1, CELL-2, CELL-2);
      aCtx.strokeRect(gh[0]*CELL+1, gh[1]*CELL+1, CELL-2, CELL-2);
      aCtx.restore();
    }

    // Snake body
    const snakeHeadColor = getEquippedColorHex();
    snake.forEach((seg,i)=>{
      const t=1-i/snake.length;
      aCtx.save();
      if(i===0){aCtx.shadowBlur=16;aCtx.shadowColor=snakeHeadColor;}
      aCtx.fillStyle=i===0?snakeHeadColor:`rgba(57,255,20,${0.2+t*0.7})`;
      aCtx.fillRect(seg.x*CELL+1,seg.y*CELL+1,CELL-2,CELL-2);
      if(i===0){
        // eyes
        aCtx.fillStyle='#000';
        const ex=dir.x===1?CELL-5:dir.x===-1?3:CELL/2-4;
        const ey=dir.y===1?CELL-5:dir.y===-1?3:CELL/2-4;
        aCtx.fillRect(seg.x*CELL+ex,seg.y*CELL+ey,3,3);
        aCtx.fillRect(seg.x*CELL+ex+(dir.y!==0?6:0),seg.y*CELL+ey+(dir.x!==0?6:0),3,3);
      }
      aCtx.restore();
      if(i===0) drawSkinBadge(seg.x*CELL+CELL/2, seg.y*CELL-8, 12);
    });

    // Food — pulsing dot
    const pulse=0.7+0.3*Math.sin(now*0.006);
    aCtx.save();aCtx.shadowBlur=18*pulse;aCtx.shadowColor='#ff0090';
    aCtx.fillStyle='#ff0090';
    aCtx.beginPath();aCtx.arc(food.x*CELL+CELL/2,food.y*CELL+CELL/2,CELL/2-2,0,Math.PI*2);aCtx.fill();
    // inner highlight
    aCtx.fillStyle='rgba(255,255,255,0.4)';
    aCtx.beginPath();aCtx.arc(food.x*CELL+CELL/2-2,food.y*CELL+CELL/2-2,3,0,Math.PI*2);aCtx.fill();
    aCtx.restore();

    // Particles
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx;p.y+=p.vy;p.alpha-=0.04;
      if(p.alpha<=0){particles.splice(i,1);continue;}
      aCtx.save();aCtx.globalAlpha=p.alpha;aCtx.fillStyle=p.color;
      aCtx.fillRect(p.x,p.y,4,4);aCtx.restore();
    }
  }
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🚁 GAME 10: FLAPPY DRONE
// ════════════════════════════════════════════
function startFlappy(){
  document.getElementById('g-canvas-holder').style.display='block';
  setControls({ action: isTouchDevice ? 'TAP / FLAP' : 'CLICK / FLAP' });
  setControlHint('TAP ANYWHERE TO FLAP', 'SPACE OR CLICK TO FLAP');
  showTouchHint('TAP ANYWHERE TO FLAP');
  fitCanvas();

  const diffMod = getDifficultyModifier();

  const W=BOARD_W,H=BOARD_H,GAP=140,PIPE_W=46,PIPE_SPEED=2.4*diffMod*(BOARD_W/400);

  // ── VERTICAL FEEL ──
  // A tier's bite belongs in the horizontal pressure — PIPE_SPEED and the spawn
  // rate — not in how fast you have to tap. The old curve scaled gravity UP by
  // diffMod and the flap impulse DOWN by the same factor, a double penalty: one
  // tap bought ~63px of climb on Stable but only ~7px on Meltdown, against a
  // 140px gap — holding altitude there needed roughly five times the tapping
  // rate Stable does. Now gravity ramps at half the tier rate and the flap ramps
  // a little faster than the square root of gravity — sqrt being the exponent
  // that holds climb-per-tap flat — so the drone lifts at least as far per tap
  // on every tier as it does on Stable, and the fall never outruns it. Harder
  // tiers ask for tighter timing, never for faster fingers. Stable is untouched.
  const gravMod=1+(diffMod-1)*0.5;        // 1.00 / 1.25 / 1.50
  const GRAVITY=0.42*gravMod;
  const FLAP=-7.5*Math.pow(gravMod,0.65); // climb per tap: 63px / 67px / 71px
  let score=0,time=0,isOver=false,frame=0;
  let droneY=H/2,droneVY=0;
  let pipes=[],particles=[];
  const DRONE_X=80,DRONE_H=28,DRONE_W=38;

  Ghost.begin('flappy');
  if(Ghost.racing) toast(`👻 Racing your best run — ${Ghost.target} to beat`, 2600);

  document.getElementById('g-time').textContent='∞';
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--gold),var(--orange))';

  function flap(){if(!isOver){droneVY=FLAP;snd('flap');}}

  document.getElementById('ctrl-action').onclick=flap;
  window.onkeydown=e=>{if(e.code==='Space'){flap();e.preventDefault();}};

  // Tap anywhere on the board. One pointerdown path instead of click +
  // touchstart, so a single tap can't register as two flaps — and it lifts on
  // contact rather than waiting out the click synthesis.
  bindCanvasDrag({ onDown(){ hideTouchHint(); flap(); } });

  function spawnPipe(){
    const topH=Math.random()*(H-GAP-80)+40;
    pipes.push({x:W,topH,scored:false});
  }

  // Initial pipe
  spawnPipe();

  function end(){
    if(isOver)return;isOver=true;
    const earned=Math.min(1000,score*50);
    const wasRacing=Ghost.racing, target=Ghost.target;
    const beat=Ghost.finish(earned);
    showResults('flappy',earned,{
      '🚧 Firewalls Cleared':score,
      ...(wasRacing?{'👻 Ghost To Beat':`${target} PTS`}:{}),
      ...(wasRacing&&beat?{'👻 Result':'GHOST BEATEN'}:{}),
      '🏆 Score Accumulation':`${earned} PTS`
    });
  }

  function drawDrone(y,isDead){
    aCtx.save();
    const cx=DRONE_X,cy=y;
    const wobble=isDead?0:Math.sin(frame*0.18)*1.2;

    // Propeller arcs
    const propSpin=frame*0.3;
    [cx-16,cx+16].forEach(px=>{
      aCtx.save();aCtx.translate(px,cy-DRONE_H/2-4);
      aCtx.rotate(propSpin);
      aCtx.strokeStyle=isDead?'#555':'rgba(255,215,0,0.85)';
      aCtx.lineWidth=2;aCtx.shadowBlur=isDead?0:10;aCtx.shadowColor='#ffd700';
      for(let b=0;b<2;b++){
        aCtx.beginPath();aCtx.arc(0,0,12,b*Math.PI,(b+0.45)*Math.PI);aCtx.stroke();
      }
      aCtx.restore();
    });

    // Body
    const droneColor = getEquippedColorHex();
    aCtx.shadowBlur=isDead?0:14;aCtx.shadowColor=droneColor;
    aCtx.fillStyle=isDead?'#444':droneColor;
    aCtx.beginPath();
    aCtx.roundRect(cx-DRONE_W/2,cy-DRONE_H/2+wobble,DRONE_W,DRONE_H,6);
    aCtx.fill();

    // Arms
    aCtx.strokeStyle=isDead?'#555':'rgba(255,215,0,0.6)';aCtx.lineWidth=3;
    aCtx.beginPath();aCtx.moveTo(cx-DRONE_W/2,cy+wobble);aCtx.lineTo(cx-DRONE_W/2-10,cy-DRONE_H/2-4+wobble);aCtx.stroke();
    aCtx.beginPath();aCtx.moveTo(cx+DRONE_W/2,cy+wobble);aCtx.lineTo(cx+DRONE_W/2+10,cy-DRONE_H/2-4+wobble);aCtx.stroke();

    // Lens
    aCtx.fillStyle=isDead?'#333':'#04040e';
    aCtx.beginPath();aCtx.arc(cx+10,cy+2+wobble,5,0,Math.PI*2);aCtx.fill();
    aCtx.fillStyle=isDead?'#666':'rgba(0,245,255,0.9)';
    aCtx.beginPath();aCtx.arc(cx+11,cy+1+wobble,2.5,0,Math.PI*2);aCtx.fill();

    aCtx.restore();
    if(!isDead) drawSkinBadge(cx, cy-DRONE_H/2-16, 12);
  }

  function loop(){
    if(isOver)return;
    frame++;
    gameLoopId=requestAnimationFrame(loop);

    // Physics
    droneVY+=GRAVITY;
    droneY+=droneVY;
    // Exactly once per frame, before any early return — playback is indexed by
    // frame, so a skipped sample would shift the whole ghost out of step.
    Ghost.sample(droneY);

    // Spawn pipes every ~90 frames -> adjusted by difficulty
    if(frame%(90/diffMod)===0)spawnPipe();

    // Move & score pipes
    for(let i=pipes.length-1;i>=0;i--){
      const p=pipes[i];
      p.x-=PIPE_SPEED;
      if(!p.scored&&p.x+PIPE_W<DRONE_X-DRONE_W/2){
        score++;setLive(score);p.scored=true;
        snd('score',{semi:Math.min(12,score-1)});
        // particle burst on clear
        for(let k=0;k<6;k++){
          const ang=Math.random()*Math.PI*2,v=Math.random()*3+1;
          particles.push({x:DRONE_X,y:droneY,vx:Math.cos(ang)*v,vy:Math.sin(ang)*v,alpha:1,color:'#ffd700'});
        }
      }
      if(p.x+PIPE_W<0)pipes.splice(i,1);

      // Collision: top pipe
      if(DRONE_X+DRONE_W/2>p.x&&DRONE_X-DRONE_W/2<p.x+PIPE_W){
        if(droneY-DRONE_H/2<p.topH||droneY+DRONE_H/2>p.topH+GAP){
          // 🛡️ A shielded hit costs the shield and phases the drone through:
          // it is parked in the middle of the gap and its fall is cancelled, so
          // the save actually buys the column rather than a single frame of it.
          if(survivedFatal()){
            droneY=p.topH+GAP/2; droneVY=0; p.shielded=true;
          }else{
            drawDrone(droneY,true);snd('bigExplode');end();return;
          }
        }
      }
    }

    // Floor / ceiling
    if(droneY+DRONE_H/2>H||droneY-DRONE_H/2<0){
      if(survivedFatal()){
        droneY=Math.max(DRONE_H/2+2, Math.min(H-DRONE_H/2-2, droneY)); droneVY=0;
      }else{
        drawDrone(droneY,true);snd('bigExplode');end();return;
      }
    }

    // ── DRAW ──
    aCtx.clearRect(0,0,W,H);

    // Scrolling bg grid
    const gridOff=(frame*PIPE_SPEED)%40;
    aCtx.strokeStyle='rgba(255,215,0,0.04)';aCtx.lineWidth=1;
    for(let x=-gridOff;x<W;x+=40){aCtx.beginPath();aCtx.moveTo(x,0);aCtx.lineTo(x,H);aCtx.stroke();}
    for(let y=0;y<H;y+=40){aCtx.beginPath();aCtx.moveTo(0,y);aCtx.lineTo(W,y);aCtx.stroke();}

    // Pipes (firewall columns)
    pipes.forEach(p=>{
      // Top pipe
      const grad=aCtx.createLinearGradient(p.x,0,p.x+PIPE_W,0);
      grad.addColorStop(0,'#b45309');grad.addColorStop(0.4,'#ffd700');grad.addColorStop(1,'#b45309');
      aCtx.save();aCtx.shadowBlur=14;aCtx.shadowColor='rgba(255,215,0,0.5)';
      aCtx.fillStyle=grad;
      aCtx.fillRect(p.x,0,PIPE_W,p.topH);
      // Cap
      aCtx.fillStyle='#ffd700';aCtx.fillRect(p.x-4,p.topH-16,PIPE_W+8,16);
      // Bottom pipe
      aCtx.fillStyle=grad;
      aCtx.fillRect(p.x,p.topH+GAP,PIPE_W,H-(p.topH+GAP));
      // Cap
      aCtx.fillStyle='#ffd700';aCtx.fillRect(p.x-4,p.topH+GAP,PIPE_W+8,16);
      aCtx.restore();

      // Circuit lines on pipes
      aCtx.strokeStyle='rgba(255,165,0,0.3)';aCtx.lineWidth=1;aCtx.setLineDash([4,6]);
      aCtx.beginPath();aCtx.moveTo(p.x+PIPE_W/2,0);aCtx.lineTo(p.x+PIPE_W/2,p.topH-16);aCtx.stroke();
      aCtx.beginPath();aCtx.moveTo(p.x+PIPE_W/2,p.topH+GAP+16);aCtx.lineTo(p.x+PIPE_W/2,H);aCtx.stroke();
      aCtx.setLineDash([]);
    });

    // Ghost of your best run, under the live drone so it never hides it.
    const ghostY = Ghost.at(frame);
    if(ghostY != null){
      aCtx.save();
      ghostStyle();
      aCtx.strokeRect(DRONE_X-DRONE_W/2, ghostY-DRONE_H/2, DRONE_W, DRONE_H);
      aCtx.fillRect(DRONE_X-DRONE_W/2, ghostY-DRONE_H/2, DRONE_W, DRONE_H);
      aCtx.restore();
    }

    // Score display
    aCtx.save();aCtx.shadowBlur=12;aCtx.shadowColor='#ffd700';
    aCtx.fillStyle='rgba(255,255,255,0.85)';aCtx.font='bold 2.2rem Orbitron,monospace';
    aCtx.textAlign='center';aCtx.fillText(score,W/2,55);aCtx.restore();

    // Particles
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx;p.y+=p.vy;p.alpha-=0.04;
      if(p.alpha<=0){particles.splice(i,1);continue;}
      aCtx.save();aCtx.globalAlpha=p.alpha;aCtx.fillStyle=p.color;
      aCtx.beginPath();aCtx.arc(p.x,p.y,4,0,Math.PI*2);aCtx.fill();aCtx.restore();
    }

    drawDrone(droneY,false);
  }
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🧊 GAME 11: ICE BREAKER
// ════════════════════════════════════════════
function startBreaker(){
  document.getElementById('g-canvas-holder').style.display='block';
  // Drag is the fast way to slide the deflector; the arrows stay so the game
  // still plays if a browser refuses the gesture — same deal as Pong.
  setControls({ left:'◀', action:'🚀 LAUNCH', right:'▶' });
  setControlHint('DRAG TO SLIDE · TAP TO LAUNCH', '← → OR MOUSE TO SLIDE · SPACE TO LAUNCH');
  showTouchHint('DRAG TO SLIDE · TAP TO LAUNCH');
  fitCanvas();

  const diffMod = getDifficultyModifier();
  const W=BOARD_W, H=BOARD_H;
  const ROWS=5, B_W=44, B_H=18, B_GAP=6, B_TOP=64;
  const COLS=Math.floor((W+B_GAP)/(B_W+B_GAP));   // 8 at 400 wide, 11 at 560
  const B_LEFT=(W-(COLS*B_W+(COLS-1)*B_GAP))/2;
  const PAD_H=11, PAD_Y=H-34, BALL_R=6;

  // A straight ×2 on ball speed at Meltdown crosses the board in under a
  // second — past reacting, into guessing. Damped, so the tier still bites
  // without turning the run into a coin flip. The deflector shrinks instead,
  // which punishes sloppy positioning rather than human reflex limits.
  const BASE_SPEED = 5.0 * (1 + (diffMod-1)*0.45);
  const BASE_PAD_W = Math.round(84 - (diffMod-1)*22);

  const baseTime = 90;
  const adjustedTime = Math.round(baseTime * getTimeModifier());

  // Top rows are worth more, so the greedy line — digging a tunnel up the side
  // and letting the ball loose behind the wall — is also the high-scoring one.
  const ROW_COLORS = ['#ff0090','#a855f7','#00f5ff','#39ff14','#ffd700'];
  const ROW_PTS    = [22,19,16,13,10];

  const CHIPS = [
    { key:'wide',  glyph:'⬌', color:'#39ff14', label:'WIDE DEFLECTOR' },
    { key:'slow',  glyph:'⏱', color:'#00f5ff', label:'TIME DILATION' },
    { key:'bonus', glyph:'★', color:'#ffd700', label:'+50 DATA' }
  ];

  let score=0, time=adjustedTime, isOver=false;
  let shields=3, combo=0, bestCombo=0, broken=0, shake=0;
  let padX=W/2-BASE_PAD_W/2, padW=BASE_PAD_W, speed=BASE_SPEED;
  let moveL=false, moveR=false, keys={};
  let stuck=true, ball={x:0,y:0,vx:0,vy:0};
  let trail=[], chips=[], particles=[], floats=[];
  let wideUntil=0, slowUntil=0, nowMs=performance.now();

  document.getElementById('g-time').textContent=time;
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--purple),var(--cyan))';

  const bricks=[];
  for(let r=0;r<ROWS;r++) for(let c=0;c<COLS;c++){
    // Armoured ICE only appears once the core is unstable: the top row at
    // Overclock, the top two at Meltdown.
    const armour = (diffMod>=2 && r<2) || (diffMod>1 && r<1) ? 2 : 1;
    bricks.push({
      x:B_LEFT+c*(B_W+B_GAP), y:B_TOP+r*(B_H+B_GAP),
      hp:armour, maxHp:armour, color:ROW_COLORS[r], pts:ROW_PTS[r]
    });
  }

  const slide = x => { padX = Math.max(0, Math.min(W-padW, x)); };

  function burst(x,y,color,n){
    for(let i=0;i<n;i++){
      const a=Math.random()*Math.PI*2, v=Math.random()*3+1;
      particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,alpha:1,color});
    }
  }

  function launch(){
    if(isOver||!stuck) return;
    stuck=false;
    const ang=(Math.random()*0.5-0.25)+(Math.random()<0.5?-0.35:0.35);
    ball.vx=Math.sin(ang)*speed; ball.vy=-Math.cos(ang)*speed;
  }

  // ── STEERING ──
  // Mouse steers absolutely — the cursor IS the deflector, held button or not.
  // Touch steers *relatively* from wherever you grab, so tapping to launch
  // doesn't yank the deflector out from under the rally, and your hand never
  // has to sit on the board to move it. Decided per event, so a touchscreen
  // laptop gets both schemes rather than the finger one for its mouse.
  let lastX=null;
  bindCanvasDrag({
    onHover(p){ if(!p.touch) slide(p.x-padW/2); },
    onDown(p){ hideTouchHint(); lastX=p.x; if(!p.touch) slide(p.x-padW/2); launch(); },
    onMove(p){
      if(p.touch && lastX!==null) slide(padX+(p.x-lastX));
      else slide(p.x-padW/2);
      lastX=p.x;
    },
    onUp(){ lastX=null; }
  });

  // Each press shifts the deflector immediately as well as starting the glide —
  // hold-to-move alone makes a quick tap travel a couple of pixels and read as
  // a dead button, the same trap Pong's pad fell into.
  const NUDGE=26;
  bindHold(document.getElementById('ctrl-left'),
           ()=>{ slide(padX-NUDGE); moveL=true; },  ()=>moveL=false);
  bindHold(document.getElementById('ctrl-right'),
           ()=>{ slide(padX+NUDGE); moveR=true; },  ()=>moveR=false);
  document.getElementById('ctrl-action').onclick = launch;

  window.onkeydown=e=>{
    if(['Space','ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code)) e.preventDefault();
    keys[e.code]=true;
    if(e.code==='Space') launch();
  };
  window.onkeyup=e=>{ keys[e.code]=false; };

  gTimer=setInterval(()=>{
    if(isOver)return;
    time--; document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/adjustedTime*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0) end('timeout');
  },1000);

  function applyChip(ch){
    snd('powerup');
    if(ch.type.key==='wide') wideUntil=nowMs+8000;
    else if(ch.type.key==='slow') slowUntil=nowMs+6000;
    else { score+=50; setLive(score); }
    floats.push({x:padX+padW/2, y:PAD_Y-22, text:ch.type.label, color:ch.type.color, life:1});
    burst(ch.x, ch.y, ch.type.color, 8);
  }

  function hitBrick(b){
    b.hp--;
    if(b.hp>0){ burst(b.x+B_W/2, b.y+B_H/2, b.color, 4); snd('hit'); return; }
    broken++;
    combo++; if(combo>bestCombo) bestCombo=combo;
    // Chain climb: the shatter note rises with the combo the same way the score
    // does, so a tunnel run behind the wall sounds like the run it is.
    snd('brick',{semi:Math.min(14,combo-1)});
    // Every brick cleared before the ball comes home is worth more than the
    // last, so a well-aimed tunnel pays for itself — capped, because a ball
    // loose behind the wall can chain thirty bricks on its own and would
    // otherwise max the run without the player touching the deflector.
    const gain=b.pts+Math.min(combo-1,6)*2;
    score+=gain; setLive(score);
    burst(b.x+B_W/2, b.y+B_H/2, b.color, 10);
    floats.push({x:b.x+B_W/2, y:b.y+B_H/2, text:'+'+gain, color:b.color, life:1});
    if(Math.random()<0.12) chips.push({x:b.x+B_W/2, y:b.y+B_H/2, type:CHIPS[Math.floor(Math.random()*CHIPS.length)]});
    if(bricks.every(k=>k.hp<=0)){ score+=150; setLive(score); end('cleared'); }
  }

  function loseShield(){
    // 🛡️ Asked BEFORE the shield is decremented, so an absorbed loss costs
    // nothing at all — including the forty points an intact shield is worth
    // on the results card.
    if(shields<=1 && survivedFatal()){ combo=0; shake=14; stuck=true; trail=[]; return; }
    shields--; combo=0; shake=14;
    burst(ball.x, H-8, '#ff2442', 14);
    snd(shields<=0 ? 'gameOver' : 'hurt');
    if(shields<=0){ end('breached'); return; }
    stuck=true; trail=[];
  }

  // Sub-stepped so a fast ball can't tunnel straight through a brick row
  // between frames — at Meltdown it travels most of a brick's height per tick.
  function step(f){
    ball.x+=ball.vx*f; ball.y+=ball.vy*f;

    if(ball.x-BALL_R<0){ ball.x=BALL_R; ball.vx=Math.abs(ball.vx); snd('bounceWall'); }
    if(ball.x+BALL_R>W){ ball.x=W-BALL_R; ball.vx=-Math.abs(ball.vx); snd('bounceWall'); }
    if(ball.y-BALL_R<0){ ball.y=BALL_R; ball.vy=Math.abs(ball.vy); snd('bounceWall'); }

    // Deflector — the bounce angle comes off where you hit, not off the
    // incoming vector, so aiming is a real skill and the speed stays constant.
    if(ball.vy>0 && ball.y+BALL_R>=PAD_Y && ball.y-BALL_R<=PAD_Y+PAD_H &&
       ball.x>=padX-BALL_R && ball.x<=padX+padW+BALL_R){
      const rel=Math.max(-1,Math.min(1,(ball.x-(padX+padW/2))/(padW/2)));
      const ang=rel*1.05;                        // ±60° off vertical at the edges
      ball.vx=Math.sin(ang)*speed; ball.vy=-Math.cos(ang)*speed;
      ball.y=PAD_Y-BALL_R-0.5;
      combo=0;
      snd('bounce');
      burst(ball.x, PAD_Y, getEquippedColorHex(), 3);
    }

    for(const b of bricks){
      if(b.hp<=0) continue;
      if(ball.x+BALL_R<b.x || ball.x-BALL_R>b.x+B_W || ball.y+BALL_R<b.y || ball.y-BALL_R>b.y+B_H) continue;
      // Leave along the shallower overlap, i.e. back the way it came in —
      // flipping the wrong axis makes corner hits look like the ball
      // teleported through the wall.
      const oX=Math.min(ball.x+BALL_R-b.x, b.x+B_W-(ball.x-BALL_R));
      const oY=Math.min(ball.y+BALL_R-b.y, b.y+B_H-(ball.y-BALL_R));
      // Flipping the component isn't enough on its own — the ball is still
      // sitting inside the brick it just hit, so the next step finds another
      // overlap and flips again. Left alone it random-walks through the wall
      // eating it from the inside, and the run plays itself. Push it back out
      // along the axis it bounced on.
      if(oX<oY){ ball.vx=-ball.vx; ball.x += ball.x<b.x+B_W/2 ? -oX : oX; }
      else     { ball.vy=-ball.vy; ball.y += ball.y<b.y+B_H/2 ? -oY : oY; }
      hitBrick(b);
      break;                                     // one brick per step reads cleanly
    }

    if(ball.y-BALL_R>H) loseShield();
  }

  function end(reason){
    if(isOver)return; isOver=true;
    // Shields are worth points on the way out, so playing the last one
    // carefully beats throwing it away for one more brick.
    const survive=shields*40;
    const final=Math.min(1100,score+survive);
    showResults('breaker',final,{
      '📡 Run Terminated': reason==='cleared'?'ICE WALL CLEARED':reason==='timeout'?'CLOCK EXPIRED':'SHIELDS BREACHED',
      '🧊 ICE Shattered': `${broken}/${bricks.length}`,
      '🔥 Longest Chain': `${bestCombo}×`,
      '🛡️ Shields Intact': `${shields} (+${survive})`,
      '🏆 Score Accumulation': `${final} PTS`
    });
  }

  function draw(now){
    aCtx.clearRect(0,0,W,H);
    aCtx.save();
    if(shake>0){
      aCtx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake);
      shake*=0.86; if(shake<0.4) shake=0;
    }

    aCtx.strokeStyle='rgba(168,85,247,0.06)'; aCtx.lineWidth=1;
    for(let x=0;x<=W;x+=40){aCtx.beginPath();aCtx.moveTo(x,0);aCtx.lineTo(x,H);aCtx.stroke();}
    for(let y=0;y<=H;y+=40){aCtx.beginPath();aCtx.moveTo(0,y);aCtx.lineTo(W,y);aCtx.stroke();}

    bricks.forEach(b=>{
      if(b.hp<=0) return;
      const cracked=b.hp<b.maxHp;
      aCtx.save();
      aCtx.shadowBlur=cracked?6:12; aCtx.shadowColor=b.color;
      aCtx.globalAlpha=cracked?0.5:1;
      aCtx.fillStyle=b.color;
      aCtx.beginPath(); aCtx.roundRect(b.x,b.y,B_W,B_H,4); aCtx.fill();
      aCtx.shadowBlur=0;
      aCtx.fillStyle='rgba(255,255,255,0.28)';
      aCtx.fillRect(b.x+3,b.y+3,B_W-6,2);        // bevel — slabs, not flat rectangles
      if(cracked){
        aCtx.globalAlpha=1; aCtx.strokeStyle='rgba(0,0,0,0.55)'; aCtx.lineWidth=1.5;
        aCtx.beginPath();
        aCtx.moveTo(b.x+8,b.y+2);            aCtx.lineTo(b.x+B_W*0.42,b.y+B_H-3);
        aCtx.moveTo(b.x+B_W*0.42,b.y+B_H*0.5); aCtx.lineTo(b.x+B_W-7,b.y+3);
        aCtx.stroke();
      }
      aCtx.restore();
    });

    chips.forEach(ch=>{
      aCtx.save();
      aCtx.shadowBlur=14; aCtx.shadowColor=ch.type.color;
      aCtx.fillStyle=hexToRgba(ch.type.color,0.18);
      aCtx.strokeStyle=ch.type.color; aCtx.lineWidth=1.5;
      aCtx.beginPath(); aCtx.roundRect(ch.x-11,ch.y-9,22,18,5); aCtx.fill(); aCtx.stroke();
      aCtx.shadowBlur=0; aCtx.fillStyle=ch.type.color;
      aCtx.font='bold 11px Orbitron,monospace'; aCtx.textAlign='center'; aCtx.textBaseline='middle';
      aCtx.fillText(ch.type.glyph, ch.x, ch.y+1);
      aCtx.restore();
    });

    trail.forEach((t,i)=>{
      const a=(i+1)/trail.length*0.35;
      aCtx.save(); aCtx.globalAlpha=a; aCtx.fillStyle='#fff';
      aCtx.beginPath(); aCtx.arc(t.x,t.y,BALL_R*(0.35+a),0,Math.PI*2); aCtx.fill(); aCtx.restore();
    });

    const dilated=nowMs<slowUntil;
    aCtx.save();
    aCtx.shadowBlur=dilated?26:18; aCtx.shadowColor=dilated?'#00f5ff':'#fff';
    aCtx.fillStyle='#fff';
    aCtx.beginPath(); aCtx.arc(ball.x,ball.y,BALL_R,0,Math.PI*2); aCtx.fill();
    aCtx.restore();

    const padColor=getEquippedColorHex();
    aCtx.save(); aCtx.shadowBlur=20; aCtx.shadowColor=padColor; aCtx.fillStyle=padColor;
    aCtx.beginPath(); aCtx.roundRect(padX,PAD_Y,padW,PAD_H,5); aCtx.fill();
    aCtx.shadowBlur=0; aCtx.fillStyle='rgba(255,255,255,0.55)';
    aCtx.fillRect(padX+padW/2-8,PAD_Y+3,16,2);   // centre mark — hit here to send it straight up
    aCtx.restore();
    drawSkinBadge(padX+padW/2, PAD_Y-16, 12);

    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx; p.y+=p.vy; p.alpha-=0.045;
      if(p.alpha<=0){ particles.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=p.alpha; aCtx.fillStyle=p.color;
      aCtx.fillRect(p.x,p.y,3,3); aCtx.restore();
    }

    for(let i=floats.length-1;i>=0;i--){
      const f=floats[i];
      f.y-=0.6; f.life-=0.02;
      if(f.life<=0){ floats.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=Math.max(0,f.life);
      aCtx.fillStyle=f.color; aCtx.font='bold 0.6rem Orbitron,monospace'; aCtx.textAlign='center';
      aCtx.fillText(f.text,f.x,f.y); aCtx.restore();
    }

    // ── HUD ──
    for(let i=0;i<3;i++){
      const on=i<shields;
      aCtx.save();
      aCtx.globalAlpha=on?1:0.16; aCtx.fillStyle=on?'#00f5ff':'#fff';
      if(on){ aCtx.shadowBlur=10; aCtx.shadowColor='#00f5ff'; }
      aCtx.beginPath(); aCtx.roundRect(12+i*16,14,11,7,2); aCtx.fill();
      aCtx.restore();
    }
    if(combo>1){
      aCtx.save(); aCtx.shadowBlur=12; aCtx.shadowColor='#ffd700';
      aCtx.fillStyle='rgba(255,215,0,0.9)'; aCtx.font='bold 0.75rem Orbitron,monospace'; aCtx.textAlign='right';
      aCtx.fillText(`CHAIN ×${combo}`,W-12,22); aCtx.restore();
    }
    if(stuck){
      aCtx.save(); aCtx.globalAlpha=0.55+0.45*Math.sin(now*0.006);
      aCtx.fillStyle='#fff'; aCtx.font='bold 0.7rem Orbitron,monospace'; aCtx.textAlign='center';
      aCtx.fillText(isTouchDevice?'TAP TO LAUNCH':'SPACE TO LAUNCH',W/2,PAD_Y-42);
      aCtx.restore();
    }

    aCtx.restore();
  }

  function loop(now){
    if(isOver)return;
    gameLoopId=requestAnimationFrame(loop);
    nowMs=now;

    padW=Math.round(BASE_PAD_W*(now<wideUntil?1.45:1));
    // The wall creeps faster the emptier it gets, so a long run doesn't coast.
    speed=BASE_SPEED*(now<slowUntil?0.72:1)*(1+Math.min(0.25,broken*0.006));
    slide(padX);   // re-clamp: a WIDE chip can push the deflector past the edge

    const PAD_SPEED=7;
    if(keys['ArrowLeft'] ||keys['KeyA']||moveL) slide(padX-PAD_SPEED);
    if(keys['ArrowRight']||keys['KeyD']||moveR) slide(padX+PAD_SPEED);

    if(stuck){
      ball.x=padX+padW/2; ball.y=PAD_Y-BALL_R-2; ball.vx=0; ball.vy=0;
      trail=[];
    }else{
      const steps=Math.max(1,Math.ceil(speed/3));
      for(let s=0;s<steps;s++){ step(1/steps); if(isOver) return; if(stuck) break; }

      if(!stuck){
        // Brick bounces only flip components, so rounding would slowly drift the
        // rally off its intended speed — renormalise every frame instead.
        const sp=Math.hypot(ball.vx,ball.vy)||1;
        ball.vx=ball.vx/sp*speed; ball.vy=ball.vy/sp*speed;
        // And never let it settle into a near-horizontal groove it can't escape.
        if(Math.abs(ball.vy)<speed*0.30){
          ball.vy=(ball.vy<0?-1:1)*speed*0.30;
          ball.vx=(ball.vx<0?-1:1)*Math.sqrt(Math.max(0,speed*speed-ball.vy*ball.vy));
        }
        trail.push({x:ball.x,y:ball.y}); if(trail.length>10) trail.shift();
      }
    }

    for(let i=chips.length-1;i>=0;i--){
      const ch=chips[i];
      ch.y+=2.1;
      if(ch.y>H+12){ chips.splice(i,1); continue; }
      if(ch.y>PAD_Y-10 && ch.y<PAD_Y+PAD_H+10 && ch.x>padX-10 && ch.x<padX+padW+10){
        applyChip(ch); chips.splice(i,1);
      }
    }

    draw(now);
  }
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  ⚔️ GAME 12: CYBER ARENA (AVATAR SIMULATOR)
// ════════════════════════════════════════════
function startArena() {
  document.getElementById('g-canvas-holder').style.display = 'block';
  // The board is the controller on touch — drag to move, tap to slash — but
  // the original pad stays underneath it so the game is never unplayable, with
  // the spare slot carrying the ability that used to be keyboard-only.
  setControls(isTouchDevice ? { left:'◀', action:'⚔ SLASH', drop:'✦ ABIL', right:'▶' }
                            : { left:'◀', action:'⚔ SLASH', right:'▶' });
  // Hint text has to land before fitCanvas() measures — it's a header row, and
  // adding it afterwards pushes the board it just sized off the bottom.
  setControlHint('DRAG = MOVE · TAP = SLASH · DOUBLE-TAP = ABILITY · ⚡ = DASH',
                 'WASD/ARROWS=MOVE · SPACE=SLASH · SHIFT=DASH · E=ABILITY · AIM WITH MOUSE');
  showTouchHint('DRAG TO MOVE · TAP TO SLASH · DOUBLE-TAP = ABILITY', 4200);
  fitCanvas();

  // ── CONSTANTS ──
  const W = BOARD_W, H = BOARD_H;
  const ARENA_W = 800, ARENA_H = 900; // scrollable world larger than canvas
  const TILE = 40;

  // ── STATE ──
  let score = 0, isOver = false, frame = 0;
  let camX = 0, camY = 0;
  let particles = [], floatingTexts = [], enemyBots = [], dataNodes = [], walls = [];
  let xpOrbs = [];
  let playerLevel = 1, playerXP = 0, playerXPNext = 100;
  let dashCooldown = 0, dashTimer = 0, isDashing = false;
  let slashActive = false, slashTimer = 0, slashAngle = 0;
  let screenShake = 0;
  let keys = {}, moveLeft = false, moveRight = false, moveUp = false, moveDown = false;
  // ── VIRTUAL STICK ──
  // Touching the board plants an invisible thumbstick wherever the finger
  // lands; steering is the offset from that anchor. Only becomes a stick once
  // the finger clears the dead zone, so a clean tap still reads as a slash.
  const STICK_R = 46, STICK_DEAD = 14;
  let stickActive = false, stickX = 0, stickY = 0, stickOX = 0, stickOY = 0;
  let botSpawnTimer = 0, botWave = 1;
  let invincibleTimer = 0;
  let comboCount = 0, comboTimer = 0;
  // Temporary buffs picked up from data nodes
  let buffHasteTimer = 0, buffShieldTimer = 0, buffOverchargeTimer = 0;
  // Special abilities earned from CORE data nodes — queued, deployed with E / double-tap
  let specialAbilities = [];
  let lastTapTime = 0;
  const ABILITY_TYPES = [
    { id:'NOVA',       label:'NOVA BLAST',  color:'#ffd700', desc:'Damages & knocks back all nearby bots' },
    { id:'FREEZE',     label:'TIME FREEZE', color:'#00f5ff', desc:'Stuns every bot on the field' },
    { id:'HEAL',       label:'REPAIR PULSE',color:'#39ff14', desc:'Instantly restores HP' },
    { id:'OVERCHARGE', label:'OVERCHARGE',  color:'#ff2442', desc:'Boosts attack & speed for a few seconds' },
    { id:'SHIELD',     label:'AEGIS SHIELD',color:'#a855f7', desc:'Grants temporary invincibility' },
  ];
  function deployAbility() {
    if (specialAbilities.length === 0) return;
    const abil = specialAbilities.shift();
    screenShake = 10;
    snd(abil.id === 'NOVA' ? 'bigExplode' : abil.id === 'HEAL' ? 'heal' : 'ability');
    popText(player.x, player.y - 34, abil.label + '!', abil.color);
    if (abil.id === 'NOVA') {
      enemyBots.forEach(bot => {
        if (bot.dead) return;
        const dx = bot.x - player.x, dy = bot.y - player.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 220) {
          const dmg = Math.round((player.attackPower + (playerLevel - 1) * 5) * 1.3);
          bot.hp -= dmg;
          bot.vx += (dx / (dist || 1)) * 8; bot.vy += (dy / (dist || 1)) * 8;
          bot.stunTimer = 20;
          explode(bot.x, bot.y, abil.color, 10);
          popText(bot.x, bot.y - 14, `-${dmg}`, abil.color);
          if (bot.hp <= 0 && !bot.dead) {
            bot.dead = true;
            const earned = Math.round(bot.pts * (1 + (playerLevel - 1) * 0.1));
            score += earned; setLive(score);
            explode(bot.x, bot.y, bot.color, 18);
          }
        }
      });
      explode(player.x, player.y, abil.color, 30);
    } else if (abil.id === 'FREEZE') {
      enemyBots.forEach(bot => { if (!bot.dead) bot.stunTimer = 150; });
      explode(player.x, player.y, abil.color, 20);
    } else if (abil.id === 'HEAL') {
      player.hp = Math.min(player.maxHp, player.hp + player.maxHp * 0.5);
      document.getElementById('prog-fill').style.width = `${(player.hp / player.maxHp) * 100}%`;
      explode(player.x, player.y, abil.color, 20);
    } else if (abil.id === 'OVERCHARGE') {
      buffOverchargeTimer = 360; buffHasteTimer = 360;
      explode(player.x, player.y, abil.color, 20);
    } else if (abil.id === 'SHIELD') {
      buffShieldTimer = 240;
      explode(player.x, player.y, abil.color, 20);
    }
  }

  // ── PLAYER ──
  const player = {
    x: ARENA_W / 2, y: ARENA_H / 2,
    r: 14, hp: 100, maxHp: 100,
    speed: 3.2,
    vx: 0, vy: 0,
    angle: 0,    // facing direction
    color: '#00f5ff',
    slashRange: 60,
    slashDamage: 35,
    slashCooldown: 0,
    attackPower: 35,
    get canSlash() { return this.slashCooldown <= 0 && !isDashing; }
  };

  // ── PROGRESS BAR = PLAYER HP ──
  document.getElementById('g-time').textContent = '∞';
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--cyan),var(--purple))';
  document.getElementById('prog-fill').style.width = '100%';

  // ── WORLD GENERATION ──
  // Scatter walls (obstacles / cover)
  const wallDefs = [
    {x:120,y:80,w:80,h:20},{x:300,y:80,w:80,h:20},{x:560,y:80,w:80,h:20},
    {x:60,y:200,w:20,h:80},{x:220,y:180,w:60,h:20},{x:400,y:200,w:20,h:80},
    {x:600,y:160,w:20,h:100},{x:700,y:80,w:20,h:80},
    {x:100,y:340,w:100,h:20},{x:320,y:300,w:20,h:100},{x:500,y:340,w:100,h:20},
    {x:680,y:300,w:20,h:80},
    {x:60,y:460,w:80,h:20},{x:240,y:420,w:20,h:100},{x:380,y:460,w:100,h:20},
    {x:560,y:440,w:20,h:80},{x:700,y:440,w:60,h:20},
    {x:120,y:580,w:60,h:20},{x:300,y:560,w:80,h:20},{x:480,y:580,w:20,h:80},
    {x:640,y:580,w:80,h:20},
    {x:80,y:700,w:20,h:80},{x:200,y:680,w:80,h:20},{x:380,y:700,w:80,h:20},
    {x:560,y:700,w:20,h:60},{x:680,y:680,w:80,h:20},
    {x:120,y:820,w:80,h:20},{x:340,y:800,w:20,h:80},{x:500,y:820,w:80,h:20},
    {x:700,y:820,w:20,h:60},
  ];
  walls = wallDefs;

  // Initial data node scatter
  // Weighted node type pool — mostly plain DATA, with rarer utility/buff/ability nodes
  const NODE_POOL = [
    { type:'DATA',       weight:58 },
    { type:'MEGA',       weight:14 },
    { type:'HEAL',       weight:10 },
    { type:'HASTE',      weight:7  },
    { type:'OVERCHARGE', weight:6  },
    { type:'SHIELD',     weight:4  },
    { type:'CORE',       weight:3  },
  ];
  function pickNodeType() {
    const totalW = NODE_POOL.reduce((s, n) => s + n.weight, 0);
    let r = Math.random() * totalW;
    for (const n of NODE_POOL) { r -= n.weight; if (r <= 0) return n.type; }
    return 'DATA';
  }
  function spawnDataNodes(count) {
    for (let i = 0; i < count; i++) {
      let nx, ny, attempts = 0;
      do {
        nx = Math.random() * (ARENA_W - 60) + 30;
        ny = Math.random() * (ARENA_H - 60) + 30;
        attempts++;
      } while (attempts < 20 && isCollidingWall(nx, ny, 10));
      dataNodes.push({
        x: nx, y: ny, r: 9,
        type: pickNodeType(),
        pulse: Math.random() * Math.PI * 2,
        collected: false
      });
    }
  }
  spawnDataNodes(22);

  // ── COLLISION HELPERS ──
  function isCollidingWall(cx, cy, cr) {
    return walls.some(w =>
      cx + cr > w.x && cx - cr < w.x + w.w &&
      cy + cr > w.y && cy - cr < w.y + w.h
    );
  }
  function resolveWall(obj, cr) {
    walls.forEach(w => {
      if (obj.x + cr > w.x && obj.x - cr < w.x + w.w &&
          obj.y + cr > w.y && obj.y - cr < w.y + w.h) {
        // Push out: find smallest overlap axis
        const overlapL = (obj.x + cr) - w.x;
        const overlapR = (w.x + w.w) - (obj.x - cr);
        const overlapT = (obj.y + cr) - w.y;
        const overlapB = (w.y + w.h) - (obj.y - cr);
        const minO = Math.min(overlapL, overlapR, overlapT, overlapB);
        if (minO === overlapL) obj.x -= overlapL;
        else if (minO === overlapR) obj.x += overlapR;
        else if (minO === overlapT) obj.y -= overlapT;
        else obj.y += overlapB;
      }
    });
  }

  // ── ENEMY BOT CLASS ──
  const BOT_TYPES = [
    { id:'GRUNT',    color:'#ff0090', r:12, speed:1.5, hp:40,  maxHp:40,  dmg:12, pts:20,  xp:15,  label:'GRUNT'    },
    { id:'CHASER',   color:'#ff6600', r:11, speed:2.6, hp:25,  maxHp:25,  dmg:8,  pts:30,  xp:20,  label:'CHASER'   },
    { id:'TANK',     color:'#a855f7', r:18, speed:0.9, hp:120, maxHp:120, dmg:20, pts:60,  xp:50,  label:'TANK'     },
    { id:'SNIPER',   color:'#ffd700', r:10, speed:1.8, hp:30,  maxHp:30,  dmg:15, pts:40,  xp:35,  label:'SNIPER'   },
    { id:'ELITE',    color:'#ff2442', r:14, speed:2.0, hp:80,  maxHp:80,  dmg:25, pts:100, xp:80,  label:'ELITE'    },
    { id:'SWARMER',  color:'#39ff14', r:8,  speed:3.4, hp:15,  maxHp:15,  dmg:6,  pts:15,  xp:10,  label:'SWARMER'  },
    { id:'BOMBER',   color:'#ff6600', r:13, speed:1.7, hp:35,  maxHp:35,  dmg:35, pts:50,  xp:30,  label:'BOMBER'   },
    { id:'SHIELDER', color:'#00f5ff', r:15, speed:1.1, hp:70,  maxHp:70,  dmg:14, pts:70,  xp:45,  label:'SHIELDER' },
    { id:'HEALER',   color:'#ff90e8', r:11, speed:1.3, hp:35,  maxHp:35,  dmg:6,  pts:55,  xp:40,  label:'HEALER'   },
  ];

  class Bot {
    constructor(type, x, y) {
      Object.assign(this, type);
      this.x = x; this.y = y;
      this.vx = 0; this.vy = 0;
      this.hp = type.hp; this.maxHp = type.maxHp;
      this.angle = 0;
      this.attackTimer = 0;
      this.attackCooldown = type.id === 'SNIPER' ? 180 : type.id === 'TANK' ? 90 : 60;
      this.projectile = null;
      this.stunTimer = 0;
      this.aggroRadius = type.id === 'SNIPER' ? 280 : 200;
      this.wobble = Math.random() * Math.PI * 2;
      this.dead = false;
      this.deathTimer = 0;
      // ── per-type extras ──
      this.jitterTimer = 0; // SWARMER erratic movement
      this.healCooldown = 90; // HEALER
      this.exploded = false; // BOMBER
      this.shieldAngle = Math.random() * Math.PI * 2; // SHIELDER — rotates slowly, must be flanked
    }

    update() {
      if (this.dead) { this.deathTimer++; return; }
      if (this.stunTimer > 0) { this.stunTimer--; return; }

      const dx = player.x - this.x, dy = player.y - this.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      this.angle = Math.atan2(dy, dx);
      this.wobble += 0.05;
      if (this.id === 'SHIELDER') this.shieldAngle += 0.018; // shield slowly rotates — flank it to land full damage

      const warpMult = 1.0; // future: can tie into time warp
      const inRange = true; // bots always actively chase/attack the player, regardless of distance

      if (inRange) {
        if (this.id === 'SNIPER' && dist > 120) {
          // Sniper keeps distance
          this.vx += (dx / dist) * this.speed * 0.3;
          this.vy += (dy / dist) * this.speed * 0.3;
        } else if (this.id === 'HEALER' && dist < 160) {
          // Healer keeps its distance from the player, preferring to hover near allies
          this.vx -= (dx / dist) * this.speed * 0.3;
          this.vy -= (dy / dist) * this.speed * 0.3;
        } else if (this.id === 'SWARMER') {
          // Swarmer darts erratically while closing in
          this.jitterTimer--;
          if (this.jitterTimer <= 0) {
            this.jitterTimer = 10 + Math.random() * 14;
            const jitterAngle = Math.atan2(dy, dx) + (Math.random() - 0.5) * 1.6;
            this.vx += Math.cos(jitterAngle) * this.speed * 0.4;
            this.vy += Math.sin(jitterAngle) * this.speed * 0.4;
          }
          this.vx += (dx / dist) * this.speed * 0.22;
          this.vy += (dy / dist) * this.speed * 0.22;
        } else {
          this.vx += (dx / dist) * this.speed * 0.25;
          this.vy += (dy / dist) * this.speed * 0.25;
        }

        // BOMBER: charge in and self-destruct in a damaging blast
        if (this.id === 'BOMBER' && !this.exploded) {
          if (dist < this.r + player.r + 26) {
            this.exploded = true;
            this.dead = true;
            this.deathTimer = 0;
            explode(this.x, this.y, this.color, 26);
            popText(this.x, this.y - 10, 'BOOM!', '#ff6600');
            const bdx = player.x - this.x, bdy = player.y - this.y;
            const bdist = Math.sqrt(bdx * bdx + bdy * bdy) || 1;
            if (bdist < 70) hitPlayer(this.dmg, this.color);
          }
        }

        // HEALER: periodically pulse-heal the most wounded nearby ally
        if (this.id === 'HEALER') {
          this.healCooldown--;
          if (this.healCooldown <= 0) {
            this.healCooldown = 150;
            let target = null, lowestPct = 1;
            enemyBots.forEach(ally => {
              if (ally === this || ally.dead) return;
              const adx = ally.x - this.x, ady = ally.y - this.y;
              if (Math.sqrt(adx * adx + ady * ady) > 180) return;
              const pct = ally.hp / ally.maxHp;
              if (pct < 1 && pct < lowestPct) { lowestPct = pct; target = ally; }
            });
            if (target) {
              target.hp = Math.min(target.maxHp, target.hp + target.maxHp * 0.3);
              popText(target.x, target.y - target.r - 14, '+HEAL', '#ff90e8');
              explode(target.x, target.y, '#ff90e8', 8);
            }
          }
        }

        // Attack logic
        this.attackTimer++;
        if (this.attackTimer >= this.attackCooldown) {
          this.attackTimer = 0;
          if (this.id === 'SNIPER' || this.id === 'ELITE') {
            // Fire projectile
            const speed = this.id === 'ELITE' ? 5.5 : 4.2;
            botProjectiles.push({
              x: this.x, y: this.y,
              vx: (dx / dist) * speed, vy: (dy / dist) * speed,
              r: 5, color: this.color, dmg: this.dmg,
              alpha: 1, trail: []
            });
          } else if (this.id !== 'BOMBER' && this.id !== 'HEALER' && dist < this.r + player.r + 20) {
            // Melee
            hitPlayer(this.dmg, this.color);
          }
        }
      }

      // Friction + friction-limit speed
      this.vx *= 0.78; this.vy *= 0.78;
      const spd = Math.sqrt(this.vx * this.vx + this.vy * this.vy);
      if (spd > this.speed * warpMult) {
        this.vx = (this.vx / spd) * this.speed * warpMult;
        this.vy = (this.vy / spd) * this.speed * warpMult;
      }
      this.x += this.vx; this.y += this.vy;
      // Arena bounds
      this.x = Math.max(this.r, Math.min(ARENA_W - this.r, this.x));
      this.y = Math.max(this.r, Math.min(ARENA_H - this.r, this.y));
      resolveWall(this, this.r);

      // Direct melee collision with player
      if (dist < this.r + player.r + 4 && this.id !== 'SNIPER' && this.id !== 'ELITE' && this.id !== 'BOMBER' && this.id !== 'HEALER') {
        if (this.attackTimer <= 0) {
          this.attackTimer = this.attackCooldown * 0.6;
          hitPlayer(this.dmg * 0.4, this.color);
        }
      }
    }

    draw(cx, cy) {
      if (this.dead) return;
      aCtx.save();
      aCtx.translate(cx, cy);

      // Bot body
      const pulse = 0.85 + Math.sin(this.wobble) * 0.15;
      aCtx.shadowBlur = 14 * pulse;
      aCtx.shadowColor = this.color;

      if (this.id === 'TANK') {
        // Chunky hexagon
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2 - Math.PI / 6;
          i === 0 ? aCtx.moveTo(Math.cos(a) * this.r, Math.sin(a) * this.r)
                  : aCtx.lineTo(Math.cos(a) * this.r, Math.sin(a) * this.r);
        }
        aCtx.closePath(); aCtx.fill();
        // Armor detail
        aCtx.strokeStyle = 'rgba(255,255,255,0.3)'; aCtx.lineWidth = 2;
        aCtx.stroke();
      } else if (this.id === 'SNIPER') {
        // Diamond + crosshair
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.beginPath();
        aCtx.moveTo(0, -this.r); aCtx.lineTo(this.r, 0);
        aCtx.lineTo(0, this.r); aCtx.lineTo(-this.r, 0);
        aCtx.closePath(); aCtx.fill();
        // Barrel
        aCtx.strokeStyle = this.color; aCtx.lineWidth = 3;
        aCtx.beginPath();
        aCtx.moveTo(0, 0);
        aCtx.lineTo(Math.cos(this.angle) * (this.r + 14), Math.sin(this.angle) * (this.r + 14));
        aCtx.stroke();
      } else if (this.id === 'ELITE') {
        // Star shape
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.beginPath();
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          const r2 = i % 2 === 0 ? this.r : this.r * 0.55;
          i === 0 ? aCtx.moveTo(Math.cos(a) * r2, Math.sin(a) * r2)
                  : aCtx.lineTo(Math.cos(a) * r2, Math.sin(a) * r2);
        }
        aCtx.closePath(); aCtx.fill();
        // Rotating ring
        aCtx.strokeStyle = `rgba(255,36,66,${0.4 + pulse * 0.4})`; aCtx.lineWidth = 1.5;
        aCtx.beginPath(); aCtx.arc(0, 0, this.r + 6, 0, Math.PI * 2); aCtx.stroke();
      } else if (this.id === 'SWARMER') {
        // Tiny sharp triangle, always pointed toward the player
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.save(); aCtx.rotate(this.angle);
        aCtx.beginPath();
        aCtx.moveTo(this.r * 1.3, 0);
        aCtx.lineTo(-this.r * 0.8, this.r * 0.8);
        aCtx.lineTo(-this.r * 0.8, -this.r * 0.8);
        aCtx.closePath(); aCtx.fill();
        aCtx.restore();
      } else if (this.id === 'BOMBER') {
        // Spiky bomb that flashes faster the closer it gets
        const flash = Math.sin(this.wobble * 3) > 0;
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : (flash ? '#fff' : this.color);
        aCtx.beginPath(); aCtx.arc(0, 0, this.r, 0, Math.PI * 2); aCtx.fill();
        aCtx.strokeStyle = this.color; aCtx.lineWidth = 2;
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          aCtx.beginPath();
          aCtx.moveTo(Math.cos(a) * this.r, Math.sin(a) * this.r);
          aCtx.lineTo(Math.cos(a) * (this.r + 6), Math.sin(a) * (this.r + 6));
          aCtx.stroke();
        }
      } else if (this.id === 'SHIELDER') {
        // Core body
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : '#0d3a3f';
        aCtx.beginPath(); aCtx.arc(0, 0, this.r, 0, Math.PI * 2); aCtx.fill();
        aCtx.strokeStyle = this.color; aCtx.lineWidth = 1.5; aCtx.stroke();
        // Rotating shield arc — reduces damage taken from this side, must be flanked
        aCtx.strokeStyle = this.color; aCtx.lineWidth = 5;
        aCtx.shadowBlur = 16; aCtx.shadowColor = this.color;
        aCtx.beginPath();
        aCtx.arc(0, 0, this.r + 6, this.shieldAngle - Math.PI * 0.4, this.shieldAngle + Math.PI * 0.4);
        aCtx.stroke();
      } else if (this.id === 'HEALER') {
        // Circle with a cross, pulsing when about to heal
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.beginPath(); aCtx.arc(0, 0, this.r, 0, Math.PI * 2); aCtx.fill();
        aCtx.fillStyle = '#fff';
        aCtx.fillRect(-2, -this.r * 0.6, 4, this.r * 1.2);
        aCtx.fillRect(-this.r * 0.6, -2, this.r * 1.2, 4);
        if (this.healCooldown < 20) {
          aCtx.strokeStyle = `rgba(255,144,232,${1 - this.healCooldown / 20})`;
          aCtx.lineWidth = 2;
          aCtx.beginPath(); aCtx.arc(0, 0, this.r + 8, 0, Math.PI * 2); aCtx.stroke();
        }
      } else {
        // GRUNT / CHASER — circle with direction indicator
        aCtx.fillStyle = this.stunTimer > 0 ? '#888' : this.color;
        aCtx.beginPath(); aCtx.arc(0, 0, this.r, 0, Math.PI * 2); aCtx.fill();
        // Direction nub
        aCtx.fillStyle = 'rgba(0,0,0,0.5)';
        aCtx.beginPath();
        aCtx.arc(Math.cos(this.angle) * (this.r * 0.55), Math.sin(this.angle) * (this.r * 0.55), 4, 0, Math.PI * 2);
        aCtx.fill();
      }

      // HP bar
      const barW = this.r * 2.4, barH = 4;
      const bx = -barW / 2, by = -this.r - 9;
      aCtx.fillStyle = 'rgba(0,0,0,0.6)';
      aCtx.fillRect(bx, by, barW, barH);
      const hpPct = this.hp / this.maxHp;
      aCtx.fillStyle = hpPct > 0.5 ? '#39ff14' : hpPct > 0.25 ? '#ffd700' : '#ff2442';
      aCtx.shadowBlur = 0;
      aCtx.fillRect(bx, by, barW * hpPct, barH);

      aCtx.restore();
    }
  }

  let botProjectiles = [];

  // ── SPAWN BOTS ──
  function spawnBot() {
    // Pick a spawn point far from player
    let bx, by, attempts = 0;
    do {
      const edge = Math.floor(Math.random() * 4);
      if (edge === 0) { bx = Math.random() * ARENA_W; by = -20; }
      else if (edge === 1) { bx = ARENA_W + 20; by = Math.random() * ARENA_H; }
      else if (edge === 2) { bx = Math.random() * ARENA_W; by = ARENA_H + 20; }
      else { bx = -20; by = Math.random() * ARENA_H; }
      attempts++;
    } while (attempts < 15 && Math.hypot(bx - player.x, by - player.y) < 200);

    // Clamp into arena bounds with margin
    bx = Math.max(30, Math.min(ARENA_W - 30, bx));
    by = Math.max(30, Math.min(ARENA_H - 30, by));

    // Pick type by wave — pool grows with wave for more variety over time
    const byId = id => BOT_TYPES.find(t => t.id === id);
    let typePool;
    if (botWave <= 1) typePool = [byId('GRUNT'), byId('CHASER'), byId('SWARMER')];
    else if (botWave <= 2) typePool = [byId('GRUNT'), byId('CHASER'), byId('SWARMER'), byId('SNIPER')];
    else if (botWave <= 3) typePool = [byId('GRUNT'), byId('CHASER'), byId('SWARMER'), byId('SNIPER'), byId('BOMBER')];
    else if (botWave <= 4) typePool = [byId('GRUNT'), byId('CHASER'), byId('SWARMER'), byId('SNIPER'), byId('BOMBER'), byId('TANK')];
    else if (botWave <= 5) typePool = [byId('GRUNT'), byId('CHASER'), byId('SWARMER'), byId('SNIPER'), byId('BOMBER'), byId('TANK'), byId('SHIELDER')];
    else typePool = BOT_TYPES; // full roster, ELITE and HEALER join in
    const type = typePool[Math.floor(Math.random() * typePool.length)];
    enemyBots.push(new Bot(type, bx, by));
  }

  // Initial bots
  for (let i = 0; i < 4; i++) spawnBot();

  // ── HELPER: PLAYER HIT ──
  function hitPlayer(dmg, color) {
    if (invincibleTimer > 0 || buffShieldTimer > 0) return;
    player.hp = Math.max(0, player.hp - dmg);
    invincibleTimer = 30;
    screenShake = 8;
    snd('hurt');
    // Flash particles
    for (let i = 0; i < 6; i++) {
      const a = Math.random() * Math.PI * 2, v = Math.random() * 3 + 1;
      particles.push({ x: player.x, y: player.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, alpha: 1, decay: 0.07, color: color || '#ff2442', size: 3 });
    }
    // Update HP bar
    document.getElementById('prog-fill').style.width = `${(player.hp / player.maxHp) * 100}%`;
    const hpPct = player.hp / player.maxHp;
    document.getElementById('prog-fill').style.background =
      hpPct > 0.5 ? 'linear-gradient(90deg,var(--cyan),var(--purple))'
      : hpPct > 0.25 ? 'linear-gradient(90deg,var(--gold),var(--orange))'
      : 'linear-gradient(90deg,var(--red),#ff6600)';

    // 🛡️ Forty percent of maximum, not one hit point: the arena's bots are
    // already on top of you by the time you die, and a revive at 1 HP is a
    // shield spent on half a second.
    if (player.hp <= 0 && survivedFatal()) player.hp = Math.max(1, Math.round(player.maxHp * 0.4));
    if (player.hp <= 0) endArena();
  }

  // ── HELPER: FLOATING TEXT ──
  function popText(x, y, text, color) {
    floatingTexts.push({ x, y, text, color, alpha: 1, vy: -1.4, life: 0 });
  }

  // ── HELPER: EXPLODE PARTICLES ──
  function explode(x, y, color, count = 10) {
    for (let i = 0; i < count; i++) {
      const a = (i / count) * Math.PI * 2 + Math.random() * 0.5;
      const v = Math.random() * 4 + 1.5;
      particles.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, alpha: 1, decay: 0.035 + Math.random() * 0.02, color, size: Math.random() * 3 + 1 });
    }
  }

  // ── PLAYER SLASH ──
  function doSlash() {
    if (!player.canSlash) return;
    slashActive = true;
    slashTimer = 14;
    slashAngle = player.angle;
    player.slashCooldown = 28;
    screenShake = 3;
    snd('slash');
    // Check hit on bots
    let hitAny = false;
    enemyBots.forEach(bot => {
      if (bot.dead) return;
      const dx = bot.x - player.x, dy = bot.y - player.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < player.slashRange + bot.r) {
        // Check angle cone (~120° arc)
        const angleToBot = Math.atan2(dy, dx);
        let diff = angleToBot - slashAngle;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        if (Math.abs(diff) < Math.PI * 0.67) {
          let dmg = player.attackPower + (playerLevel - 1) * 5 + (buffOverchargeTimer > 0 ? 20 : 0);
          let blocked = false;
          if (bot.id === 'SHIELDER') {
            // Hits landing on the shielded side are heavily reduced — flank for full damage
            let sdiff = angleToBot - bot.shieldAngle;
            while (sdiff > Math.PI) sdiff -= Math.PI * 2;
            while (sdiff < -Math.PI) sdiff += Math.PI * 2;
            if (Math.abs(sdiff) < Math.PI * 0.4) { dmg = Math.round(dmg * 0.2); blocked = true; }
          }
          dmg = Math.round(dmg);
          bot.hp -= dmg;
          bot.stunTimer = 12;
          hitAny = true;
          explode(bot.x, bot.y, blocked ? '#00f5ff' : bot.color, blocked ? 3 : 6);
          snd(blocked ? 'bounceWall' : 'hit');
          popText(bot.x, bot.y - 14, blocked ? `-${dmg} (BLOCKED)` : `-${dmg}`, blocked ? '#00f5ff' : '#ff2442');
          // Combo
          comboCount++;
          comboTimer = 120;
          if (comboCount >= 3) {
            const bonus = comboCount * 5;
            score += bonus;
            snd('combo', { semi: Math.min(12, comboCount - 3) });
            popText(bot.x, bot.y - 28, `${comboCount}x COMBO! +${bonus}`, '#ffd700');
          }
          if (bot.hp <= 0 && !bot.dead) {
            bot.dead = true;
            const earned = bot.pts * (1 + (playerLevel - 1) * 0.1);
            score += Math.round(earned);
            setLive(score);
            explode(bot.x, bot.y, bot.color, 18);
            snd('explode');
            popText(bot.x, bot.y, `+${Math.round(earned)}`, '#ffd700');
            // Drop XP orbs
            for (let i = 0; i < 3; i++) {
              const a = Math.random() * Math.PI * 2, v = Math.random() * 2 + 1;
              xpOrbs.push({ x: bot.x, y: bot.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, r: 5, xp: Math.round(bot.xp / 3), color: bot.color, alpha: 1 });
            }
          }
        }
      }
    });
    if (!hitAny) {
      // Slash particles in arc direction regardless
      for (let i = -3; i <= 3; i++) {
        const a = slashAngle + i * 0.2, v = 5;
        particles.push({ x: player.x, y: player.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, alpha: 0.9, decay: 0.1, color: '#00f5ff', size: 2 });
      }
    }
  }

  // ── PLAYER DASH ──
  function doDash() {
    if (dashCooldown > 0) return;
    isDashing = true;
    dashTimer = 12;
    dashCooldown = 70;
    invincibleTimer = 12;
    // Dash in facing direction
    player.vx = Math.cos(player.angle) * 12;
    player.vy = Math.sin(player.angle) * 12;
    snd('dash');
    explode(player.x, player.y, '#00f5ff', 8);
  }

  // ── XP & LEVEL UP ──
  function gainXP(amount) {
    playerXP += amount;
    if (playerXP >= playerXPNext) {
      playerXP -= playerXPNext;
      playerLevel++;
      playerXPNext = Math.round(playerXPNext * 1.45);
      player.maxHp += 20;
      player.hp = Math.min(player.maxHp, player.hp + 30);
      player.attackPower += 8;
      player.speed = Math.min(5, player.speed + 0.15);
      screenShake = 15;
      snd('levelUp');
      popText(player.x, player.y - 30, `⬆ LEVEL ${playerLevel}!`, '#ffd700');
      explode(player.x, player.y, '#ffd700', 30);
      document.getElementById('prog-fill').style.width = `${(player.hp / player.maxHp) * 100}%`;
      toast(`⬆ LEVEL UP! Now Level ${playerLevel}`, 2000);
      botWave = playerLevel;
    }
  }

  // ── END GAME ──
  function endArena() {
    if (isOver) return;
    isOver = true;
    snd('gameOver');
    showResults('arena', score, {
      '⚔️ Bots Eliminated': enemyBots.filter(b => b.dead).length,
      '📡 Data Nodes Collected': Math.floor(score / 20),
      '🎖️ Arena Level Reached': playerLevel,
      '🏆 Final Score': `${score} PTS`
    });
  }

  // ── CONTROLS ──
  window.onkeydown = e => {
    keys[e.code] = true;
    if (e.code === 'Space') { e.preventDefault(); doSlash(); }
    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') { e.preventDefault(); doDash(); }
    if (e.code === 'KeyE') { e.preventDefault(); deployAbility(); }
    if (['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)) e.preventDefault();
  };
  window.onkeyup = e => { keys[e.code] = false; };

  // Pad controls. Same on both: hold to strafe, tap to slash. Touch gets the
  // extra ABILITY key, which was E-only before. Pressing a direction clears any
  // stale stick claim so a gesture the browser cut off can't jam the buttons.
  bindHold(document.getElementById('ctrl-left'),
           ()=>{ stickActive=false; stickX=stickY=0; moveLeft=true; },  ()=>moveLeft=false);
  bindHold(document.getElementById('ctrl-right'),
           ()=>{ stickActive=false; stickX=stickY=0; moveRight=true; }, ()=>moveRight=false);
  document.getElementById('ctrl-action').onclick = () => doSlash();
  const abilBtn = document.getElementById('ctrl-drop');
  if (abilBtn) abilBtn.onclick = () => deployAbility();

  // ── BOARD GESTURES ──
  // Drag = move (and face where you're heading). Tap = slash toward the point
  // you tapped. Double-tap = deploy the queued ability, same as KeyE.
  let tapT = 0, tapX = 0, tapY = 0;
  bindCanvasDrag({
    // Mouse hover keeps free aiming; a coarse pointer has no hover to speak of.
    onHover(p){
      if (isTouchDevice) return;
      player.angle = Math.atan2((p.y + camY) - player.y, (p.x + camX) - player.x);
    },
    onDown(p){
      hideTouchHint();
      tapT = performance.now(); tapX = p.x; tapY = p.y;
      stickOX = p.x; stickOY = p.y; stickActive = false; stickX = stickY = 0;
    },
    onMove(p){
      const dx = p.x - stickOX, dy = p.y - stickOY;
      const dist = Math.hypot(dx, dy);
      if (dist < STICK_DEAD) {
        if (!stickActive) return;          // still inside the tap dead zone
        stickX = stickY = 0;
        return;
      }
      stickActive = true;
      stickX = dx / dist; stickY = dy / dist;
      player.angle = Math.atan2(dy, dx);   // you face where you're running
      // Let the anchor trail the finger so the stick never runs out of throw
      // on a long drag across the board.
      if (dist > STICK_R) {
        stickOX = p.x - stickX * STICK_R;
        stickOY = p.y - stickY * STICK_R;
      }
    },
    onUp(p){
      const wasStick = stickActive;
      stickActive = false; stickX = stickY = 0;
      if (wasStick) return;                // that was steering, not a tap
      if (performance.now() - tapT > 320) return;
      if (Math.hypot(p.x - tapX, p.y - tapY) > STICK_DEAD) return;

      const now = Date.now();
      if (now - lastTapTime < 320) { deployAbility(); lastTapTime = 0; return; }
      lastTapTime = now;
      // Aim at what you tapped, unless you tapped yourself — then keep facing.
      const sx = player.x - camX, sy = player.y - camY;
      if (Math.hypot(p.x - sx, p.y - sy) > 12) {
        player.angle = Math.atan2((p.y + camY) - player.y, (p.x + camX) - player.x);
      }
      doSlash();
    }
  });

  // Virtual stick overlay — drawn only while a finger is steering, so it never
  // sits on the board as clutter.
  function drawTouchStick(){
    if (!stickActive) return;
    aCtx.save();
    aCtx.strokeStyle = '#00f5ff'; aCtx.lineWidth = 2;
    aCtx.shadowBlur = 12; aCtx.shadowColor = '#00f5ff';
    aCtx.globalAlpha = 0.45;
    aCtx.beginPath(); aCtx.arc(stickOX, stickOY, STICK_R, 0, Math.PI * 2); aCtx.stroke();
    aCtx.globalAlpha = 0.8;
    aCtx.beginPath();
    aCtx.arc(stickOX + stickX * STICK_R, stickOY + stickY * STICK_R, 15, 0, Math.PI * 2);
    aCtx.fillStyle = 'rgba(0,245,255,0.25)'; aCtx.fill(); aCtx.stroke();
    aCtx.restore();
  }

  // ── WORLD TILE COLORS (cyber grid) ──
  function drawWorld() {
    const cols = Math.ceil(W / TILE) + 2;
    const rows = Math.ceil(H / TILE) + 2;
    const startX = Math.floor(camX / TILE) * TILE - camX;
    const startY = Math.floor(camY / TILE) * TILE - camY;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const tx = Math.floor(camX / TILE) + c;
        const ty = Math.floor(camY / TILE) + r;
        const isDark = (tx + ty) % 2 === 0;
        aCtx.fillStyle = isDark ? '#04040e' : '#060610';
        aCtx.fillRect(startX + c * TILE, startY + r * TILE, TILE, TILE);
      }
    }
    // Grid lines
    aCtx.strokeStyle = 'rgba(0,245,255,0.035)'; aCtx.lineWidth = 1;
    for (let c = 0; c < cols; c++) {
      aCtx.beginPath();
      aCtx.moveTo(startX + c * TILE, 0); aCtx.lineTo(startX + c * TILE, H); aCtx.stroke();
    }
    for (let r = 0; r < rows; r++) {
      aCtx.beginPath();
      aCtx.moveTo(0, startY + r * TILE); aCtx.lineTo(W, startY + r * TILE); aCtx.stroke();
    }
  }

  function drawWalls() {
    walls.forEach(w => {
      const sx = w.x - camX, sy = w.y - camY;
      if (sx + w.w < -10 || sx > W + 10 || sy + w.h < -10 || sy > H + 10) return;
      // Wall body
      const grad = aCtx.createLinearGradient(sx, sy, sx + w.w, sy + w.h);
      grad.addColorStop(0, '#1a0a2e'); grad.addColorStop(1, '#0d0520');
      aCtx.fillStyle = grad;
      aCtx.fillRect(sx, sy, w.w, w.h);
      // Neon border
      aCtx.strokeStyle = 'rgba(168,85,247,0.4)'; aCtx.lineWidth = 1.5;
      aCtx.shadowBlur = 6; aCtx.shadowColor = '#a855f7';
      aCtx.strokeRect(sx + 0.5, sy + 0.5, w.w - 1, w.h - 1);
      // Circuit line detail
      aCtx.strokeStyle = 'rgba(168,85,247,0.15)'; aCtx.lineWidth = 1; aCtx.shadowBlur = 0;
      aCtx.setLineDash([4, 8]);
      aCtx.beginPath(); aCtx.moveTo(sx + 4, sy + w.h / 2); aCtx.lineTo(sx + w.w - 4, sy + w.h / 2); aCtx.stroke();
      aCtx.setLineDash([]);
    });
    aCtx.shadowBlur = 0;
  }

  // ── DRAW PLAYER ──
  function drawPlayer() {
    const sx = player.x - camX, sy = player.y - camY;
    const eqColor = getEquippedColorHex();
    const skinEmoji = getEquippedSkinEmoji();
    aCtx.save();
    aCtx.translate(sx, sy);

    // Invincible flicker
    if (invincibleTimer > 0 && Math.floor(invincibleTimer / 3) % 2 === 0) {
      aCtx.globalAlpha = 0.35;
    }

    // AEGIS SHIELD buff glow ring
    if (buffShieldTimer > 0) {
      aCtx.save();
      aCtx.strokeStyle = `rgba(168,85,247,${0.5 + Math.sin(frame * 0.2) * 0.3})`;
      aCtx.lineWidth = 3; aCtx.shadowBlur = 16; aCtx.shadowColor = '#a855f7';
      aCtx.beginPath(); aCtx.arc(0, 0, player.r + 12, 0, Math.PI * 2); aCtx.stroke();
      aCtx.restore();
    }

    // Dash trail
    if (isDashing) {
      aCtx.shadowBlur = 30; aCtx.shadowColor = eqColor;
    }

    // Outer glow ring
    const ringPulse = 0.4 + Math.sin(frame * 0.08) * 0.2;
    aCtx.strokeStyle = hexToRgba(eqColor, ringPulse); aCtx.lineWidth = 2;
    aCtx.beginPath(); aCtx.arc(0, 0, player.r + 5, 0, Math.PI * 2); aCtx.stroke();

    // Body (octagon)
    aCtx.fillStyle = eqColor; aCtx.shadowBlur = 18; aCtx.shadowColor = eqColor;
    aCtx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + Math.PI / 8;
      i === 0 ? aCtx.moveTo(Math.cos(a) * player.r, Math.sin(a) * player.r)
              : aCtx.lineTo(Math.cos(a) * player.r, Math.sin(a) * player.r);
    }
    aCtx.closePath(); aCtx.fill();

    // Face direction indicator
    aCtx.fillStyle = '#ffffff'; aCtx.shadowBlur = 5; aCtx.shadowColor = '#fff';
    aCtx.beginPath();
    aCtx.arc(Math.cos(player.angle) * 8, Math.sin(player.angle) * 8, 4, 0, Math.PI * 2);
    aCtx.fill();

    // Equipped skin badge
    if (skinEmoji) {
      aCtx.save();
      aCtx.shadowBlur = 0;
      aCtx.font = '14px sans-serif';
      aCtx.textAlign = 'center';
      aCtx.textBaseline = 'middle';
      aCtx.fillText(skinEmoji, 0, -player.r - 12);
      aCtx.restore();
    }

    // Slash arc
    if (slashActive) {
      const t = 1 - slashTimer / 14;
      aCtx.globalAlpha = 1 - t;
      aCtx.strokeStyle = eqColor; aCtx.lineWidth = 4;
      aCtx.shadowBlur = 25; aCtx.shadowColor = eqColor;
      aCtx.beginPath();
      aCtx.arc(0, 0, player.slashRange, slashAngle - Math.PI * 0.55, slashAngle + Math.PI * 0.55);
      aCtx.stroke();
      aCtx.globalAlpha = 1;
    }

    aCtx.restore();
    aCtx.textAlign = 'left';
  }

  // ── DRAW DATA NODES ──
  function drawDataNodes() {
    dataNodes.forEach(node => {
      if (node.collected) return;
      node.pulse += 0.06;
      const sx = node.x - camX, sy = node.y - camY;
      if (sx < -20 || sx > W + 20 || sy < -20 || sy > H + 20) return;

      const p = 0.7 + Math.sin(node.pulse) * 0.3;
      const NODE_STYLE = {
        DATA:       { color:'#39ff14', size:8  },
        MEGA:       { color:'#ffd700', size:11 },
        HEAL:       { color:'#ff4d6d', size:10 },
        HASTE:      { color:'#00f5ff', size:10 },
        OVERCHARGE: { color:'#ff2442', size:10 },
        SHIELD:     { color:'#a855f7', size:10 },
        CORE:       { color:'#ffffff', size:12 },
      };
      const style = NODE_STYLE[node.type] || NODE_STYLE.DATA;
      const color = style.color, size = style.size;

      aCtx.save();
      aCtx.shadowBlur = 14 * p; aCtx.shadowColor = color;
      aCtx.fillStyle = color;
      aCtx.translate(sx, sy);

      if (node.type === 'HEAL') {
        // Cross icon
        aCtx.fillRect(-size/2, -2, size, 4);
        aCtx.fillRect(-2, -size/2, 4, size);
      } else if (node.type === 'CORE') {
        // Rotating diamond ring — ability core
        aCtx.rotate(node.pulse * 0.8);
        aCtx.beginPath();
        aCtx.moveTo(0, -size); aCtx.lineTo(size, 0); aCtx.lineTo(0, size); aCtx.lineTo(-size, 0);
        aCtx.closePath(); aCtx.fill();
        aCtx.strokeStyle = '#00f5ff'; aCtx.lineWidth = 1.5;
        aCtx.beginPath(); aCtx.arc(0, 0, size + 5, 0, Math.PI * 2); aCtx.stroke();
      } else if (node.type === 'HASTE') {
        // Chevron / speed arrow
        aCtx.rotate(node.pulse * 0.4);
        aCtx.beginPath();
        aCtx.moveTo(-size*0.6, -size*0.7); aCtx.lineTo(size*0.6, 0); aCtx.lineTo(-size*0.6, size*0.7);
        aCtx.closePath(); aCtx.fill();
      } else if (node.type === 'SHIELD') {
        // Hexagon shield icon
        aCtx.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2 - Math.PI / 6;
          i === 0 ? aCtx.moveTo(Math.cos(a) * size, Math.sin(a) * size) : aCtx.lineTo(Math.cos(a) * size, Math.sin(a) * size);
        }
        aCtx.closePath(); aCtx.fill();
      } else {
        // DATA / MEGA / OVERCHARGE — rotating square
        aCtx.rotate(node.pulse * 0.6);
        aCtx.fillRect(-size / 2, -size / 2, size, size);
        aCtx.fillStyle = '#ffffff';
        aCtx.fillRect(-2, -2, 4, 4);
      }
      aCtx.restore();
    });
  }

  // ── DRAW XP ORBS ──
  function drawXPOrbs() {
    for (let i = xpOrbs.length - 1; i >= 0; i--) {
      const orb = xpOrbs[i];
      orb.x += orb.vx; orb.y += orb.vy;
      orb.vx *= 0.9; orb.vy *= 0.9;

      // Magnetic pull toward player when close
      const dx = player.x - orb.x, dy = player.y - orb.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 80) {
        orb.vx += (dx / dist) * 3;
        orb.vy += (dy / dist) * 3;
      }
      // Collect
      if (dist < player.r + orb.r + 2) {
        gainXP(orb.xp);
        xpOrbs.splice(i, 1);
        continue;
      }

      const sx = orb.x - camX, sy = orb.y - camY;
      aCtx.save();
      aCtx.shadowBlur = 10; aCtx.shadowColor = orb.color;
      aCtx.fillStyle = orb.color; aCtx.globalAlpha = orb.alpha;
      aCtx.beginPath(); aCtx.arc(sx, sy, orb.r, 0, Math.PI * 2); aCtx.fill();
      aCtx.restore();
    }
  }

  // ── DRAW BOT PROJECTILES ──
  function updateBotProjectiles() {
    for (let i = botProjectiles.length - 1; i >= 0; i--) {
      const p = botProjectiles[i];
      p.trail.push({ x: p.x, y: p.y });
      if (p.trail.length > 6) p.trail.shift();
      p.x += p.vx; p.y += p.vy;
      p.alpha -= 0.005;

      // Off arena
      if (p.x < 0 || p.x > ARENA_W || p.y < 0 || p.y > ARENA_H || p.alpha <= 0) {
        botProjectiles.splice(i, 1); continue;
      }
      // Wall hit
      if (isCollidingWall(p.x, p.y, p.r)) {
        explode(p.x, p.y, p.color, 4);
        botProjectiles.splice(i, 1); continue;
      }
      // Player hit
      const dx = p.x - player.x, dy = p.y - player.y;
      if (Math.sqrt(dx * dx + dy * dy) < player.r + p.r) {
        hitPlayer(p.dmg, p.color);
        explode(p.x, p.y, p.color, 5);
        botProjectiles.splice(i, 1); continue;
      }

      // Draw trail
      const sx = p.x - camX, sy = p.y - camY;
      p.trail.forEach((pt, idx) => {
        const ta = (idx / p.trail.length) * 0.5;
        aCtx.fillStyle = p.color;
        aCtx.globalAlpha = ta;
        aCtx.beginPath(); aCtx.arc(pt.x - camX, pt.y - camY, p.r * 0.5, 0, Math.PI * 2); aCtx.fill();
      });
      aCtx.globalAlpha = 1;
      aCtx.save();
      aCtx.shadowBlur = 12; aCtx.shadowColor = p.color;
      aCtx.fillStyle = p.color;
      aCtx.beginPath(); aCtx.arc(sx, sy, p.r, 0, Math.PI * 2); aCtx.fill();
      aCtx.restore();
    }
    aCtx.globalAlpha = 1;
  }

  // ── DRAW PARTICLES ──
  function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx; p.y += p.vy; p.vx *= 0.93; p.vy *= 0.93; p.alpha -= p.decay;
      if (p.alpha <= 0) { particles.splice(i, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = p.alpha;
      aCtx.fillStyle = p.color; aCtx.shadowBlur = 6; aCtx.shadowColor = p.color;
      aCtx.beginPath(); aCtx.arc(p.x - camX, p.y - camY, p.size, 0, Math.PI * 2); aCtx.fill();
      aCtx.restore();
    }
    aCtx.globalAlpha = 1;
  }

  // ── DRAW FLOATING TEXTS ──
  function updateFloatingTexts() {
    for (let i = floatingTexts.length - 1; i >= 0; i--) {
      const t = floatingTexts[i];
      t.y += t.vy; t.alpha -= 0.018; t.life++;
      if (t.alpha <= 0) { floatingTexts.splice(i, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = t.alpha;
      aCtx.fillStyle = t.color; aCtx.shadowBlur = 8; aCtx.shadowColor = t.color;
      aCtx.font = `bold ${t.text.includes('COMBO') || t.text.includes('LEVEL') ? '11' : '9'}px Orbitron`;
      aCtx.textAlign = 'center';
      aCtx.fillText(t.text, t.x - camX, t.y - camY);
      aCtx.restore();
    }
    aCtx.textAlign = 'left'; aCtx.globalAlpha = 1;
  }

  // ── HUD OVERLAY ──
  function drawHUD() {
    // XP bar (top strip)
    const xpPct = playerXP / playerXPNext;
    aCtx.fillStyle = 'rgba(0,0,0,0.55)'; aCtx.fillRect(0, 0, W, 22);
    aCtx.fillStyle = '#ffd700'; aCtx.fillRect(0, 18, W * xpPct, 4);
    aCtx.fillStyle = '#ffd700'; aCtx.font = 'bold 8px Orbitron';
    aCtx.shadowBlur = 5; aCtx.shadowColor = '#ffd700';
    aCtx.fillText(`LV ${playerLevel}  XP ${playerXP}/${playerXPNext}`, 8, 14);
    // Score
    aCtx.textAlign = 'right';
    aCtx.fillStyle = '#00f5ff'; aCtx.shadowColor = '#00f5ff';
    aCtx.fillText(`${score} PTS`, W - 8, 14);
    aCtx.textAlign = 'left'; aCtx.shadowBlur = 0;

    // Slash cooldown indicator (bottom right)
    if (player.slashCooldown > 0) {
      const pct = 1 - player.slashCooldown / 28;
      aCtx.fillStyle = 'rgba(0,0,0,0.6)'; aCtx.fillRect(W - 56, H - 30, 48, 14);
      aCtx.fillStyle = '#00f5ff'; aCtx.fillRect(W - 56, H - 30, 48 * pct, 14);
      aCtx.fillStyle = '#fff'; aCtx.font = '7px Orbitron'; aCtx.textAlign = 'center';
      aCtx.fillText('SLASH', W - 32, H - 20);
      aCtx.textAlign = 'left';
    } else {
      aCtx.fillStyle = '#00f5ff'; aCtx.font = '7px Orbitron'; aCtx.shadowBlur = 8; aCtx.shadowColor = '#00f5ff';
      aCtx.textAlign = 'center'; aCtx.fillText('⚔ READY', W - 32, H - 20);
      aCtx.textAlign = 'left'; aCtx.shadowBlur = 0;
    }

    // Dash cooldown (bottom left)
    if (dashCooldown > 0) {
      const pct2 = 1 - dashCooldown / 70;
      aCtx.fillStyle = 'rgba(0,0,0,0.6)'; aCtx.fillRect(8, H - 30, 48, 14);
      aCtx.fillStyle = '#a855f7'; aCtx.fillRect(8, H - 30, 48 * pct2, 14);
      aCtx.fillStyle = '#fff'; aCtx.font = '7px Orbitron'; aCtx.textAlign = 'center';
      aCtx.fillText('DASH', 32, H - 20);
    } else {
      aCtx.fillStyle = '#a855f7'; aCtx.font = '7px Orbitron'; aCtx.shadowBlur = 8; aCtx.shadowColor = '#a855f7';
      aCtx.textAlign = 'center'; aCtx.fillText('💨 READY', 32, H - 20);
      aCtx.shadowBlur = 0;
    }
    aCtx.textAlign = 'left';

    // Bot count
    const alive = enemyBots.filter(b => !b.dead).length;
    aCtx.fillStyle = 'rgba(0,0,0,0.55)';
    aCtx.fillRect(W / 2 - 40, 4, 80, 16);
    aCtx.fillStyle = '#ff0090'; aCtx.font = '7.5px Orbitron'; aCtx.textAlign = 'center'; aCtx.shadowBlur = 5; aCtx.shadowColor = '#ff0090';
    aCtx.fillText(`${alive} BOTS ALIVE`, W / 2, 15);
    aCtx.textAlign = 'left'; aCtx.shadowBlur = 0;

    // Combo display
    if (comboTimer > 0 && comboCount >= 2) {
      aCtx.save();
      const comboAlpha = Math.min(1, comboTimer / 30);
      aCtx.globalAlpha = comboAlpha;
      aCtx.fillStyle = '#ffd700'; aCtx.font = `bold ${9 + comboCount}px Orbitron`;
      aCtx.textAlign = 'center'; aCtx.shadowBlur = 12; aCtx.shadowColor = '#ffd700';
      aCtx.fillText(`${comboCount}x COMBO`, W / 2, 42);
      aCtx.restore();
      aCtx.textAlign = 'left';
    }

    // Controls hint (fades after 5s). Keyboard only — 7px Orbitron scaled down
    // to phone size is unreadable, so touch gets the #touch-hint overlay
    // instead and this stays out of its way.
    if (frame < 300 && !isTouchDevice) {
      const hintAlpha = Math.max(0, 1 - frame / 300);
      aCtx.save(); aCtx.globalAlpha = hintAlpha * 0.7;
      aCtx.fillStyle = 'rgba(0,0,0,0.6)'; aCtx.fillRect(W/2 - 100, H/2 + 30, 200, 48);
      aCtx.fillStyle = '#ffffff'; aCtx.font = '7px Orbitron'; aCtx.textAlign = 'center';
      aCtx.fillText('WASD / ARROWS = MOVE', W/2, H/2 + 44);
      aCtx.fillText('SPACE = SLASH  SHIFT = DASH', W/2, H/2 + 58);
      aCtx.fillText('E (OR DOUBLE-TAP) = ABILITY', W/2, H/2 + 72);
      aCtx.restore(); aCtx.textAlign = 'left';
    }

    // Special ability queue indicator (top center, below bot count)
    if (specialAbilities.length > 0) {
      const abil = specialAbilities[0];
      const bob = Math.sin(frame * 0.1) * 2;
      aCtx.save();
      aCtx.fillStyle = 'rgba(0,0,0,0.6)'; aCtx.fillRect(W / 2 - 70, 24 + bob, 140, 15);
      aCtx.strokeStyle = abil.color; aCtx.lineWidth = 1; aCtx.strokeRect(W / 2 - 70, 24 + bob, 140, 15);
      aCtx.fillStyle = abil.color; aCtx.font = 'bold 7px Orbitron'; aCtx.textAlign = 'center';
      aCtx.shadowBlur = 8; aCtx.shadowColor = abil.color;
      aCtx.fillText(`[E] ${abil.label}${specialAbilities.length > 1 ? ` x${specialAbilities.length}` : ''}`, W / 2, 34 + bob);
      aCtx.restore(); aCtx.textAlign = 'left';
    }

    // Active buff indicators (right side, under score)
    let buffY = 30;
    const drawBuff = (label, color, timer, maxTimer) => {
      if (timer <= 0) return;
      const pct = timer / maxTimer;
      aCtx.save();
      aCtx.fillStyle = 'rgba(0,0,0,0.55)'; aCtx.fillRect(W - 66, buffY, 58, 12);
      aCtx.fillStyle = color; aCtx.globalAlpha = 0.85; aCtx.fillRect(W - 66, buffY, 58 * pct, 12);
      aCtx.globalAlpha = 1; aCtx.fillStyle = '#000'; aCtx.font = 'bold 6.5px Orbitron'; aCtx.textAlign = 'center';
      aCtx.fillText(label, W - 37, buffY + 9);
      aCtx.restore(); aCtx.textAlign = 'left';
      buffY += 15;
    };
    drawBuff('HASTE', '#00f5ff', buffHasteTimer, 300);
    drawBuff('OVERCHARGE', '#ff2442', buffOverchargeTimer, 300);
    drawBuff('AEGIS', '#a855f7', buffShieldTimer, 180);
  }

  // ── MAIN LOOP ──
  function loop() {
    if (isOver) return;
    frame++;
    gameLoopId = requestAnimationFrame(loop);

    // ── UPDATE PLAYER ──
    if (!isOver) {
      // Movement
      let dx = 0, dy = 0;
      if (keys['ArrowLeft']  || keys['KeyA'] || moveLeft)  dx -= 1;
      if (keys['ArrowRight'] || keys['KeyD'] || moveRight) dx += 1;
      if (keys['ArrowUp']    || keys['KeyW'])              dy -= 1;
      if (keys['ArrowDown']  || keys['KeyS'])              dy += 1;
      if (stickActive) { dx += stickX; dy += stickY; }

      const hasteMult = buffHasteTimer > 0 ? 1.6 : 1;
      if (dx !== 0 || dy !== 0) {
        const len = Math.sqrt(dx * dx + dy * dy);
        const spd = (isDashing ? player.speed * 3 : player.speed) * hasteMult;
        player.vx += (dx / len) * spd * 0.4;
        player.vy += (dy / len) * spd * 0.4;
        // Update facing if not mouse-aiming recently
        if (!aCanvas.onmousemove || (dx !== 0 || dy !== 0)) {
          // Don't override mouse aim; angle only updates from mouse
        }
      }
      player.vx *= 0.82; player.vy *= 0.82;
      const pspd = Math.sqrt(player.vx * player.vx + player.vy * player.vy);
      const maxSpd = (isDashing ? player.speed * 4 : player.speed) * hasteMult;
      if (pspd > maxSpd) { player.vx = (player.vx / pspd) * maxSpd; player.vy = (player.vy / pspd) * maxSpd; }

      player.x += player.vx; player.y += player.vy;
      player.x = Math.max(player.r, Math.min(ARENA_W - player.r, player.x));
      player.y = Math.max(player.r, Math.min(ARENA_H - player.r, player.y));
      resolveWall(player, player.r);

      // Timers
      if (invincibleTimer > 0) invincibleTimer--;
      if (player.slashCooldown > 0) player.slashCooldown--;
      if (dashCooldown > 0) dashCooldown--;
      if (slashTimer > 0) slashTimer--; else slashActive = false;
      if (dashTimer > 0) dashTimer--; else isDashing = false;
      if (comboTimer > 0) comboTimer--; else if (comboTimer === 0 && comboCount > 0) comboCount = 0;
      if (buffHasteTimer > 0) buffHasteTimer--;
      if (buffShieldTimer > 0) buffShieldTimer--;
      if (buffOverchargeTimer > 0) buffOverchargeTimer--;

      // ── UPDATE BOTS ──
      enemyBots.forEach(bot => bot.update());

      // ── COLLECT DATA NODES ──
      dataNodes.forEach(node => {
        if (node.collected) return;
        const dx2 = player.x - node.x, dy2 = player.y - node.y;
        if (Math.sqrt(dx2 * dx2 + dy2 * dy2) < player.r + node.r + 4) {
          node.collected = true;
          if (node.type === 'MEGA') {
            score += 50; setLive(score); gainXP(30);
            snd('pickup', { semi: 7 });
            explode(node.x, node.y, '#ffd700', 8);
            popText(node.x, node.y - 12, '+50', '#ffd700');
          } else if (node.type === 'DATA') {
            score += 20; setLive(score); gainXP(10);
            snd('pickup');
            explode(node.x, node.y, '#39ff14', 8);
            popText(node.x, node.y - 12, '+20', '#39ff14');
          } else if (node.type === 'HEAL') {
            player.hp = Math.min(player.maxHp, player.hp + player.maxHp * 0.25);
            document.getElementById('prog-fill').style.width = `${(player.hp / player.maxHp) * 100}%`;
            snd('heal');
            explode(node.x, node.y, '#ff4d6d', 10);
            popText(node.x, node.y - 12, '+HP', '#ff4d6d');
          } else if (node.type === 'HASTE') {
            buffHasteTimer = 300;
            snd('powerup');
            explode(node.x, node.y, '#00f5ff', 10);
            popText(node.x, node.y - 12, 'HASTE!', '#00f5ff');
          } else if (node.type === 'OVERCHARGE') {
            buffOverchargeTimer = 300;
            snd('powerup');
            explode(node.x, node.y, '#ff2442', 10);
            popText(node.x, node.y - 12, 'OVERCHARGE!', '#ff2442');
          } else if (node.type === 'SHIELD') {
            buffShieldTimer = 180;
            snd('shield');
            explode(node.x, node.y, '#a855f7', 10);
            popText(node.x, node.y - 12, 'SHIELDED!', '#a855f7');
          } else if (node.type === 'CORE') {
            const abil = ABILITY_TYPES[Math.floor(Math.random() * ABILITY_TYPES.length)];
            specialAbilities.push(abil);
            snd('charge');
            if (specialAbilities.length > 3) specialAbilities.shift();
            explode(node.x, node.y, abil.color, 14);
            popText(node.x, node.y - 12, `${abil.label} READY`, abil.color);
            toast(`⚡ Ability acquired: ${abil.label} — press E (or double-tap) to use`, 2200);
          }
        }
      });

      // Respawn collected nodes
      const activeNodes = dataNodes.filter(n => !n.collected).length;
      if (activeNodes < 10 && frame % 120 === 0) spawnDataNodes(4);

      // ── SPAWN BOTS ──
      botSpawnTimer++;
      const spawnInterval = Math.max(180, 420 - botWave * 30);
      if (botSpawnTimer >= spawnInterval) {
        botSpawnTimer = 0;
        const maxBots = Math.min(12, 4 + botWave * 2);
        const alive = enemyBots.filter(b => !b.dead).length;
        if (alive < maxBots) spawnBot();
      }

      // Clean dead bots after death animation
      for (let i = enemyBots.length - 1; i >= 0; i--) {
        if (enemyBots[i].dead && enemyBots[i].deathTimer > 40) enemyBots.splice(i, 1);
      }

      // ── CAMERA FOLLOW ──
      const targetCamX = player.x - W / 2;
      const targetCamY = player.y - H / 2;
      camX += (targetCamX - camX) * 0.1;
      camY += (targetCamY - camY) * 0.1;
      camX = Math.max(0, Math.min(ARENA_W - W, camX));
      camY = Math.max(0, Math.min(ARENA_H - H, camY));

      // Screen shake
      let shakeX = 0, shakeY = 0;
      if (screenShake > 0) {
        const sh = VFX.shake(screenShake);
        shakeX = (Math.random() - 0.5) * sh;
        shakeY = (Math.random() - 0.5) * sh;
        screenShake = Math.max(0, screenShake - 1.5);
      }

      // ── DRAW ──
      aCtx.save();
      aCtx.translate(shakeX, shakeY);
      drawWorld();
      drawWalls();
      drawDataNodes();
      drawXPOrbs();
      // Draw bots
      enemyBots.forEach(bot => {
        const sx = bot.x - camX, sy = bot.y - camY;
        if (sx > -40 && sx < W + 40 && sy > -40 && sy < H + 40) bot.draw(sx, sy);
      });
      updateBotProjectiles();
      drawPlayer();
      updateParticles();
      updateFloatingTexts();
      drawHUD();
      aCtx.restore();
      drawTouchStick();   // outside the shake transform — a control shouldn't jitter
    }
  }

  onQuitGame = () => { if(!isOver) endArena(); };
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🌌 GAME 13: CYBER RUNNER
// ════════════════════════════════════════════
function startRunner(){
  document.getElementById('g-canvas-holder').style.display='block';
  // Lane shifts are discrete, so these are plain clicks rather than hold-to-
  // repeat — holding ◀ should not walk you across the whole track.
  setControls({ left:'◀', action:'⤒ JUMP', right:'▶' });
  setControlHint('SWIPE ◀ ▶ TO SHIFT LANE · TAP TO JUMP',
                 '← → / A D = SHIFT LANE · SPACE / ↑ / W = JUMP');
  showTouchHint('SWIPE LEFT / RIGHT TO SHIFT LANE · TAP TO JUMP');
  fitCanvas();

  const diffMod = getDifficultyModifier();
  const W=BOARD_W, H=BOARD_H;
  const LANES=3, LANE_W=W/LANES;
  const laneX = i => LANE_W*i + LANE_W/2;
  const RIDE_Y = H-92;          // the hover-bike's ground line
  const HIT_H  = 26;            // vertical slack on a collision test

  // The speed ramp IS this game's difficulty curve. A straight ×2 on the
  // ceiling at Meltdown puts the track past reacting and into guessing — the
  // same problem Ice Breaker's ball had — so the tier scales the RAMP fully
  // (you reach terminal velocity much sooner) but the start and ceiling only
  // partially. Rows still arrive at a readable rate; there are just more of
  // them, sooner.
  const BASE_SPEED = 3.6*(1+(diffMod-1)*0.5);
  const RAMP       = 0.0024*diffMod;
  const MAX_SPEED  = 11*(1+(diffMod-1)*0.4);
  const JUMP_FRAMES = 34;

  let speed=BASE_SPEED, dist=0, cubes=0, hull=3, frame=0, elapsed=0;
  let lane=1, visX=laneX(1), jumpT=0, invuln=0, shake=0, isOver=false;
  let items=[], particles=[], floats=[], spawnCd=90;

  Ghost.begin('runner');
  if(Ghost.racing) toast(`👻 Racing your best run — ${Ghost.target} to beat`, 2600);

  document.getElementById('g-time').textContent='0';
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--pink),var(--purple))';

  const score = () => Math.floor(dist/13) + cubes*30;
  const pop = (x,y,txt,color) => floats.push({x,y,txt,color,alpha:1,vy:-0.9});
  function burst(x,y,color,n){
    for(let i=0;i<n;i++){
      const a=Math.random()*Math.PI*2, v=Math.random()*3+1;
      particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,alpha:1,color,r:Math.random()*2+1});
    }
  }

  function shift(dir){
    if(isOver) return;
    const nl=Math.max(0,Math.min(LANES-1,lane+dir));
    if(nl===lane) return;
    lane=nl;
    snd('move');
    burst(visX, RIDE_Y+12, getEquippedColorHex(), 5);
  }
  function jump(){
    if(isOver||jumpT>0) return;
    jumpT=JUMP_FRAMES;
    snd('jump');
    burst(visX, RIDE_Y+14, '#ff0090', 8);
  }

  // ── STEERING ──
  // One gesture set covers both input styles: a horizontal drag past the
  // threshold shifts lane (and re-anchors, so a long swipe can cross two
  // lanes), while a short stationary press is a jump. Works identically with
  // a mouse, which is why there is no separate desktop path.
  let anchorX=0, swiped=false, downAt=0;
  bindCanvasDrag({
    onDown(p){ hideTouchHint(); anchorX=p.x; swiped=false; downAt=performance.now(); },
    onMove(p){
      const dx=p.x-anchorX;
      if(Math.abs(dx)>34){ shift(dx>0?1:-1); anchorX=p.x; swiped=true; }
    },
    onUp(){ if(!swiped && performance.now()-downAt<420) jump(); }
  });

  document.getElementById('ctrl-left').onclick  = ()=>shift(-1);
  document.getElementById('ctrl-right').onclick = ()=>shift(1);
  document.getElementById('ctrl-action').onclick= jump;

  window.onkeydown = e => {
    // Enter does nothing here, but it still activates whatever button holds
    // focus — swallow it alongside the keys the game actually uses.
    if(['ArrowLeft','ArrowRight','ArrowUp','Space','Enter','KeyA','KeyD','KeyW'].includes(e.code)) e.preventDefault();
    if(e.repeat) return;                       // one shift per keypress
    if(e.code==='ArrowLeft' ||e.code==='KeyA') shift(-1);
    if(e.code==='ArrowRight'||e.code==='KeyD') shift(1);
    if(e.code==='ArrowUp'   ||e.code==='KeyW'||e.code==='Space') jump();
  };

  gTimer=setInterval(()=>{ if(!isOver){ elapsed++; document.getElementById('g-time').textContent=elapsed; } },1000);

  // Every row leaves at least one clean lane, so no arrangement is unwinnable.
  // Spacing is measured in DISTANCE, not frames — the gap between rows stays
  // constant on the track while the time you get to read it shrinks with speed.
  function spawnRow(){
    const safe=Math.floor(Math.random()*LANES);
    for(let i=0;i<LANES;i++){
      if(i===safe){
        if(Math.random()<0.42) items.push({kind:'cube',lane:i,y:-26,spin:Math.random()*6});
        continue;
      }
      const r=Math.random();
      if(r<0.74)      items.push({kind: Math.random()<0.45?'spike':'wall', lane:i, y:-32});
      else if(r<0.90) items.push({kind:'cube',lane:i,y:-26,spin:Math.random()*6});
    }
  }

  function takeHit(){
    hull--; invuln=64; shake=16;
    snd(hull<=0 ? 'bigExplode' : 'hurt');
    burst(visX, RIDE_Y, '#ff2442', 18);
    pop(visX, RIDE_Y-30, 'HULL BREACH', '#ff2442');
    // 🛡️ An absorbed breach hands the last hull point back and doubles the
    // invulnerability window — the bike is usually still inside the obstacle
    // that hit it, and a one-point hull with 64 frames of grace dies to the
    // same wall a moment later.
    if(hull<=0 && survivedFatal()){ hull=1; invuln=128; }
    document.getElementById('prog-fill').style.width=`${Math.max(0,hull)/3*100}%`;
    if(hull<=0) end();
  }

  function end(){
    if(isOver)return; isOver=true;
    const final=Math.min(1200, score());
    const wasRacing=Ghost.racing, target=Ghost.target;
    const beat=Ghost.finish(final);
    showResults('runner', final, {
      '🌌 Distance Run': `${Math.floor(dist/10)} M`,
      '💠 Data Cubes': cubes,
      '⚡ Top Velocity': `${(speed/BASE_SPEED).toFixed(2)}×`,
      '⏱️ Uptime': `${elapsed}s`,
      ...(wasRacing?{'👻 Ghost To Beat':`${target} PTS`}:{}),
      ...(wasRacing&&beat?{'👻 Result':'GHOST BEATEN'}:{}),
      '🏆 Score Accumulation': `${final} PTS`
    });
  }

  function drawTrack(){
    // Lane dividers
    aCtx.strokeStyle='rgba(255,0,144,0.22)'; aCtx.lineWidth=2;
    aCtx.shadowBlur=10; aCtx.shadowColor='#ff0090';
    for(let i=1;i<LANES;i++){
      aCtx.beginPath(); aCtx.moveTo(LANE_W*i,0); aCtx.lineTo(LANE_W*i,H); aCtx.stroke();
    }
    aCtx.shadowBlur=0;
    // Scrolling rungs — the whole sense of speed lives here
    const off=dist%56;
    for(let y=-56+off; y<H; y+=56){
      const a=0.05+(y/H)*0.16;
      aCtx.strokeStyle=`rgba(168,85,247,${a})`; aCtx.lineWidth=1;
      aCtx.beginPath(); aCtx.moveTo(0,y); aCtx.lineTo(W,y); aCtx.stroke();
    }
    // Horizon bloom
    const g=aCtx.createLinearGradient(0,0,0,150);
    g.addColorStop(0,'rgba(255,0,144,0.16)'); g.addColorStop(1,'rgba(255,0,144,0)');
    aCtx.fillStyle=g; aCtx.fillRect(0,0,W,150);
  }

  // eq is the equipped Black Market colour, resolved once per frame by loop().
  // Only the cube — the thing you WANT to hit — takes it; the firewall and the
  // spikes keep their fixed red/orange so no cosmetic can disguise a hazard.
  function drawItem(it, eq){
    const x=laneX(it.lane), y=it.y;
    aCtx.save();
    if(it.kind==='wall'){
      // Firewall barrier — spans the lane, cannot be jumped
      aCtx.shadowBlur=16; aCtx.shadowColor='#ff2442';
      aCtx.fillStyle='rgba(255,36,66,0.9)';
      aCtx.fillRect(x-LANE_W/2+8, y-10, LANE_W-16, 20);
      aCtx.fillStyle='rgba(4,4,14,0.85)';
      for(let s=-LANE_W/2+10; s<LANE_W/2-8; s+=16) aCtx.fillRect(x+s, y-10, 7, 20);
      aCtx.strokeStyle='#fff'; aCtx.lineWidth=1; aCtx.shadowBlur=8; aCtx.shadowColor='#fff';
      aCtx.strokeRect(x-LANE_W/2+8, y-10, LANE_W-16, 20);
    } else if(it.kind==='spike'){
      // Spike hazard — low enough to clear with a jump
      aCtx.shadowBlur=14; aCtx.shadowColor='#ff6600';
      aCtx.fillStyle='#ff6600';
      for(let s=-1;s<=1;s++){
        const sx=x+s*22;
        aCtx.beginPath(); aCtx.moveTo(sx,y-14); aCtx.lineTo(sx+9,y+8); aCtx.lineTo(sx-9,y+8);
        aCtx.closePath(); aCtx.fill();
      }
    } else {
      // Data cube — a slowly tumbling wireframe box
      it.spin+=0.06;
      aCtx.translate(x,y); aCtx.rotate(it.spin);
      aCtx.shadowBlur=18; aCtx.shadowColor=eq;
      aCtx.strokeStyle=eq; aCtx.lineWidth=2;
      aCtx.strokeRect(-11,-11,22,22);
      aCtx.fillStyle=hexToRgba(eq,0.28); aCtx.fillRect(-11,-11,22,22);
      aCtx.strokeStyle='rgba(255,255,255,0.85)'; aCtx.lineWidth=1.5;
      aCtx.strokeRect(-5,-5,10,10);
    }
    aCtx.restore();
  }

  function drawRider(){
    const t = jumpT>0 ? 1-jumpT/JUMP_FRAMES : 0;
    const lift = Math.sin(t*Math.PI)*46;
    const y = RIDE_Y-lift, sc = 1+lift/320;
    const col = getEquippedColorHex();

    // Ground shadow shrinks as the bike climbs — the only cue that says
    // "you are airborne" while the sprite itself barely moves on a small board.
    aCtx.save();
    aCtx.globalAlpha=0.34-lift*0.005;
    aCtx.fillStyle='#000';
    aCtx.beginPath(); aCtx.ellipse(visX, RIDE_Y+20, 19-lift*0.16, 5, 0,0,Math.PI*2); aCtx.fill();
    aCtx.restore();

    aCtx.save();
    aCtx.translate(visX,y); aCtx.scale(sc,sc);
    if(invuln>0) aCtx.globalAlpha=0.35+Math.abs(Math.sin(frame*0.4))*0.65;
    // Thruster
    aCtx.shadowBlur=14; aCtx.shadowColor='#ff0090';
    aCtx.fillStyle=Math.random()>0.5?'#ff0090':'#a855f7';
    aCtx.beginPath(); aCtx.moveTo(-7,13); aCtx.lineTo(7,13);
    aCtx.lineTo(0,13+Math.random()*13+(jumpT>0?14:7)); aCtx.closePath(); aCtx.fill();
    // Hull
    aCtx.shadowBlur=18; aCtx.shadowColor=col; aCtx.fillStyle=col;
    aCtx.beginPath();
    aCtx.moveTo(0,-21); aCtx.lineTo(15,9); aCtx.lineTo(7,15);
    aCtx.lineTo(-7,15); aCtx.lineTo(-15,9); aCtx.closePath(); aCtx.fill();
    // Canopy
    aCtx.shadowBlur=6; aCtx.shadowColor='#fff'; aCtx.fillStyle='rgba(255,255,255,.92)';
    aCtx.beginPath(); aCtx.moveTo(0,-12); aCtx.lineTo(5,3); aCtx.lineTo(-5,3); aCtx.closePath(); aCtx.fill();
    aCtx.restore();

    drawSkinBadge(visX, y-32, 13);
  }

  function drawHUD(){
    aCtx.save();
    aCtx.fillStyle='rgba(0,0,0,0.5)'; aCtx.strokeStyle='rgba(255,0,144,0.5)'; aCtx.lineWidth=1;
    aCtx.beginPath(); aCtx.roundRect(8,10,150,26,6); aCtx.fill(); aCtx.stroke();
    aCtx.fillStyle='#ff0090'; aCtx.font='bold 9px Orbitron,monospace';
    aCtx.shadowBlur=6; aCtx.shadowColor='#ff0090';
    aCtx.fillText(`${Math.floor(dist/10)}M`, 15, 27);
    const eq=getEquippedColorHex();
    aCtx.fillStyle=eq; aCtx.shadowColor=eq;
    aCtx.fillText(`◇${cubes}`, 62, 27);
    aCtx.fillStyle='#ffd700'; aCtx.shadowColor='#ffd700';
    aCtx.fillText(`${(speed/BASE_SPEED).toFixed(1)}×`, 110, 27);

    // Hull pips, top-right
    for(let i=0;i<3;i++){
      const on=i<hull;
      aCtx.fillStyle=on?'#39ff14':'rgba(255,255,255,0.14)';
      aCtx.shadowBlur=on?10:0; aCtx.shadowColor='#39ff14';
      aCtx.beginPath(); aCtx.roundRect(W-22-i*18, 14, 13, 13, 3); aCtx.fill();
    }
    aCtx.restore();
  }

  function loop(){
    if(isOver) return;
    gameLoopId=requestAnimationFrame(loop);
    frame++;

    speed=Math.min(MAX_SPEED, speed+RAMP);
    dist+=speed;
    if(jumpT>0) jumpT--;
    if(invuln>0) invuln--;
    visX+=(laneX(lane)-visX)*0.28;
    Ghost.sample(visX);

    spawnCd-=speed;
    if(spawnCd<=0){ spawnRow(); spawnCd=152+Math.random()*66; }

    // ── ITEMS & COLLISIONS ──
    for(let i=items.length-1;i>=0;i--){
      const it=items[i];
      it.y+=speed;
      if(it.y>H+44){ items.splice(i,1); continue; }
      if(it.lane!==lane || Math.abs(it.y-RIDE_Y)>HIT_H) continue;

      if(it.kind==='cube'){
        cubes++; setLive(score());
        // Cubes walk a repeating four-note figure rather than one flat blip, so
        // a clean run of them sounds like a phrase instead of a stutter.
        snd('pickup',{semi:[0,4,7,12][cubes%4]});
        const eq=getEquippedColorHex();
        pop(laneX(it.lane), it.y-14, '+30', eq);
        burst(laneX(it.lane), it.y, eq, 9);
        items.splice(i,1);
      } else if(it.kind==='spike' && jumpT>0){
        continue;                                  // cleared it on the hop
      } else if(invuln<=0){
        items.splice(i,1);
        takeHit();
        if(isOver) return;
      }
    }

    if(frame%10===0) setLive(score());

    // ── DRAW ──
    aCtx.clearRect(0,0,W,H);
    aCtx.save();
    if(shake>0){
      const sh=VFX.shake(shake);
      aCtx.translate((Math.random()-0.5)*sh,(Math.random()-0.5)*sh);
      shake*=0.85; if(shake<0.4) shake=0;
    }

    drawTrack();
    const eq=getEquippedColorHex();
    items.forEach(it=>drawItem(it,eq));

    // Ghost bike from your best run — track-level, under the live rider.
    const gx = Ghost.at(frame);
    if(gx != null){
      aCtx.save();
      ghostStyle();
      aCtx.strokeRect(gx-16, RIDE_Y-14, 32, 28);
      aCtx.fillRect(gx-16, RIDE_Y-14, 32, 28);
      aCtx.restore();
    }

    drawRider();

    // No shadowBlur on particles: a blurred shadow is per-pixel work on a board
    // that can be 2× retina, and there can be dozens of these in a frame. The
    // other games draw sparks as flat fills for the same reason.
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx; p.y+=p.vy+speed*0.35; p.alpha-=0.035;
      if(p.alpha<=0){ particles.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=p.alpha; aCtx.fillStyle=p.color;
      aCtx.beginPath(); aCtx.arc(p.x,p.y,p.r,0,Math.PI*2); aCtx.fill(); aCtx.restore();
    }
    for(let i=floats.length-1;i>=0;i--){
      const f=floats[i];
      f.y+=f.vy; f.alpha-=0.02;
      if(f.alpha<=0){ floats.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=f.alpha; aCtx.fillStyle=f.color;
      aCtx.font='bold 12px Orbitron,monospace'; aCtx.textAlign='center';
      aCtx.shadowBlur=10; aCtx.shadowColor=f.color;
      aCtx.fillText(f.txt,f.x,f.y); aCtx.restore();
    }

    aCtx.restore();
    drawHUD();
  }
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🔓 GAME 14: NODE HACKER
// ════════════════════════════════════════════
function startHacker(){
  const wrap=document.getElementById('g-hacker');
  wrap.style.display='flex';
  setControlHint('TAP THE NODES IN THE ORDER THEY PULSED',
                 'CLICK NODES · OR THE 1234 / QWER / ASDF / ZXCV KEYPAD');

  const grid=document.getElementById('hack-grid');
  const statusEl=document.getElementById('hack-status');
  const seqEl=document.getElementById('hack-seq');
  // The LEVEL pill in .g-hdr is generic chrome that only Tetris happened to
  // claim first — reused here rather than adding a second identical pill.
  const lvlPill=document.getElementById('tetris-lvl-pill');
  const lvlEl=document.getElementById('tetris-lvl');
  lvlPill.style.display='';

  const diffMod=getDifficultyModifier();
  const KEYS=['1','2','3','4','Q','W','E','R','A','S','D','F','Z','X','C','V'];
  // Each row gets its own neon, so a long key is memorable by colour as well as
  // position. The four are hue-rotations of the equipped Black Market colour —
  // the keypad re-themes on equip while the rows stay distinct from each other.
  // The offsets are the original cyan/pink/lime/gold spacing, which is why the
  // default cyan still reproduces the palette this game shipped with.
  const ROW_COLORS=[0,144,-72,-132].map(d=>shiftHue(getEquippedColorHex(),d));
  const START_LEN=3;
  // Same sequence, less time to burn it in — the honest way to make a memory
  // game harder without making it unfair.
  const FLASH=Math.round(400/diffMod), GAP=Math.round(170/diffMod);
  const time0=Math.round(90*getTimeModifier());

  let level=1, score=0, seq=[], inputIdx=0, phase='play';
  let cleared=0, best=0, time=time0, ended=false;

  document.getElementById('g-time').textContent=time;
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--lime),var(--cyan))';

  // Rebuilding the keypad each round drops the previous round's click handlers
  // with the nodes that carried them — same trick Memory Match uses.
  grid.innerHTML='';
  const nodes=KEYS.map((k,i)=>{
    const n=document.createElement('div');
    n.className='hack-node';
    const c=ROW_COLORS[Math.floor(i/4)];
    n.style.setProperty('--nc', c);
    n.style.setProperty('--nc-soft', hexToRgba(c,0.22));
    n.style.setProperty('--nc-glow', hexToRgba(c,0.30));
    n.innerHTML=`<span class="hack-key">${k}</span>`;
    n.onclick=()=>press(i);
    grid.appendChild(n);
    return n;
  });

  function rnd(){ return Math.floor(Math.random()*16); }
  function setStatus(txt,cls){ statusEl.className='hack-status'+(cls?' '+cls:''); statusEl.textContent=txt; }
  function paintPips(){
    seqEl.innerHTML='';
    seq.forEach((_,i)=>{
      const p=document.createElement('div');
      p.className='hack-pip'+(i<inputIdx?' done':'');
      seqEl.appendChild(p);
    });
  }
  // Every deferred step goes through gLater(), so quitting mid-playback can't
  // leave a stray flash landing on the next round's keypad.
  // Each node carries its own pitch — the mainframe's broadcast is a melody,
  // and replaying it correctly plays that melody back. Getting one wrong is
  // audible before you've read the status line.
  function flash(i,ms){
    nodes[i].classList.add('lit');
    snd('node',{semi:i});
    gLater(()=>nodes[i].classList.remove('lit'), ms);
  }

  function playback(){
    phase='play';
    grid.classList.add('locked');
    inputIdx=0; paintPips();
    setStatus(`▶ BROADCASTING ${seq.length}-NODE KEY…`);
    let t=420;
    seq.forEach(idx=>{
      gLater(()=>{ if(!ended) flash(idx,FLASH); }, t);
      t+=FLASH+GAP;
    });
    gLater(()=>{
      if(ended) return;
      phase='input';
      grid.classList.remove('locked');
      setStatus('◀ REPLICATE THE SEQUENCE');
    }, t+120);
  }

  function nextLevel(){
    if(ended) return;
    // Seeds three at once, then grows by one per cleared level.
    if(!seq.length) for(let i=0;i<START_LEN;i++) seq.push(rnd());
    else seq.push(rnd());
    best=Math.max(best,seq.length);
    lvlEl.textContent=level;
    playback();
  }

  function press(i){
    if(ended || phase!=='input') return;
    if(seq[inputIdx]===i){
      flash(i,190);
      inputIdx++; score+=5; setLive(score); paintPips();
      if(inputIdx===seq.length){
        phase='clear';
        grid.classList.add('locked');
        cleared++;
        const bonus=40+level*12;
        score+=bonus; setLive(score);
        snd('success');
        setStatus(`✅ NODE DECRYPTED · +${bonus} PTS`);
        level++;
        gLater(nextLevel,950);
      }
    } else {
      systemLock(i);
    }
  }

  function systemLock(i){
    phase='lock';
    grid.classList.add('locked');
    nodes[i].classList.add('err');
    snd('error');
    setStatus('⛔ SYSTEM LOCK — INTRUSION TRACED','fail');
    // Show the node it should have been: a lockout you can learn something from.
    gLater(()=>{ if(!ended) flash(seq[inputIdx],700); }, 430);
    gLater(()=>end('locked'),1550);
  }

  window.onkeydown=e=>{
    if(e.ctrlKey||e.metaKey||e.altKey) return;   // don't eat browser shortcuts
    // Neither key is on the keypad, but both fire a focused button, so they get
    // swallowed before the early return rather than leaking out to the UI.
    if(e.code==='Space'||e.code==='Enter') e.preventDefault();
    const idx=KEYS.indexOf(String(e.key).toUpperCase());
    if(idx<0) return;
    e.preventDefault();
    press(idx);
  };

  gTimer=setInterval(()=>{
    if(ended) return;
    time--;
    document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/time0*100}%`;
    if(time<=8 && time>0 && phase==='input'){ setStatus('⚠️ TRACE INCOMING — HURRY','warn'); if(time<=5) snd('tick'); }
    if(time<=0) end('timeout');
  },1000);

  function end(reason){
    if(ended) return; ended=true;
    grid.classList.add('locked');
    const final=Math.min(800,score);
    showResults('hacker',final,{
      '📡 Run Terminated': reason==='timeout'?'TRACE TIMEOUT':'SYSTEM LOCK',
      '🔓 Mainframes Decrypted': cleared,
      '🧠 Longest Key': `${best} NODES`,
      '🏆 Score Accumulation': `${final} PTS`
    });
  }

  setStatus('⚡ UPLINK ESTABLISHED — WATCH THE NODES');
  nextLevel();
}

// ════════════════════════════════════════════
//  ☄️ GAME 15: METEOR SHIELD
// ════════════════════════════════════════════
function startMeteor(){
  document.getElementById('g-canvas-holder').style.display='block';
  setControls(null);   // the board itself is the control — no pad to steal height
  setControlHint('TAP TO BLAST · TAP THE PAD BELOW TO DEPLOY AN ABILITY',
                 'CLICK TO FIRE · ARROWS / WASD AIM · SPACE FIRES · Q/E ABILITY');
  showTouchHint('TAP ANYWHERE TO DETONATE A BLAST');
  fitCanvas();

  const diffMod=getDifficultyModifier();
  const W=BOARD_W, H=BOARD_H;
  const GROUND=H-34;
  // A tighter blast at higher tiers asks for better timing rather than faster
  // tapping — the ammo bank already caps how fast you can fire.
  const BLAST_R=Math.round(62/(1+(diffMod-1)*0.28));
  const MISSILE_V=9.5, AMMO_MAX=8, RELOAD=Math.round(820*diffMod);
  const time0=Math.round(80*getTimeModifier());
  const GLYPHS=['0','1','#','$','%','&','@','?','//','<>','01','ERR'];

  // ── TURRET GEOMETRY ──
  // The barrel pivots on top of the rack. Aim is measured from straight up,
  // positive to the right, and clamped short of horizontal so a battery can
  // never swing far enough to point into its own server stack.
  const PIVOT_Y=GROUND-30, BARREL_L=19, RECOIL_PX=6, AIM_LIMIT=1.32;
  // The smallest elevation the aim is ever measured against. The reticle can go
  // BELOW the pivot — it is clamped at GROUND-14, which is 16px under it, and
  // fragments land 30px under it — and an elevation measured from a target
  // below the muzzle is not an elevation at all: see aimAt().
  const MIN_ELEV=26;

  let score=0, time=time0, wave=1, isOver=false, frame=0, shake=0;
  let ammo=AMMO_MAX, reloadT=0, killed=0, bestChain=1;
  let frags=[], missiles=[], blasts=[], particles=[], floats=[];
  let toSpawn=0, spawnT=0, banner=120;
  let retX=W/2, retY=H*0.45, keys={}, lastT=performance.now();

  // aim/recoil/muzzle drive the animation; flash is the existing damage blink.
  const bases=[0.18,0.5,0.82].map(f=>({x:W*f, hp:2, alive:true, flash:0, aim:0, recoil:0, muzzle:0}));

  // ── BATTERY ABILITIES ──
  // One charge per wave purged, cycling the list. Deployed with Q/E or the pad
  // on the ground strip. Effect timers are in frames; the queue caps at three.
  const ABILITIES=[
    { id:'SALVO',  label:'🔥 RAPID SALVO', color:'#ff6600', desc:'AUTO-SALVO FIRING' },
    { id:'AEGIS',  label:'🛡️ AEGIS DOME',  color:'#39ff14', desc:'DOME ABSORBING HITS' },
    { id:'OVER',   label:'⚡ OVERCHARGE',  color:'#ffd700', desc:'WIDE BLASTS · FAST RELOAD' },
    { id:'REPAIR', label:'🔧 NANO-REPAIR', color:'#00f5ff', desc:'SERVER RESTORED' }
  ];
  const ABIL_MAX=3, OVER_FRAMES=420, DOME_FRAMES=420, SALVO_SHOTS=6;
  const DOME_RX=W*0.5, DOME_RY=96;
  const AB_PAD={x:10, y:GROUND+6, w:108, h:22};
  let abilQueue=[], abilEarned=0, activeAbil=null, abilT=0;
  let salvoLeft=0, salvoT=0, domeT=0, overT=0;

  document.getElementById('g-time').textContent=time;
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--orange),var(--gold))';

  const pop=(x,y,txt,color)=>floats.push({x,y,txt,color,alpha:1,vy:-0.9});
  function burst(x,y,color,n){
    for(let i=0;i<n;i++){
      const a=Math.random()*Math.PI*2, v=Math.random()*3.4+1;
      particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,alpha:1,color,r:Math.random()*2+1});
    }
  }

  function startWave(){ toSpawn=5+wave*2; spawnT=0; banner=120; }
  startWave();

  // allowSplit is strictly one generation deep. A child is born BELOW the
  // altitude band splitY is drawn from, so if it were allowed to roll its own
  // split it would fire on the very next frame — and so would its children.
  // That is a branching process, not a weapon: it grows without bound and
  // takes the frame rate with it.
  function spawnFrag(x, y, targetX, allowSplit){
    const alive=bases.filter(b=>b.alive);
    const tx = targetX!=null ? targetX
             : (alive.length ? alive[Math.floor(Math.random()*alive.length)].x : W/2);
    const sp=(1.05+wave*0.11)*diffMod;
    const dx=tx-x, dy=GROUND-y, d=Math.hypot(dx,dy)||1;
    frags.push({
      x, y, ox:x, oy:y, vx:dx/d*sp, vy:dy/d*sp,
      glyph:GLYPHS[Math.floor(Math.random()*GLYPHS.length)],
      // MIRV fragments only show up once the run has warmed up.
      split: !!allowSplit && wave>=3 && Math.random()<0.26,
      splitY: 130+Math.random()*120
    });
  }

  // Launches come from whichever server is nearest the target, so losing a
  // server costs you reach as well as a life.
  function nearestBase(tx){
    const alive=bases.filter(b=>b.alive);
    if(!alive.length) return null;
    let from=alive[0];
    alive.forEach(b=>{ if(Math.abs(b.x-tx)<Math.abs(from.x-tx)) from=b; });
    return from;
  }

  // Elevation off straight up, positive to the right, clamped short of
  // horizontal so a battery can never point into its own server stack.
  //
  // The vertical component is FLOORED, and that is the whole fix. Measured raw,
  // `PIVOT_Y-ty` goes negative for any target below the pivot — the bottom 16px
  // the reticle can reach, and every fragment in the act of landing — and
  // atan2 with a negative second argument returns an angle PAST ±90° whose sign
  // flips the instant the target crosses the barrel's own x. Two board pixels
  // of reticle movement (279 → 281, either side of the middle rack) swung every
  // barrel through 151°: atan2(-1,-16) = -3.08 rad and atan2(1,-16) = +3.08,
  // both clamped to the opposite ends of AIM_LIMIT. So the guns snapped
  // violently from one side to the other exactly when the player was tracking
  // something about to hit the ground, and sat pinned at 76° pointing at their
  // neighbours instead of at the target. fire() reads the tip from this angle,
  // so the missile left the side of a sideways barrel too.
  //
  // Floored, the elevation is always measured from a point above the muzzle, so
  // the angle stays inside ±90°, is continuous everywhere, and reads the way a
  // mount should: near vertical for a target overhead, leaning further over the
  // lower and wider the target gets, horizontal only for something genuinely
  // out to the side.
  function aimAt(b,tx,ty){
    const a=Math.atan2(tx-b.x, Math.max(PIVOT_Y-ty, MIN_ELEV));
    return Math.max(-AIM_LIMIT, Math.min(AIM_LIMIT, a));
  }
  // recoil is passed rather than read, so a launch can ask for the tip at full
  // extension while the drawing asks for wherever the barrel currently sits.
  function barrelTip(b, recoil){
    const len=BARREL_L-recoil*RECOIL_PX;
    return { x:b.x+Math.sin(b.aim)*len, y:PIVOT_Y-Math.cos(b.aim)*len };
  }

  // Overcharge widens every blast and cuts the reload; both are read through
  // these so the buff can't drift out of sync with the HUD that reports it.
  const blastR  = () => overT>0 ? BLAST_R*1.7 : BLAST_R;
  const reloadMs= () => overT>0 ? RELOAD*0.35 : RELOAD;

  function inDome(x,y){
    if(y>GROUND) return false;
    const nx=(x-W/2)/DOME_RX, ny=(y-GROUND)/DOME_RY;
    return nx*nx+ny*ny<=1;
  }

  // free shots come from RAPID SALVO and skip the ammo bank.
  function fire(tx,ty,free){
    if(isOver) return;
    if(!free && ammo<=0){ snd('deny'); pop(tx,ty,'RELOADING','#ff2442'); return; }
    const from=nearestBase(tx);
    if(!from) return;
    if(!free) ammo--;
    snd('missile');
    // Snap the firing battery onto the shot before measuring the muzzle. A tap
    // can beat the idle tracking to a target, and a missile leaving the side of
    // a barrel is the one thing that would give the animation away.
    from.aim=aimAt(from,tx,ty);
    const tip=barrelTip(from, 0);
    from.recoil=1; from.muzzle=1;
    shake=Math.max(shake,3);
    const sx=tip.x, sy=tip.y, d=Math.hypot(tx-sx,ty-sy)||1;
    missiles.push({x:sx,y:sy,sx,sy,tx,ty,vx:(tx-sx)/d*MISSILE_V,vy:(ty-sy)/d*MISSILE_V});
    burst(sx,sy,'#ffd700',4);
  }

  function detonate(x,y,r,chain){
    blasts.push({x,y,r:2,max:r,grow:true,chain:chain||0});
    shake=Math.max(shake,6);
    // Secondary detonations in a chain are quieter and higher than the shot
    // that started them, so a big cluster reads as one rolling blast.
    snd(chain ? 'explode' : 'bigExplode');
    burst(x,y,getEquippedColorHex(),8);
  }

  function grantAbility(){
    // A full bank loses the wave's charge, but the rotation does NOT advance —
    // otherwise hoarding could skip you past NANO-REPAIR entirely, which is the
    // one charge you most want available when a rack is already down.
    if(abilQueue.length>=ABIL_MAX) return;
    const a=ABILITIES[abilEarned % ABILITIES.length];
    abilEarned++;
    abilQueue.push(a);
    pop(W/2, H*0.47, `${a.label} READY`, a.color);
  }

  function deployAbility(){
    if(isOver || !abilQueue.length) return;
    const a=abilQueue.shift();
    activeAbil=a; abilT=170;
    shake=Math.max(shake,7);
    snd(a.id==='REPAIR' ? 'heal' : a.id==='AEGIS' ? 'shield' : 'ability');
    pop(W/2, H*0.34, a.label, a.color);

    if(a.id==='SALVO'){ salvoLeft=SALVO_SHOTS; salvoT=0; }
    else if(a.id==='AEGIS'){ domeT=DOME_FRAMES; }
    else if(a.id==='OVER'){ overT=OVER_FRAMES; ammo=AMMO_MAX; reloadT=0; }
    else if(a.id==='REPAIR'){
      // Revive a downed rack first, else patch the most damaged one. If every
      // rack is already full the charge refills the ammo bank rather than
      // silently doing nothing.
      const dead=bases.find(b=>!b.alive);
      const hurt=bases.filter(b=>b.alive && b.hp<2).sort((p,q)=>p.hp-q.hp)[0];
      if(dead){
        dead.alive=true; dead.hp=1; dead.flash=24; dead.aim=0; dead.recoil=0; dead.muzzle=0;
        pop(dead.x, GROUND-46, 'SERVER ONLINE', '#39ff14');
        burst(dead.x, GROUND-14, '#39ff14', 20);
      } else if(hurt){
        hurt.hp=2; hurt.flash=24;
        pop(hurt.x, GROUND-46, 'SHIELD RESTORED', '#39ff14');
        burst(hurt.x, GROUND-14, '#39ff14', 16);
      } else {
        ammo=AMMO_MAX; reloadT=0;
        pop(W/2, H*0.4, 'AMMO BANK REFILLED', '#39ff14');
      }
    }
  }

  const inAbilPad=(px,py)=>px>=AB_PAD.x && px<=AB_PAD.x+AB_PAD.w
                        && py>=AB_PAD.y && py<=AB_PAD.y+AB_PAD.h;

  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      // The pad sits in the ground strip — terrain, not airspace. A blast down
      // there is worthless anyway, so claiming those taps costs no shots.
      if(inAbilPad(p.x,p.y)){ if(abilQueue.length) deployAbility(); return; }
      retX=p.x; retY=p.y; fire(p.x,p.y);
    },
    onHover(p){ if(!p.touch){ retX=p.x; retY=p.y; } }
  });

  window.onkeydown=e=>{
    if(['Space','Enter','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyW','KeyA','KeyS','KeyD'].includes(e.code)) e.preventDefault();
    keys[e.code]=true;
    if(e.code==='Space'||e.code==='Enter') fire(retX,retY);
    if(!e.repeat && (e.code==='KeyQ'||e.code==='KeyE')) deployAbility();
  };
  window.onkeyup=e=>{ keys[e.code]=false; };

  gTimer=setInterval(()=>{
    if(isOver) return;
    time--;
    document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${time/time0*100}%`;
    if(time<=5&&time>0) snd('tick');
    if(time<=0) end('timeout');
  },1000);

  function end(reason){
    if(isOver) return; isOver=true;
    const aliveN=bases.filter(b=>b.alive).length;
    const survive=aliveN*70;
    const final=Math.min(1100, score+survive);
    showResults('meteor',final,{
      '📡 Run Terminated': reason==='overrun'?'ALL SERVERS DOWN':'MISSION CLOCK EXPIRED',
      '☄️ Fragments Purged': killed,
      '🌊 Wave Reached': wave,
      '💥 Best Chain': `${bestChain}×`,
      '🖥️ Servers Intact': `${aliveN} (+${survive})`,
      '🏆 Score Accumulation': `${final} PTS`
    });
  }

  function damageBase(b){
    b.hp--; b.flash=20; shake=18;
    burst(b.x,GROUND-10,'#ff2442',22);
    if(b.hp<=0){
      b.alive=false;
      snd('gameOver');
      pop(b.x,GROUND-40,'SERVER LOST','#ff2442');
      if(!bases.some(s=>s.alive)) end('overrun');
    } else {
      snd('hurt');
      pop(b.x,GROUND-40,'SHIELD DOWN','#ff6600');
    }
  }

  function drawBase(b){
    aCtx.save();
    const x=b.x;
    if(!b.alive){
      // Wreckage: a dead rack still marks the position you failed to hold
      aCtx.fillStyle='rgba(60,60,70,0.85)';
      aCtx.beginPath(); aCtx.moveTo(x-22,GROUND); aCtx.lineTo(x-12,GROUND-14);
      aCtx.lineTo(x+6,GROUND-8); aCtx.lineTo(x+22,GROUND); aCtx.closePath(); aCtx.fill();
      if(frame%7===0) particles.push({x:x+(Math.random()-0.5)*20,y:GROUND-12,vx:(Math.random()-0.5)*0.6,vy:-0.9,alpha:0.5,color:'#555',r:3});
      aCtx.restore(); return;
    }
    const hurt=b.hp<=1;
    const col=b.flash>0 ? '#fff' : (hurt?'#ff6600':'#39ff14');
    aCtx.shadowBlur=hurt?18:12; aCtx.shadowColor=col;
    aCtx.fillStyle='rgba(10,14,26,0.95)';
    aCtx.beginPath(); aCtx.roundRect(x-22,GROUND-30,44,30,4); aCtx.fill();
    aCtx.strokeStyle=col; aCtx.lineWidth=2; aCtx.stroke();
    // Rack LEDs
    for(let r=0;r<3;r++){
      const on = !hurt || (frame+r*9)%26<15;
      aCtx.fillStyle = on ? col : 'rgba(255,255,255,0.1)';
      aCtx.fillRect(x-16, GROUND-25+r*8, 32, 4);
    }
    aCtx.restore();

    // ── TURRET ──
    // Everything below rides in the barrel's own rotated frame, so the recoil
    // slide and the muzzle flare stay true to the aim at any angle.
    const kick=b.recoil*RECOIL_PX;
    const tipY=-BARREL_L+kick;
    aCtx.save();
    aCtx.translate(x, PIVOT_Y);
    aCtx.rotate(b.aim);

    // Barrel — dark body, lit edge, muzzle collar at the tip
    aCtx.shadowBlur=hurt?14:9; aCtx.shadowColor=col;
    aCtx.fillStyle='rgba(10,14,26,0.95)';
    aCtx.beginPath(); aCtx.roundRect(-3.5, tipY, 7, BARREL_L, 2); aCtx.fill();
    aCtx.strokeStyle=col; aCtx.lineWidth=1.5; aCtx.stroke();
    aCtx.fillStyle=col;
    aCtx.fillRect(-4.5, tipY, 9, 3);

    // Muzzle flare — a bright cone that collapses back into the barrel
    if(b.muzzle>0.02){
      aCtx.globalAlpha=b.muzzle;
      aCtx.shadowBlur=20; aCtx.shadowColor='#ffd700';
      aCtx.fillStyle='#fff';
      aCtx.beginPath();
      aCtx.moveTo(0, tipY-14*b.muzzle);
      aCtx.lineTo(7*b.muzzle, tipY+3);
      aCtx.lineTo(-7*b.muzzle, tipY+3);
      aCtx.closePath(); aCtx.fill();
      aCtx.globalAlpha=1;
    }
    aCtx.restore();

    // Yoke sits outside the rotation so the pivot itself never appears to spin
    aCtx.save();
    aCtx.shadowBlur=hurt?12:8; aCtx.shadowColor=col;
    aCtx.fillStyle='rgba(10,14,26,0.95)';
    aCtx.beginPath(); aCtx.arc(x, PIVOT_Y, 6, 0, Math.PI*2); aCtx.fill();
    aCtx.strokeStyle=col; aCtx.lineWidth=1.5; aCtx.stroke();
    aCtx.restore();

    if(b.flash>0) b.flash--;
  }

  function drawHUD(){
    aCtx.save();
    aCtx.fillStyle='rgba(0,0,0,0.5)'; aCtx.strokeStyle='rgba(255,102,0,0.5)'; aCtx.lineWidth=1;
    aCtx.beginPath(); aCtx.roundRect(8,10,132,26,6); aCtx.fill(); aCtx.stroke();
    aCtx.fillStyle='#ff6600'; aCtx.font='bold 9px Orbitron,monospace';
    aCtx.shadowBlur=6; aCtx.shadowColor='#ff6600';
    aCtx.fillText(`WAVE ${wave}`, 15, 27);
    aCtx.fillStyle='#ffd700'; aCtx.shadowColor='#ffd700';
    aCtx.fillText(`☄ ${killed}`, 78, 27);

    // Ammo pips — the whole tactical constraint in one row
    const eq=getEquippedColorHex();
    for(let i=0;i<AMMO_MAX;i++){
      const on=i<ammo;
      aCtx.fillStyle=on?eq:'rgba(255,255,255,0.13)';
      aCtx.shadowBlur=on?8:0; aCtx.shadowColor=eq;
      aCtx.beginPath(); aCtx.roundRect(W-16-i*15, 14, 9, 16, 2); aCtx.fill();
    }
    // Partial recharge on the next empty slot
    if(ammo<AMMO_MAX){
      aCtx.fillStyle=hexToRgba(eq,0.45); aCtx.shadowBlur=0;
      const h=16*Math.min(1, reloadT/reloadMs());
      aCtx.fillRect(W-16-ammo*15, 30-h, 9, h);
    }

    // Active-effect chips, stacked under the wave box
    let cy=44;
    const chip=(txt,frac,color)=>{
      aCtx.shadowBlur=0;
      aCtx.fillStyle='rgba(0,0,0,0.45)';
      aCtx.beginPath(); aCtx.roundRect(8,cy,104,13,4); aCtx.fill();
      aCtx.fillStyle=hexToRgba(color,0.30);
      aCtx.beginPath(); aCtx.roundRect(8,cy,104*Math.max(0,Math.min(1,frac)),13,4); aCtx.fill();
      aCtx.fillStyle=color; aCtx.font='bold 7px Orbitron,monospace';
      aCtx.fillText(txt, 13, cy+9);
      cy+=16;
    };
    if(overT>0)     chip('⚡ OVERCHARGE', overT/OVER_FRAMES, '#ffd700');
    if(domeT>0)     chip('🛡 AEGIS DOME', domeT/DOME_FRAMES, '#39ff14');
    if(salvoLeft>0) chip(`🔥 SALVO ×${salvoLeft}`, salvoLeft/SALVO_SHOTS, '#ff6600');
    aCtx.restore();
  }

  // ── ABILITY PAD ──
  // Lives in the ground strip so it costs the playfield no height, and reads as
  // part of the installation rather than an overlay.
  function drawAbilityPad(){
    const next=abilQueue[0] || null;
    const col=next ? next.color : 'rgba(255,255,255,0.20)';
    const pulse=next ? 0.55+Math.sin(frame*0.13)*0.45 : 0;
    aCtx.save();
    aCtx.fillStyle='rgba(0,0,0,0.55)';
    aCtx.strokeStyle=col; aCtx.lineWidth=1.5;
    if(next){ aCtx.shadowBlur=14*pulse; aCtx.shadowColor=next.color; }
    aCtx.beginPath(); aCtx.roundRect(AB_PAD.x,AB_PAD.y,AB_PAD.w,AB_PAD.h,6);
    aCtx.fill(); aCtx.stroke();
    aCtx.shadowBlur=0;

    aCtx.textAlign='center'; aCtx.textBaseline='middle';
    aCtx.fillStyle=col; aCtx.font='bold 8px Orbitron,monospace';
    aCtx.fillText(next ? next.label : 'NO CHARGE', AB_PAD.x+AB_PAD.w/2, AB_PAD.y+8);
    aCtx.fillStyle=next ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.22)';
    aCtx.font='bold 6px Orbitron,monospace';
    aCtx.fillText(next ? (isTouchDevice?'TAP TO DEPLOY':'CLICK OR [Q]') : 'CLEAR A WAVE',
                  AB_PAD.x+AB_PAD.w/2, AB_PAD.y+16);

    // Queued charges beyond the one on deck
    for(let i=1;i<abilQueue.length;i++){
      aCtx.fillStyle=abilQueue[i].color;
      aCtx.beginPath(); aCtx.arc(AB_PAD.x+AB_PAD.w+7+(i-1)*9, AB_PAD.y+AB_PAD.h/2, 3, 0, Math.PI*2);
      aCtx.fill();
    }
    aCtx.restore();
  }

  function loop(now){
    if(isOver) return;
    gameLoopId=requestAnimationFrame(loop);
    const dt=Math.min(50, now-lastT); lastT=now;
    frame++;
    // Everything the player owns — reticle, missiles, blast core, kill sparks —
    // is drawn in the equipped Black Market colour. Incoming fragments keep their
    // fixed red and the servers their green, so a loud cosmetic can never make a
    // threat or a dying base harder to read.
    const eq=getEquippedColorHex();

    // Reticle steering for keyboard players
    const RS=7;
    if(keys['ArrowLeft'] ||keys['KeyA']) retX-=RS;
    if(keys['ArrowRight']||keys['KeyD']) retX+=RS;
    if(keys['ArrowUp']   ||keys['KeyW']) retY-=RS;
    if(keys['ArrowDown'] ||keys['KeyS']) retY+=RS;
    retX=Math.max(8,Math.min(W-8,retX)); retY=Math.max(8,Math.min(GROUND-14,retY));

    if(ammo<AMMO_MAX){
      reloadT+=dt;
      if(reloadT>=reloadMs()){ ammo++; reloadT=0; }
    }
    if(banner>0) banner--;

    // ── TURRETS ──
    // Idle batteries ease onto the reticle so the guns are always looking where
    // you are; recoil and muzzle flare decay on their own clocks.
    //
    // All three rates are PER SECOND, raised to this frame's own share of one.
    // As bare per-frame constants they were rates per REFRESH: the barrel
    // tracked 2.4× faster on a 144Hz panel than the 60Hz it was tuned on, and
    // the muzzle flare — 0.74 a frame, a ~9-frame life — was gone in 60ms
    // there and lingered for a fifth of a second on a 30fps phone. Recoil was
    // the worst of the three, because `fire()` sets it to 1 on a tap: on a fast
    // display the barrel was back at full extension before the missile had
    // cleared the muzzle, so the kick simply did not read.
    const fr = dt / 16.6667;
    const decay = (k) => Math.pow(k, fr);
    bases.forEach(b=>{
      if(!b.alive) return;
      b.aim += (aimAt(b,retX,retY)-b.aim)*(1-decay(0.82));
      b.recoil*=decay(0.82); if(b.recoil<0.01) b.recoil=0;
      b.muzzle*=decay(0.74); if(b.muzzle<0.02) b.muzzle=0;
    });

    // ── ABILITY TIMERS ──
    if(abilT>0){ abilT--; if(!abilT) activeAbil=null; }
    if(overT>0) overT--;
    if(domeT>0) domeT--;
    if(salvoLeft>0){
      salvoT+=dt;
      // Shots stay banked while the sky is empty rather than firing into
      // nothing, so a salvo deployed on the last fragment isn't wasted.
      if(salvoT>=130 && frags.length){
        salvoT=0;
        let target=frags[0];
        frags.forEach(f=>{ if(f.y>target.y) target=f; });   // lowest = closest to landing
        const src=nearestBase(target.x);
        if(src){
          // Lead the shot, or an auto-salvo mostly detonates behind its marks.
          const t=Math.hypot(target.x-src.x, target.y-PIVOT_Y)/MISSILE_V;
          const lx=Math.max(10, Math.min(W-10, target.x+target.vx*t));
          const ly=Math.max(14, Math.min(GROUND-8, target.y+target.vy*t));
          fire(lx,ly,true);
          salvoLeft--;
        }
      }
    }

    // ── SPAWNING ──
    spawnT+=dt;
    const interval=Math.max(360, 1150-wave*70)/diffMod;
    if(toSpawn>0 && spawnT>=interval && banner<=0){
      spawnT=0; toSpawn--;
      spawnFrag(Math.random()*(W-40)+20, -16, null, true);
    }
    if(toSpawn===0 && !frags.length && !missiles.length){
      const bonus=40+wave*20;
      score+=bonus; setLive(score);
      snd('wave');
      pop(W/2,H*0.4,`WAVE ${wave} PURGED +${bonus}`,'#39ff14');
      grantAbility();
      wave++; startWave();
    }

    // ── MISSILES ──
    for(let i=missiles.length-1;i>=0;i--){
      const m=missiles[i];
      m.x+=m.vx; m.y+=m.vy;
      if(Math.hypot(m.tx-m.x, m.ty-m.y)<=MISSILE_V){
        detonate(m.tx,m.ty,blastR(),0);
        missiles.splice(i,1);
      }
    }

    // ── FRAGMENTS ──
    for(let i=frags.length-1;i>=0;i--){
      const f=frags[i];
      f.x+=f.vx; f.y+=f.vy;
      if(f.split && f.y>f.splitY){
        f.split=false;
        const alive=bases.filter(b=>b.alive);
        for(let k=0;k<2;k++){
          const t=alive.length?alive[Math.floor(Math.random()*alive.length)].x:W/2;
          spawnFrag(f.x, f.y, t, false);
        }
        burst(f.x,f.y,'#a855f7',10);
      }
      // Aegis burns anything that reaches the dome. The test is the same
      // ellipse the dome is drawn from, so the barrier stops exactly where it
      // looks like it stops.
      if(domeT>0 && inDome(f.x,f.y)){
        burst(f.x,f.y,'#39ff14',12);
        snd('hit');
        score+=10; killed++; setLive(score);
        pop(f.x,f.y-12,'+10','#39ff14');
        frags.splice(i,1);
        continue;
      }
      if(f.y>=GROUND){
        burst(f.x,GROUND,'#ff6600',14);
        const hit=bases.find(b=>b.alive && Math.abs(b.x-f.x)<28);
        if(hit) damageBase(hit); else shake=Math.max(shake,6);
        frags.splice(i,1);
        if(isOver) return;
      }
    }

    // ── BLASTS ──
    for(let i=blasts.length-1;i>=0;i--){
      const b=blasts[i];
      if(b.grow){ b.r+=3.4; if(b.r>=b.max) b.grow=false; }
      else { b.r-=2.2; if(b.r<=0){ blasts.splice(i,1); continue; } }

      for(let j=frags.length-1;j>=0;j--){
        const f=frags[j];
        if(Math.hypot(f.x-b.x, f.y-b.y)>b.r) continue;
        b.chain++;
        bestChain=Math.max(bestChain,b.chain);
        snd('combo',{semi:Math.min(12,b.chain-1)});
        // Each extra kill inside one blast is worth more than the last, so
        // waiting for a cluster beats swatting fragments one at a time.
        const pts=20*b.chain;
        score+=pts; killed++; setLive(score);
        pop(f.x,f.y,`+${pts}`, b.chain>1?'#ffd700':eq);
        burst(f.x,f.y,eq,10);
        frags.splice(j,1);
        // Secondary detonation keeps the chain rolling outward, Missile-Command style
        detonate(f.x,f.y,blastR()*0.62,b.chain);
      }
    }

    // ── DRAW ──
    aCtx.clearRect(0,0,W,H);
    aCtx.save();
    if(shake>0){
      aCtx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake);
      shake*=0.86; if(shake<0.4) shake=0;
    }

    aCtx.strokeStyle='rgba(255,102,0,0.05)'; aCtx.lineWidth=1;
    for(let x=0;x<=W;x+=40){aCtx.beginPath();aCtx.moveTo(x,0);aCtx.lineTo(x,H);aCtx.stroke();}
    for(let y=0;y<=H;y+=40){aCtx.beginPath();aCtx.moveTo(0,y);aCtx.lineTo(W,y);aCtx.stroke();}

    // Ground
    aCtx.fillStyle='rgba(255,102,0,0.09)'; aCtx.fillRect(0,GROUND,W,H-GROUND);
    aCtx.strokeStyle='rgba(255,102,0,0.55)'; aCtx.lineWidth=2;
    aCtx.shadowBlur=12; aCtx.shadowColor='#ff6600';
    aCtx.beginPath(); aCtx.moveTo(0,GROUND); aCtx.lineTo(W,GROUND); aCtx.stroke();
    aCtx.shadowBlur=0;

    bases.forEach(drawBase);

    // Aegis dome — drawn from the same ellipse inDome() tests against
    if(domeT>0){
      const fade=Math.min(1, domeT/50);
      const pulse=0.45+Math.sin(frame*0.16)*0.13;
      aCtx.save();
      aCtx.beginPath(); aCtx.ellipse(W/2,GROUND,DOME_RX,DOME_RY,0,Math.PI,Math.PI*2);
      aCtx.closePath();
      aCtx.fillStyle=`rgba(57,255,20,${fade*0.07})`; aCtx.fill();
      aCtx.strokeStyle=`rgba(57,255,20,${fade*pulse})`; aCtx.lineWidth=2.5;
      aCtx.shadowBlur=20; aCtx.shadowColor='#39ff14';
      aCtx.stroke();
      aCtx.restore();
    }

    // Fragment trails + heads
    frags.forEach(f=>{
      aCtx.save();
      aCtx.strokeStyle='rgba(255,36,66,0.32)'; aCtx.lineWidth=1.5;
      aCtx.setLineDash([5,5]);
      aCtx.beginPath(); aCtx.moveTo(f.ox,f.oy); aCtx.lineTo(f.x,f.y); aCtx.stroke();
      aCtx.setLineDash([]);
      aCtx.shadowBlur=14; aCtx.shadowColor='#ff2442';
      aCtx.fillStyle='#ff2442'; aCtx.font='bold 13px Orbitron,monospace';
      aCtx.textAlign='center'; aCtx.textBaseline='middle';
      aCtx.fillText(f.glyph,f.x,f.y);
      aCtx.restore();
    });

    // Missiles
    missiles.forEach(m=>{
      aCtx.save();
      aCtx.strokeStyle=hexToRgba(eq,0.5); aCtx.lineWidth=2;
      aCtx.shadowBlur=10; aCtx.shadowColor=eq;
      aCtx.beginPath(); aCtx.moveTo(m.sx,m.sy); aCtx.lineTo(m.x,m.y); aCtx.stroke();
      aCtx.fillStyle='#fff';
      aCtx.beginPath(); aCtx.arc(m.x,m.y,3,0,Math.PI*2); aCtx.fill();
      // Target marker
      aCtx.strokeStyle=hexToRgba(eq,0.35); aCtx.lineWidth=1;
      aCtx.beginPath(); aCtx.arc(m.tx,m.ty,5,0,Math.PI*2); aCtx.stroke();
      aCtx.restore();
    });

    // Blasts
    blasts.forEach(b=>{
      aCtx.save();
      const g=aCtx.createRadialGradient(b.x,b.y,0,b.x,b.y,Math.max(1,b.r));
      g.addColorStop(0,'rgba(255,255,255,0.95)');
      g.addColorStop(0.45,hexToRgba(eq,0.55));
      g.addColorStop(1,hexToRgba(eq,0));
      aCtx.fillStyle=g;
      aCtx.beginPath(); aCtx.arc(b.x,b.y,Math.max(1,b.r),0,Math.PI*2); aCtx.fill();
      aCtx.strokeStyle='rgba(255,255,255,0.7)'; aCtx.lineWidth=1.5;
      aCtx.stroke();
      aCtx.restore();
    });

    // Reticle
    aCtx.save();
    aCtx.strokeStyle=hexToRgba(eq,0.75); aCtx.lineWidth=1.5;
    aCtx.shadowBlur=10; aCtx.shadowColor=eq;
    aCtx.beginPath(); aCtx.arc(retX,retY,11,0,Math.PI*2); aCtx.stroke();
    aCtx.beginPath();
    aCtx.moveTo(retX-17,retY); aCtx.lineTo(retX-5,retY);
    aCtx.moveTo(retX+5,retY);  aCtx.lineTo(retX+17,retY);
    aCtx.moveTo(retX,retY-17); aCtx.lineTo(retX,retY-5);
    aCtx.moveTo(retX,retY+5);  aCtx.lineTo(retX,retY+17);
    aCtx.stroke();
    aCtx.restore();

    // Flat fills, no per-particle shadowBlur — see the note in Cyber Runner.
    // A dense wave here can put a hundred sparks on screen at once.
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i];
      p.x+=p.vx; p.y+=p.vy; p.vy+=0.05; p.alpha-=0.03;
      if(p.alpha<=0){ particles.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=p.alpha; aCtx.fillStyle=p.color;
      aCtx.beginPath(); aCtx.arc(p.x,p.y,p.r,0,Math.PI*2); aCtx.fill(); aCtx.restore();
    }
    for(let i=floats.length-1;i>=0;i--){
      const f=floats[i];
      f.y+=f.vy; f.alpha-=0.018;
      if(f.alpha<=0){ floats.splice(i,1); continue; }
      aCtx.save(); aCtx.globalAlpha=f.alpha; aCtx.fillStyle=f.color;
      aCtx.font='bold 12px Orbitron,monospace'; aCtx.textAlign='center';
      aCtx.shadowBlur=10; aCtx.shadowColor=f.color;
      aCtx.fillText(f.txt,f.x,f.y); aCtx.restore();
    }

    aCtx.restore();
    drawHUD();
    drawAbilityPad();

    if(activeAbil){
      aCtx.save();
      aCtx.globalAlpha=Math.min(1, abilT/30);
      aCtx.fillStyle=activeAbil.color; aCtx.font='bold 10px Orbitron,monospace';
      aCtx.textAlign='center'; aCtx.shadowBlur=12; aCtx.shadowColor=activeAbil.color;
      aCtx.fillText(`ACTIVE: ${activeAbil.desc}`, W/2, 56);
      aCtx.restore();
    }

    if(banner>0){
      aCtx.save();
      aCtx.globalAlpha=Math.min(1,banner/40);
      aCtx.fillStyle='#ff6600'; aCtx.font='bold 22px Orbitron,monospace';
      aCtx.textAlign='center'; aCtx.shadowBlur=18; aCtx.shadowColor='#ff6600';
      aCtx.fillText(`WAVE ${wave}`, W/2, H*0.42);
      aCtx.fillStyle='rgba(255,255,255,0.7)'; aCtx.font='bold 10px Orbitron,monospace';
      aCtx.fillText('INCOMING MALICIOUS CODE', W/2, H*0.42+22);
      aCtx.restore();
    }
  }
  requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🤖 GAME 16: BATTLE BOTS — LANE SIEGE
// ════════════════════════════════════════════
// A side-scrolling lane defence. RAM accrues on its own, you spend it on bots
// that walk right under their own power, and the two fronts brawl wherever
// they happen to meet. Bring The Glitch down before it breaches the Mainframe.
//
// The game owns no timers of its own: the siege clock is gTimer, the battle
// loop is gameLoopId, deferred effects go through gLater() and the keyboard
// lives on window.onkeydown — all four are torn down by stopGame(), which also
// empties the deploy deck. Quitting therefore leaves nothing of this running.
//
// The BB* consts below are initialised at load time and read BOARD_W, so they
// have to stay below its declaration — which is why the whole game sits here
// with the other start* functions rather than at the top of the file.
// ── TUNING ──
// Everything that decides how the siege feels lives here, so balancing never
// means reading the simulation.
const BB = {
  baseHP: 1000,

  // Bases are fortified: a bot that reaches one deals only this fraction of its
  // damage there. Without it, whoever's first blob gets across simply wins —
  // four Scouts would delete a 1000 HP base in ten seconds and the siege would
  // never become a siege. It's deliberately low, and paired with player units
  // that clearly out-duel their counterparts: together those two make the
  // battle's LENGTH come from chewing through a fixed 1000 HP, which is linear
  // and predictable, rather than from wherever the lane's attrition equilibrium
  // happens to settle — a knife edge where an 8% enemy buff is the difference
  // between a reliable win and a permanent midfield stall. This is the dial to
  // turn for battle length; unit-vs-unit combat is balanced on its own terms.
  // Raised 0.30 -> 0.33 with the five-bot roster: headless siege sims left
  // Meltdown's only failures as near-miss timeouts (~100 HP shy of the purge),
  // and the extra 10% of base chew converts those into wins for tight play
  // without changing a single duel. Both sides get it; the Mainframe still
  // never actually fell across 1800 simulated sieges, so in practice it is
  // pure pace.
  siege: 0.33,

  // Edge gap a unit keeps behind the ally in front of it in its own lane.
  // Without this queueing, both sides' units occupy the same x and the WHOLE
  // stack attacks the single front enemy at once — army size then multiplies
  // damage instead of adding depth, and the larger stack wins every fight with
  // no losses at all. Queued, each lane resolves as a duel and reinforcements
  // matter because they step up when the unit in front dies.
  spacing: 3,

  // Economy. Bots are cheap enough to feel disposable; the upgrade is a real
  // decision, costing several Tanks up front to pay off over the whole siege.
  ram:      { start: 80, cap: 999, rate: 20, step: 8, tiers: [150, 260, 420, 700] },

  // Player units. `reach` is the EDGE gap at which a unit stops and swings, so
  // small numbers read as melee — the two sprites end up nearly touching.
  // A Scout beats a lone BUG comfortably: the early game has to let you push
  // the line forward, or there's no siege to fight back from later.
  // `reach` doubles as the ranged stat: anything at or past BB_RANGED stops
  // well short of the brawl and fires tracers instead. The attack check runs
  // BEFORE the ally-queue check in stepSide(), so a Zapper shoots OVER the
  // ally holding the line in front of it — which is what makes Firewall+Zapper
  // a real combo rather than two units taking turns to die.
  units: {
    scout:  { key:'scout',  icon:'🤖', name:'SCOUT',    cost:30,  hp:110, atk:14, speed:40, reach:8,  rate:520,  cool:800,  w:22, h:26 },
    wall:   { key:'wall',   icon:'🧱', name:'FIREWALL', cost:20,  hp:320, atk:4,  speed:30, reach:6,  rate:1000, cool:1800, w:24, h:26 },
    zapper: { key:'zapper', icon:'🔫', name:'ZAPPER',   cost:70,  hp:90,  atk:16, speed:30, reach:52, rate:700,  cool:1600, w:22, h:26 },
    tank:   { key:'tank',   icon:'🛡️', name:'TANK',     cost:110, hp:380, atk:30, speed:22, reach:12, rate:950,  cool:2400, w:30, h:34 },
    titan:  { key:'titan',  icon:'🦾', name:'TITAN',    cost:300, hp:950, atk:62, speed:14, reach:12, rate:1300, cool:6000, w:36, h:42 }
  },

  // The deck's artillery piece: flat damage to every hostile on the field, on
  // the longest cooldown in the deck. 70 deletes the chaff outright (BUG,
  // SPYWARE) and softens everything heavier without touching the bases — it
  // buys the front line a breath, it doesn't win the siege by itself.
  emp: { cost:120, dmg:70, cool:22000 },

  // Hostiles. `from` is the elapsed second at which the type joins the spawn
  // pool, and `bounty` is the RAM a kill pays back — pushing the front line
  // forward is how you part-fund the next push. Bounties stay well under what
  // the kill cost you: paying for itself turns a winning Scout into free
  // reinforcement and the battle snowballs out of the player's hands.
  // ADWARE is the enemy's ranged answer — it out-reaches everything but the
  // Zapper, so a pure turtle gets chipped down and pushing the line stays the
  // winning move. SPYWARE is fast chaff that makes the EMP feel great, and
  // TROJAN.SYS is the gilded siege engine that punishes a stalled front late.
  foes: {
    bug:     { key:'bug',     icon:'🐛', name:'BUG',        hp:70,  atk:10, speed:34, reach:8,  rate:620,  w:22, h:24, color:'#ff0090', from:0,   bounty:5  },
    virus:   { key:'virus',   icon:'🦠', name:'VIRUS',      hp:170, atk:18, speed:22, reach:10, rate:880,  w:28, h:30, color:'#a855f7', from:45,  bounty:12 },
    adware:  { key:'adware',  icon:'📢', name:'ADWARE',     hp:130, atk:12, speed:26, reach:46, rate:900,  w:26, h:28, color:'#ff8c00', from:70,  bounty:16 },
    worm:    { key:'worm',    icon:'🪱', name:'WORM.EXE',   hp:430, atk:34, speed:16, reach:12, rate:1150, w:34, h:38, color:'#ff2442', from:105, bounty:28 },
    spyware: { key:'spyware', icon:'🕷️', name:'SPYWARE',    hp:60,  atk:9,  speed:58, reach:7,  rate:470,  w:20, h:22, color:'#c8ff00', from:140, bounty:9  },
    trojan:  { key:'trojan',  icon:'🐴', name:'TROJAN.SYS', hp:780, atk:46, speed:12, reach:12, rate:1300, w:40, h:44, color:'#ffd700', from:170, bounty:65 }
  },

  // Siege clock. Fixed across all three stability tiers — see startBattleBots().
  seconds: 240,

  // Waves start lazy and tighten as the siege drags on.
  // Three duelling lanes can only chew through roughly one hostile per second,
  // so spawning faster than that just banks an unkillable queue off-screen and
  // the siege is decided by a backlog the player never sees. This ramps from
  // ~0.3/s to ~1.3/s: comfortably under the front's throughput early, over it
  // by the end, which is what makes the late clock genuinely tense.
  wave: { first: 3000, start: 3500, floor: 2200, tighten: 4, burst: 300 },

  // 550 + 400 + 250 tops out at exactly the 1200 cap. The time bonus pays in
  // full for winning with `timeFull` of the clock still on it rather than
  // scaling all the way from an unreachable zero-second purge — a real siege
  // takes ~170s, so a linear scale would have quietly capped the game at ~1030
  // and made the card's "UP TO 1200" a lie. A loss still banks up to 400 for
  // the damage you did put through; a near-miss shouldn't pay nothing.
  score: { win: 550, hpBonus: 400, timeBonus: 250, timeFull: 0.55, lossMax: 400, cap: 1200 }
};

// ── GEOMETRY ── (all in the engine's 560×500 board units)
const BB_GROUND = 402;                      // the lane the units walk on
const BB_TOWER_W = 68, BB_TOWER_H = 104;
const BB_P_TOWER = 6, BB_E_TOWER = BOARD_W - 6 - BB_TOWER_W;
const BB_P_SPAWN = 86, BB_E_SPAWN = BOARD_W - 86;
const BB_P_LINE = 90, BB_E_LINE = BOARD_W - 90;   // where a unit starts hitting a base
const BB_LANES = [-14, 0, 14];              // visual stagger, so a stack of four still reads
const BB_RANGED = 24;                       // reach at or past this = a shooter, drawn with tracers

function startBattleBots(){
  const holder = document.getElementById('g-canvas-holder');
  const deck   = document.getElementById('bb-deck');
  const ramPill= document.getElementById('bb-ram-pill');
  const ramEl  = document.getElementById('bb-ram');
  const progEl = document.getElementById('prog-fill');
  const timeEl = document.getElementById('g-time');

  holder.style.display = 'block';
  deck.style.display   = 'flex';
  ramPill.style.display= '';
  setControls(null);              // the deck IS the control pad — no arrows to show
  setControlHint('TAP A CARD TO DEPLOY · YOUR BOTS ADVANCE ON THEIR OWN',
                 'CLICK A CARD OR PRESS 1–7 · YOUR BOTS ADVANCE ON THEIR OWN');
  showTouchHint('TAP THE CARDS BELOW TO DEPLOY');

  const diffMod = getDifficultyModifier();
  // ── HOW THE STABILITY TIER APPLIES HERE ──
  // A lane battle is an attrition race with a TIPPING POINT, not a dial: either
  // your side out-trades theirs and the front walks forward, or it doesn't and
  // the game stalls at midfield until the clock runs out. Outcomes either side
  // of that point are bimodal — clean win or dead stall, very little between —
  // so the tier gets ONE gentle penalty applied three ways rather than several
  // stacked ones. Stacking tougher hostiles, more of them, less RAM AND less
  // time (each modest alone) put both hard tiers so far past the tipping point
  // that they were unwinnable at any skill level, which made the ×1.5 / ×2.0
  // payout — the entire reason the tiers exist — impossible to collect.
  //
  // Two deliberate omissions:
  //  · No RAM cut. Extra income doesn't move a stalled front, it just lengthens
  //    the queue behind it, so throttling income cost the player nothing they
  //    could feel and bought no real difficulty.
  //  · No time cut. Alone among the hub's games, this one's win condition is a
  //    race the clock can put out of reach outright rather than merely scoring
  //    lower — a halved Meltdown clock left 120s for a ~170s siege.
  const foeHpScale  = 1 + (diffMod - 1) * 0.16;  // 1.00 / 1.08 / 1.16
  const foeAtkScale = 1 + (diffMod - 1) * 0.16;
  const waveScale   = 1 + (diffMod - 1) * 0.16;
  const TOTAL = BB.seconds;

  // Player colours follow the Black Market equip, the way every other game's
  // player sprite does. Every other bot is a hue-rotation of that one colour
  // rather than a fixed palette, so however the deck grows the whole roster
  // still reads as one faction against the malware's fixed pinks and reds.
  const pColor = getEquippedColorHex();
  const colorOf = {
    scout:  pColor,
    wall:   shiftHue(pColor, -26),
    zapper: shiftHue(pColor, 20),
    tank:   shiftHue(pColor, 42),
    titan:  shiftHue(pColor, 64)
  };

  // 🌳 Perk B lifts the throughput the siege is built around. It multiplies the
  // RATE rather than handing out a lump of RAM, so the advantage compounds over
  // a long hold instead of just buying the opening bot.
  const ramPerk = perkRamMult();
  let ram = BB.ram.start, ramRate = BB.ram.rate * ramPerk, upgIdx = 0;
  if(ramPerk > 1) toast(`🌳 ACCELERATED RAM — throughput ×${ramPerk.toFixed(2)}`, 2600);
  let mainHP = BB.baseHP, glitchHP = BB.baseHP;
  let bots = [], foes = [], parts = [], beams = [];
  let pLane = 0, eLane = 0;         // round-robin, so a deploy spreads your force
  let elapsed = 0, time = TOTAL, waveNo = 0, waveT = BB.wave.first;
  // Hostiles a wave has called for but that have not found free ground yet, and
  // the countdown to the next attempt. See spawnWave() / drainQueue().
  let foeQueue = [], queueT = 0;
  let kills = 0, deployed = 0, empFired = 0, ended = false, outro = null;
  let hurtFlash = 0, hitFlash = 0, empFlash = 0, banner = null, scroll = 0, last = 0;

  timeEl.textContent = fmtTime(time);
  progEl.style.width = '100%';
  progEl.style.background = 'linear-gradient(90deg,var(--red),var(--gold))';
  setLive(0);

  // ── DEPLOY DECK ──
  // Rebuilt from scratch every round, so the previous round's click handlers
  // die with the nodes that carried them — the same trick Node Hacker's keypad
  // and Memory Match's tiles use. stopGame() empties the container, which means
  // quitting mid-siege drops them too.
  const cards = [
    { kind:'unit', spec: BB.units.scout,  color: colorOf.scout,  cdLeft: 0 },
    { kind:'unit', spec: BB.units.wall,   color: colorOf.wall,   cdLeft: 0 },
    { kind:'unit', spec: BB.units.zapper, color: colorOf.zapper, cdLeft: 0 },
    { kind:'unit', spec: BB.units.tank,   color: colorOf.tank,   cdLeft: 0 },
    { kind:'unit', spec: BB.units.titan,  color: colorOf.titan,  cdLeft: 0 },
    { kind:'emp',  icon:'💥', name:'EMP',       color:'#ffffff', cdLeft: 0 },
    { kind:'upg',  icon:'⚡', name:'RAM SPEED', color:'#ffd700', cdLeft: 0 }
  ];
  deck.innerHTML = '';
  const btns = cards.map((c, i) => {
    const b = document.createElement('button');
    b.className = 'bb-btn';
    b.style.setProperty('--bc', c.color);
    b.innerHTML = `<span class="bb-ico">${c.kind === 'unit' ? c.spec.icon : c.icon}</span>` +
                  `<span class="bb-name">${c.kind === 'unit' ? c.spec.name : c.name}</span>` +
                  `<span class="bb-cost"></span>`;
    b.onclick = () => buy(i);
    deck.appendChild(b);
    return { el: b, cost: b.querySelector('.bb-cost'), lastCost: '', lastState: '', lastCd: -1, lastSecs: '' };
  });

  // The deck changes the board's available height, so it has to be in the DOM
  // and visible before the canvas measures itself.
  fitCanvas();
  paintDeck();

  function costOf(i){
    const c = cards[i];
    if(c.kind === 'unit') return c.spec.cost;
    if(c.kind === 'emp')  return BB.emp.cost;
    return upgIdx < BB.ram.tiers.length ? BB.ram.tiers[upgIdx] : Infinity;
  }

  function buy(i){
    if(ended) return;
    const c = cards[i], cost = costOf(i);
    if(!Number.isFinite(cost)){ snd('deny'); toast('⚡ RAM THROUGHPUT ALREADY MAXED'); return; }
    if(c.cdLeft > 0){ snd('deny'); return; }
    if(ram < cost){ snd('deny'); toast(`⚠️ INSUFFICIENT RAM — NEED ${Math.ceil(cost - ram)} MORE`); return; }

    ram -= cost;
    if(c.kind === 'upg'){
      upgIdx++;
      // Scaled by the perk too, so an upgrade bought under it is worth the same
      // proportional jump as the base rate it is added to.
      ramRate += BB.ram.step * ramPerk;
      snd('levelUp');
      toast(`⚡ RAM THROUGHPUT → ${Math.round(ramRate)}/s`);
      banner = { text: `⚡ THROUGHPUT ${Math.round(ramRate)}/s`, life: 1400, color: '#ffd700' };
    } else if(c.kind === 'emp'){
      fireEMP();
      c.cdLeft = BB.emp.cool;
    } else {
      spawnBot(c.spec);
      c.cdLeft = c.spec.cool;
      deployed++;
      snd(c.spec.key === 'tank' || c.spec.key === 'titan' ? 'ability' : 'powerup');
    }
    paintDeck();
  }

  // Only touches the DOM when something actually changed — this runs every
  // frame, and a blind write per card per frame is layout churn for nothing.
  //
  // Three separate readouts, and they answer three different questions: the
  // cost label says what it costs, `broke`/`maxed` say whether you can afford
  // it AT ALL (a lit card must mean "deployable now" or the deck is lying), and
  // the cooldown says how long the bay has left — as a receding shade for the
  // shape of it and as a number of seconds for planning the next push.
  // The 3D build paints from this same function's rules; keep them in step.
  function paintDeck(){
    cards.forEach((c, i) => {
      const b = btns[i], cost = costOf(i);
      const label = Number.isFinite(cost) ? `${cost} RAM` : 'MAXED';
      if(label !== b.lastCost){ b.cost.textContent = label; b.lastCost = label; }

      const state = !Number.isFinite(cost) ? 'maxed' : (ram < cost ? 'broke' : '');
      if(state !== b.lastState){
        b.el.classList.toggle('broke', state === 'broke');
        b.el.classList.toggle('maxed', state === 'maxed');
        b.lastState = state;
      }

      const cool = c.kind === 'unit' ? c.spec.cool : c.kind === 'emp' ? BB.emp.cool : 0;
      const left = cool ? Math.max(0, c.cdLeft) : 0;
      const q = cool ? Math.round(left / cool * 20) / 20 : 0;   // 20 steps is plenty
      if(q !== b.lastCd){ b.el.style.setProperty('--cd', q); b.lastCd = q; }
      // Seconds, rounded UP: a bay showing 1 has not reloaded yet, and a bay
      // showing nothing is one you can press.
      const secs = left > 0 ? String(Math.ceil(left / 1000)) : '';
      if(secs !== b.lastSecs){
        if(secs) b.el.dataset.cd = secs; else b.el.removeAttribute('data-cd');
        b.lastSecs = secs;
      }
    });
  }

  // ── SPAWNING ──
  function mkUnit(spec, side, x, lane, color){
    return {
      spec, side, x, color, lane,
      hp: spec.hp * (side < 0 ? foeHpScale : 1),
      hpMax: spec.hp * (side < 0 ? foeHpScale : 1),
      atk: spec.atk * (side < 0 ? foeAtkScale : 1),
      w: spec.w, h: spec.h, speed: spec.speed, reach: spec.reach, rate: spec.rate,
      cd: 0, yOff: BB_LANES[lane],
      flash: 0, bob: Math.random() * 6
    };
  }

  // ── THE SPAWN SHELF ──
  // Nothing arrives on top of something already standing there. allyGap() only
  // holds units that are ALREADY apart — two bodies at the same x have a
  // negative edge gap, which does not block — so a body dropped onto another
  // walks the whole lane inside it, and a wave landing on a held front reads as
  // one flickering sprite instead of three.
  //
  // `shelfX` answers "where can this actually stand": the spawn point, or far
  // enough behind whatever is sitting on it, stepping back toward our own base
  // until it finds room or runs out of ground and gives up.
  function shelfX(list, spec, lane, x, side, wall){
    let px = x;
    for(let guard = 0; guard < 5; guard++){
      let hit = null;
      for(const u of list){
        if(u.hp <= 0 || u.lane !== lane) continue;
        if(Math.abs(u.x - px) < (u.w + spec.w) / 2 + BB.spacing){ hit = u; break; }
      }
      if(!hit) return px;
      px = hit.x - side * ((hit.w + spec.w) / 2 + BB.spacing);
      if(side > 0 ? px < wall : px > wall) return null;
    }
    return null;
  }
  // The emptiest lane, scanned from `from` so an unobstructed field still
  // round-robins and a deploy still spreads across the three fronts.
  function placeIn(list, spec, from, x, side, wall){
    for(let i = 0; i < 3; i++){
      const lane = (from + i) % 3;
      const px = shelfX(list, spec, lane, x, side, wall);
      if(px != null) return { lane, x: px };
    }
    return null;
  }

  // The player has already paid, so a blocked shelf must never swallow a
  // deploy — it falls back to the spawn point in the round-robin lane.
  function spawnBot(spec){
    const at = placeIn(bots, spec, pLane, BB_P_SPAWN, +1, BB_P_TOWER + BB_TOWER_W)
            || { lane: pLane % 3, x: BB_P_SPAWN };
    pLane = (at.lane + 1) % 3;
    bots.push(mkUnit(spec, +1, at.x, at.lane, colorOf[spec.key]));
  }
  // Returns false when there is nowhere to put it: the wave queue holds onto
  // the hostile and tries again shortly rather than dropping it on an occupied
  // square. See the drain in simulate().
  function spawnFoe(spec){
    const at = placeIn(foes, spec, eLane, BB_E_SPAWN, -1, BB_E_TOWER);
    if(!at) return false;
    eLane = (at.lane + 1) % 3;
    foes.push(mkUnit(spec, -1, at.x, at.lane, spec.color));
    return true;
  }

  // ── EMP SURGE ──
  // Whole-field damage, paid in RAM and throttled by the deck's longest
  // cooldown. Kills pay their bounty like any other, so surging a wave of
  // chaff part-refunds itself — the Battle Cats cannon, in Mainframe money.
  function fireEMP(){
    empFired++;
    empFlash = 1;
    snd('bigExplode');
    banner = { text: '💥 EMP SURGE', life: 1400, color: '#ffffff' };
    for(const f of foes){
      if(f.hp <= 0) continue;
      f.hp -= BB.emp.dmg;
      f.flash = 200;
      if(f.hp <= 0) killUnit(f, +1);
      else burst(f.x, BB_GROUND + f.yOff - f.h / 2, '#ffffff', 3);
    }
    foes = foes.filter(u => u.hp > 0);
  }

  // Later waves lean on the heavier types without ever dropping BUGs entirely,
  // so the lane keeps its chaff while the real threats arrive behind it.
  function pickFoe(){
    const pool = Object.values(BB.foes).filter(f => elapsed >= f.from);
    const weights = pool.map(f => f.key === 'bug' ? 3 : (elapsed - f.from) / 40 + 1);
    let r = Math.random() * weights.reduce((a, b) => a + b, 0);
    for(let i = 0; i < pool.length; i++){ if((r -= weights[i]) <= 0) return pool[i]; }
    return pool[0];
  }

  // A wave is REQUESTED here, not spawned. Its hostiles go into a queue that
  // drainQueue() empties one at a time onto free ground, and a new wave is not
  // started at all while the shelf is congested or the last one is still
  // landing. The old code fired one `gLater` per hostile, and a timer does not
  // care whether the ground under the spawn point is occupied — a wave arriving
  // on a stalled column put three bodies inside each other, and the pile then
  // walked the lane as one.
  function spawnWave(){
    if(foeQueue.length || !placeIn(foes, BB.foes.bug, eLane, BB_E_SPAWN, -1, BB_E_TOWER)){
      waveT = 400;                     // shelf busy — look again, don't bank a pile-up
      return;
    }
    waveNo++;
    const count = Math.min(3, 1 + Math.floor(elapsed / 70));
    for(let i = 0; i < count; i++) foeQueue.push(pickFoe());
    waveT = Math.max(BB.wave.floor, BB.wave.start - elapsed * BB.wave.tighten) / waveScale;
    if(waveNo % 5 === 0){
      snd('wave');
      banner = { text: `⚠ WAVE ${waveNo} INBOUND`, life: 1700, color: '#ff2442' };
    }
  }

  // One hostile per burst interval, and only onto ground that is free. A
  // refusal costs a short re-check, never a lost hostile — so the pressure the
  // wave table asks for still arrives, just never inside another body.
  function drainQueue(dt){
    queueT = Math.max(0, queueT - dt);
    if(!foeQueue.length || queueT > 0) return;
    if(spawnFoe(foeQueue[0])){ foeQueue.shift(); queueT = BB.wave.burst; }
    else queueT = 220;
  }

  // ── COMBAT ──
  // Three lanes, each resolving as its own duel: a unit walks until the edge gap
  // to the frontmost opponent IN ITS LANE closes to `reach`, then stops dead and
  // trades blows. The lanes are the same three the renderer staggers units into,
  // so what you see on the board is exactly what the simulation is doing.
  function frontTarget(u, list, dir){
    let best = null, bestGap = Infinity;
    for(const f of list){
      if(f.hp <= 0 || f.lane !== u.lane) continue;
      const gap = dir > 0 ? (f.x - f.w / 2) - (u.x + u.w / 2)
                          : (u.x - u.w / 2) - (f.x + f.w / 2);
      if(gap < -44) continue;                 // long past each other — don't moonwalk back
      if(gap < bestGap){ bestGap = gap; best = f; }
    }
    return { target: best, gap: bestGap };
  }

  // Gap to the nearest ally ahead in the same lane — the queue that stops a
  // column collapsing onto one x.
  function allyGap(u, list, dir){
    let best = Infinity;
    for(const a of list){
      if(a === u || a.hp <= 0 || a.lane !== u.lane) continue;
      const gap = dir > 0 ? (a.x - a.w / 2) - (u.x + u.w / 2)
                          : (u.x - u.w / 2) - (a.x + a.w / 2);
      if(gap >= 0 && gap < best) best = gap;
    }
    return best;
  }

  function stepSide(list, opposing, dir, dt){
    const line = dir > 0 ? BB_E_LINE : BB_P_LINE;
    for(const u of list){
      if(u.hp <= 0) continue;
      if(u.flash > 0) u.flash -= dt;

      const { target, gap } = frontTarget(u, opposing, dir);
      if(target && gap <= u.reach){
        u.cd -= dt;
        if(u.cd <= 0){
          u.cd = u.rate;
          u.flash = 130;
          target.hp -= u.atk;
          // Shooters read as GUNS, not long arms: a tracer to the target and
          // an impact spark, where melee keeps the little white jab.
          if(u.reach >= BB_RANGED){
            const ty = BB_GROUND + target.yOff - target.h * 0.5;
            beams.push({ x1: u.x + dir * u.w / 2, y1: BB_GROUND + u.yOff - u.h * 0.55,
                         x2: target.x - dir * target.w / 2, y2: ty,
                         color: u.color, life: 1 });
            burst(target.x - dir * target.w / 2, ty, u.color, 2);
            snd('shoot');
          } else {
            snd('hit');
          }
          if(target.hp <= 0) killUnit(target, dir);
        }
        continue;
      }

      const atBase = dir > 0 ? (u.x + u.w / 2 >= line) : (u.x - u.w / 2 <= line);
      if(atBase){
        u.cd -= dt;
        if(u.cd <= 0){
          u.cd = u.rate;
          u.flash = 130;
          hitBase(u, dir);
        }
        continue;
      }

      // Hold position behind the ally in front rather than walking through it.
      if(allyGap(u, list, dir) <= BB.spacing) continue;

      u.x += dir * u.speed * dt / 1000;
      u.bob += dt / 90;
    }
  }

  function killUnit(u, dir){
    burst(u.x, BB_GROUND + u.yOff - u.h / 2, u.color, 9);
    snd('explode');
    if(dir > 0){                       // a player bot did the killing
      kills++;
      ram = Math.min(BB.ram.cap, ram + u.spec.bounty);
      snd('coin');
    }
  }

  function hitBase(u, dir){
    const dmg = u.atk * BB.siege;
    if(dir > 0){
      glitchHP -= dmg;
      hitFlash = 1;
      snd('brick', { semi: 3 });
      if(glitchHP <= 0){ glitchHP = 0; end('win'); }
    } else {
      mainHP -= dmg;
      hurtFlash = 1;
      snd('brick', { semi: -7 });
      if(mainHP <= 0){ mainHP = 0; end('loss'); }
    }
  }

  function burst(x, y, color, n){
    for(let i = 0; i < n; i++){
      const a = Math.random() * Math.PI * 2, s = 40 + Math.random() * 110;
      parts.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 40, life: 1, color, sz: 2 + Math.random() * 2.5 });
    }
  }

  // ── SIEGE CLOCK ──
  // One second per tick is all the clock needs; the simulation runs on the
  // frame delta so the RAM counter climbs smoothly rather than in steps.
  gTimer = setInterval(() => {
    if(ended) return;
    time--;
    timeEl.textContent = fmtTime(time);
    progEl.style.width = `${Math.max(0, time / TOTAL) * 100}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  window.onkeydown = e => {
    if(e.ctrlKey || e.metaKey || e.altKey) return;
    // Neither fires anything here, but both activate a focused button, so they
    // get swallowed rather than leaking out into the UI behind the board.
    if(e.code === 'Space' || e.code === 'Enter') e.preventDefault();
    if(e.key.length !== 1) return;
    const i = e.key.charCodeAt(0) - 49;            // '1'…'9' → card index
    if(i < 0 || i >= cards.length) return;
    e.preventDefault();
    hideTouchHint();
    buy(i);
  };

  // ── SIMULATION ──
  function simulate(dt){
    elapsed += dt / 1000;
    ram = Math.min(BB.ram.cap, ram + ramRate * dt / 1000);

    cards.forEach(c => { if(c.cdLeft > 0) c.cdLeft = Math.max(0, c.cdLeft - dt); });

    waveT -= dt;
    if(waveT <= 0) spawnWave();
    drainQueue(dt);

    stepSide(bots, foes, +1, dt);
    stepSide(foes, bots, -1, dt);
    bots = bots.filter(u => u.hp > 0);
    foes = foes.filter(u => u.hp > 0);

    // What you'd bank if the siege ended right now, climbing as you chew
    // through The Glitch. A win replaces it with the full formula.
    setLive(Math.round(BB.score.lossMax * (1 - Math.max(0, glitchHP) / BB.baseHP)));
  }

  function stepFx(dt){
    scroll += dt * 0.012;
    if(hurtFlash > 0) hurtFlash = Math.max(0, hurtFlash - dt / 420);
    if(hitFlash  > 0) hitFlash  = Math.max(0, hitFlash  - dt / 300);
    if(empFlash  > 0) empFlash  = Math.max(0, empFlash  - dt / 260);
    if(banner){ banner.life -= dt; if(banner.life <= 0) banner = null; }
    for(let i = parts.length - 1; i >= 0; i--){
      const p = parts[i];
      p.x += p.vx * dt / 1000;
      p.y += p.vy * dt / 1000;
      p.vy += 420 * dt / 1000;
      p.life -= dt / 620;
      if(p.life <= 0) parts.splice(i, 1);
    }
    for(let i = beams.length - 1; i >= 0; i--){
      beams[i].life -= dt / 140;
      if(beams[i].life <= 0) beams.splice(i, 1);
    }
  }

  // ── RENDER ──
  function rrect(x, y, w, h, r){
    aCtx.beginPath();
    aCtx.moveTo(x + r, y);
    aCtx.arcTo(x + w, y, x + w, y + h, r);
    aCtx.arcTo(x + w, y + h, x, y + h, r);
    aCtx.arcTo(x, y + h, x, y, r);
    aCtx.arcTo(x, y, x + w, y, r);
    aCtx.closePath();
  }

  function drawField(){
    aCtx.fillStyle = '#07070f';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);

    // Drifting grid in the sky band — cheap parallax that sells the side-scroll
    // without moving anything the simulation cares about.
    aCtx.save();
    aCtx.strokeStyle = 'rgba(255,255,255,0.045)';
    aCtx.lineWidth = 1;
    const off = scroll % 40;
    for(let x = -off; x <= BOARD_W; x += 40){
      aCtx.beginPath(); aCtx.moveTo(x, 56); aCtx.lineTo(x, BB_GROUND); aCtx.stroke();
    }
    for(let y = 56; y <= BB_GROUND; y += 40){
      aCtx.beginPath(); aCtx.moveTo(0, y); aCtx.lineTo(BOARD_W, y); aCtx.stroke();
    }
    aCtx.restore();

    // Ground slab + the lit lane the whole game happens on
    aCtx.fillStyle = '#0b0b16';
    aCtx.fillRect(0, BB_GROUND, BOARD_W, BOARD_H - BB_GROUND);
    aCtx.save();
    aCtx.strokeStyle = 'rgba(255,255,255,0.05)';
    const goff = (scroll * 2) % 28;
    for(let x = -goff; x <= BOARD_W; x += 28){
      aCtx.beginPath(); aCtx.moveTo(x, BB_GROUND); aCtx.lineTo(x - 16, BOARD_H); aCtx.stroke();
    }
    aCtx.shadowBlur = 12; aCtx.shadowColor = pColor;
    aCtx.strokeStyle = hexToRgba(pColor, 0.55); aCtx.lineWidth = 2;
    aCtx.beginPath(); aCtx.moveTo(0, BB_GROUND); aCtx.lineTo(BOARD_W, BB_GROUND); aCtx.stroke();
    aCtx.restore();
  }

  function drawTower(x, color, icon, label, hp, flash){
    const top = BB_GROUND - BB_TOWER_H;
    aCtx.save();
    aCtx.shadowBlur = 20; aCtx.shadowColor = color;
    aCtx.fillStyle = hexToRgba(color, 0.10 + flash * 0.35);
    aCtx.strokeStyle = color; aCtx.lineWidth = 2;
    rrect(x, top, BB_TOWER_W, BB_TOWER_H, 6);
    aCtx.fill(); aCtx.stroke();
    aCtx.shadowBlur = 0;

    // Window lights, dimming as the base loses integrity — the tower itself
    // reports its health, so the fight reads without looking up at the bars.
    const lit = Math.max(0, hp) / BB.baseHP;
    for(let r = 0; r < 3; r++){
      for(let c = 0; c < 2; c++){
        const on = Math.random() < 0.06 ? 0.15 : lit;
        aCtx.fillStyle = hexToRgba(color, 0.18 + on * 0.55);
        aCtx.fillRect(x + 13 + c * 28, top + 40 + r * 18, 16, 9);
      }
    }
    aCtx.font = '17px sans-serif';
    aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
    aCtx.fillText(icon, x + BB_TOWER_W / 2, top + 20);

    aCtx.font = 'bold 8px Orbitron,monospace';
    aCtx.fillStyle = hexToRgba(color, 0.85);
    aCtx.fillText(label, x + BB_TOWER_W / 2, BB_GROUND + 16);
    aCtx.restore();
  }

  function drawUnit(u){
    const feet = BB_GROUND + u.yOff;
    // u.bob only advances while a unit is walking, so an engaged unit stands
    // still rather than jittering in place through the whole brawl.
    const top = feet - u.h + Math.sin(u.bob) * 1.2;

    aCtx.save();
    aCtx.globalAlpha = 0.32;
    aCtx.fillStyle = '#000';
    aCtx.beginPath(); aCtx.ellipse(u.x, feet + 2, u.w * 0.5, 3.5, 0, 0, Math.PI * 2); aCtx.fill();
    aCtx.globalAlpha = 1;

    aCtx.shadowBlur = u.flash > 0 ? 22 : 13;
    aCtx.shadowColor = u.color;
    aCtx.fillStyle = hexToRgba(u.color, u.flash > 0 ? 0.45 : 0.17);
    aCtx.strokeStyle = u.color; aCtx.lineWidth = 2;
    rrect(u.x - u.w / 2, top, u.w, u.h, 5);
    aCtx.fill(); aCtx.stroke();
    aCtx.shadowBlur = 0;

    aCtx.font = `${Math.round(u.h * 0.5)}px sans-serif`;
    aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
    aCtx.fillText(u.spec.icon, u.x, top + u.h * 0.5);

    // HP pip — flips red once a unit is nearly spent, which is the cue to send
    // the next one rather than watch this one die.
    const frac = Math.max(0, u.hp / u.hpMax), pw = u.w + 4;
    aCtx.fillStyle = 'rgba(0,0,0,0.6)';
    aCtx.fillRect(u.x - pw / 2, top - 7, pw, 3);
    aCtx.fillStyle = frac > 0.35 ? u.color : '#ff2442';
    aCtx.fillRect(u.x - pw / 2, top - 7, pw * frac, 3);

    if(u.flash > 0){
      const dir = u.side, mx = u.x + dir * (u.w / 2 + 3);
      aCtx.strokeStyle = '#fff'; aCtx.lineWidth = 2;
      aCtx.globalAlpha = Math.min(1, u.flash / 130);
      aCtx.beginPath();
      aCtx.moveTo(mx, top + u.h * 0.55);
      aCtx.lineTo(mx + dir * 9, top + u.h * 0.55);
      aCtx.stroke();
    }
    aCtx.restore();
  }

  function drawHPBar(x, y, w, h, frac, color, label, value, rightAlign){
    aCtx.save();
    aCtx.font = 'bold 9px Orbitron,monospace';
    aCtx.textBaseline = 'alphabetic';
    aCtx.textAlign = rightAlign ? 'right' : 'left';
    aCtx.fillStyle = hexToRgba(color, 0.9);
    aCtx.fillText(label, rightAlign ? x + w : x, y - 5);

    aCtx.fillStyle = 'rgba(255,255,255,0.06)';
    aCtx.fillRect(x, y, w, h);
    const fw = Math.max(0, Math.min(1, frac)) * w;
    aCtx.shadowBlur = 12; aCtx.shadowColor = color;
    aCtx.fillStyle = color;
    aCtx.fillRect(rightAlign ? x + w - fw : x, y, fw, h);
    aCtx.shadowBlur = 0;
    aCtx.strokeStyle = 'rgba(255,255,255,0.16)'; aCtx.lineWidth = 1;
    aCtx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

    aCtx.font = 'bold 9px Orbitron,monospace';
    aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
    aCtx.fillStyle = '#fff';
    aCtx.fillText(value, x + w / 2, y + h / 2 + 0.5);
    aCtx.restore();
  }

  function drawHUD(){
    drawHPBar(16, 20, 244, 15, mainHP / BB.baseHP, pColor,
              '🛡️ MAINFRAME', `${Math.max(0, Math.ceil(mainHP))}`, false);
    drawHPBar(BOARD_W - 260, 20, 244, 15, glitchHP / BB.baseHP, '#ff2442',
              '☠️ THE GLITCH', `${Math.max(0, Math.ceil(glitchHP))}`, true);

    aCtx.save();
    aCtx.font = 'bold 8px Orbitron,monospace';
    aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
    aCtx.fillStyle = 'rgba(255,255,255,0.34)';
    aCtx.fillText(`WAVE ${waveNo}  ·  ${Math.round(ramRate)}/s RAM`, BOARD_W / 2, 48);
    aCtx.restore();

    if(banner){
      const a = Math.min(1, banner.life / 400);
      aCtx.save();
      aCtx.globalAlpha = a;
      aCtx.font = 'bold 15px Orbitron,monospace';
      aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
      aCtx.shadowBlur = 16; aCtx.shadowColor = banner.color;
      aCtx.fillStyle = banner.color;
      aCtx.fillText(banner.text, BOARD_W / 2, 100);
      aCtx.restore();
    }

    if(outro){
      aCtx.save();
      aCtx.fillStyle = 'rgba(4,4,14,0.62)';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
      aCtx.font = 'bold 26px Orbitron,monospace';
      aCtx.textAlign = 'center'; aCtx.textBaseline = 'middle';
      aCtx.shadowBlur = 26; aCtx.shadowColor = outro.color;
      aCtx.fillStyle = outro.color;
      aCtx.fillText(outro.text, BOARD_W / 2, BOARD_H / 2);
      aCtx.restore();
    }

    // Damage vignettes: red when the Mainframe is hit, the equipped colour when
    // The Glitch takes one, so the two are never confusable at a glance.
    if(hurtFlash > 0){
      aCtx.save();
      aCtx.globalAlpha = hurtFlash * 0.3;
      aCtx.fillStyle = '#ff2442';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
      aCtx.restore();
    }
    if(hitFlash > 0){
      aCtx.save();
      aCtx.globalAlpha = hitFlash * 0.16;
      aCtx.fillStyle = pColor;
      aCtx.fillRect(BOARD_W * 0.55, 0, BOARD_W * 0.45, BOARD_H);
      aCtx.restore();
    }
    if(empFlash > 0){
      aCtx.save();
      aCtx.globalAlpha = empFlash * 0.22;
      aCtx.fillStyle = '#eaf6ff';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
      aCtx.restore();
    }
  }

  function draw(){
    drawField();
    drawTower(BB_P_TOWER, pColor,   '🖥️', 'MAINFRAME',  mainHP,   hurtFlash);
    drawTower(BB_E_TOWER, '#ff2442', '👾', 'THE GLITCH', glitchHP, hitFlash);
    drawSkinBadge(BB_P_TOWER + BB_TOWER_W / 2, BB_GROUND - BB_TOWER_H - 14, 14);

    // Back lane first, so a crowded front line layers instead of z-fighting.
    [...bots, ...foes].sort((a, b) => a.yOff - b.yOff).forEach(drawUnit);

    for(const b of beams){
      aCtx.save();
      aCtx.globalAlpha = Math.max(0, b.life) * 0.9;
      aCtx.strokeStyle = b.color;
      aCtx.lineWidth = 2;
      aCtx.shadowBlur = 8; aCtx.shadowColor = b.color;
      aCtx.beginPath(); aCtx.moveTo(b.x1, b.y1); aCtx.lineTo(b.x2, b.y2); aCtx.stroke();
      aCtx.restore();
    }

    for(const p of parts){
      aCtx.save();
      aCtx.globalAlpha = Math.max(0, p.life);
      aCtx.fillStyle = p.color;
      aCtx.fillRect(p.x - p.sz / 2, p.y - p.sz / 2, p.sz, p.sz);
      aCtx.restore();
    }
    drawHUD();
    ramEl.textContent = Math.floor(ram);
  }

  // ── LOOP ──
  // Drawing outlives the simulation on purpose: `ended` freezes the battle but
  // the frame keeps running so the final explosion and the verdict card play
  // out. stopGame() cancels it for real, from showResults() or from Quit.
  function loop(now){
    const dt = last ? Math.min(50, now - last) : 16;   // a stalled tab must not teleport the front line
    last = now;
    if(!ended) simulate(dt);
    stepFx(dt);
    if(!ended) paintDeck();
    draw();
    gameLoopId = requestAnimationFrame(loop);
  }

  function end(outcome){
    if(ended) return;
    ended = true;
    const win = outcome === 'win';
    let pts, verdict;

    if(win){
      pts = Math.min(BB.score.cap,
        BB.score.win +
        Math.round(BB.score.hpBonus * Math.max(0, mainHP) / BB.baseHP) +
        Math.round(BB.score.timeBonus * Math.min(1, (Math.max(0, time) / TOTAL) / BB.score.timeFull)));
      verdict = '☠️ THE GLITCH PURGED';
      outro = { text: 'GLITCH PURGED', color: '#39ff14' };
      burst(BB_E_TOWER + BB_TOWER_W / 2, BB_GROUND - BB_TOWER_H / 2, '#ff2442', 40);
      snd('bigExplode');
    } else {
      pts = Math.round(BB.score.lossMax * (1 - Math.max(0, glitchHP) / BB.baseHP));
      verdict = outcome === 'timeout' ? '⏱️ SIEGE TIMED OUT' : '💀 MAINFRAME BREACHED';
      outro = { text: outcome === 'timeout' ? 'SIEGE FAILED' : 'MAINFRAME BREACHED', color: '#ff2442' };
      if(outcome !== 'timeout') burst(BB_P_TOWER + BB_TOWER_W / 2, BB_GROUND - BB_TOWER_H / 2, pColor, 40);
      snd(outcome === 'timeout' ? 'alarm' : 'gameOver');
    }
    setLive(pts);
    btns.forEach(b => b.el.classList.add('broke'));

    // Let the explosion and the verdict land before the results card wipes the
    // board. gLater(), so quitting inside that window cancels it cleanly.
    gLater(() => {
      showResults('battlebots', pts, {
        '⚔️ Outcome': verdict,
        '🛡️ Mainframe Integrity': `${Math.max(0, Math.ceil(mainHP))} / ${BB.baseHP}`,
        '☠️ Glitch Integrity': `${Math.max(0, Math.ceil(glitchHP))} / ${BB.baseHP}`,
        '💀 Hostiles Deleted': kills,
        '🤖 Bots Deployed': deployed,
        '💥 EMP Surges': empFired,
        '🌊 Waves Repelled': waveNo,
        '⚡ RAM Throughput': `${Math.round(ramRate)}/s`,
        '🏆 Score Accumulation': `${pts} PTS`
      });
    }, 1050);
  }

  gameLoopId = requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🔌 GAME 17: OVERCLOCK PATH
// ════════════════════════════════════════════
// A one-line circuit puzzle: energise node A, then drag the current through
// every live node exactly once without ever crossing the trace you have
// already laid.
//
// The board is generated BACKWARDS FROM A SOLUTION. A randomised self-avoiding
// walk is carved first, and whatever cells it never reaches become the dead
// code. Scattering blocks first and then hoping a Hamiltonian path survives is
// the version that hands out impossible boards — and on a 15 second clock an
// unsolvable board is indistinguishable from a player who is simply too slow.
// Carving first makes "solvable" a property of the generator instead of
// something to test for afterwards.
function startOverclockPath(){
  const wrap=document.getElementById('g-path');
  wrap.style.display='flex';
  setControlHint('DRAG FROM NODE A THROUGH EVERY LIVE NODE',
                 'CLICK OR DRAG NODE TO NODE · ARROWS / WASD ALSO STEER THE CURRENT');

  const grid=document.getElementById('path-grid');
  const trace=document.getElementById('path-trace');
  const statusEl=document.getElementById('path-status');
  const meterEl=document.getElementById('path-meter');

  // The current runs in the equipped Black Market colour, so the board
  // re-themes on equip the same way Node Hacker's keypad does.
  const NEON=getEquippedColorHex();
  wrap.style.setProperty('--pc', NEON);
  wrap.style.setProperty('--pc-soft', hexToRgba(NEON,0.20));
  wrap.style.setProperty('--pc-glow', hexToRgba(NEON,0.34));

  const diffMod=getDifficultyModifier();
  const N=5, CELLS=N*N;
  // More dead code at the hotter tiers. It reads as a nastier board, but it is
  // also the only thing keeping one winnable once the clock is cut in half — a
  // shorter route is the compensation for having a third less time to find it.
  const DEAD_COUNT=Math.min(9, 4+Math.round((diffMod-1)*2));   // 4 / 5 / 6
  const OPEN=CELLS-DEAD_COUNT;
  // 15s is the brief's clock; the tier dial scales it like every other mission.
  // Floored, because 15 × 0.5 is a different game rather than a harder one.
  const time0=Math.max(10, Math.round(15*getTimeModifier()));

  const ROUTE_PTS=700, CLEAR_BONUS=250, SPEED_PTS=15;
  const rc=i=>[Math.floor(i/N), i%N];
  const neighbours=i=>{
    const [r,c]=rc(i), out=[];
    if(r>0)   out.push(i-N);
    if(r<N-1) out.push(i+N);
    if(c>0)   out.push(i-1);
    if(c<N-1) out.push(i+1);
    return out;
  };
  const shuffle=a=>{
    for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
    return a;
  };

  // ── BOARD GENERATION ──
  // Randomised depth-first walk with backtracking, looking for a self-avoiding
  // route of exactly OPEN cells. The step budget is what stops a bad start from
  // freezing the tab; blowing it just means "try a different start", and a 5×5
  // has far too many routes for forty starts to all fail.
  function carve(){
    for(let attempt=0; attempt<40; attempt++){
      const seen=new Array(CELLS).fill(false), route=[];
      let budget=20000;
      const walk=i=>{
        if(budget--<=0) return false;
        seen[i]=true; route.push(i);
        if(route.length===OPEN) return true;
        for(const n of shuffle(neighbours(i))) if(!seen[n] && walk(n)) return true;
        seen[i]=false; route.pop();
        return false;
      };
      if(walk(Math.floor(Math.random()*CELLS))) return route;
    }
    return null;
  }
  // Belt and braces: a boustrophedon sweep is a valid self-avoiding walk over
  // the whole grid, so its first OPEN cells are a valid route too. Dull, but a
  // dull board beats a broken one.
  function fallback(){
    const p=[];
    for(let r=0;r<N;r++) for(let k=0;k<N;k++) p.push(r*N + (r%2 ? N-1-k : k));
    return p.slice(0,OPEN);
  }

  const solution=carve()||fallback();
  const dead=new Set();
  for(let i=0;i<CELLS;i++) dead.add(i);
  solution.forEach(i=>dead.delete(i));
  const START=solution[0];

  // ── BOARD DOM ──
  // Rebuilt every round, which drops the previous round's nodes and anything
  // clinging to them — the same trick Memory Match and Node Hacker use.
  grid.innerHTML='';
  grid.style.gridTemplateColumns=`repeat(${N},1fr)`;
  grid.classList.remove('recal','done');
  const nodes=[];
  for(let i=0;i<CELLS;i++){
    const n=document.createElement('div');
    n.className='path-node'+(dead.has(i)?' dead':'')+(i===START?' start':'');
    n.dataset.idx=i;
    n.innerHTML = dead.has(i)  ? '<span class="path-glyph">✕</span>'
                : i===START    ? '<span class="path-glyph">A</span>'
                :                '<span class="path-dot"></span>';
    grid.appendChild(n);
    nodes.push(n);
  }

  let time=time0, route=[], best=0, resets=0;
  let ended=false, scored=false, locked=false, dragging=false;

  document.getElementById('g-time').textContent=time;
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--purple),var(--cyan))';

  // Progress is measured in SEGMENTS laid, not nodes touched — sitting on node
  // A having done nothing is worth nothing, and the last hop is worth as much
  // as the first.
  const routeScore=len=>Math.round(Math.max(0,len-1)/(OPEN-1)*ROUTE_PTS);
  const setStatus=(txt,cls)=>{ statusEl.className='path-status'+(cls?' '+cls:''); statusEl.textContent=txt; };

  // ── TRACE ──
  // Drawn in the grid's own pixel space off each node's measured box, so the
  // current lands dead centre whatever the board has been sized to.
  function paint(){
    const w=grid.clientWidth, h=grid.clientHeight;
    trace.setAttribute('viewBox',`0 0 ${w} ${h}`);
    trace.setAttribute('width',w);
    trace.setAttribute('height',h);
    const head=route.length ? route[route.length-1] : -1;
    const live=new Set(route);
    nodes.forEach((n,i)=>{
      n.classList.toggle('on', live.has(i));
      n.classList.toggle('head', i===head);
    });
    if(route.length>1){
      const pts=route.map(i=>{
        const n=nodes[i];
        return `${(n.offsetLeft+n.offsetWidth/2).toFixed(1)},${(n.offsetTop+n.offsetHeight/2).toFixed(1)}`;
      }).join(' ');
      // Two passes: a fat blurred pass for the bloom, a thin bright one for the
      // wire itself. One stroke with a shadow cannot do both.
      trace.innerHTML=`<polyline class="trace-glow" points="${pts}"/><polyline class="trace-core" points="${pts}"/>`;
    } else trace.innerHTML='';
    meterEl.style.width=`${route.length/OPEN*100}%`;
  }

  // A straight run between two cells in the same row or column, as the list of
  // cells it passes through. Null if they are not in line.
  function straightRun(from,to){
    const [r0,c0]=rc(from), [r1,c1]=rc(to);
    if(r0!==r1 && c0!==c1) return null;
    const dr=Math.sign(r1-r0), dc=Math.sign(c1-c0), out=[];
    let r=r0, c=c0;
    while(r!==r1 || c!==c1){ r+=dr; c+=dc; out.push(r*N+c); }
    return out.length ? out : null;
  }

  function tryEnter(i){
    if(ended || locked || !Number.isFinite(i)) return;

    if(!route.length){
      // Nothing is energised yet, so only node A can start the current.
      // Touching another live node is a misread rather than a mistake — it
      // costs a nudge, not a recalibration, because there is no trace to spoil.
      if(i===START){
        route=[START];
        snd('node',{semi:0});
        setStatus('▶ CURRENT LIVE — ROUTE EVERY NODE');
        paint();
      } else if(!dead.has(i)) setStatus('◀ BEGIN AT NODE A','warn');
      return;
    }

    const head=route[route.length-1];
    if(i===head) return;
    // Stepping back onto the cell you just left RETRACTS the trace. That is an
    // undo, not a crossing — without it, one wrong turn during a drag would
    // cost the whole board.
    if(route.length>1 && i===route[route.length-2]){
      route.pop(); snd('move'); paint(); return;
    }

    // A fast drag can cross a cell between two pointermove samples, which would
    // read as a broken link the player never made. A run along a row or column
    // is therefore filled in rather than rejected — the trace they drew IS that
    // run. Anything not in line is a genuine jump and still fails.
    let steps;
    if(neighbours(head).includes(i)) steps=[i];
    else steps=straightRun(head,i);
    if(!steps) return fail('⛔ BROKEN LINK');
    for(const s of steps){
      if(dead.has(s))      return fail('⛔ DEAD CODE NODE');
      if(route.includes(s)) return fail('⛔ TRACE CROSSED ITSELF');
    }

    steps.forEach(s=>route.push(s));
    best=Math.max(best,route.length);
    setLive(routeScore(best));
    snd('node',{semi:(route.length%8)*2});
    paint();
    if(route.length===OPEN) complete();
    else setStatus(`▶ ${route.length} / ${OPEN} NODES ENERGISED`);
  }

  function fail(why){
    if(ended || locked) return;
    locked=true; resets++;
    snd('error');
    grid.classList.add('recal');
    setStatus(`${why} — RECALIBRATING…`,'fail');
    route=[];
    paint();
    // A short lockout on purpose: the clock does not stop for it, so a long
    // penalty would be the entire round rather than a stumble inside it.
    gLater(()=>{
      if(ended) return;
      locked=false;
      grid.classList.remove('recal');
      setStatus('▶ RESTART FROM NODE A');
    }, 700);
  }

  function complete(){
    if(ended) return;
    ended=true; locked=true;                 // freezes the clock and the board
    grid.classList.add('done');
    snd('victory');
    setStatus('✅ CIRCUIT OVERCLOCKED — FULL CURRENT','win');
    gLater(()=>end('complete'), 950);
  }

  gTimer=setInterval(()=>{
    if(ended) return;
    time--;
    document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${Math.max(0,time/time0*100)}%`;
    if(time<=5 && time>0){ snd('tick'); if(!locked) setStatus('⚠️ POWER DRAIN CRITICAL','warn'); }
    if(time<=0) end('timeout');
  },1000);

  // ── INPUT ──
  // One activation path for click and drag alike: whatever node is under the
  // pointer gets offered to tryEnter(). Hit-testing by coordinate rather than
  // by listening on each node is what makes touch work — a captured finger
  // reports every move to the GRID, never to the node it happens to be over.
  const idxAt=(x,y)=>{
    const el=document.elementFromPoint(x,y);
    const node=el && el.closest ? el.closest('.path-node') : null;
    return node && grid.contains(node) ? parseInt(node.dataset.idx,10) : NaN;
  };
  grid.onpointerdown=e=>{
    if(ended) return;
    e.preventDefault();
    dragging=true;
    // Capture keeps the whole gesture on the grid; without it a finger that
    // strays off the board stops reporting and the trace freezes mid-route.
    try{ grid.setPointerCapture(e.pointerId); }catch(err){}
    tryEnter(idxAt(e.clientX,e.clientY));
  };
  grid.onpointermove=e=>{
    if(!dragging || ended) return;
    e.preventDefault();
    tryEnter(idxAt(e.clientX,e.clientY));
  };
  const release=e=>{
    dragging=false;
    try{ grid.releasePointerCapture(e.pointerId); }catch(err){}
  };
  grid.onpointerup=release;
  grid.onpointercancel=release;

  const STEP={ArrowUp:-N,ArrowDown:N,ArrowLeft:-1,ArrowRight:1,W:-N,S:N,A:-1,D:1};
  window.onkeydown=e=>{
    if(e.ctrlKey||e.metaKey||e.altKey||ended) return;
    if(e.code==='Space'||e.code==='Enter'){
      e.preventDefault();
      if(!route.length) tryEnter(START);
      return;
    }
    const key=String(e.key).length===1 ? String(e.key).toUpperCase() : e.key;
    const d=STEP[key];
    if(d===undefined) return;
    e.preventDefault();
    if(!route.length) return tryEnter(START);
    const head=route[route.length-1], [r,c]=rc(head);
    // Reject a step that would wrap the edge: head+1 from the last column is
    // the NEXT row's first cell, which is not a neighbour of anything here.
    if((d===-1&&c===0)||(d===1&&c===N-1)||(d===-N&&r===0)||(d===N&&r===N-1)) return;
    tryEnter(head+d);
  };

  // The trace lives in the grid's pixel space, so it has to be redrawn whenever
  // that space changes — a phone rotating, or the header wrapping to a second
  // line — or the current runs beside the nodes instead of through them.
  let ro=null;
  if(window.ResizeObserver){ ro=new ResizeObserver(()=>paint()); ro.observe(grid); }

  // stopGame() knows nothing about pointer handlers hung on a DOM panel, so the
  // round takes its own down — however it ends, and including a mid-board quit.
  onStopGame=()=>{
    ended=true;
    if(ro){ ro.disconnect(); ro=null; }
    grid.onpointerdown=grid.onpointermove=grid.onpointerup=grid.onpointercancel=null;
  };

  function end(reason){
    if(scored) return; scored=true;
    ended=true; locked=true;
    const cleared=reason==='complete';
    const left=Math.max(0,time);
    const final=Math.min(1100,
      routeScore(best) + (cleared ? CLEAR_BONUS + left*SPEED_PTS : 0));
    showResults('path', final, {
      '🔌 Circuit Status': cleared ? 'FULLY OVERCLOCKED' : 'POWER DRAINED',
      '🧩 Nodes Routed': `${best} / ${OPEN}`,
      '💀 Dead Code Bypassed': DEAD_COUNT,
      '♻️ Recalibrations': resets,
      ...(cleared ? {'⏱️ Current To Spare': `${left}s`} : {}),
      '🏆 Score Accumulation': `${final} PTS`
    }, cleared ? undefined : { sound:'gameOver' });
  }

  setStatus('⚡ BOARD ENERGISED — BEGIN AT NODE A');
  paint();
}

// ════════════════════════════════════════════
//  🎚️ GAME 18: FREQUENCY MODULATOR
// ════════════════════════════════════════════
// A two-scope signal bench. The top scope carries the array's target waveform,
// the bottom one carries your output — with the target ghosted over it, since
// comparing two curves 240px apart is a memory test, not a tuning one.
//
// Only AMPLITUDE and WAVELENGTH are yours to move; the waveform SHAPE is given
// and both scopes always draw the same one. Matching a shape you cannot control
// would be a guessing game, and the printed formula is there to name what you
// are tuning, not to be reverse-engineered.
function startFrequencyModulator(){
  document.getElementById('g-canvas-holder').style.display='block';
  const panel=document.getElementById('g-freq-ctl');
  panel.style.display='flex';
  setControls(null);                 // the sliders below the scope are the pad
  setControlHint('DRAG THE TWO SLIDERS UNTIL BOTH SCOPES AGREE',
                 '↑/↓ AMPLITUDE · ←/→ WAVELENGTH · HOLD SHIFT FOR FINE TRIM');
  showTouchHint('MATCH THE TOP SIGNAL WITH THE SLIDERS');
  fitCanvas();

  const W=BOARD_W, H=BOARD_H;        // 560 × 500
  const HALF=94;                     // scope half-height
  const TY=132, BY=368, MID=250;     // target scope · output scope · readout band
  // Amplitude is in board pixels and capped just inside HALF, so even a maxed
  // wave draws inside its own scope instead of bleeding into the other one.
  const A_MIN=16, A_MAX=90, L_MIN=40, L_MAX=180;
  const A_SPAN=A_MAX-A_MIN, L_SPAN=L_MAX-L_MIN;
  const LOCK_AT=0.95;                // the brief's 95% margin…
  const HOLD_MS=1500;                // …sustained for a second and a half
  const A_TOL=(1-LOCK_AT)*A_SPAN, L_TOL=(1-LOCK_AT)*L_SPAN;

  // Both scopes are drawn with f(), so the player is always tuning against a
  // shape they can actually reach. Only the printed formula cycles.
  const FORMS=[
    { name:'SINE',     label:(a,l)=>`ƒ(x) = ${a}·sin(2πx/${l})`,        f:t=>Math.sin(t) },
    { name:'HARMONIC', label:(a,l)=>`ƒ(x) = ${a}·[sinθ + ½sin2θ] · λ=${l}`, f:t=>(Math.sin(t)+0.5*Math.sin(2*t))/1.5 },
    { name:'SAWTOOTH', label:(a,l)=>`ƒ(x) = ${a}·saw(2πx/${l})`,        f:t=>{ const p=((t/(Math.PI*2))%1+1)%1; return 2*p-1; } },
    { name:'TRIANGLE', label:(a,l)=>`ƒ(x) = ${a}·tri(2πx/${l})`,        f:t=>{ const p=((t/(Math.PI*2))%1+1)%1; return 4*Math.abs(p-0.5)-1; } },
    // tanh rather than Math.sign: a true square draws as vertical jumps that
    // alias into a ladder at this line width. This reads square and stays smooth.
    { name:'SQUARE',   label:(a,l)=>`ƒ(x) = ${a}·sgn(sin 2πx/${l})`,    f:t=>Math.tanh(Math.sin(t)*4) }
  ];

  const diffMod=getDifficultyModifier();
  const time0=Math.round(45*getTimeModifier());
  const TARGET_C='#ff0090';
  const OUT_C=getEquippedColorHex();
  const LOCK_C='#39ff14';

  let time=time0, score=0, stage=1, cleared=0, ended=false;
  let amp=52, len=110;                        // your output
  let tAmp=0, tLen=0, form=FORMS[0], drift={a:0,l:0};
  let held=0, stageT=0, bestMatch=0, phase=0;
  let banner='', bannerT=0, lastT=performance.now();
  // 🎯 True until a lock on stage one is reached and then lost. Cleared by the
  // loop, read once by stageClear() — see the PERFECT SYNC achievement.
  let firstTryClean=true, perfectSync=false;

  document.getElementById('g-time').textContent=time;
  document.getElementById('prog-fill').style.width='100%';
  document.getElementById('prog-fill').style.background='linear-gradient(90deg,var(--cyan),var(--pink))';

  // ── CONSOLE ──
  const ampEl=document.getElementById('freq-amp');
  const lenEl=document.getElementById('freq-len');
  const ampVal=document.getElementById('freq-amp-val');
  const lenVal=document.getElementById('freq-len-val');
  ampEl.min=A_MIN; ampEl.max=A_MAX; ampEl.value=amp;
  lenEl.min=L_MIN; lenEl.max=L_MAX; lenEl.value=len;
  const syncConsole=()=>{
    ampEl.value=Math.round(amp); lenEl.value=Math.round(len);
    ampVal.textContent=Math.round(amp); lenVal.textContent=Math.round(len);
  };
  // snd() throttles 'move' to one every 25ms of its own accord, which is what
  // keeps a dragged slider from firing a click per pixel.
  ampEl.oninput=()=>{ if(ended) return; hideTouchHint(); amp=parseFloat(ampEl.value); syncConsole(); snd('move'); };
  lenEl.oninput=()=>{ if(ended) return; hideTouchHint(); len=parseFloat(lenEl.value); syncConsole(); snd('move'); };
  syncConsole();

  function newStage(){
    form=FORMS[(stage-1)%FORMS.length];
    // Held clear of where the dials already sit, so a stage can never arrive
    // pre-solved by whatever the last one happened to end on.
    do{ tAmp=A_MIN+Math.random()*A_SPAN; } while(Math.abs(tAmp-amp)<A_SPAN*0.2);
    do{ tLen=L_MIN+Math.random()*L_SPAN; } while(Math.abs(tLen-len)<L_SPAN*0.2);
    // Above STABLE the target will not hold still. A locked signal then has to
    // be TRACKED for its 1.5 seconds rather than dialled in once and released,
    // which is a fairer way to charge for the ×1.5 and ×2.0 than shaving the
    // 95% margin the brief fixed.
    const wander=(diffMod-1)*0.6;
    drift={ a:(Math.random()<.5?-1:1)*wander*3.2, l:(Math.random()<.5?-1:1)*wander*3.6 };
    held=0; stageT=0;
  }

  // Both properties have to agree, so the WORSE of the two is the score — an
  // average would hand out a lock to a perfect amplitude on a wrong wavelength.
  const matchPct=()=>Math.max(0, Math.min(
    1-Math.abs(amp-tAmp)/A_SPAN,
    1-Math.abs(len-tLen)/L_SPAN
  ));

  function stageClear(){
    // Base plus what is left of a speed window: dialling it in fast is the
    // whole skill, and the 1.5s hold is already sunk into every clear.
    const speed=Math.max(0, Math.round(70 - stageT/1000*9));
    const gained=85+speed;
    if(stage===1 && firstTryClean) perfectSync=true;
    score+=gained; cleared++; stage++;
    setLive(Math.min(950,score));
    snd('levelUp');
    banner=`✅ NODE STABILISED · +${gained} PTS`;
    bannerT=1100;
    newStage();
  }

  gTimer=setInterval(()=>{
    if(ended) return;
    time--;
    document.getElementById('g-time').textContent=time;
    document.getElementById('prog-fill').style.width=`${Math.max(0,time/time0*100)}%`;
    if(time<=5 && time>0) snd('tick');
    if(time<=0) end();
  },1000);

  window.onkeydown=e=>{
    if(e.ctrlKey||e.metaKey||e.altKey||ended) return;
    const step=e.shiftKey ? 0.5 : 2;
    const k=String(e.key).length===1 ? String(e.key).toUpperCase() : e.key;
    let used=true;
    if(k==='ArrowUp'   || k==='W') amp=Math.min(A_MAX,amp+step);
    else if(k==='ArrowDown'  || k==='S') amp=Math.max(A_MIN,amp-step);
    else if(k==='ArrowRight' || k==='D') len=Math.min(L_MAX,len+step);
    else if(k==='ArrowLeft'  || k==='A') len=Math.max(L_MIN,len-step);
    else used=false;
    if(!used) return;
    e.preventDefault();
    syncConsole();
  };

  // ── DRAWING ──
  // `l` is the wavelength in pixels, so x/l·2π is the phase at that column.
  // `phase` scrolls both waves together — a frozen trace reads as a picture of
  // a signal rather than a live one.
  function wave(cy, a, l, colour, alpha, width, glow){
    aCtx.save();
    aCtx.globalAlpha=alpha;
    aCtx.strokeStyle=colour;
    aCtx.lineWidth=width;
    aCtx.lineJoin='round';
    if(glow){ aCtx.shadowBlur=glow; aCtx.shadowColor=colour; }
    aCtx.beginPath();
    for(let x=0;x<=W;x+=2){
      const y=cy - a*form.f(x/l*Math.PI*2 + phase);
      if(x===0) aCtx.moveTo(x,y); else aCtx.lineTo(x,y);
    }
    aCtx.stroke();
    aCtx.restore();
  }

  function scope(cy, colour, title){
    aCtx.save();
    aCtx.fillStyle=hexToRgba(colour,0.04);
    aCtx.fillRect(6, cy-HALF, W-12, HALF*2);
    aCtx.strokeStyle=hexToRgba(colour,0.30);
    aCtx.lineWidth=1.5;
    aCtx.strokeRect(6, cy-HALF, W-12, HALF*2);
    aCtx.setLineDash([4,5]);
    aCtx.strokeStyle=hexToRgba(colour,0.22);
    aCtx.beginPath(); aCtx.moveTo(6,cy); aCtx.lineTo(W-6,cy); aCtx.stroke();
    aCtx.setLineDash([]);
    aCtx.font='bold 10px Orbitron,monospace';
    aCtx.fillStyle=colour;
    aCtx.textAlign='left';
    aCtx.fillText(title, 14, cy-HALF+15);
    aCtx.restore();
  }

  const trim=(d,tol,up,down)=> Math.abs(d)<=tol ? '● LOCKED' : (d>0 ? up : down);

  function loop(){
    if(ended) return;
    const now=performance.now();
    const dt=Math.min(50, now-lastT); lastT=now;
    phase += dt/1000*1.6;
    if(bannerT>0) bannerT-=dt;

    if(drift.a || drift.l){
      tAmp+=drift.a*dt/1000;
      tLen+=drift.l*dt/1000;
      if(tAmp<A_MIN||tAmp>A_MAX){ tAmp=Math.max(A_MIN,Math.min(A_MAX,tAmp)); drift.a*=-1; }
      if(tLen<L_MIN||tLen>L_MAX){ tLen=Math.max(L_MIN,Math.min(L_MAX,tLen)); drift.l*=-1; }
    }

    const m=matchPct();
    const locking=m>=LOCK_AT;
    bestMatch=Math.max(bestMatch,m);
    stageT+=dt;
    if(locking) held+=dt;
    else{
      // Losing a lock that was most of the way home is worth hearing about.
      if(held>HOLD_MS*0.4) snd('deny');
      // 🎯 PERFECT SYNC watches exactly this: a lock that was reached and then
      // dropped is no longer a first-try match, so the flag dies the first time
      // the hold breaks on stage one. Only a hold that RAN is a broken one —
      // the frames before the dials ever reach 95% are not a miss.
      if(held>0 && stage===1) firstTryClean=false;
      held=0;
    }
    if(held>=HOLD_MS) stageClear();

    // ── board ──
    // fitCanvas() only wipes the context when the backing store actually
    // changes size, so whatever the previous mission left on the shared canvas
    // — a globalAlpha, a shadow, a dash pattern, a centred baseline — is still
    // set when this one mounts. Normalised here rather than trusted, since the
    // first thing below is a full-board fill that a stale alpha would make
    // translucent.
    aCtx.globalAlpha=1;
    aCtx.shadowBlur=0;
    aCtx.setLineDash([]);
    aCtx.textBaseline='alphabetic';
    aCtx.fillStyle='#05060f';
    aCtx.fillRect(0,0,W,H);
    aCtx.strokeStyle='rgba(255,255,255,0.045)';
    aCtx.lineWidth=1;
    for(let x=0;x<=W;x+=40){ aCtx.beginPath(); aCtx.moveTo(x,0); aCtx.lineTo(x,H); aCtx.stroke(); }
    for(let y=0;y<=H;y+=40){ aCtx.beginPath(); aCtx.moveTo(0,y); aCtx.lineTo(W,y); aCtx.stroke(); }

    // ── header: the cycling formula ──
    aCtx.font='bold 12px Orbitron,monospace';
    aCtx.fillStyle=TARGET_C;
    aCtx.textAlign='center';
    aCtx.fillText(form.label(Math.round(tAmp), Math.round(tLen)), W/2, 24);

    // ── target scope ──
    scope(TY, TARGET_C, `TARGET SIGNAL · ${form.name}${drift.a||drift.l ? ' · DRIFTING' : ''}`);
    wave(TY, tAmp, tLen, TARGET_C, 1, 2.4, 16);

    // ── output scope, target ghosted over it ──
    scope(BY, locking?LOCK_C:OUT_C, `YOUR OUTPUT · STAGE ${stage}`);
    wave(BY, tAmp, tLen, TARGET_C, 0.30, 1.6, 0);
    wave(BY, amp, len, locking?LOCK_C:OUT_C, 1, 2.6, locking?22:14);

    // ── readout band ──
    const pct=Math.round(m*100);
    aCtx.save();
    aCtx.textAlign='center';
    aCtx.font='900 24px Orbitron,monospace';
    aCtx.fillStyle=locking ? LOCK_C : (m>0.85 ? '#ffd700' : '#ff2442');
    aCtx.shadowBlur=locking?18:0; aCtx.shadowColor=aCtx.fillStyle;
    aCtx.fillText(`${pct}% MATCH`, W/2, MID-4);
    aCtx.restore();

    const lw=230, lx=(W-lw)/2, ly=MID+10;
    aCtx.fillStyle='rgba(255,255,255,0.08)';
    aCtx.fillRect(lx,ly,lw,7);
    aCtx.save();
    aCtx.fillStyle=locking?LOCK_C:'rgba(255,255,255,0.16)';
    if(locking){ aCtx.shadowBlur=12; aCtx.shadowColor=LOCK_C; }
    aCtx.fillRect(lx,ly,lw*Math.min(1,held/HOLD_MS),7);
    aCtx.restore();
    aCtx.font='bold 8px Orbitron,monospace';
    aCtx.fillStyle='rgba(255,255,255,0.45)';
    aCtx.textAlign='center';
    aCtx.fillText(`HOLD ${(HOLD_MS/1000).toFixed(1)}s ABOVE ${Math.round(LOCK_AT*100)}% TO STABILISE`, W/2, ly+20);

    // ── footer: which way each dial has to go ──
    const dA=tAmp-amp, dL=tLen-len;
    aCtx.font='bold 11px Orbitron,monospace';
    aCtx.textAlign='left';
    aCtx.fillStyle=Math.abs(dA)<=A_TOL ? LOCK_C : 'rgba(255,255,255,0.62)';
    aCtx.fillText(`AMP ${Math.round(amp)}  ${trim(dA,A_TOL,'▲ RAISE','▼ LOWER')}`, 14, H-12);
    aCtx.textAlign='right';
    aCtx.fillStyle=Math.abs(dL)<=L_TOL ? LOCK_C : 'rgba(255,255,255,0.62)';
    aCtx.fillText(`${trim(dL,L_TOL,'▶ WIDEN','◀ NARROW')}  λ ${Math.round(len)}`, W-14, H-12);

    // ── stage-clear banner ──
    if(bannerT>0){
      aCtx.save();
      aCtx.globalAlpha=Math.min(1,bannerT/400);
      aCtx.font='900 15px Orbitron,monospace';
      aCtx.fillStyle=LOCK_C;
      aCtx.shadowBlur=16; aCtx.shadowColor=LOCK_C;
      aCtx.textAlign='center';
      aCtx.fillText(banner, W/2, TY-HALF-8);
      aCtx.restore();
    }

    gameLoopId=requestAnimationFrame(loop);
  }

  // The console lives in the shared DOM, so its handlers come down with the
  // round however it ends — including a quit part-way through a stage.
  onStopGame=()=>{
    ended=true;
    ampEl.oninput=lenEl.oninput=null;
    panel.style.display='none';
  };

  function end(){
    if(ended) return; ended=true;
    const final=Math.min(950,score);
    showResults('freq', final, {
      '📡 Node Array': cleared ? `${cleared} NODE${cleared===1?'':'S'} STABILISED` : 'ARRAY UNSTABLE',
      '🎚️ Stages Cleared': cleared,
      '🎯 Peak Correlation': `${Math.round(bestMatch*100)}%`,
      ...(perfectSync ? {'🎯 First Lock':'PERFECT — NO MISS'} : {}),
      '📶 Last Waveform': form.name,
      '🏆 Score Accumulation': `${final} PTS`
    }, { perfect: perfectSync, ...(cleared ? {} : { sound:'gameOver' }) });
  }

  newStage();
  gameLoopId=requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🎵 GAME 19: PULSE SYNC
// ════════════════════════════════════════════
// The arcade had eighteen missions and not one of them was about TIME. Every
// other mission asks where something is or what it is; this one asks only when,
// which is why it earns a slot rather than being a reskin of Node Hacker.
//
// It is charted against the round soundtrack's actual tempo — SFX.bpm, which a
// Music Drive retunes. That is the point of building it: the drives were four
// cosmetics that changed what you heard and nothing else, and here a drive
// bought in the market changes how a mission plays. Synthwave at 136 and a
// slower dark-synth chart are genuinely different rounds.
//
// Three lanes, not four, because the shared control pad has exactly three
// direction keys (◀ ACTION ▶) and a fourth lane would have needed a pad of its
// own on every phone in the arcade.
function startPulseSync(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls({ left: '◀', action: '●', right: '▶' });
  setControlHint('TAP A LANE AS ITS PULSE CROSSES THE LINE',
                 'A · S · D  or  ◀ ↓ ▶  —  strike on the line');
  // After setControls, never before: fitCanvas() measures the pad to decide how
  // much height the board gets, and run first it measures the pad the PREVIOUS
  // round left standing.
  fitCanvas();

  const W = BOARD_W, H = BOARD_H;
  const LANES = 3;
  const LANE_W = W / LANES;
  const HIT_Y = H - 96;                 // the strike line
  const diff = getDifficultyModifier();

  // Beats-per-second from the LIVE track. Falls back to the stock game tempo if
  // the audio engine is muted or unsupported — the chart still has to exist.
  const bpm = (window.SFX && SFX.bpm) || 136;
  const beat = 60 / bpm;                // seconds per beat
  // Notes fall for exactly two bars, so the read-ahead is a musical length
  // rather than a pixel distance: at a slower drive they fall more slowly and
  // the player gets the same number of beats of warning either way.
  const FALL = beat * 8;
  const SPEED = (HIT_Y + 40) / FALL;    // px per second

  // Windows, in seconds. Generous on purpose: this is an arcade mission on a
  // phone, not a rhythm sim, and the interesting failure is missing the note
  // rather than being eleven milliseconds late on it.
  const PERFECT = 0.075, GOOD = 0.145, LATE = 0.215;

  let time = Math.round(50 * getTimeModifier());
  let score = 0, combo = 0, bestCombo = 0, hits = 0, perfects = 0, misses = 0;
  let over = false, t0 = performance.now(), flash = [0, 0, 0], shake = 0;
  const notes = [];
  const pops = [];

  document.getElementById('g-time').textContent = time;

  // ── THE CHART ──
  // Generated rather than authored: a fixed chart would be the same round every
  // time, and the seeded Daily Hack would have nothing to seed. Built in bars of
  // eight eighth-notes with a density that climbs, so the round has an arc.
  let chartT = beat * 4;                // one bar of lead-in before the first note
  let bar = 0, lastLane = -1;
  function chartAhead(until){
    while(chartT < until){
      const density = Math.min(0.82, 0.34 + bar * 0.045) * Math.min(1.25, diff);
      for(let i = 0; i < 8; i++){
        const at = chartT + i * beat / 2;
        if(dailyRand() > density) continue;
        // Never the same lane twice running: a repeated lane reads as one long
        // note and the second tap feels like it did not register.
        let lane = Math.floor(dailyRand() * LANES);
        if(lane === lastLane) lane = (lane + 1 + Math.floor(dailyRand() * (LANES - 1))) % LANES;
        lastLane = lane;
        // Downbeats are doubles once the round has warmed up — the only place
        // two lanes are ever live at the same instant, so it reads as emphasis.
        const dbl = i === 0 && bar >= 4 && dailyRand() < 0.3;
        notes.push({ lane, at, hit: false, dead: false });
        if(dbl) notes.push({ lane: (lane + 2) % LANES, at, hit: false, dead: false });
      }
      chartT += beat * 4;
      bar++;
    }
  }
  chartAhead(FALL + beat * 8);

  const now = () => (performance.now() - t0) / 1000;

  function strike(lane){
    if(over) return;
    hideTouchHint();
    flash[lane] = 1;
    const t = now();
    // The nearest live note in this lane, and only if it is inside the widest
    // window — a tap into empty air is not a miss, it is just a tap. Punishing
    // it would make the right strategy "play fewer notes".
    let best = null, bestD = Infinity;
    for(const n of notes){
      if(n.lane !== lane || n.hit || n.dead) continue;
      const d = Math.abs(n.at - t);
      if(d < bestD){ bestD = d; best = n; }
    }
    if(!best || bestD > LATE){
      // A strike into empty air is a MISS, not a free swing. That one rule is
      // what makes mashing all three lanes a losing strategy rather than the
      // optimal one: it holds the chain at 1× and it drags the accuracy bonus
      // down, so the spammer ends up well short of a player who reads the chart.
      snd('wrong');
      combo = 0;
      misses++;
      return;
    }
    best.hit = true;
    hits++;
    const grade = bestD <= PERFECT ? 'PERFECT' : bestD <= GOOD ? 'GOOD' : 'LATE';
    // Small per-note values on purpose: the chart is long, and the number that
    // should decide the round is the CHAIN, not the count.
    const base  = bestD <= PERFECT ? 6 : bestD <= GOOD ? 4 : 2;
    if(grade === 'PERFECT') perfects++;
    combo++;
    bestCombo = Math.max(bestCombo, combo);
    // Combo multiplies but saturates: an uninterrupted round should pay for
    // being uninterrupted without making the first thirty seconds irrelevant.
    const mult = 1 + Math.min(1, Math.floor(combo / 8) * 0.25);
    const gain = Math.round(base * mult);
    score += gain;
    setLive(Math.min(1400, score));
    snd(grade === 'PERFECT' ? 'match' : 'correct', { semi: Math.min(combo, 14) });
    if(grade === 'PERFECT') shake = Math.max(shake, 4);
    pops.push({ x: lane * LANE_W + LANE_W / 2, y: HIT_Y - 26, life: 1,
                text: `${grade} +${gain}`, color: grade === 'PERFECT' ? '#39ff88' : grade === 'GOOD' ? '#00f5ff' : '#ffd700' });
  }

  window.onkeydown = e => {
    const map = { KeyA: 0, KeyS: 1, KeyD: 2, ArrowLeft: 0, ArrowDown: 1, ArrowRight: 2, Space: 1 };
    const lane = map[e.code];
    if(lane == null) return;
    e.preventDefault();
    strike(lane);
  };
  document.getElementById('ctrl-left').onclick   = () => strike(0);
  document.getElementById('ctrl-action').onclick = () => strike(1);
  document.getElementById('ctrl-right').onclick  = () => strike(2);
  bindCanvasDrag({ onDown(p){ strike(Math.max(0, Math.min(LANES - 1, Math.floor(p.x / LANE_W)))); } });

  gTimer = setInterval(() => {
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = `${Math.max(0, time) / Math.round(50 * getTimeModifier()) * 100}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end();
  }, 1000);

  const LANE_COL = ['#ff0090', '#00f5ff', '#39ff88'];

  function loop(){
    if(over) return;
    gameLoopId = requestAnimationFrame(loop);
    const t = now();
    chartAhead(t + FALL + beat * 8);

    // Retire notes that fell past the window. A note is only a MISS once it is
    // unhittable — retiring it at the line would punish the late-but-legal tap
    // the LATE window exists to accept.
    for(const n of notes){
      if(n.hit || n.dead) continue;
      if(t > n.at + LATE){ n.dead = true; misses++; combo = 0; snd('wrong'); shake = Math.max(shake, 6); }
    }

    aCtx.clearRect(0, 0, W, H);
    aCtx.save();
    if(shake > 0){
      aCtx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
      shake *= 0.85; if(shake < 0.3) shake = 0;
    }

    // ── LANES ──
    for(let i = 0; i < LANES; i++){
      const x = i * LANE_W;
      const g = aCtx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, 'rgba(255,255,255,0.02)');
      g.addColorStop(1, `rgba(255,255,255,${0.03 + flash[i] * 0.12})`);
      aCtx.fillStyle = g;
      aCtx.fillRect(x + 3, 0, LANE_W - 6, H);
      aCtx.strokeStyle = 'rgba(255,255,255,0.10)';
      aCtx.lineWidth = 1;
      aCtx.strokeRect(x + 3, 0, LANE_W - 6, H);
      flash[i] = Math.max(0, flash[i] - 0.07);
    }

    // ── THE STRIKE LINE ──
    // The one thing on screen that must never be ambiguous, so it gets the
    // brightest treatment in the mission and a pad per lane under it.
    for(let i = 0; i < LANES; i++){
      const x = i * LANE_W, c = LANE_COL[i];
      aCtx.save();
      aCtx.shadowBlur = 18 + flash[i] * 28; aCtx.shadowColor = c;
      aCtx.strokeStyle = c;
      aCtx.lineWidth = 3 + flash[i] * 3;
      aCtx.beginPath();
      aCtx.roundRect(x + 10, HIT_Y - 20, LANE_W - 20, 40, 10);
      aCtx.stroke();
      aCtx.restore();
    }
    aCtx.save();
    aCtx.strokeStyle = 'rgba(255,255,255,0.55)';
    aCtx.lineWidth = 2;
    aCtx.setLineDash([6, 6]);
    aCtx.beginPath(); aCtx.moveTo(0, HIT_Y); aCtx.lineTo(W, HIT_Y); aCtx.stroke();
    aCtx.restore();

    // ── NOTES ──
    for(const n of notes){
      if(n.hit || n.dead) continue;
      const dy = (n.at - t) * SPEED;
      const y = HIT_Y - dy;
      if(y < -40 || y > H + 40) continue;
      const x = n.lane * LANE_W + LANE_W / 2;
      const c = LANE_COL[n.lane];
      // Closeness is drawn, not just positioned: the glow tightens as the note
      // approaches so peripheral vision can time it without reading the gap.
      const near = Math.max(0, 1 - Math.abs(dy) / 90);
      aCtx.save();
      aCtx.shadowBlur = 12 + near * 22; aCtx.shadowColor = c;
      aCtx.fillStyle = c;
      aCtx.beginPath();
      aCtx.roundRect(x - LANE_W / 2 + 20, y - 13, LANE_W - 40, 26, 8);
      aCtx.fill();
      aCtx.fillStyle = `rgba(255,255,255,${0.25 + near * 0.5})`;
      aCtx.beginPath();
      aCtx.roundRect(x - LANE_W / 2 + 26, y - 9, LANE_W - 52, 7, 4);
      aCtx.fill();
      aCtx.restore();
    }

    // ── COMBO ──
    if(combo >= 4){
      aCtx.save();
      aCtx.textAlign = 'center';
      aCtx.font = '900 34px Orbitron,monospace';
      const c = getEquippedColorHex();
      aCtx.shadowBlur = 18; aCtx.shadowColor = c;
      aCtx.fillStyle = c;
      aCtx.fillText(`${combo}×`, W / 2, 64);
      aCtx.font = 'bold 11px Orbitron,monospace';
      aCtx.fillStyle = 'rgba(255,255,255,0.65)';
      aCtx.shadowBlur = 0;
      aCtx.fillText('CHAIN', W / 2, 82);
      aCtx.restore();
    }

    for(let i = pops.length - 1; i >= 0; i--){
      const p = pops[i];
      p.life -= 0.03; p.y -= 0.9;
      if(p.life <= 0){ pops.splice(i, 1); continue; }
      aCtx.save();
      aCtx.globalAlpha = Math.min(1, p.life * 1.6);
      aCtx.textAlign = 'center';
      aCtx.font = '900 15px Orbitron,monospace';
      aCtx.fillStyle = p.color;
      aCtx.shadowBlur = 10; aCtx.shadowColor = p.color;
      aCtx.fillText(p.text, p.x, p.y);
      aCtx.restore();
    }

    // Tempo readout — the mission's whole conceit is that it is charted to YOUR
    // drive, so it says so.
    aCtx.save();
    aCtx.textAlign = 'left';
    aCtx.font = 'bold 10px Orbitron,monospace';
    aCtx.fillStyle = 'rgba(255,255,255,0.4)';
    aCtx.fillText(`♪ ${Math.round(bpm)} BPM`, 10, 18);
    aCtx.restore();

    aCtx.restore();
  }

  function end(){
    if(over) return; over = true;
    clearCanvasDrag();
    const acc = hits + misses > 0 ? hits / (hits + misses) : 0;
    // Accuracy is worth points on the way out, so a clean round beats a longer
    // sloppy one — the same shape as Ice Breaker paying for intact shields.
    const bonus = Math.round(acc * 160);
    const final = Math.min(1400, score + bonus);
    showResults('rhythm', final, {
      '🎵 Pulses Struck': `${hits}/${hits + misses}`,
      '🎯 Perfect Sync': perfects,
      '🔥 Longest Chain': `${bestCombo}×`,
      '📊 Accuracy': `${Math.round(acc * 100)}% (+${bonus})`,
      '♪ Charted At': `${Math.round(bpm)} BPM`,
      '🏆 Score Accumulation': `${final} PTS`
    }, { perfect: misses === 0 && hits > 0 });
  }

  gameLoopId = requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🧮 GAME 20: CORE MERGE
// ════════════════════════════════════════════
// Everything else in the arcade is dexterity or recall under a clock. This one
// is the arithmetic of a board you can stare at: every move is reversible in
// your head before you make it, and the clock only decides how many moves you
// get. It is the only mission where sitting still and thinking is the correct
// play, which is the whole reason it is here.
//
// Scoring is the sum of every core produced, so a single 512 is worth more than
// the entire sequence of 2s that built it — the board pays for depth, not for
// activity.
function startCoreMerge(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls({ left: '◀', action: '▲', drop: '▼', right: '▶' });
  setControlHint('SWIPE TO COMPACT THE LATTICE', 'ARROW KEYS or WASD to compact the lattice');
  fitCanvas();                       // after setControls — see startPulseSync()

  const W = BOARD_W, H = BOARD_H;
  const N = 4;
  const PAD = 14, GAP = 10;
  const BOARD = Math.min(W - PAD * 2, H - PAD * 2 - 70);
  const CELL = (BOARD - GAP * (N + 1)) / N;
  const OX = (W - BOARD) / 2, OY = (H - BOARD) / 2 + 24;
  const cellX = c => OX + GAP + c * (CELL + GAP);
  const cellY = r => OY + GAP + r * (CELL + GAP);

  // Value → colour. Stops at 4096 because a board that reaches it has already
  // beaten the clock several times over.
  const TILE_COL = {
    2:'#1d2233', 4:'#26304a', 8:'#2b7bff', 16:'#00f5ff', 32:'#39ff88',
    64:'#ffd700', 128:'#ff9500', 256:'#ff6600', 512:'#ff0090',
    1024:'#a855f7', 2048:'#ff2442', 4096:'#ffffff'
  };
  const tileCol = v => TILE_COL[v] || '#ffffff';
  // Dark plates need light type and the bright ones need dark type, or half the
  // board is unreadable at a glance — which is fatal in a game about scanning.
  const tileInk = v => (v <= 4 ? 'rgba(255,255,255,0.92)' : 'rgba(5,7,15,0.92)');

  let grid = [];
  for(let i = 0; i < N * N; i++) grid.push(0);
  let score = 0, best = 0, moves = 0, merges = 0, over = false;
  let time = Math.round(100 * getTimeModifier());
  const anims = [];

  // ── THE SLIDE ──
  // Without this the board TELEPORTS: you swipe, and sixteen cores are simply
  // somewhere else. The travel is the only thing that shows WHY the board ended
  // up the way it did — which core ran into which, and which pair was one cell
  // short of touching — so the move is animated and the spawn and the merge
  // pops are held back until it lands.
  const SLIDE = 0.1;                     // seconds
  let slideT = 0;
  let movers = [];                       // {v, fr, fc, tr, tc}
  let holdGrid = null;                   // the board as it stood BEFORE the move
  let srcs = new Set();                  // cells the movers left behind

  const at = (r, c) => grid[r * N + c];
  const put = (r, c, v) => { grid[r * N + c] = v; };
  // What the player is looking at right now: mid-slide that is the old board
  // with the travelling cores lifted out of it, otherwise the real one.
  const shown = i => slideT > 0 ? (srcs.has(i) ? 0 : holdGrid[i]) : grid[i];

  function freeCells(){
    const out = [];
    for(let i = 0; i < N * N; i++) if(!grid[i]) out.push(i);
    return out;
  }
  function spawn(){
    const free = freeCells();
    if(!free.length) return false;
    const i = free[Math.floor(dailyRand() * free.length)];
    grid[i] = dailyRand() < 0.88 ? 2 : 4;
    anims.push({ i, t: 1, delay: SLIDE, kind: 'spawn' });
    return true;
  }
  spawn(); spawn();

  document.getElementById('g-time').textContent = time;

  // One slide routine, four directions, by reading the grid along the axis the
  // move happens on. Writing four of these is how a 2048 board ends up with
  // three of them subtly wrong.
  function slide(dr, dc){
    if(over) return;
    let moved = false;
    const gained = [];
    const flying = [];
    const before = grid.slice();
    // Iterate from the far edge so a merged cell can never merge twice in one
    // move — the rule everyone gets wrong first, and the one that decides
    // whether the board is beatable.
    const order = [];
    for(let r = 0; r < N; r++) for(let c = 0; c < N; c++) order.push([r, c]);
    if(dr > 0) order.sort((a, b) => b[0] - a[0]);
    if(dr < 0) order.sort((a, b) => a[0] - b[0]);
    if(dc > 0) order.sort((a, b) => b[1] - a[1]);
    if(dc < 0) order.sort((a, b) => a[1] - b[1]);

    const locked = new Set();
    for(const [r, c] of order){
      const v = at(r, c);
      if(!v) continue;
      let rr = r, cc = c;
      while(true){
        const nr = rr + dr, nc = cc + dc;
        if(nr < 0 || nr >= N || nc < 0 || nc >= N) break;
        const nv = at(nr, nc);
        if(nv === 0){ put(nr, nc, v); put(rr, cc, 0); rr = nr; cc = nc; moved = true; continue; }
        if(nv === v && !locked.has(nr * N + nc)){
          put(nr, nc, v * 2);
          put(rr, cc, 0);
          locked.add(nr * N + nc);
          gained.push(v * 2);
          moved = true;
          // The tile keeps travelling into the cell it merged with, so the
          // animation carries it all the way there and the doubled core
          // appears under it rather than beside it.
          rr = nr; cc = nc;
          anims.push({ i: nr * N + nc, t: 1, delay: SLIDE, kind: 'merge' });
        }
        break;
      }
      if(rr !== r || cc !== c) flying.push({ v, fr: r, fc: c, tr: rr, tc: cc });
    }

    if(!moved){ snd('deny'); return; }
    holdGrid = before;
    movers = flying;
    srcs = new Set(flying.map(m => m.fr * N + m.fc));
    slideT = SLIDE;
    moves++;
    if(gained.length){
      merges += gained.length;
      const sum = gained.reduce((a, b) => a + b, 0);
      score += sum;
      best = Math.max(best, ...gained);
      setLive(Math.min(1300, score));
      // The chime climbs with the size of the core, so a 256 sounds like a 256.
      snd('match', { semi: Math.min(16, Math.round(Math.log2(Math.max(...gained))) * 2) });
    }else{
      snd('move');
    }
    spawn();
    if(!canMove()) end('gridlock');
  }

  function canMove(){
    if(freeCells().length) return true;
    for(let r = 0; r < N; r++) for(let c = 0; c < N; c++){
      const v = at(r, c);
      if(r + 1 < N && at(r + 1, c) === v) return true;
      if(c + 1 < N && at(r, c + 1) === v) return true;
    }
    return false;
  }

  window.onkeydown = e => {
    const map = { ArrowUp:[-1,0], KeyW:[-1,0], ArrowDown:[1,0], KeyS:[1,0],
                  ArrowLeft:[0,-1], KeyA:[0,-1], ArrowRight:[0,1], KeyD:[0,1] };
    const d = map[e.code];
    if(!d) return;
    e.preventDefault();
    slide(d[0], d[1]);
  };
  document.getElementById('ctrl-left').onclick   = () => slide(0, -1);
  document.getElementById('ctrl-right').onclick  = () => slide(0, 1);
  document.getElementById('ctrl-action').onclick = () => slide(-1, 0);
  document.getElementById('ctrl-drop').onclick   = () => slide(1, 0);

  // Swipe. A threshold in BOARD units rather than pixels, so the gesture feels
  // the same on a phone and on a 1.9×-scaled desktop board. It is read on the
  // way as well as at the end: a flick that leaves the canvas — easy on a phone,
  // where the board is most of the screen — never delivers a touchend the
  // gesture can use, and the move was simply lost.
  let sx = 0, sy = 0, swiping = false;
  const SWIPE = 26;
  function trySwipe(p){
    if(!swiping) return;
    const dx = p.x - sx, dy = p.y - sy;
    if(Math.abs(dx) < SWIPE && Math.abs(dy) < SWIPE) return;
    swiping = false;
    if(Math.abs(dx) > Math.abs(dy)) slide(0, dx > 0 ? 1 : -1);
    else slide(dy > 0 ? 1 : -1, 0);
  }
  bindCanvasDrag({
    onDown(p){ hideTouchHint(); sx = p.x; sy = p.y; swiping = true; },
    onMove: trySwipe,
    onUp(p){ trySwipe(p); swiping = false; }
  });

  gTimer = setInterval(() => {
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = `${Math.max(0, time) / Math.round(100 * getTimeModifier()) * 100}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  // One core, drawn at an arbitrary position so the same routine serves a tile
  // sitting in its cell and a tile halfway between two.
  function drawTile(x, y, v, k){
    const s = CELL * k, ox = (CELL - s) / 2;
    const col = tileCol(v);
    aCtx.save();
    aCtx.shadowBlur = v >= 64 ? 16 : 6; aCtx.shadowColor = col;
    aCtx.fillStyle = col;
    aCtx.beginPath(); aCtx.roundRect(x + ox, y + ox, s, s, 9); aCtx.fill();
    aCtx.shadowBlur = 0;
    aCtx.strokeStyle = 'rgba(255,255,255,0.22)';
    aCtx.lineWidth = 1.5;
    aCtx.beginPath(); aCtx.roundRect(x + ox, y + ox, s, s, 9); aCtx.stroke();
    const txt = String(v);
    aCtx.fillStyle = tileInk(v);
    aCtx.textAlign = 'center';
    aCtx.textBaseline = 'middle';
    aCtx.font = `900 ${Math.round(CELL * (txt.length >= 4 ? 0.26 : txt.length === 3 ? 0.32 : 0.4))}px Orbitron,monospace`;
    aCtx.fillText(txt, x + CELL / 2, y + CELL / 2 + 1);
    aCtx.restore();
  }

  let last = performance.now();
  function loop(now){
    if(over) return;
    gameLoopId = requestAnimationFrame(loop);
    let dt = (now - last) / 1000; last = now;
    if(!(dt > 0)) dt = 1 / 60;
    if(dt > 0.05) dt = 0.05;
    if(slideT > 0) slideT = Math.max(0, slideT - dt);

    aCtx.clearRect(0, 0, W, H);

    // Well.
    aCtx.save();
    aCtx.fillStyle = 'rgba(255,255,255,0.03)';
    aCtx.strokeStyle = 'rgba(255,255,255,0.10)';
    aCtx.lineWidth = 2;
    aCtx.beginPath(); aCtx.roundRect(OX, OY, BOARD, BOARD, 14); aCtx.fill(); aCtx.stroke();
    aCtx.restore();

    for(let i = anims.length - 1; i >= 0; i--){
      const a = anims[i];
      // Held until the travel is over, so a spawn does not grow in while the
      // board it is landing on is still moving.
      if(a.delay > 0){ a.delay -= dt; continue; }
      a.t -= dt * 5.5;
      if(a.t <= 0) anims.splice(i, 1);
    }
    const animFor = i => anims.find(a => a.i === i && a.delay <= 0);

    // Empty sockets first, under everything.
    for(let r = 0; r < N; r++) for(let c = 0; c < N; c++){
      aCtx.save();
      aCtx.fillStyle = 'rgba(255,255,255,0.035)';
      aCtx.beginPath(); aCtx.roundRect(cellX(c), cellY(r), CELL, CELL, 9); aCtx.fill();
      aCtx.restore();
    }

    // Cores that are standing still.
    for(let r = 0; r < N; r++) for(let c = 0; c < N; c++){
      const i = r * N + c;
      const v = shown(i);
      if(!v) continue;
      const a = slideT > 0 ? null : animFor(i);
      // A spawn grows in and a merge overshoots and settles. The two have to
      // look different or the board reads as noise the moment it gets busy.
      const k = !a ? 1
        : a.kind === 'spawn' ? 1 - a.t
        : 1 + Math.sin(a.t * Math.PI) * 0.16;
      drawTile(cellX(c), cellY(r), v, k);
    }

    // Cores in transit, on top — a core sliding over the cell it is about to
    // merge with has to be the thing you see, not the thing underneath it.
    if(slideT > 0){
      const p = 1 - slideT / SLIDE;
      const e = 1 - Math.pow(1 - p, 3);        // ease out: leaves fast, arrives soft
      for(const m of movers){
        drawTile(cellX(m.fc) + (cellX(m.tc) - cellX(m.fc)) * e,
                 cellY(m.fr) + (cellY(m.tr) - cellY(m.fr)) * e, m.v, 1);
      }
    }

    aCtx.save();
    aCtx.textAlign = 'center';
    aCtx.textBaseline = 'alphabetic';
    aCtx.font = 'bold 12px Orbitron,monospace';
    aCtx.fillStyle = 'rgba(255,255,255,0.5)';
    aCtx.fillText(`LARGEST CORE  ${best || '—'}    ·    ${moves} MOVES`, W / 2, OY - 12);
    aCtx.restore();
  }

  function end(reason){
    if(over) return; over = true;
    clearCanvasDrag();
    // A core still standing on the board is worth a quarter of itself, so
    // building one big core beats farming small merges right up to the buzzer.
    const standing = Math.round(grid.reduce((a, b) => a + b, 0) * 0.25);
    const final = Math.min(1300, score + standing);
    showResults('merge', final, {
      '🧮 Run Terminated': reason === 'gridlock' ? 'LATTICE GRIDLOCKED' : 'CLOCK EXPIRED',
      '🔷 Largest Core': best || '—',
      '🔗 Merges Executed': merges,
      '♟️ Moves Made': moves,
      '📦 Lattice Residue': `+${standing}`,
      '🏆 Score Accumulation': `${final} PTS`
    }, reason === 'gridlock' ? { sound: 'gameOver' } : {});
  }

  gameLoopId = requestAnimationFrame(loop);
}

// ════════════════════════════════════════════
//  🛰️ GAME 21: ORBITAL UPLINK
// ════════════════════════════════════════════
// The arcade could not, until now, ask you to judge an ARC. Everything that
// moves in it travels in a straight line or under your continuous control;
// nothing was ever thrown. So this is the mission where you commit to a shot
// and then watch it be right or wrong, which is a completely different kind of
// tension from anything else on the grid.
//
// Drag BACKWARDS anywhere on the board to aim — the pull is the power, the
// same gesture on a phone and on a mouse, and the only control the mission has.
// Anchored where the drag starts rather than at the dish; see the gesture note
// inside for why that is not a detail.
function startOrbitalUplink(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls(null);                 // pure drag — no pad to steal board height
  setControlHint('DRAG BACKWARDS ANYWHERE ON THE BOARD, THEN RELEASE',
                 'DRAG BACKWARDS ANYWHERE AND RELEASE — the pull is the power');
  showTouchHint('DRAG BACKWARDS ANYWHERE TO LOB');
  fitCanvas();                       // after setControls — see startPulseSync()

  const W = BOARD_W, H = BOARD_H;
  const GROUND = H - 46;
  const PAD_X = 62, PAD_Y = GROUND - 12;
  const G = 560;                         // px/s²

  // ── THE SLING, AND WHY IT IS SHAPED LIKE THIS ──
  // Range under gravity goes as v², so a pull mapped LINEARLY onto speed spends
  // its first half crossing a third of the board and its second half sailing
  // off the far edge: every shot actually worth taking lived in a three-pixel
  // band of the drag, and the mission read as unaimable rather than as hard.
  // Mapping the pull onto √speed makes RANGE linear in the pull instead, so a
  // millimetre of finger is worth the same number of pixels downrange wherever
  // in the stroke it happens.
  const MAX_PULL = 190;                  // board units of drag for full power
  const V_MAX = 680;                     // px/s at full pull. A 45° shot then
                                         // carries ~825px — past the far edge
                                         // with margin, but not so far that the
                                         // useful half of the stroke vanishes.
  const shotSpeed = pull => V_MAX * Math.sqrt(Math.min(1, pull / MAX_PULL));
  const diff = getDifficultyModifier();

  let time = Math.round(75 * getTimeModifier());
  let score = 0, sunk = 0, shots = 0, streak = 0, bestStreak = 0, over = false;
  let wind = 0, relays = [], packet = null, aiming = false, aim = { x: 0, y: 0 };
  let anchor = null, ghost = null;
  const sparks = [], pops = [];
  let shake = 0, barrier = null;

  document.getElementById('g-time').textContent = time;

  // ── THE FIELD ──
  // A relay to hit, and a firewall slab between you and it. The slab is what
  // makes the mission about arcs rather than about aiming: a flat shot is
  // always wrong, so every shot has to go over something.
  function newField(){
    // The slab is placed FIRST and the relay is placed around it. The other way
    // round, a relay could land just behind a tall firewall — a field whose
    // only solution is an arc that clears the slab and drops inside a few
    // pixels — and nothing on screen tells the player that the field, not the
    // shot, is the problem.
    const bx = PAD_X + 90 + Math.random() * 60;
    barrier = { x: bx, w: 20, h: 70 + Math.random() * 80 * Math.min(1.3, diff) };
    const near = bx + 130, far = W - 44;
    relays = [{
      x: near + Math.random() * Math.max(40, far - near),
      // Never below the top of the slab either: threading UNDER a firewall is
      // a different mission, and an unwinnable one at this launch height.
      y: GROUND - Math.max(barrier.h + 26, 30 + Math.random() * 150),
      r: 26,
      bob: Math.random() * Math.PI * 2
    }];
    // Crosswind arrives only once the player has landed a few, so the mission
    // teaches the arc before it starts moving it.
    wind = sunk >= 3 ? (Math.random() * 2 - 1) * 70 * Math.min(1.4, diff) : 0;
  }
  newField();

  function fire(vx, vy){
    if(packet || over) return;
    shots++;
    packet = { x: PAD_X, y: PAD_Y - 12, vx, vy, trail: [], t: 0 };
    snd('shoot');
  }

  // ── THE GESTURE ──
  // The pull is measured from where the finger WENT DOWN, not from the dish.
  // The dish sits in the bottom-left corner, and "pull back from the dish"
  // means dragging down and to the left — into that corner, off the board, and
  // on a phone (where the whole board is scaled to about 0.65) clean off the
  // screen. Full power in the one direction the mission asks for was literally
  // out of reach. Anchoring the sling wherever the drag starts gives the stroke
  // the entire board to happen in, and a drag that does begin at the dish
  // behaves exactly as it always did.
  function pullFrom(p){
    if(!anchor) return null;
    const dx = anchor.x - p.x, dy = anchor.y - p.y;
    const len = Math.hypot(dx, dy);
    if(len < 14) return null;                    // a tap is not a shot
    const pull = Math.min(MAX_PULL, len);
    const k = shotSpeed(pull);
    return { vx: dx / len * k, vy: dy / len * k, pull };
  }

  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      if(packet) return;
      anchor = { x: p.x, y: p.y };
      aim = { x: p.x, y: p.y };
      aiming = true;
    },
    onMove(p){ if(aiming) aim = { x: p.x, y: p.y }; },
    onUp(p){
      if(!aiming) return;
      aiming = false;
      const s = pullFrom(p);
      if(s) fire(s.vx, s.vy);
    }
  });

  gTimer = setInterval(() => {
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = `${Math.max(0, time) / Math.round(75 * getTimeModifier()) * 100}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end();
  }, 1000);

  // One collision pass, run per PHYSICS SUBSTEP rather than per frame. At full
  // power the packet covers 34px in a stalled 50ms frame — wider than the 20px
  // firewall — so a frame-sized step let shots pass straight THROUGH the slab
  // and skim past a relay without either registering. Both failures are
  // invisible; both read as the physics being arbitrary.
  function resolve(){
    let done = null;
    for(const rl of relays){
      const by = rl.y + Math.sin(rl.bob) * 8;
      if(Math.hypot(packet.x - rl.x, packet.y - by) < rl.r + 10){ done = 'hit'; break; }
    }
    if(!done && packet.x > barrier.x && packet.x < barrier.x + barrier.w &&
       packet.y > GROUND - barrier.h) done = 'wall';
    if(!done && (packet.y > GROUND || packet.x > W + 60 || packet.x < -60 || packet.t > 9)) done = 'miss';
    if(!done) return;

    if(done === 'hit'){
      const rl = relays[0];
      sunk++; streak++;
      bestStreak = Math.max(bestStreak, streak);
      // Distance is the skill, so distance is the pay. Plus a streak bonus,
      // because the second consecutive hit is the one that proves the first
      // was not luck.
      const dist = Math.round((rl.x - PAD_X) / 10);
      const gain = 40 + dist * 2 + Math.min(80, (streak - 1) * 20);
      score += gain;
      setLive(Math.min(1000, score));
      snd('correct', { semi: Math.min(14, streak * 2) });
      shake = 8;
      for(let i = 0; i < 26; i++) sparks.push({
        x: rl.x, y: rl.y, vx: (Math.random() - 0.5) * 320, vy: (Math.random() - 0.5) * 320,
        life: 0.6, color: '#39ff88'
      });
      pops.push({ x: rl.x, y: rl.y - 34, text: `UPLINK +${gain}`, color: '#39ff88', life: 1 });
      ghost = null;                              // new field, old line is moot
      packet = null;
      newField();
    }else{
      streak = 0;
      snd(done === 'wall' ? 'shieldHit' : 'wrong');
      shake = done === 'wall' ? 5 : 2;
      for(let i = 0; i < 12; i++) sparks.push({
        x: packet.x, y: Math.min(packet.y, GROUND), vx: (Math.random() - 0.5) * 180,
        vy: -Math.random() * 180, life: 0.45, color: done === 'wall' ? '#ff2442' : '#5a6cff'
      });
      // The line the last shot took, kept on screen until the next one. A miss
      // you cannot see is a miss you cannot correct: the field does not change
      // until you land it, so the ghost turns the next attempt into an
      // adjustment rather than another guess.
      ghost = packet.trail.slice();
      packet = null;
    }
  }

  let last = performance.now();
  function loop(now){
    if(over) return;
    gameLoopId = requestAnimationFrame(loop);
    let dt = (now - last) / 1000; last = now;
    if(!(dt > 0)) dt = 1 / 60;
    if(dt > 0.05) dt = 0.05;

    for(const rl of relays) rl.bob += dt * 1.6;

    // ── PHYSICS ──
    if(packet){
      const steps = Math.max(1, Math.ceil(dt / 0.006));
      const sdt = dt / steps;
      for(let s = 0; s < steps && packet; s++){
        packet.t += sdt;
        packet.vy += G * sdt;
        packet.vx += wind * sdt;
        packet.x += packet.vx * sdt;
        packet.y += packet.vy * sdt;
        resolve();
      }
      if(packet){
        packet.trail.push({ x: packet.x, y: packet.y });
        if(packet.trail.length > 90) packet.trail.shift();
      }
    }

    for(let i = sparks.length - 1; i >= 0; i--){
      const s = sparks[i];
      s.life -= dt * 1.8;
      if(s.life <= 0){ sparks.splice(i, 1); continue; }
      s.vy += G * 0.6 * dt;
      s.x += s.vx * dt; s.y += s.vy * dt;
    }
    for(let i = pops.length - 1; i >= 0; i--){
      pops[i].life -= dt * 1.4; pops[i].y -= dt * 34;
      if(pops[i].life <= 0) pops.splice(i, 1);
    }

    // ── DRAW ──
    aCtx.clearRect(0, 0, W, H);
    aCtx.save();
    if(shake > 0){
      aCtx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
      shake *= 0.86; if(shake < 0.3) shake = 0;
    }

    // Ground.
    aCtx.save();
    const gg = aCtx.createLinearGradient(0, GROUND, 0, H);
    gg.addColorStop(0, 'rgba(0,245,255,0.16)');
    gg.addColorStop(1, 'rgba(0,245,255,0.02)');
    aCtx.fillStyle = gg;
    aCtx.fillRect(0, GROUND, W, H - GROUND);
    aCtx.strokeStyle = 'rgba(0,245,255,0.55)';
    aCtx.lineWidth = 2;
    aCtx.beginPath(); aCtx.moveTo(0, GROUND); aCtx.lineTo(W, GROUND); aCtx.stroke();
    aCtx.restore();

    // Ghost of the last shot, under everything else.
    if(ghost && ghost.length > 1){
      aCtx.save();
      aCtx.strokeStyle = 'rgba(255,255,255,0.16)';
      aCtx.lineWidth = 2;
      aCtx.setLineDash([5, 7]);
      aCtx.beginPath();
      ghost.forEach((p, i) => i ? aCtx.lineTo(p.x, p.y) : aCtx.moveTo(p.x, p.y));
      aCtx.stroke();
      aCtx.restore();
    }

    // Firewall slab.
    aCtx.save();
    aCtx.shadowBlur = 14; aCtx.shadowColor = '#ff2442';
    aCtx.fillStyle = 'rgba(255,36,66,0.22)';
    aCtx.strokeStyle = '#ff2442';
    aCtx.lineWidth = 2;
    aCtx.beginPath();
    aCtx.roundRect(barrier.x, GROUND - barrier.h, barrier.w, barrier.h, 4);
    aCtx.fill(); aCtx.stroke();
    aCtx.restore();

    // Relay.
    for(const rl of relays){
      const by = rl.y + Math.sin(rl.bob) * 8;
      aCtx.save();
      aCtx.shadowBlur = 20; aCtx.shadowColor = '#39ff88';
      aCtx.strokeStyle = '#39ff88';
      aCtx.lineWidth = 3;
      aCtx.beginPath(); aCtx.arc(rl.x, by, rl.r, 0, Math.PI * 2); aCtx.stroke();
      aCtx.fillStyle = 'rgba(57,255,136,0.18)';
      aCtx.fill();
      aCtx.beginPath(); aCtx.arc(rl.x, by, rl.r * 0.34, 0, Math.PI * 2);
      aCtx.fillStyle = '#39ff88'; aCtx.fill();
      // Mast down to the ground, so the relay reads as standing there rather
      // than as floating in an unexplained way.
      aCtx.shadowBlur = 0;
      aCtx.strokeStyle = 'rgba(57,255,136,0.28)';
      aCtx.lineWidth = 2;
      aCtx.setLineDash([4, 6]);
      aCtx.beginPath(); aCtx.moveTo(rl.x, by + rl.r); aCtx.lineTo(rl.x, GROUND); aCtx.stroke();
      aCtx.restore();
    }

    // Launcher.
    const mine = getEquippedColorHex();
    aCtx.save();
    aCtx.shadowBlur = 14; aCtx.shadowColor = mine;
    aCtx.fillStyle = mine;
    aCtx.beginPath(); aCtx.roundRect(PAD_X - 20, PAD_Y - 8, 40, 16, 5); aCtx.fill();
    aCtx.beginPath(); aCtx.arc(PAD_X, PAD_Y - 12, 7, 0, Math.PI * 2); aCtx.fill();
    aCtx.restore();
    drawSkinBadge(PAD_X, PAD_Y - 32, 12);

    // ── THE AIM ──
    // The whole arc, fading out along its length. The first build drew two
    // thirds of a second of flight on the theory that showing the answer left
    // nothing to judge — but with the launcher pinned to one corner and the
    // relay half a board away, a third of a parabola is not a read, it is a
    // guess, and the mission played as though the physics were random. The
    // fade keeps the judgement where it belongs: the near half is exact, the
    // far end is a suggestion, and the wind still has to be allowed for.
    if(aiming && !packet && anchor){
      const s = pullFrom(aim);
      if(s){
        let px = PAD_X, py = PAD_Y - 12, pvx = s.vx, pvy = s.vy;
        const step = 0.022;
        aCtx.save();
        for(let i = 0; i < 110; i++){
          pvy += G * step; pvx += wind * step;
          px += pvx * step; py += pvy * step;
          if(py > GROUND || px > W + 20 || px < -20) break;
          if(px > barrier.x && px < barrier.x + barrier.w && py > GROUND - barrier.h) break;
          const fade = Math.max(0.06, 1 - i / 90);
          aCtx.globalAlpha = fade * (0.35 + (s.pull / MAX_PULL) * 0.45);
          aCtx.fillStyle = '#ffffff';
          aCtx.beginPath(); aCtx.arc(px, py, 1.4 + fade * 1.6, 0, Math.PI * 2); aCtx.fill();
        }
        aCtx.restore();

        // ── THE BAND ──
        // Drawn at the anchor rather than at the dish, because the anchor is
        // where the hand is and the hand is what needs the feedback. It is the
        // only thing on screen that says the sling is relative.
        const pw = s.pull / MAX_PULL;
        aCtx.save();
        aCtx.strokeStyle = pw > 0.86 ? '#ff2442' : mine;
        aCtx.lineWidth = 2;
        aCtx.globalAlpha = 0.75;
        aCtx.beginPath(); aCtx.moveTo(anchor.x, anchor.y); aCtx.lineTo(aim.x, aim.y); aCtx.stroke();
        aCtx.globalAlpha = 1;
        aCtx.fillStyle = 'rgba(255,255,255,0.16)';
        aCtx.beginPath(); aCtx.arc(anchor.x, anchor.y, 7, 0, Math.PI * 2); aCtx.fill();
        // Above the thumb, unless the thumb is at the top of the board — then
        // below it, so the readout is never drawn off the field.
        const flip = anchor.y < 46;
        const by2 = flip ? anchor.y + 22 : anchor.y - 26;
        aCtx.fillStyle = 'rgba(255,255,255,0.14)';
        aCtx.fillRect(anchor.x - 26, by2, 52, 6);
        aCtx.fillStyle = pw > 0.86 ? '#ff2442' : mine;
        aCtx.fillRect(anchor.x - 26, by2, 52 * pw, 6);
        aCtx.textAlign = 'center';
        aCtx.font = 'bold 11px Orbitron,monospace';
        aCtx.fillStyle = 'rgba(255,255,255,0.8)';
        aCtx.fillText(`${Math.round(pw * 100)}%`, anchor.x, flip ? by2 + 18 : by2 - 6);
        aCtx.restore();
      }
    }

    // Packet + wake.
    if(packet){
      aCtx.save();
      aCtx.strokeStyle = 'rgba(255,255,255,0.28)';
      aCtx.lineWidth = 2;
      aCtx.beginPath();
      packet.trail.forEach((p, i) => i ? aCtx.lineTo(p.x, p.y) : aCtx.moveTo(p.x, p.y));
      aCtx.stroke();
      aCtx.shadowBlur = 16; aCtx.shadowColor = mine;
      aCtx.fillStyle = '#fff';
      aCtx.beginPath(); aCtx.arc(packet.x, packet.y, 6, 0, Math.PI * 2); aCtx.fill();
      aCtx.restore();
    }

    for(const s of sparks){
      aCtx.save();
      aCtx.globalAlpha = Math.max(0, s.life * 1.6);
      aCtx.fillStyle = s.color;
      aCtx.fillRect(s.x - 2, s.y - 2, 4, 4);
      aCtx.restore();
    }
    for(const p of pops){
      aCtx.save();
      aCtx.globalAlpha = Math.min(1, p.life * 1.5);
      aCtx.textAlign = 'center';
      aCtx.font = '900 15px Orbitron,monospace';
      aCtx.fillStyle = p.color;
      aCtx.shadowBlur = 10; aCtx.shadowColor = p.color;
      aCtx.fillText(p.text, p.x, p.y);
      aCtx.restore();
    }

    // Wind readout — a shot cannot be aimed without it, so it is never subtle.
    if(wind){
      aCtx.save();
      aCtx.textAlign = 'center';
      aCtx.font = 'bold 11px Orbitron,monospace';
      aCtx.fillStyle = 'rgba(255,255,255,0.55)';
      const arrows = '▶'.repeat(Math.min(4, Math.round(Math.abs(wind) / 26)));
      aCtx.fillText(wind > 0 ? `CROSSWIND ${arrows}` : `${arrows.replace(/▶/g, '◀')} CROSSWIND`, W / 2, 22);
      aCtx.restore();
    }
    if(streak >= 2){
      aCtx.save();
      aCtx.textAlign = 'right';
      aCtx.font = '900 18px Orbitron,monospace';
      aCtx.fillStyle = '#39ff88';
      aCtx.shadowBlur = 12; aCtx.shadowColor = '#39ff88';
      aCtx.fillText(`${streak}× LINKED`, W - 12, 26);
      aCtx.restore();
    }

    aCtx.restore();
  }

  function end(){
    if(over) return; over = true;
    clearCanvasDrag();
    const acc = shots ? sunk / shots : 0;
    const final = Math.min(1000, score);
    showResults('uplink', final, {
      '🛰️ Relays Linked': `${sunk}/${shots}`,
      '🎯 Link Accuracy': `${Math.round(acc * 100)}%`,
      '🔗 Longest Chain': `${bestStreak}×`,
      '🏆 Score Accumulation': `${final} PTS`
    });
  }

  gameLoopId = requestAnimationFrame(loop);
}

// ══════════════════════════════════════════════════════════════════════
//  § 9 · THE PATIENCE WING — five missions whose verb is not "react"
// ══════════════════════════════════════════════════════════════════════
// Twenty-one missions, and nineteen of them were won by being FAST. The arcade
// had no answer at all for a player who wants to think, and no mission whose
// difficulty could rise without the board simply moving quicker — which is the
// one lever that eventually makes a game unreadable rather than harder.
//
// So: a stealth run whose verb is waiting, a triage floor that escalates by
// changing the RULE instead of the speed, a pure deduction puzzle with no
// reflex component at all, a sweep scored on a curve rather than won or lost,
// and one genuine physics mission with mass and inertia.
//
// Every one of them honours the funnels rather than reimplementing them: input
// through boardPos() (so INVERSE CONTROLS and AXIS DRIFT work for free), live
// score through setLive() (so the pace ghost rides along), every fatal point
// through survivedFatal() (so a shield is real here), scoring only through
// showResults(), and hazards and clocks scaled by getDifficultyModifier() /
// getTimeModifier(). Each also hands its countdown to registerRoundClock(),
// which is what a Time Dilator actually adds its three seconds to.

// ════════════════════════════════════════════
//  ❄️ GAME 22: ICE CUTTER — the patrol floor
// ════════════════════════════════════════════
// A dark floor, a handful of sweeping patrol cones, and eight data nodes that
// have to be touched. The whole mission is the gap between two beams: the
// correct play is very often to STOP and let one pass, which is something no
// other mission in the arcade has ever asked for.
//
// Being lit is not instantly fatal — EXPOSURE fills while you are in a beam and
// drains while you are dark. That is the difference between a stealth game and
// a maze: a dash through the edge of a cone is a real option with a real price,
// so the player is making a trade rather than obeying a rule.
function startIceCutter(){
  document.getElementById('g-canvas-holder').style.display='block';
  setControls(null);                 // pure drag — a pad would only steal board height
  setControlHint('DRAG TO CREEP · STOP AND LET THE BEAMS PASS',
                 'MOVE THE MOUSE TO CREEP · STOP AND LET THE BEAMS PASS');
  showTouchHint('DRAG ANYWHERE TO CREEP — STAY OUT OF THE LIGHT');
  fitCanvas();

  const NEONC = getEquippedColorHex();
  const diff  = getDifficultyModifier();
  const time0 = Math.max(22, Math.round(62 * getTimeModifier()));
  const CONES = Math.min(7, 3 + Math.round((diff - 1) * 2.2));
  const NODES = 8;
  const NODE_PTS = 92, CLEAR_BONUS = 280, PER_SEC = 7;

  let time = time0, score = 0, tagged = 0, expo = 0, lit = false;
  let spotted = 0, over = false, scored = false, calm = 0, gameT = 0;
  const player = { x: BOARD_W / 2, y: BOARD_H - 42, r: 8 };

  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--cyan),#8fa6ff)';

  // ── THE FLOOR ──
  // Cones are anchored on the perimeter and sweep about a base heading that
  // points into the room. Everything about a cone's MOTION is a pure function
  // of elapsed time — nothing is rolled per frame — so the Daily Hack's seeded
  // layout plays out identically on every machine and in either renderer.
  const cones = [];
  for(let i = 0; i < CONES; i++){
    const side = i % 4;
    const t = 0.18 + Math.random() * 0.64;
    const pos = side === 0 ? [BOARD_W * t, 0]
              : side === 1 ? [BOARD_W, BOARD_H * t]
              : side === 2 ? [BOARD_W * t, BOARD_H]
                           : [0, BOARD_H * t];
    const base = side === 0 ? Math.PI / 2 : side === 1 ? Math.PI : side === 2 ? -Math.PI / 2 : 0;
    cones.push({
      x: pos[0], y: pos[1], base,
      span:  0.55 + Math.random() * 0.5,          // how far off centre it sweeps
      half:  0.26 + Math.random() * 0.10,         // the beam's own half-angle
      speed: (0.34 + Math.random() * 0.30) * diff,// radians of phase per second
      phase: Math.random() * 6.28,
      len:   250 + Math.random() * 180
    });
  }

  // Nodes are kept off the walls, off each other, and away from the start
  // corner — a node sitting under the opening position is a free point that
  // teaches nothing about the mission.
  const nodes = [];
  for(let i = 0; i < NODES; i++){
    let n = null;
    for(let tryN = 0; tryN < 60; tryN++){
      const c = { x: 46 + Math.random() * (BOARD_W - 92), y: 46 + Math.random() * (BOARD_H - 120), got: false, pulse: 0 };
      if(Math.hypot(c.x - player.x, c.y - player.y) < 90) continue;
      if(nodes.some(o => Math.hypot(o.x - c.x, o.y - c.y) < 76)) continue;
      n = c; break;
    }
    nodes.push(n || { x: 46 + (i % 4) * 150, y: 70 + Math.floor(i / 4) * 150, got: false, pulse: 0 });
  }

  const place = (x, y) => {
    player.x = Math.max(player.r, Math.min(BOARD_W - player.r, x));
    player.y = Math.max(player.r, Math.min(BOARD_H - player.r, y));
  };

  // The same per-EVENT split every drag mission uses: a mouse gets absolute
  // cursor-following, a finger gets a relative drag so the thumb is never over
  // the gap it is threading.
  let lastP = null;
  bindCanvasDrag({
    onHover(p){ if(!p.touch) place(p.x, p.y); },
    onDown(p){ hideTouchHint(); lastP = p; if(!p.touch) place(p.x, p.y); },
    onMove(p){
      if(p.touch && lastP) place(player.x + (p.x - lastP.x), player.y + (p.y - lastP.y));
      else place(p.x, p.y);
      lastP = p;
    },
    onUp(){ lastP = null; }
  });

  const aimOf = c => c.base + Math.sin(gameT * c.speed + c.phase) * c.span;
  const inCone = (c, px, py) => {
    const dx = px - c.x, dy = py - c.y;
    const d = Math.hypot(dx, dy);
    if(d > c.len || d < 1) return false;
    let a = Math.atan2(dy, dx) - aimOf(c);
    while(a >  Math.PI) a -= Math.PI * 2;
    while(a < -Math.PI) a += Math.PI * 2;
    // The beam narrows slightly with distance, which is a kindness: the far end
    // of a cone is exactly where you get the least warning.
    return Math.abs(a) < c.half * (1 - 0.18 * (d / c.len));
  };

  // ⏳ The door a Time Dilator adds three seconds through.
  registerRoundClock(n => {
    time += n;
    document.getElementById('g-time').textContent = time;
  });

  gTimer = setInterval(() => {
    if(over) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = Math.max(0, time / time0 * 100) + '%';
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  function detected(){
    // 🛡️ Every fatal point asks. A shield sweeps the exposure back to nothing
    // and buys a breath of grace rather than a single frame — an absorb that
    // leaves you standing in the same beam is an absorb that did nothing.
    if(survivedFatal()){ expo = 0; calm = 1.6; spotted++; snd('shieldHit'); return; }
    over = true;
    snd('bigExplode');
    end('spotted');
  }

  let last = performance.now();
  function loop(now){
    if(over || scored) return;
    const dt = Math.min(50, now - last); last = now;
    const sec = dt / 1000;
    gameT += sec;
    if(calm > 0) calm = Math.max(0, calm - sec);

    // ── EXPOSURE ──
    // Rates are per SECOND, never per frame: a 144Hz panel must not light you
    // up 2.4x faster than the 60Hz one this was tuned on.
    lit = calm <= 0 && cones.some(c => inCone(c, player.x, player.y));
    if(lit) expo = Math.min(1, expo + sec * (0.62 * diff));
    else    expo = Math.max(0, expo - sec * 0.42);
    if(expo >= 1) detected();

    // ── TAGGING ──
    for(const n of nodes){
      if(n.got){ n.pulse = Math.max(0, n.pulse - sec * 2); continue; }
      if(Math.hypot(n.x - player.x, n.y - player.y) < 16 + player.r){
        n.got = true; n.pulse = 1; tagged++;
        score += NODE_PTS;
        setLive(Math.min(1250, score));
        snd('node', { semi: tagged * 2 });
        if(tagged === NODES){ over = true; snd('victory'); gLater(() => end('clear'), 620); }
      }
    }

    // ── PAINT ──
    aCtx.fillStyle = '#05060f';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    aCtx.strokeStyle = 'rgba(120,160,255,0.05)';
    aCtx.lineWidth = 1;
    for(let gx = 0; gx <= BOARD_W; gx += 40){ aCtx.beginPath(); aCtx.moveTo(gx, 0); aCtx.lineTo(gx, BOARD_H); aCtx.stroke(); }
    for(let gy = 0; gy <= BOARD_H; gy += 40){ aCtx.beginPath(); aCtx.moveTo(0, gy); aCtx.lineTo(BOARD_W, gy); aCtx.stroke(); }

    // Cones, as real wedges with a falloff, so the far end reads as weaker
    // light rather than as a hard-edged triangle.
    for(const c of cones){
      const a = aimOf(c);
      const hot = inCone(c, player.x, player.y);
      const g = aCtx.createRadialGradient(c.x, c.y, 4, c.x, c.y, c.len);
      g.addColorStop(0,   hot ? 'rgba(255,80,110,0.42)' : 'rgba(160,190,255,0.30)');
      g.addColorStop(0.6, hot ? 'rgba(255,60,90,0.16)'  : 'rgba(130,165,255,0.11)');
      g.addColorStop(1,   'rgba(120,150,255,0)');
      aCtx.beginPath();
      aCtx.moveTo(c.x, c.y);
      aCtx.arc(c.x, c.y, c.len, a - c.half, a + c.half);
      aCtx.closePath();
      aCtx.fillStyle = g; aCtx.fill();
      aCtx.strokeStyle = hot ? 'rgba(255,90,120,0.55)' : 'rgba(170,200,255,0.28)';
      aCtx.lineWidth = 1.5; aCtx.stroke();
      // The emitter itself, so a beam can be seen coming FROM somewhere and
      // planned against, rather than reacted to at its edge.
      aCtx.beginPath(); aCtx.arc(c.x, c.y, 7, 0, Math.PI * 2);
      aCtx.fillStyle = hot ? '#ff2442' : '#8fa6ff';
      aCtx.shadowBlur = 14; aCtx.shadowColor = hot ? '#ff2442' : '#8fa6ff';
      aCtx.fill(); aCtx.shadowBlur = 0;
    }

    for(const n of nodes){
      aCtx.save();
      if(n.got){
        aCtx.globalAlpha = 0.35 + n.pulse * 0.5;
        aCtx.strokeStyle = '#39ff88'; aCtx.lineWidth = 2;
        aCtx.beginPath(); aCtx.arc(n.x, n.y, 11 + n.pulse * 12, 0, Math.PI * 2); aCtx.stroke();
        aCtx.fillStyle = 'rgba(57,255,136,0.22)';
        aCtx.beginPath(); aCtx.arc(n.x, n.y, 9, 0, Math.PI * 2); aCtx.fill();
      }else{
        const pulse = 0.65 + 0.35 * Math.sin(gameT * 3 + n.x);
        aCtx.shadowBlur = 16 * pulse; aCtx.shadowColor = NEONC;
        aCtx.strokeStyle = NEONC; aCtx.lineWidth = 2.5;
        aCtx.beginPath(); aCtx.arc(n.x, n.y, 12, 0, Math.PI * 2); aCtx.stroke();
        aCtx.globalAlpha = 0.35 * pulse;
        aCtx.fillStyle = NEONC;
        aCtx.beginPath(); aCtx.arc(n.x, n.y, 6, 0, Math.PI * 2); aCtx.fill();
      }
      aCtx.restore();
    }

    aCtx.save();
    const glow = lit ? '#ff2442' : NEONC;
    aCtx.shadowBlur = lit ? 26 : 14; aCtx.shadowColor = glow;
    aCtx.beginPath(); aCtx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
    aCtx.fillStyle = glow; aCtx.fill();
    aCtx.shadowBlur = 4; aCtx.shadowColor = '#fff';
    aCtx.strokeStyle = '#fff'; aCtx.lineWidth = 2; aCtx.stroke();
    if(calm > 0){
      aCtx.globalAlpha = 0.35 + 0.35 * Math.sin(gameT * 18);
      aCtx.strokeStyle = '#39ff88'; aCtx.lineWidth = 2;
      aCtx.beginPath(); aCtx.arc(player.x, player.y, player.r + 7, 0, Math.PI * 2); aCtx.stroke();
    }
    aCtx.restore();
    drawSkinBadge(player.x, player.y - player.r - 10);

    // ── EXPOSURE METER ──
    // Over the floor rather than in the shared stat strip: it is the one number
    // that changes what you do THIS second, and it has to be readable without
    // taking your eyes off the beam that is causing it.
    const mw = 168, mx = 14, my = 14;
    aCtx.fillStyle = 'rgba(6,10,22,0.82)';
    aCtx.fillRect(mx - 4, my - 4, mw + 8, 26);
    aCtx.strokeStyle = expo > 0.62 ? '#ff2442' : 'rgba(140,170,255,0.4)';
    aCtx.lineWidth = 1.5;
    aCtx.strokeRect(mx - 4, my - 4, mw + 8, 26);
    aCtx.fillStyle = expo > 0.62 ? '#ff2442' : expo > 0.3 ? '#ffd700' : '#39ff88';
    aCtx.fillRect(mx, my + 8, mw * expo, 10);
    aCtx.font = '700 10px Orbitron,monospace';
    aCtx.fillStyle = '#cfe4ff';
    aCtx.fillText(lit ? 'EXPOSURE — IN THE BEAM' : 'EXPOSURE', mx, my + 4);
    aCtx.font = '900 13px Orbitron,monospace';
    aCtx.textAlign = 'right';
    aCtx.fillText(tagged + '/' + NODES + ' TAGGED', BOARD_W - 14, my + 14);
    aCtx.textAlign = 'left';

    gameLoopId = requestAnimationFrame(loop);
  }
  gameLoopId = requestAnimationFrame(loop);

  function end(reason){
    if(scored) return; scored = true; over = true;
    clearInterval(gTimer); gTimer = null;
    clearCanvasDrag();
    const cleared = reason === 'clear';
    const left = Math.max(0, time);
    const final = Math.min(1250, score + (cleared ? CLEAR_BONUS + left * PER_SEC : 0));
    showResults('cutter', final, {
      '❄️ Entry Status': cleared ? 'FLOOR CLEARED — NEVER BURNED'
                       : reason === 'spotted' ? 'BURNED — PATROL LOCK' : 'EXTRACTED ON THE CLOCK',
      '📍 Nodes Tagged': tagged + ' / ' + NODES,
      '🔦 Patrol Cones': CONES,
      ...(spotted ? { '🛡️ Detections Absorbed': spotted } : {}),
      ...(cleared ? { '⏱️ Time To Spare': left + 's' } : {}),
      '🏆 Score Accumulation': final + ' PTS'
    }, cleared ? undefined : { sound: 'gameOver' });
  }
}

// ════════════════════════════════════════════
//  🗂️ GAME 23: PACKET SORT — the triage floor
// ════════════════════════════════════════════
// Packets ride four conveyors toward four ports. Each packet carries a COLOUR
// and a SHAPE; each port has a colour and a shape too, and the two are
// deliberately different permutations — so "which port?" always has two
// plausible answers and the RULE is what picks between them.
//
// The rule flips every twenty seconds. That is the entire difficulty curve:
// nothing ever gets faster and nothing ever gets denser. What changes is what
// you have to hold in your head, and the POOL the flip draws from grows as the
// shift goes on. A mission that escalates by speed eventually becomes
// unreadable rather than harder; one that escalates by rule stays legible and
// gets harder anyway, which is a far better shape for a triage fantasy.
const SORT_COLS   = ['#00f5ff', '#ff0090', '#39ff14', '#ffd700'];
const SORT_SHAPES = ['circle', 'square', 'triangle', 'diamond'];
const SORT_RULES = [
  { id:'col', name:'MATCH COLOUR',
    hint:'Send each packet to the port of its own COLOUR.',
    port:(p, ports) => ports.findIndex(q => q.col === p.col) },
  { id:'shp', name:'MATCH SHAPE',
    hint:'Ignore colour entirely. Send each packet to the port of its own SHAPE.',
    port:(p, ports) => ports.findIndex(q => q.shape === p.shape) },
  { id:'mir', name:'MIRROR THE COLOUR',
    hint:'Find its colour port — then send it to the port OPPOSITE that one.',
    port:(p, ports) => 3 - ports.findIndex(q => q.col === p.col) },
  { id:'shf', name:'SHIFT ONE RIGHT',
    hint:'Find its SHAPE port — then send it one port to the RIGHT, wrapping.',
    port:(p, ports) => (ports.findIndex(q => q.shape === p.shape) + 1) % 4 }
];

// One glyph vocabulary, shared by the packets and by the ports that accept
// them — a port has to be recognisable as "the square one" at a glance.
function sortDrawGlyph(ctx, shape, x, y, r, fill, stroke){
  ctx.beginPath();
  if(shape === 'circle') ctx.arc(x, y, r, 0, Math.PI * 2);
  else if(shape === 'square') ctx.rect(x - r * 0.86, y - r * 0.86, r * 1.72, r * 1.72);
  else if(shape === 'triangle'){
    ctx.moveTo(x, y - r); ctx.lineTo(x + r * 0.92, y + r * 0.72); ctx.lineTo(x - r * 0.92, y + r * 0.72); ctx.closePath();
  }else{
    ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
  }
  if(fill){ ctx.fillStyle = fill; ctx.fill(); }
  if(stroke){ ctx.strokeStyle = stroke; ctx.lineWidth = 2; ctx.stroke(); }
}

// Two independent permutations of four, with the pairs that would make two
// rules identical rejected. A port whose colour and shape line up quietly
// removes the whole point of the flip.
function sortBuildPorts(laneX){
  const perm = a => {
    const b = a.slice();
    for(let i = b.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); const t = b[i]; b[i] = b[j]; b[j] = t; }
    return b;
  };
  const pc = perm(SORT_COLS);
  let ps = perm(SORT_SHAPES);
  const clash = () => pc.some((c, i) => SORT_COLS.indexOf(c) === SORT_SHAPES.indexOf(ps[i]));
  for(let g = 0; g < 40 && clash(); g++) ps = perm(SORT_SHAPES);
  return pc.map((c, i) => ({ col: c, shape: ps[i], x: laneX[i], flash: 0 }));
}

// The feed and the rule schedule, generated in FULL before the first frame —
// so a Daily Hack deals the identical packets in the identical order on every
// machine and in either renderer. Nothing here is rolled during play.
function sortBuildFeed(seconds, diff){
  const GAP = 1.15 / Math.max(0.6, diff * 0.85);
  const feed = [];
  for(let t = 1.2, i = 0; t < seconds + 4; t += GAP * (0.75 + Math.random() * 0.6), i++){
    feed.push({
      at: t,
      lane: Math.floor(Math.random() * 4),
      col: SORT_COLS[Math.floor(Math.random() * 4)],
      shape: SORT_SHAPES[Math.floor(Math.random() * 4)],
      id: i
    });
  }
  // The POOL grows: the opening stretch only ever draws the two simple rules,
  // so the floor is learned before the floor starts arguing back.
  const schedule = [0];
  for(let k = 1; k < 48; k++){
    const poolN = k < 2 ? 2 : k < 4 ? 3 : 4;
    let n = Math.floor(Math.random() * poolN);
    if(n === schedule[k - 1]) n = (n + 1) % poolN;   // never "flip" to the rule already running
    schedule.push(n);
  }
  return { feed, schedule };
}

function startPacketSort(){
  // 🗂️ The console goes up BEFORE fitCanvas() measures the board. A panel that
  // appears afterwards steals height the board was already sized into — the
  // same contract the Battle Bots deck and the Frequency Modulator's sliders
  // are under, and fitCanvas() measures all four by id.
  const strip = document.getElementById('g-sort-rule');
  strip.style.display = 'flex';
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls(null);
  setControlHint('DRAG A PACKET DOWN INTO A PORT',
                 'DRAG A PACKET INTO A PORT · KEYS 1-4 SEND THE LOWEST PACKET');
  showTouchHint('DRAG A PACKET DOWN INTO A PORT');
  fitCanvas();

  const diff  = getDifficultyModifier();
  const time0 = Math.max(40, Math.round(105 * getTimeModifier()));
  const RULE_MS = 20000;
  const FEED_TOP = 54, DROP_Y = 372, PORT_Y = 418, PORT_H = 62;
  const LANE_X = [86, 202, 318, 434], HIT = 120;

  let time = time0, score = 0, sorted = 0, wrong = 0, missed = 0, streak = 0, bestStreak = 0;
  let integrity = 5, ruleIdx = 0, flips = 0, absorbed = 0;
  let over = false, scored = false, flash = 0, gameT = 0, ruleT = 0, nextIdx = 0;

  const ports = sortBuildPorts(LANE_X);
  const built = sortBuildFeed(time0, diff);
  const feed = built.feed, schedule = built.schedule;
  const live = [];

  function paintRule(pulse){
    const R = SORT_RULES[ruleIdx];
    document.getElementById('sr-tag').textContent = 'RULE ' + (flips + 1);
    document.getElementById('sr-txt').textContent = R.name;
    const left = Math.max(0, Math.ceil((RULE_MS - ruleT * 1000) / 1000));
    document.getElementById('sr-next').textContent = 'FLIP IN ' + left + 's';
    strip.classList.toggle('warn', left <= 3);
    if(pulse){
      strip.classList.add('flip');
      gLater(() => strip.classList.remove('flip'), 900);
    }
  }
  paintRule(false);

  registerRoundClock(n => {
    time += n;
    document.getElementById('g-time').textContent = time;
  });

  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--orange),var(--gold))';
  gTimer = setInterval(() => {
    if(over) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = Math.max(0, time / time0 * 100) + '%';
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  function damage(why){
    integrity--;
    streak = 0;
    flash = 1;
    snd('wrong');
    if(integrity > 0) return;
    // 🛡️ The floor collapsing is this mission's fatal point, so it asks.
    if(survivedFatal()){ integrity = 2; absorbed++; return; }
    over = true;
    snd('bigExplode');
    end(why);
  }

  function deliver(pkt, portIdx){
    const want = SORT_RULES[ruleIdx].port(pkt, ports);
    ports[portIdx].flash = 1;
    const i = live.indexOf(pkt);
    if(i >= 0) live.splice(i, 1);
    if(portIdx === want){
      sorted++; streak++;
      bestStreak = Math.max(bestStreak, streak);
      // Tuned down from 62+6/link: a shift deals seventy-odd packets, so the old
      // rate put the 1,150 cap on the board inside twenty-five seconds and the
      // rest of the shift paid nothing. At 30+3 the cap lands around thirty
      // clean packets — which, with five integrity and a rule flip every twenty
      // seconds, is a shift you have to survive rather than one you outlast.
      score += 30 + Math.min(36, streak * 3);
      setLive(Math.min(1150, score));
      snd('coin', { semi: Math.min(14, streak) });
    }else{
      wrong++;
      damage('overrun');
    }
  }

  let held = null;
  const grab = p => {
    let best = null, bd = HIT;
    for(const pkt of live){
      const d = Math.hypot(pkt.x - p.x, pkt.y - p.y);
      if(d < bd){ bd = d; best = pkt; }
    }
    return best;
  };
  const portAt = p => {
    if(p.y < PORT_Y - 16) return -1;
    for(let i = 0; i < 4; i++) if(Math.abs(p.x - ports[i].x) < 58) return i;
    return -1;
  };

  bindCanvasDrag({
    onDown(p){ hideTouchHint(); held = grab(p); if(held) held.grabbed = true; },
    onMove(p){ if(held){ held.x = p.x; held.y = p.y; } },
    onUp(p){
      if(!held) return;
      const idx = portAt(p);
      if(idx >= 0) deliver(held, idx);
      else held.grabbed = false;
      held = null;
    }
  });

  // Keys 1-4 send the LOWEST packet — the one about to be lost. Same decision
  // the finger is making, offered to a keyboard without asking it to aim.
  window.onkeydown = e => {
    if(over || e.ctrlKey || e.metaKey) return;
    const n = '1234'.indexOf(e.key);
    if(n < 0) return;
    e.preventDefault();
    let low = null;
    for(const pkt of live) if(!low || pkt.y > low.y) low = pkt;
    if(low) deliver(low, n);
  };

  const FALL = 46;                     // board units per second — constant, by design
  let last = performance.now();
  function loop(now){
    if(over || scored) return;
    const dt = Math.min(50, now - last); last = now;
    const sec = dt / 1000;
    gameT += sec; ruleT += sec;
    if(flash > 0) flash = Math.max(0, flash - sec * 2);

    if(ruleT * 1000 >= RULE_MS){
      ruleT = 0; flips++;
      ruleIdx = schedule[flips % schedule.length];
      snd('alarm');
      toast('🗂️ SORT RULE ' + (flips + 1) + ' — ' + SORT_RULES[ruleIdx].name + ' · ' + SORT_RULES[ruleIdx].hint, 3200);
      paintRule(true);
    }else{
      paintRule(false);
    }

    while(nextIdx < feed.length && feed[nextIdx].at <= gameT){
      const f = feed[nextIdx++];
      live.push({ lane: f.lane, col: f.col, shape: f.shape, id: f.id, x: LANE_X[f.lane], y: FEED_TOP, grabbed: false });
    }

    for(let i = live.length - 1; i >= 0; i--){
      const pkt = live[i];
      if(pkt.grabbed) continue;
      pkt.y += FALL * sec;
      if(pkt.y > DROP_Y){
        live.splice(i, 1);
        missed++;
        damage('overrun');
      }
    }

    // ── PAINT ──
    aCtx.fillStyle = '#0a0a18';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    if(flash > 0){
      aCtx.fillStyle = 'rgba(255,36,66,' + (0.18 * flash).toFixed(3) + ')';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    }

    // Conveyors — travelling chevrons, so a belt reads as running even when it
    // happens to be empty.
    for(let l = 0; l < 4; l++){
      const x = LANE_X[l];
      aCtx.fillStyle = 'rgba(255,255,255,0.03)';
      aCtx.fillRect(x - 46, FEED_TOP - 20, 92, DROP_Y - FEED_TOP + 24);
      aCtx.strokeStyle = 'rgba(255,255,255,0.07)';
      aCtx.lineWidth = 1;
      aCtx.strokeRect(x - 46, FEED_TOP - 20, 92, DROP_Y - FEED_TOP + 24);
      aCtx.strokeStyle = 'rgba(255,255,255,0.10)';
      aCtx.lineWidth = 2;
      for(let y = FEED_TOP - 20 + ((gameT * FALL) % 26); y < DROP_Y + 4; y += 26){
        aCtx.beginPath();
        aCtx.moveTo(x - 16, y - 6); aCtx.lineTo(x, y); aCtx.lineTo(x + 16, y - 6);
        aCtx.stroke();
      }
    }

    // The drop line. Below it, a packet is gone.
    aCtx.setLineDash([7, 6]);
    aCtx.strokeStyle = 'rgba(255,102,0,0.55)';
    aCtx.lineWidth = 2;
    aCtx.beginPath(); aCtx.moveTo(0, DROP_Y); aCtx.lineTo(BOARD_W, DROP_Y); aCtx.stroke();
    aCtx.setLineDash([]);

    for(let i = 0; i < 4; i++){
      const q = ports[i];
      q.flash = Math.max(0, q.flash - sec * 2.4);
      aCtx.save();
      aCtx.globalAlpha = 0.16 + q.flash * 0.5;
      aCtx.fillStyle = q.col;
      aCtx.fillRect(q.x - 56, PORT_Y, 112, PORT_H);
      aCtx.restore();
      aCtx.strokeStyle = q.col;
      aCtx.lineWidth = 2 + q.flash * 2;
      aCtx.shadowBlur = 12 + q.flash * 18; aCtx.shadowColor = q.col;
      aCtx.strokeRect(q.x - 56, PORT_Y, 112, PORT_H);
      aCtx.shadowBlur = 0;
      sortDrawGlyph(aCtx, q.shape, q.x, PORT_Y + PORT_H / 2 + 2, 15, null, q.col);
      aCtx.font = '700 9px Orbitron,monospace';
      aCtx.fillStyle = 'rgba(255,255,255,0.55)';
      aCtx.textAlign = 'center';
      aCtx.fillText(String(i + 1), q.x, PORT_Y + 13);
      aCtx.textAlign = 'left';
    }

    // Packets. The held one paints last, so it is never buried under another.
    const paint = pkt => {
      aCtx.save();
      aCtx.shadowBlur = pkt.grabbed ? 24 : 12; aCtx.shadowColor = pkt.col;
      sortDrawGlyph(aCtx, pkt.shape, pkt.x, pkt.y, pkt.grabbed ? 19 : 16, pkt.col, '#ffffff');
      aCtx.restore();
    };
    for(const pkt of live) if(!pkt.grabbed) paint(pkt);
    for(const pkt of live) if(pkt.grabbed) paint(pkt);

    aCtx.font = '900 12px Orbitron,monospace';
    aCtx.fillStyle = '#cfe4ff';
    aCtx.fillText('FLOOR', 14, 24);
    for(let i = 0; i < 5; i++){
      aCtx.fillStyle = i < integrity ? (integrity <= 2 ? '#ff2442' : '#39ff88') : 'rgba(255,255,255,0.12)';
      aCtx.fillRect(64 + i * 15, 14, 11, 11);
    }
    aCtx.fillStyle = '#cfe4ff';
    aCtx.textAlign = 'right';
    aCtx.fillText(sorted + ' SORTED' + (streak > 1 ? '  ·  ' + streak + '× CHAIN' : ''), BOARD_W - 14, 24);
    aCtx.textAlign = 'left';

    gameLoopId = requestAnimationFrame(loop);
  }
  gameLoopId = requestAnimationFrame(loop);

  function end(reason){
    if(scored) return; scored = true; over = true;
    clearInterval(gTimer); gTimer = null;
    clearCanvasDrag();
    strip.classList.remove('flip', 'warn');
    strip.style.display = 'none';
    const handled = sorted + wrong + missed;
    const acc = handled ? sorted / handled : 0;
    const final = Math.min(1150, score + Math.round(acc * 180) + flips * 24);
    showResults('sorter', final, {
      '🗂️ Floor Status': reason === 'overrun' ? 'FLOOR OVERRUN' : 'SHIFT COMPLETE',
      '✅ Packets Routed': sorted,
      '🎯 Routing Accuracy': Math.round(acc * 100) + '%',
      '🔁 Rule Changes Survived': flips,
      '🔗 Longest Chain': bestStreak + '×',
      ...(absorbed ? { '🛡️ Collapses Absorbed': absorbed } : {}),
      '🏆 Score Accumulation': final + ' PTS'
    }, reason === 'overrun' ? { sound: 'gameOver' } : undefined);
  }
}

// ════════════════════════════════════════════
//  📡 GAME 24: SIGNAL TRACE — the cipher bench
// ════════════════════════════════════════════
// Mastermind on a four-slot cipher. No clock pressure inside a guess, no
// reflex component anywhere, and every control is a large target in the bottom
// half of the board — this is the one mission in the arcade that is genuinely
// playable one-handed on a phone, held in the hand you are not using for
// anything else.
//
// Symbols carry a COLOUR and a SHAPE together rather than a colour alone. Six
// flat colours at phone size are hard to tell apart under a neon grade and
// impossible for a colour-blind player; a cyan circle and a gold diamond are
// two facts about the same token, and either one is enough to read it.
const TRACE_SYMS = [
  { col:'#00f5ff', shape:'circle'   },
  { col:'#ff0090', shape:'square'   },
  { col:'#39ff14', shape:'triangle' },
  { col:'#ffd700', shape:'diamond'  },
  { col:'#a855f7', shape:'circle'   },
  { col:'#ff6600', shape:'square'   },
  { col:'#ff2442', shape:'triangle' }
];

// Exact = right symbol, right slot. Present = right symbol, wrong slot. Counted
// with the standard two-pass tally, because the naive version double-counts a
// repeated symbol and turns a deduction puzzle into a guessing one.
function tracePegs(guess, code){
  let exact = 0, present = 0;
  const gl = guess.slice(), cl = code.slice();
  for(let i = 0; i < gl.length; i++) if(gl[i] === cl[i]){ exact++; gl[i] = -1; cl[i] = -2; }
  for(let i = 0; i < gl.length; i++){
    if(gl[i] < 0) continue;
    const j = cl.indexOf(gl[i]);
    if(j >= 0){ present++; cl[j] = -2; }
  }
  return { exact, present };
}

function startSignalTrace(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls(null);
  setControlHint('TAP A SYMBOL TO PLACE IT · TAP A SLOT TO CLEAR IT',
                 'TAP OR PRESS 1-7 TO PLACE · BACKSPACE CLEARS · ENTER PROBES');
  showTouchHint('TAP SYMBOLS TO BUILD A PROBE, THEN TAP SEND');
  fitCanvas();

  const diff  = getDifficultyModifier();
  const time0 = Math.max(55, Math.round(150 * getTimeModifier()));
  const SLOTS = 4;
  const SOLVE_BASE = 210, PEG_PTS = 9;

  let time = time0, score = 0, cracked = 0, probes = 0, over = false, scored = false;
  let symCount = 6, attempts = 0, maxTry = 8, pulse = 0, shake = 0, winFlash = 0;
  let code = [], entry = [], history = [];

  // ── LAYOUT ──
  // Everything the thumb has to reach lives below HAND_Y. The history above it
  // is read, never touched.
  const HAND_Y = 300;
  const PAL_Y = HAND_Y + 96, PAL_R = 25;
  const ENTRY_Y = HAND_Y + 34, ENTRY_R = 25;
  const palX = i => 48 + i * ((BOARD_W - 96) / Math.max(1, symCount - 1));
  const slotX = i => BOARD_W / 2 - (SLOTS - 1) * 33 + i * 66;
  const SEND = { x: BOARD_W - 78, y: PAL_Y + 62, w: 128, h: 40 };
  const CLR  = { x: 78,           y: PAL_Y + 62, w: 118, h: 40 };

  function newCipher(){
    // Repeats are allowed and are the whole difficulty of the later ciphers —
    // the peg tally above is what makes them fair rather than cruel.
    code = [];
    for(let i = 0; i < SLOTS; i++) code.push(Math.floor(Math.random() * symCount));
    entry = [];
    history = [];
    attempts = 0;
  }
  newCipher();

  registerRoundClock(n => {
    time += n;
    document.getElementById('g-time').textContent = time;
  });

  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--lime),var(--cyan))';
  gTimer = setInterval(() => {
    if(over) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = Math.max(0, time / time0 * 100) + '%';
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  function place(sym){
    if(over || entry.length >= SLOTS) return;
    entry.push(sym);
    pulse = 1;
    snd('node', { semi: sym * 2 });
  }
  function clearSlot(i){
    if(over) return;
    if(i == null) entry = [];
    else if(i < entry.length) entry.splice(i, 1);
    snd('move');
  }
  function probe(){
    if(over || entry.length < SLOTS) return;
    const pegs = tracePegs(entry, code);
    history.push({ g: entry.slice(), exact: pegs.exact, present: pegs.present });
    attempts++; probes++;
    entry = [];
    // Partial credit is the whole reason this scores on a curve: a cipher you
    // ran out of attempts on still narrowed, and the narrowing was the work.
    score += pegs.exact * PEG_PTS * 2 + pegs.present * PEG_PTS;
    setLive(Math.min(900, score));
    if(pegs.exact === SLOTS){
      cracked++;
      winFlash = 1;
      const left = maxTry - attempts;
      score += SOLVE_BASE + left * 26;
      setLive(Math.min(900, score));
      snd('victory');
      // Each crack widens the alphabet, up to the table's length. That is the
      // escalation: the board never moves faster, the space just gets bigger.
      symCount = Math.min(TRACE_SYMS.length, symCount + (cracked % 2 === 0 ? 1 : 0));
      gLater(() => { if(!over){ newCipher(); } }, 700);
      return;
    }
    snd(pegs.exact ? 'correct' : 'wrong');
    if(attempts >= maxTry){
      // A burned cipher is not the end of the round — it costs the SOLVE bonus
      // and hands over a fresh one. Ending the mission on a failed deduction
      // would make a wrong guess feel like a crash, which is the opposite of
      // what a deduction puzzle wants.
      shake = 1;
      snd('error');
      toast('📡 CIPHER BURNED — the trace resets. Pegs you found still paid.', 3000);
      gLater(() => { if(!over) newCipher(); }, 700);
    }
  }

  // ── INPUT ── everything through boardPos(), via bindCanvasDrag.
  const hitBox = (b, p) => Math.abs(p.x - b.x) < b.w / 2 && Math.abs(p.y - b.y) < b.h / 2;
  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      if(over) return;
      if(hitBox(SEND, p)) return probe();
      if(hitBox(CLR, p))  return clearSlot(null);
      for(let i = 0; i < symCount; i++){
        if(Math.hypot(p.x - palX(i), p.y - PAL_Y) < PAL_R + 14) return place(i);
      }
      for(let i = 0; i < SLOTS; i++){
        if(Math.hypot(p.x - slotX(i), p.y - ENTRY_Y) < ENTRY_R + 10) return clearSlot(i);
      }
    }
  });

  window.onkeydown = e => {
    if(over || e.ctrlKey || e.metaKey) return;
    if(e.key === 'Enter'){ e.preventDefault(); return probe(); }
    if(e.key === 'Backspace'){ e.preventDefault(); return clearSlot(entry.length - 1); }
    const n = '1234567'.indexOf(e.key);
    if(n >= 0 && n < symCount){ e.preventDefault(); place(n); }
  };

  function glyph(i, x, y, r, dim){
    const s = TRACE_SYMS[i];
    aCtx.save();
    aCtx.globalAlpha = dim ? 0.5 : 1;
    aCtx.shadowBlur = dim ? 4 : 14; aCtx.shadowColor = s.col;
    sortDrawGlyph(aCtx, s.shape, x, y, r, s.col, '#ffffff');
    aCtx.restore();
  }

  let last = performance.now();
  function loop(now){
    if(over || scored) return;
    const dt = Math.min(50, now - last); last = now;
    const sec = dt / 1000;
    pulse = Math.max(0, pulse - sec * 3);
    shake = Math.max(0, shake - sec * 2);
    winFlash = Math.max(0, winFlash - sec * 1.4);

    aCtx.save();
    if(shake > 0) aCtx.translate((Math.random() - 0.5) * shake * 9, 0);

    aCtx.fillStyle = '#060b10';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    if(winFlash > 0){
      aCtx.fillStyle = 'rgba(57,255,136,' + (0.16 * winFlash).toFixed(3) + ')';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    }

    // ── HEADER ──
    aCtx.font = '900 13px Orbitron,monospace';
    aCtx.fillStyle = '#39ff14';
    aCtx.fillText('CIPHER #' + (cracked + 1) + '  ·  ' + symCount + ' SYMBOLS', 14, 24);
    aCtx.textAlign = 'right';
    aCtx.fillStyle = attempts >= maxTry - 2 ? '#ff2442' : '#cfe4ff';
    aCtx.fillText('PROBES ' + attempts + '/' + maxTry, BOARD_W - 14, 24);
    aCtx.textAlign = 'left';

    // ── HISTORY ──
    // Newest at the bottom, nearest the entry row it came from.
    // Bottom-anchored: the newest probe sits directly above the row you are
    // building, because that is the one you are reasoning from. Top-anchoring
    // left the freshest information furthest from the hand and a growing void
    // in the middle of the board.
    const rowH = 30;
    for(let k = 0; k < history.length; k++){
      const h = history[k];
      const y = Math.max(56, HAND_Y - 26 - (history.length - 1 - k) * rowH);
      aCtx.fillStyle = 'rgba(255,255,255,0.03)';
      aCtx.fillRect(40, y - 13, BOARD_W - 80, 26);
      for(let i = 0; i < SLOTS; i++) glyph(h.g[i], 78 + i * 40, y, 11, true);
      // Pegs: a filled dot is an exact hit, a ring is a symbol in the wrong
      // slot. Drawn as four positions so "two of them are blank" is itself
      // information, which a bare count does not give you.
      for(let i = 0; i < SLOTS; i++){
        const px = BOARD_W - 130 + i * 22;
        aCtx.beginPath(); aCtx.arc(px, y, 6, 0, Math.PI * 2);
        if(i < h.exact){ aCtx.fillStyle = '#39ff88'; aCtx.fill(); }
        else if(i < h.exact + h.present){ aCtx.strokeStyle = '#ffd700'; aCtx.lineWidth = 2; aCtx.stroke(); }
        else { aCtx.strokeStyle = 'rgba(255,255,255,0.14)'; aCtx.lineWidth = 1.5; aCtx.stroke(); }
      }
    }
    if(!history.length){
      aCtx.font = '700 11px Rajdhani,sans-serif';
      aCtx.fillStyle = 'rgba(207,228,255,0.4)';
      aCtx.textAlign = 'center';
      aCtx.fillText('● EXACT = RIGHT SYMBOL, RIGHT SLOT      ○ = RIGHT SYMBOL, WRONG SLOT', BOARD_W / 2, 80);
      aCtx.textAlign = 'left';
    }

    // ── ENTRY ROW ──
    aCtx.strokeStyle = 'rgba(57,255,20,0.25)';
    aCtx.lineWidth = 1;
    aCtx.beginPath(); aCtx.moveTo(24, HAND_Y - 6); aCtx.lineTo(BOARD_W - 24, HAND_Y - 6); aCtx.stroke();
    aCtx.font = '700 10px Orbitron,monospace';
    aCtx.fillStyle = 'rgba(207,228,255,0.55)';
    aCtx.fillText('PROBE', 24, HAND_Y + 12);
    for(let i = 0; i < SLOTS; i++){
      const x = slotX(i);
      aCtx.beginPath(); aCtx.arc(x, ENTRY_Y, ENTRY_R, 0, Math.PI * 2);
      aCtx.strokeStyle = i === entry.length ? '#39ff14' : 'rgba(255,255,255,0.18)';
      aCtx.lineWidth = i === entry.length ? 2.5 : 1.5;
      aCtx.stroke();
      if(i < entry.length) glyph(entry[i], x, ENTRY_Y, 17, false);
    }

    // ── PALETTE ──
    for(let i = 0; i < symCount; i++){
      const x = palX(i);
      aCtx.beginPath(); aCtx.arc(x, PAL_Y, PAL_R, 0, Math.PI * 2);
      aCtx.fillStyle = 'rgba(255,255,255,0.04)';
      aCtx.fill();
      aCtx.strokeStyle = 'rgba(255,255,255,0.12)'; aCtx.lineWidth = 1.5; aCtx.stroke();
      glyph(i, x, PAL_Y, 16, false);
      aCtx.font = '700 8px Orbitron,monospace';
      aCtx.fillStyle = 'rgba(255,255,255,0.42)';
      aCtx.textAlign = 'center';
      aCtx.fillText(String(i + 1), x, PAL_Y + PAL_R + 12);
      aCtx.textAlign = 'left';
    }

    // ── BUTTONS ──
    const btn = (b, label, col, on) => {
      aCtx.save();
      aCtx.globalAlpha = on ? 1 : 0.32;
      aCtx.fillStyle = 'rgba(255,255,255,0.05)';
      aCtx.fillRect(b.x - b.w / 2, b.y - b.h / 2, b.w, b.h);
      aCtx.strokeStyle = col; aCtx.lineWidth = 2;
      aCtx.shadowBlur = on ? 14 : 0; aCtx.shadowColor = col;
      aCtx.strokeRect(b.x - b.w / 2, b.y - b.h / 2, b.w, b.h);
      aCtx.shadowBlur = 0;
      aCtx.font = '900 13px Orbitron,monospace';
      aCtx.fillStyle = col;
      aCtx.textAlign = 'center';
      aCtx.fillText(label, b.x, b.y + 5);
      aCtx.textAlign = 'left';
      aCtx.restore();
    };
    btn(CLR, '✕ CLEAR', '#ff6600', entry.length > 0);
    btn(SEND, '📡 SEND PROBE', '#39ff14', entry.length === SLOTS);

    aCtx.restore();
    gameLoopId = requestAnimationFrame(loop);
  }
  gameLoopId = requestAnimationFrame(loop);

  function end(reason){
    if(scored) return; scored = true; over = true;
    clearInterval(gTimer); gTimer = null;
    clearCanvasDrag();
    const final = Math.min(900, score);
    showResults('trace', final, {
      '📡 Trace Status': cracked ? 'SIGNAL DECODED' : 'TRACE COLD',
      '🔓 Ciphers Cracked': cracked,
      '🎯 Probes Sent': probes,
      '🔤 Alphabet Reached': symCount + ' symbols',
      '🏆 Score Accumulation': final + ' PTS'
    }, cracked ? undefined : { sound: 'gameOver' });
  }
}

// ════════════════════════════════════════════
//  🧹 GAME 25: DEFRAG — the corrupted volume
// ════════════════════════════════════════════
// Minesweeper over a corrupted volume, on a clock, and — the important part —
// scored on a CURVE. Every sector you clear pays; hitting corruption loses the
// volume and hands you a fresh one rather than ending the round. A binary
// win/lose sweeper on a clock is a mission where nine tenths of the runs are
// worth nothing, which is exactly the shape the arcade already has too much of.
//
// The board is generated in FULL before the first frame, and the opening safe
// region is opened automatically rather than on the player's first click. That
// is a determinism requirement, not a kindness: "move the mines away from
// wherever they tapped" makes the board depend on player input, and a Daily
// Hack has to deal the same volume to everyone.
function startDefrag(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls({ action: '🚩 MARK' });
  setControlHint('TAP A SECTOR TO CLEAR · HOLD TO MARK · MARK BUTTON TOGGLES',
                 'CLICK TO CLEAR · RIGHT-CLICK OR F TO MARK · SPACE TOGGLES MARK MODE');
  showTouchHint('TAP TO CLEAR A SECTOR · HOLD TO MARK IT');
  fitCanvas();

  const diff  = getDifficultyModifier();
  const time0 = Math.max(34, Math.round(95 * getTimeModifier()));
  const COLS = 12, ROWS = 9, CELL = 42, OX = 28, OY = 92;
  const CORRUPT = Math.min(30, Math.round(18 * diff));
  // Tuned by playing it: a flood fill routinely opens sixty sectors in one tap,
  // so a generous per-sector rate put a full 1,050 on the board inside the first
  // volume and made the remaining eighty seconds decoration. At five a point a
  // sector, one clean volume is worth about 640 and the cap sits a volume and a
  // half out — which is a run you have to actually finish.
  const SECTOR_PTS = 5, VOLUME_BONUS = 180;

  let time = time0, score = 0, cleared = 0, volumes = 0, hits = 0, absorbed = 0;
  let drives = 3, flagMode = false, over = false, scored = false;
  let grid = [], flash = 0, holdT = null, holdCell = -1, gameT = 0;

  const idx = (c, r) => r * COLS + c;
  const inb = (c, r) => c >= 0 && c < COLS && r >= 0 && r < ROWS;
  const around = i => {
    const c = i % COLS, r = (i / COLS) | 0, out = [];
    for(let dc = -1; dc <= 1; dc++) for(let dr = -1; dr <= 1; dr++){
      if(!dc && !dr) continue;
      if(inb(c + dc, r + dr)) out.push(idx(c + dc, r + dr));
    }
    return out;
  };

  function newVolume(){
    grid = [];
    for(let i = 0; i < COLS * ROWS; i++) grid.push({ bad: false, open: false, flag: false, n: 0, lit: 0 });
    // A safe opening region, picked BEFORE the mines so it is part of the seed
    // rather than part of the player's first tap.
    const sc = 1 + Math.floor(Math.random() * (COLS - 2));
    const sr = 1 + Math.floor(Math.random() * (ROWS - 2));
    const safe = new Set([idx(sc, sr), ...around(idx(sc, sr))]);
    let placed = 0, guard = 0;
    while(placed < CORRUPT && guard++ < 4000){
      const i = Math.floor(Math.random() * grid.length);
      if(grid[i].bad || safe.has(i)) continue;
      grid[i].bad = true; placed++;
    }
    for(let i = 0; i < grid.length; i++) grid[i].n = around(i).filter(j => grid[j].bad).length;
    open(idx(sc, sr), true);
  }

  // Flood fill, iteratively. A recursive fill over 108 cells is fine until a
  // volume is nearly empty, and then it is a stack the browser does not have.
  function open(i, quiet){
    const stack = [i];
    let got = 0;
    while(stack.length){
      const k = stack.pop();
      const cell = grid[k];
      if(!cell || cell.open || cell.flag) continue;
      cell.open = true; cell.lit = 1; got++;
      if(cell.n === 0) around(k).forEach(j => { if(!grid[j].open) stack.push(j); });
    }
    if(!got) return 0;
    cleared += got;
    score += got * SECTOR_PTS;
    setLive(Math.min(1050, score));
    if(!quiet) snd('node', { semi: Math.min(16, got) });
    // A volume is complete when every clean sector is open.
    if(grid.every(c => c.bad || c.open)){
      volumes++;
      score += VOLUME_BONUS;
      setLive(Math.min(1050, score));
      snd('victory');
      toast('🧹 VOLUME DEFRAGGED — mounting the next one', 2400);
      gLater(() => { if(!over) newVolume(); }, 620);
    }
    return got;
  }

  function strike(i){
    grid[i].open = true;
    hits++;
    flash = 1;
    // 🛡️ Touching corruption is this mission's fatal point.
    if(survivedFatal()){
      absorbed++;
      grid[i].bad = false;
      grid[i].n = around(i).filter(j => grid[j].bad).length;
      snd('shieldHit');
      return;
    }
    drives--;
    snd('explode');
    if(drives <= 0){
      over = true;
      snd('bigExplode');
      gLater(() => end('lost'), 520);
      return;
    }
    toast('💥 SECTOR CORRUPTED — volume lost, ' + drives + ' drive' + (drives === 1 ? '' : 's') + ' left', 2600);
    gLater(() => { if(!over) newVolume(); }, 620);
  }

  function tap(i, mark){
    if(over || i < 0 || !grid[i]) return;
    const cell = grid[i];
    if(mark || flagMode){
      if(cell.open) return;
      cell.flag = !cell.flag;
      snd('toggle');
      return;
    }
    if(cell.flag || cell.open) return;
    if(cell.bad) return strike(i);
    open(i, false);
  }

  const cellAt = p => {
    const c = Math.floor((p.x - OX) / CELL), r = Math.floor((p.y - OY) / CELL);
    return inb(c, r) ? idx(c, r) : -1;
  };

  bindCanvasDrag({
    onDown(p){
      hideTouchHint();
      holdCell = cellAt(p);
      if(holdCell < 0) return;
      // Hold-to-mark. gLater so it dies with the round rather than landing on
      // whatever mounts next.
      gCancel(holdT);
      holdT = gLater(() => { if(holdCell >= 0){ tap(holdCell, true); holdCell = -1; } }, 420);
    },
    onMove(p){ if(holdCell >= 0 && cellAt(p) !== holdCell){ gCancel(holdT); holdCell = -1; } },
    onUp(p){
      gCancel(holdT);
      if(holdCell < 0) return;
      const i = cellAt(p);
      if(i === holdCell) tap(i, false);
      holdCell = -1;
    }
  });

  // Right-click marks, which is what a desktop hand reaches for first. Removed
  // in end(); stopGame() also clears aCanvas handlers wholesale.
  aCanvas.oncontextmenu = e => {
    e.preventDefault();
    const p = boardPos(e.clientX, e.clientY);
    tap(cellAt(p), true);
  };

  const markBtn = document.getElementById('ctrl-action');
  const paintMark = () => { if(markBtn) markBtn.textContent = flagMode ? '🚩 MARK ✓' : '🚩 MARK'; };
  if(markBtn) markBtn.onclick = () => { flagMode = !flagMode; paintMark(); snd('toggle'); };

  window.onkeydown = e => {
    if(over || e.ctrlKey || e.metaKey) return;
    if(e.key === ' ' || e.key === 'f' || e.key === 'F'){
      e.preventDefault();
      flagMode = !flagMode;
      paintMark();
      snd('toggle');
    }
  };

  registerRoundClock(n => {
    time += n;
    document.getElementById('g-time').textContent = time;
  });

  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--gold),var(--orange))';
  gTimer = setInterval(() => {
    if(over) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = Math.max(0, time / time0 * 100) + '%';
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  newVolume();

  const NUMC = ['', '#8fa6ff', '#39ff88', '#ffd700', '#ff9d00', '#ff6600', '#ff2442', '#ff0090', '#ffffff'];
  let last = performance.now();
  function loop(now){
    if(scored) return;
    const dt = Math.min(50, now - last); last = now;
    const sec = dt / 1000;
    gameT += sec;
    flash = Math.max(0, flash - sec * 2);

    aCtx.fillStyle = '#0a0910';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    if(flash > 0){
      aCtx.fillStyle = 'rgba(255,36,66,' + (0.22 * flash).toFixed(3) + ')';
      aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    }

    // ── HEADER ──
    const flags = grid.filter(c => c.flag).length;
    aCtx.font = '900 13px Orbitron,monospace';
    aCtx.fillStyle = '#ffd700';
    aCtx.fillText('VOLUME ' + (volumes + 1) + '  ·  ' + CORRUPT + ' CORRUPT', 14, 28);
    aCtx.fillStyle = '#cfe4ff';
    aCtx.font = '700 11px Orbitron,monospace';
    aCtx.fillText('🚩 ' + flags + ' / ' + CORRUPT + (flagMode ? '   ·   MARK MODE ON' : ''), 14, 50);
    aCtx.textAlign = 'right';
    aCtx.font = '900 13px Orbitron,monospace';
    aCtx.fillStyle = drives === 1 ? '#ff2442' : '#39ff88';
    aCtx.fillText('💾 ' + drives + ' DRIVE' + (drives === 1 ? '' : 'S'), BOARD_W - 14, 28);
    aCtx.font = '700 11px Orbitron,monospace';
    aCtx.fillStyle = '#cfe4ff';
    aCtx.fillText(cleared + ' SECTORS SWEPT', BOARD_W - 14, 50);
    aCtx.textAlign = 'left';

    // ── GRID ──
    for(let i = 0; i < grid.length; i++){
      const cell = grid[i];
      cell.lit = Math.max(0, cell.lit - sec * 2);
      const c = i % COLS, r = (i / COLS) | 0;
      const x = OX + c * CELL, y = OY + r * CELL;
      if(cell.open){
        // A swept sector is a HOLE in the surface, not a slightly darker tile: at
        // 0.035 against the unswept 0.075 the two read as the same grey and the
        // board stopped saying what had been done to it.
        aCtx.fillStyle = cell.bad ? 'rgba(255,36,66,0.35)' : 'rgba(0,0,0,0.55)';
        aCtx.fillRect(x + 1, y + 1, CELL - 2, CELL - 2);
        if(cell.lit > 0){
          aCtx.fillStyle = 'rgba(255,215,0,' + (0.3 * cell.lit).toFixed(3) + ')';
          aCtx.fillRect(x + 1, y + 1, CELL - 2, CELL - 2);
        }
        if(cell.bad){
          aCtx.font = '900 20px Orbitron,monospace';
          aCtx.fillStyle = '#ff2442';
          aCtx.textAlign = 'center';
          aCtx.fillText('☣', x + CELL / 2, y + CELL / 2 + 8);
          aCtx.textAlign = 'left';
        }else if(cell.n){
          aCtx.font = '900 17px Orbitron,monospace';
          aCtx.fillStyle = NUMC[cell.n] || '#fff';
          aCtx.textAlign = 'center';
          aCtx.fillText(String(cell.n), x + CELL / 2, y + CELL / 2 + 6);
          aCtx.textAlign = 'left';
        }
      }else{
        // An unswept sector is a raised block, so the board reads as a surface
        // being eaten into rather than as a grid being coloured in.
        aCtx.fillStyle = 'rgba(150,170,220,0.16)';
        aCtx.fillRect(x + 1, y + 1, CELL - 2, CELL - 2);
        aCtx.fillStyle = 'rgba(255,255,255,0.13)';
        aCtx.fillRect(x + 1, y + 1, CELL - 2, 3);
        aCtx.fillStyle = 'rgba(0,0,0,0.30)';
        aCtx.fillRect(x + 1, y + CELL - 5, CELL - 2, 4);
        if(cell.flag){
          aCtx.font = '900 18px Orbitron,monospace';
          aCtx.textAlign = 'center';
          aCtx.fillStyle = '#ff6600';
          aCtx.fillText('🚩', x + CELL / 2, y + CELL / 2 + 7);
          aCtx.textAlign = 'left';
        }
      }
      aCtx.strokeStyle = 'rgba(255,255,255,0.06)';
      aCtx.lineWidth = 1;
      aCtx.strokeRect(x + 0.5, y + 0.5, CELL - 1, CELL - 1);
    }

    if(!over) gameLoopId = requestAnimationFrame(loop);
  }
  gameLoopId = requestAnimationFrame(loop);

  function end(reason){
    if(scored) return; scored = true; over = true;
    clearInterval(gTimer); gTimer = null;
    gCancel(holdT);
    clearCanvasDrag();
    aCanvas.oncontextmenu = null;
    if(markBtn) markBtn.onclick = null;
    const final = Math.min(1050, score);
    showResults('defrag', final, {
      '🧹 Sweep Status': reason === 'lost' ? 'ALL DRIVES LOST' : volumes ? 'VOLUMES RECOVERED' : 'SWEEP TIMED OUT',
      '📦 Sectors Swept': cleared,
      '💽 Volumes Defragged': volumes,
      '☣️ Corruption Struck': hits,
      ...(absorbed ? { '🛡️ Strikes Absorbed': absorbed } : {}),
      '🏆 Score Accumulation': final + ' PTS'
    }, reason === 'lost' ? { sound: 'gameOver' } : undefined);
  }
}

// ════════════════════════════════════════════
//  🌡️ GAME 26: COOLANT — the cooling shaft
// ════════════════════════════════════════════
// The arcade's one true physics mission. ONE button, real mass, and nothing
// stops when you let go: thrust does not lift you, it reverses the sign of your
// acceleration, and whatever velocity you already had is still yours. That is
// the difference between this and FLAPPY DRONE, which is an impulse — here you
// are steering a weight, and the correct input is usually a tap earlier than
// feels natural.
//
// The second dial is HEAT. Thrusting cooks the drive and coasting cools it, so
// "just hold it down" is not a strategy — the shaft is threaded on a rhythm of
// burns and glides, which is exactly the feel this was tuned for. Coolant cells
// in the shaft vent heat and pay.
//
// ⚙️ The integration runs on a FIXED 120Hz accumulator rather than on dt. Two
// machines therefore integrate the identical trajectory from the identical
// inputs, which is what lets a physics game sit in the Daily Hack's seeded pool
// at all — the pool's rule is that a frame-rate difference must not quietly
// make it a different run, and a fixed step is how that is earned rather than
// hoped for.
const COOL_STEP = 1 / 120;

// The shaft, generated in full up front. Two height fields sampled from summed
// sines with seeded phases: continuous by construction (so there is never a
// wall edge to clip on), and the gap narrows with distance rather than with
// time — the shaft gets harder because you have flown further, not because a
// clock said so.
function coolBuildShaft(len, diff){
  const ph = [];
  for(let i = 0; i < 6; i++) ph.push(Math.random() * 6.28);
  const cells = [];
  const at = x => {
    const wob = Math.sin(x * 0.0062 + ph[0]) * 78 +
                Math.sin(x * 0.0131 + ph[1]) * 34 +
                Math.sin(x * 0.0271 + ph[2]) * 14;
    const mid = BOARD_H / 2 + wob;
    // 232 down to 96 over the run, tightened further by the tier.
    const gap = Math.max(84, (232 - Math.min(136, x * 0.030)) / Math.max(0.85, diff * 0.92));
    return { top: mid - gap / 2, bot: mid + gap / 2 };
  };
  for(let x = 620; x < len; x += 300 + Math.random() * 280){
    const s = at(x);
    cells.push({ x, y: s.top + (s.bot - s.top) * (0.25 + Math.random() * 0.5), got: false, pulse: 0 });
  }
  return { at, cells };
}

function startCoolant(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  setControls({ action: '🔥 BURN' });
  setControlHint('HOLD ANYWHERE ON THE BOARD TO BURN · LET GO TO FALL AND COOL',
                 'HOLD SPACE / ▲ / THE BURN PAD · LET GO TO FALL AND COOL');
  showTouchHint('HOLD TO BURN — NOTHING STOPS WHEN YOU LET GO');
  fitCanvas();

  const NEONC = getEquippedColorHex();
  const diff  = getDifficultyModifier();
  const time0 = Math.max(34, Math.round(92 * getTimeModifier()));

  // The flight model. Every one of these was tuned by playing it, and the two
  // that matter most are DRAG (how much the craft remembers) and HEAT_UP vs
  // HEAT_DN (how long a burn you can afford before the shaft makes you glide).
  const GRAV = 560, THRUST = 1180, DRAG = 0.30;
  const VMAX = 620, SPD = 210 * Math.max(0.9, diff * 0.85);
  const HEAT_UP = 0.46, HEAT_DN = 0.60, VENT = 0.42;
  const CRAFT_X = 148, RAD = 11;

  const shaft = coolBuildShaft(SPD * (time0 + 8) + 2400, diff);
  let time = time0, score = 0, dist = 0, heat = 0, vy = 0, y = BOARD_H / 2;
  let burning = false, over = false, scored = false, grace = 0, crashes = 0, vented = 0;
  let acc = 0, shakeT = 0, trail = [];

  const setBurn = on => { if(!over) burning = on; };

  bindCanvasDrag({
    onDown(){ hideTouchHint(); setBurn(true); },
    onUp(){ setBurn(false); }
  });
  bindHold(document.getElementById('ctrl-action'), () => setBurn(true), () => setBurn(false));
  window.onkeydown = e => {
    if(over || e.ctrlKey || e.metaKey) return;
    if(e.code === 'Space' || e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W'){ e.preventDefault(); setBurn(true); }
  };
  window.onkeyup = e => {
    if(e.code === 'Space' || e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W'){ e.preventDefault(); setBurn(false); }
  };

  registerRoundClock(n => {
    time += n;
    document.getElementById('g-time').textContent = time;
  });

  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--red),var(--orange))';
  gTimer = setInterval(() => {
    if(over) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = Math.max(0, time / time0 * 100) + '%';
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  function fatal(why){
    // 🛡️ Both of this mission's endings are fatal points, so both ask.
    if(survivedFatal()){
      crashes++;
      const s = shaft.at(dist + CRAFT_X);
      y = (s.top + s.bot) / 2;
      vy = 0; heat = 0; grace = 1.4; shakeT = 0.5;
      snd('shieldHit');
      return;
    }
    over = true;
    snd('bigExplode');
    gLater(() => end(why), 520);
  }

  // One fixed physics step. Nothing in here reads dt.
  function step(){
    vy += (burning ? -THRUST : GRAV) * COOL_STEP;
    // Drag as a per-SECOND rate, raised to the step — the same discipline the
    // frame loops are under, applied to a fixed step so it is exact.
    vy *= Math.pow(1 - DRAG, COOL_STEP);
    vy = Math.max(-VMAX, Math.min(VMAX, vy));
    y += vy * COOL_STEP;
    dist += SPD * COOL_STEP;

    heat = burning ? Math.min(1.35, heat + HEAT_UP * COOL_STEP)
                   : Math.max(0, heat - HEAT_DN * COOL_STEP);

    const s = shaft.at(dist + CRAFT_X);
    if(grace > 0){
      grace = Math.max(0, grace - COOL_STEP);
    }else{
      if(y - RAD < s.top || y + RAD > s.bot){
        y = Math.max(s.top + RAD, Math.min(s.bot - RAD, y));
        vy = 0;
        fatal('crash');
        return;
      }
      if(heat >= 1){ heat = 0.55; fatal('overheat'); return; }
    }

    for(const c of shaft.cells){
      if(c.got) continue;
      if(Math.abs(c.x - (dist + CRAFT_X)) < 16 && Math.abs(c.y - y) < 22){
        c.got = true; c.pulse = 1; vented++;
        heat = Math.max(0, heat - VENT);
        score += 46;
        setLive(Math.min(1350, Math.round(score + dist * 0.34)));
        snd('pickup', { semi: Math.min(12, vented) });
      }
    }
  }

  let last = performance.now();
  function loop(now){
    if(scored) return;
    const dt = Math.min(50, now - last); last = now;
    const sec = dt / 1000;

    if(!over){
      acc += sec;
      if(acc > 0.25) acc = 0.25;             // a stalled tab resumes, it does not teleport
      while(acc >= COOL_STEP && !over){ step(); acc -= COOL_STEP; }
      setLive(Math.min(1350, Math.round(score + dist * 0.34)));
    }
    if(shakeT > 0) shakeT = Math.max(0, shakeT - sec);

    trail.push({ x: CRAFT_X, y, b: burning });
    if(trail.length > 22) trail.shift();

    // ── PAINT ──
    aCtx.save();
    if(shakeT > 0) aCtx.translate((Math.random() - 0.5) * shakeT * 14, (Math.random() - 0.5) * shakeT * 14);

    const hot = Math.min(1, heat);
    aCtx.fillStyle = '#0b0710';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);
    aCtx.fillStyle = 'rgba(255,60,40,' + (0.10 * hot * hot).toFixed(3) + ')';
    aCtx.fillRect(0, 0, BOARD_W, BOARD_H);

    // The shaft. Sampled every 8 board units, which is well inside the
    // wavelength of the slowest sine, so the walls are smooth.
    const STEPX = 8;
    aCtx.beginPath();
    aCtx.moveTo(0, 0);
    for(let sx = 0; sx <= BOARD_W; sx += STEPX) aCtx.lineTo(sx, shaft.at(dist + sx).top);
    aCtx.lineTo(BOARD_W, 0);
    aCtx.closePath();
    const gTop = aCtx.createLinearGradient(0, 0, 0, BOARD_H);
    gTop.addColorStop(0, '#2a1018'); gTop.addColorStop(1, '#4a1524');
    aCtx.fillStyle = gTop; aCtx.fill();
    aCtx.strokeStyle = '#ff6600'; aCtx.lineWidth = 2.5;
    aCtx.shadowBlur = 14; aCtx.shadowColor = '#ff6600'; aCtx.stroke(); aCtx.shadowBlur = 0;

    aCtx.beginPath();
    aCtx.moveTo(0, BOARD_H);
    for(let sx = 0; sx <= BOARD_W; sx += STEPX) aCtx.lineTo(sx, shaft.at(dist + sx).bot);
    aCtx.lineTo(BOARD_W, BOARD_H);
    aCtx.closePath();
    aCtx.fillStyle = gTop; aCtx.fill();
    aCtx.strokeStyle = '#ff6600'; aCtx.lineWidth = 2.5;
    aCtx.shadowBlur = 14; aCtx.shadowColor = '#ff6600'; aCtx.stroke(); aCtx.shadowBlur = 0;

    // Coolant cells.
    for(const c of shaft.cells){
      const sx = c.x - dist;
      if(sx < -40 || sx > BOARD_W + 40) continue;
      if(c.got){
        c.pulse = Math.max(0, c.pulse - sec * 2);
        if(c.pulse <= 0) continue;
        aCtx.save();
        aCtx.globalAlpha = c.pulse;
        aCtx.strokeStyle = '#00f5ff'; aCtx.lineWidth = 2;
        aCtx.beginPath(); aCtx.arc(sx, c.y, 10 + (1 - c.pulse) * 26, 0, Math.PI * 2); aCtx.stroke();
        aCtx.restore();
        continue;
      }
      const p = 0.7 + 0.3 * Math.sin(dist * 0.03 + c.x);
      aCtx.save();
      aCtx.shadowBlur = 18 * p; aCtx.shadowColor = '#00f5ff';
      aCtx.fillStyle = 'rgba(0,245,255,0.22)';
      aCtx.beginPath(); aCtx.arc(sx, c.y, 13, 0, Math.PI * 2); aCtx.fill();
      aCtx.strokeStyle = '#00f5ff'; aCtx.lineWidth = 2.5;
      aCtx.stroke();
      aCtx.restore();
      aCtx.font = '900 12px Orbitron,monospace';
      aCtx.fillStyle = '#00f5ff';
      aCtx.textAlign = 'center';
      aCtx.fillText('❄', sx, c.y + 4);
      aCtx.textAlign = 'left';
    }

    // Exhaust trail — only where the drive was actually lit, so the picture
    // says what the last twenty frames of INPUT were.
    for(let i = 0; i < trail.length; i++){
      const t = trail[i];
      if(!t.b) continue;
      const a = i / trail.length;
      aCtx.globalAlpha = a * 0.55;
      aCtx.fillStyle = '#ff6600';
      aCtx.beginPath();
      aCtx.arc(t.x - (trail.length - i) * 3.4, t.y + (trail.length - i) * 0.5, 6 * a, 0, Math.PI * 2);
      aCtx.fill();
    }
    aCtx.globalAlpha = 1;

    // The craft. It PITCHES with its vertical velocity, which is most of what
    // makes the mass legible before you have crashed into anything.
    const pitch = Math.max(-0.7, Math.min(0.7, vy / 520));
    aCtx.save();
    aCtx.translate(CRAFT_X, y);
    aCtx.rotate(pitch);
    aCtx.shadowBlur = burning ? 26 : 12; aCtx.shadowColor = burning ? '#ff6600' : NEONC;
    aCtx.fillStyle = burning ? '#ff9d00' : NEONC;
    aCtx.beginPath();
    aCtx.moveTo(16, 0); aCtx.lineTo(-11, -9); aCtx.lineTo(-6, 0); aCtx.lineTo(-11, 9);
    aCtx.closePath(); aCtx.fill();
    aCtx.shadowBlur = 0;
    aCtx.strokeStyle = '#fff'; aCtx.lineWidth = 1.5; aCtx.stroke();
    if(burning){
      aCtx.fillStyle = 'rgba(255,215,0,0.85)';
      aCtx.beginPath();
      aCtx.moveTo(-8, -5); aCtx.lineTo(-20 - Math.random() * 10, 0); aCtx.lineTo(-8, 5);
      aCtx.closePath(); aCtx.fill();
    }
    if(grace > 0){
      aCtx.globalAlpha = 0.4 + 0.4 * Math.sin(dist * 0.5);
      aCtx.strokeStyle = '#39ff88'; aCtx.lineWidth = 2;
      aCtx.beginPath(); aCtx.arc(0, 0, RAD + 8, 0, Math.PI * 2); aCtx.stroke();
    }
    aCtx.restore();
    drawSkinBadge(CRAFT_X, y - 24);

    // ── HEAT BAR ──
    const bw = 190;
    aCtx.fillStyle = 'rgba(6,6,14,0.8)';
    aCtx.fillRect(10, 10, bw + 8, 26);
    aCtx.strokeStyle = hot > 0.75 ? '#ff2442' : 'rgba(255,157,0,0.5)';
    aCtx.lineWidth = 1.5;
    aCtx.strokeRect(10, 10, bw + 8, 26);
    const hg = aCtx.createLinearGradient(14, 0, 14 + bw, 0);
    hg.addColorStop(0, '#00f5ff'); hg.addColorStop(0.55, '#ffd700'); hg.addColorStop(1, '#ff2442');
    aCtx.fillStyle = hg;
    aCtx.fillRect(14, 22, bw * hot, 10);
    aCtx.font = '700 10px Orbitron,monospace';
    aCtx.fillStyle = hot > 0.75 ? '#ff2442' : '#cfe4ff';
    aCtx.fillText(hot > 0.85 ? 'CORE HEAT — CRITICAL' : 'CORE HEAT', 14, 20);
    aCtx.textAlign = 'right';
    aCtx.font = '900 13px Orbitron,monospace';
    aCtx.fillStyle = '#cfe4ff';
    aCtx.fillText(Math.round(dist) + 'm', BOARD_W - 14, 26);
    aCtx.textAlign = 'left';

    aCtx.restore();
    if(!scored) gameLoopId = requestAnimationFrame(loop);
  }
  gameLoopId = requestAnimationFrame(loop);

  function end(reason){
    if(scored) return; scored = true; over = true;
    clearInterval(gTimer); gTimer = null;
    clearCanvasDrag();
    clearHold(document.getElementById('ctrl-action'));
    const final = Math.min(1350, Math.round(score + dist * 0.34));
    showResults('coolant', final, {
      '🌡️ Run Status': reason === 'crash' ? 'HULL BREACH'
                     : reason === 'overheat' ? 'CORE OVERHEAT' : 'SHAFT RUN COMPLETE',
      '📏 Shaft Flown': Math.round(dist) + 'm',
      '❄️ Coolant Vented': vented + ' cells',
      ...(crashes ? { '🛡️ Impacts Absorbed': crashes } : {}),
      '🏆 Score Accumulation': final + ' PTS'
    }, reason === 'timeout' ? undefined : { sound: 'gameOver' });
  }
}


function fmtTime(s){
  const t = Math.max(0, s);
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
}

// ══════════════════════════════════════════════════════════════════════
//  💾 PROFILE WRITES — one door, online or not
// ══════════════════════════════════════════════════════════════════════
// Everything added below this line mutates `user` and then calls this. The
// mirror is written UNCONDITIONALLY and first, which is the whole guest story:
// a player with no account, no connection, or both still keeps their level,
// their perks, their kit and today's Daily Hack, because localStorage is the
// authority the boot path already falls back to (see readCachedProfile).
//
// The server write is best-effort on top of that. It is skipped entirely for a
// local session, whose uid the database rules would reject anyway.
function saveProfilePatch(patch){
  if(!user) return Promise.resolve();
  cacheProfile(user);
  if(!db || offlineMode || isLocalSession()) return Promise.resolve();
  return db.ref('players/' + user.uid).update(patch)
    .catch(e => { console.warn('Profile write failed — kept in the local mirror:', e); });
}

// ══════════════════════════════════════════════════════════════════════
//  🌀 CHAOS MODIFIERS — one rule bent per round
// ══════════════════════════════════════════════════════════════════════
// A modifier is applied by BENDING A SEAM THE ARCADE ALREADY HAS, never by
// editing a game:
//
//   🔄 INVERSE CONTROLS  boardPos() mirrors the play field, and the keyboard
//                        handler each game installs is wrapped in one that
//                        swaps the arrow it was handed. Two funnels, eighteen
//                        games, zero per-game code.
//   ⏩ DOUBLE SPEED      setInterval is halved for the duration of the game's
//                        own start() call, so every clock and tick-driven
//                        behaviour it installs runs twice as fast — plus a lift
//                        on the hazard-speed multiplier for the loops that are
//                        driven by requestAnimationFrame instead.
//   🕶️ BLIND TERMINAL    a CSS class blanks the play area to opacity 0 for
//                        0.3s once every 1.5s. Purely visual: the round keeps
//                        running underneath, which is the point.
//
//   📉 PACKET LOSS       one capture-phase listener on window drops a share of
//                        the keystrokes and taps before any game sees them.
//   📶 SIGNAL DEGRADATION a CSS filter over the play area. The round underneath
//                        is pristine and no mission learns it happened.
//   🌀 AXIS DRIFT        #board-frame rotates and boardPos() rotates the finger
//                        back, so the picture lies and the aim does not.
//   ⚡ 📦 🛡️ BOONS        pay, stock the kit, or absorb a fatal hit. Settled on
//                        the results card, or armed as a free shield.
//
// Who ROLLS one is the caller's business. Boss Rush rolls per stage; the
// Network Arena's host rolls once into the room record so every client reads
// the same id; and an ordinary mission rolls its own in prepGame() — but only
// when the player has armed CHAOS PROTOCOL in the hub. Until that opt-in
// existed, two thirds of this table was unreachable from the mission grid.
// A modifier is a HAZARD or a BOON, and the split is the whole point of the
// redesign. A pool of nothing but handicaps makes the roll something to dread:
// the best outcome is "nothing happened", so a player learns to hope the dice
// stay quiet. Mixing in modifiers that PAY turns the same roll into a gamble
// worth taking, which is what makes arming it voluntarily (see chaosOptIn)
// something anyone would ever do.
//
// `pay` is the multiplier the modifier adds to the final award. A hazard pays
// because it cost you something; a boon pays because paying IS the boon.
const CHAOS_MODS = [
  // ── HAZARDS ──
  { id:'inverse', icon:'🔄', name:'INVERSE CONTROLS', kind:'hazard', pay:1.25,
    desc:'Every direction you press comes out backwards.' },
  { id:'double',  icon:'⏩', name:'DOUBLE SPEED', kind:'hazard', pay:1.25,
    desc:'Clocks and hazards run at twice the rate. Half the round, same target.' },
  { id:'blind',   icon:'🕶️', name:'BLIND TERMINAL', kind:'hazard', pay:1.25,
    desc:'The feed cuts out for a third of a second, every second and a half.' },
  { id:'packet',  icon:'📉', name:'PACKET LOSS', kind:'hazard', pay:1.3,
    desc:'One input in seven never reaches the grid. You will not be told which.' },
  { id:'lowband', icon:'📶', name:'SIGNAL DEGRADATION', kind:'hazard', pay:1.2,
    desc:'The feed arrives smeared and torn. The round underneath is pristine.' },
  { id:'drift',   icon:'🌀', name:'AXIS DRIFT', kind:'hazard', pay:1.3,
    desc:'The display rotates slowly off true. Your aim follows the picture, not the grid.' },

  // ── BOONS ──
  { id:'surge',   icon:'⚡', name:'POINT SURGE', kind:'boon', pay:2.0,
    desc:'The grid is paying double. Nothing else changes — go and take it.' },
  { id:'surplus', icon:'📦', name:'SUPPLY DROP', kind:'boon', pay:1.1,
    desc:'Finish the round and the grid pays out a consumable on top of the points.' },
  { id:'bulwark', icon:'🛡️', name:'HARDENED SHELL', kind:'boon', pay:1.15,
    desc:'One fatal hit this round is absorbed for free. Spend it well.' }
];

// Two pools, because a stack of two must never be two boons — that is not a
// gamble, it is a jackpot, and it would be the only roll anyone remembered.
const CHAOS_HAZARDS = CHAOS_MODS.filter(m => m.kind === 'hazard');
const CHAOS_BOONS   = CHAOS_MODS.filter(m => m.kind === 'boon');

// Better than even, but not certain — a stage that comes up clean is what makes
// the ones that don't feel like an event.
const CHAOS_ODDS = 0.55;
// How often a roll that DID fire comes up a boon. A third: often enough that
// the pre-round banner is worth reading, rare enough that it still lands as
// luck rather than as an entitlement. 🌳 Wildcard Protocol doubles it.
const CHAOS_BOON_ODDS = 0.34;
const CHAOS_BLIND_EVERY = 1500, CHAOS_BLIND_FOR = 300;
// Meltdown stacks a SECOND modifier on top of the first. The tier already pays
// double; this is what it costs.
const CHAOS_STACK_TIER = 'meltdown';

// Read by boardPos() on every pointer sample, so it is a bare boolean rather
// than a lookup through the chaos record.
let chaosInverse = false;
// 🌀 AXIS DRIFT's current rotation, in radians. Read by boardPos() to undo the
// tilt, so a finger lands on the thing it is pointing at rather than on where
// that thing would have been if the board were straight. Zero when undrifted,
// which makes the un-rotation a single cheap branch on every pointer sample.
let chaosDrift = 0, chaosDriftTimer = 0;
// 📉 PACKET LOSS. A capture-phase interceptor on window reads this; keeping it
// a bare number rather than a lookup matters because it is consulted on every
// keystroke and every tap of the round.
let chaosDropOdds = 0;
// 🛡️ HARDENED SHELL's free absorb, armed for the round and spent by the first
// fatal event that asks for it. Separate from the shop's Shield Overlay so the
// boon can never quietly eat a consumable the player paid for.
let chaosFreeShield = false;
// The ◀/▶ rebinding INVERSE CONTROLS performs, recorded so it can be put
// back. See chaosDampen().
let chaosPadSwap = null;
// ⚙️ OVERCLOCK CHIP, armed for the round it was pressed in. Round-scoped
// rather than profile state: it is spent the moment it is pressed, and what
// survives is a fact about THIS round that the results card has to read after
// stopGame() has already torn the round down.
let runOverclock = 0;

// `last` is what the round that just ENDED was played under. It exists because
// stopGame() tears the modifier down before the results card is written — the
// card and the achievement check both need to know what was running a moment
// ago, and `active` is already null by then.
//
// `stack` is the live list — one modifier normally, two on Meltdown. `active`
// stays the FIRST of them so every existing reader (the banner, the results
// row, the achievement test, the Boss Rush log) keeps working unchanged, and
// only the code that genuinely cares about the second one looks at the list.
const chaos = { active: null, last: null, stack: [], lastStack: [], pending: [],
                blindTimer: 0, bannerTimer: 0 };

const chaosById  = id => CHAOS_MODS.find(m => m.id === id) || null;

// 🌳 Wildcard Protocol doubles a boon's share of the pool without touching how
// often chaos fires at all — a perk that made chaos MORE frequent would be a
// perk that made the arcade harder, which is not what a perk is for.
function chaosBoonOdds(){
  return Math.min(0.75, CHAOS_BOON_ODDS * (hasPerk('perk-wildcard') ? 2 : 1));
}
const chaosPickFrom = pool => pool[Math.floor(Math.random() * pool.length)];

// One modifier or null. Still the shape the Network Arena publishes (a single
// id into the room record) and the shape Boss Rush logs per stage, which is why
// stacking is a separate function rather than a change to this one.
const chaosRoll = () => Math.random() < CHAOS_ODDS
  ? chaosPickFrom(Math.random() < chaosBoonOdds() ? CHAOS_BOONS : CHAOS_HAZARDS)
  : null;

// The list an ordinary solo round is armed with. Meltdown stacks a second
// modifier, and the second one is always a HAZARD: two boons at once is not a
// gamble, it is a payday, and it would be the only roll anyone remembered.
function chaosRollStack(){
  const first = chaosRoll();
  if(!first) return [];
  if(currentDifficultyTier !== CHAOS_STACK_TIER) return [first];
  const pool = CHAOS_HAZARDS.filter(m => m.id !== first.id);
  const second = chaosPickFrom(pool);
  return second ? [first, second] : [first];
}

// Exactly `n` modifiers, odds ignored. Boss Rush uses it to ESCALATE across a
// chain: rolling each stage at the ordinary 55% could hand out five clean
// stages or five loaded ones, so the shape of a run was luck rather than
// design. At most one boon, and never two, for the same reason chaosRollStack()
// refuses two boons — a stacked payday is the only roll anyone would remember.
function chaosForce(n){
  const out = [];
  if(n <= 0) return out;
  const wantBoon = Math.random() < chaosBoonOdds();
  const pools = wantBoon ? [CHAOS_BOONS, CHAOS_HAZARDS] : [CHAOS_HAZARDS, CHAOS_HAZARDS];
  for(let i = 0; i < n; i++){
    const pool = (pools[i] || CHAOS_HAZARDS).filter(m => !out.some(o => o.id === m.id));
    const pick = chaosPickFrom(pool.length ? pool : CHAOS_HAZARDS);
    if(pick && !out.some(o => o.id === pick.id)) out.push(pick);
  }
  return out;
}

// What the round just played is worth. Multiplicative, so a stack of two is
// genuinely worth stacking — and clamped, because Meltdown's own ×2 is already
// riding on top of this.
function chaosPayMult(list){
  const stack = list || chaos.lastStack;
  if(!stack || !stack.length) return 1;
  return Math.min(2.6, stack.reduce((m, c) => m * (c.pay || 1), 1));
}

// Every reader that used to ask "what modifier?" and mean "name one" still
// works; this is for the places that want to name all of them.
const chaosLabel = list => (list || chaos.lastStack || [])
  .map(c => `${c.icon} ${c.name}`).join(' · ');
// Shown during the countdown, so the modifier is read BEFORE the round it
// changes rather than discovered by losing to it.
//
// Takes one modifier or a list of them. The three elements the markup provides
// are filled from the whole stack rather than one entry, because a Meltdown
// round that armed two and announced one would be lying to the player about
// what it was doing.
function chaosAnnounce(mod){
  const el = document.getElementById('chaos-banner');
  if(!el) return;
  clearTimeout(chaos.bannerTimer);
  const list = !mod ? [] : (Array.isArray(mod) ? mod.filter(Boolean) : [mod]);
  if(!list.length){ el.style.display = 'none'; el.className = ''; chaosRerollBtn(null); return; }
  const allBoon = list.every(c => c.kind === 'boon');
  document.getElementById('chaos-icon').textContent = list.map(c => c.icon).join('');
  document.getElementById('chaos-name').textContent = list.map(c => c.name).join('  +  ');
  document.getElementById('chaos-desc').textContent = list.map(c => c.desc).join(' ');
  el.style.display = 'flex';
  // A boon has to LOOK different from the first glance, or the player reads the
  // banner as bad news and plays the round defensively for nothing.
  el.className = 'big' + (allBoon ? ' chaos-boon' : ' chaos-hazard');
  snd(allBoon ? 'powerup' : 'alarm');
  const pay = chaosPayMult(list);
  toast(`${allBoon ? '🎁 WINDFALL' : '🌀 CHAOS'} — ${chaosLabel(list)} · ×${pay.toFixed(2)} PAY`, 3000);
  chaosRerollBtn(list);
  // Shrinks to a chip rather than disappearing: mid-round is exactly when a
  // player looks up wondering why the controls feel wrong.
  chaos.bannerTimer = setTimeout(() => el.classList.replace('big', 'chip'), 3200);
}

// 🌳 Signal Filter. The reroll is a control on the BANNER rather than a button
// somewhere in the hub, because the only moment the choice is live is the one
// where you have read what you rolled and the round has not started — which is
// exactly how long the banner is up at full size.
let chaosRerollLeft = 0;
function chaosRerollBtn(list){
  const el = document.getElementById('chaos-banner');
  let btn = document.getElementById('chaos-reroll');
  if(!el) return;
  // Never in a Network Arena round. The room's host rolls ONE modifier into the
  // room record and every client reads that id — a local reroll would leave the
  // two boards running different games while both believed the duel was fair.
  // (The perk is not wasted there: mp rounds do not consume the reroll either.)
  if(!list || mp || !hasPerk('perk-filter') || chaosRerollLeft <= 0){ if(btn) btn.remove(); return; }
  if(!btn){
    btn = document.createElement('button');
    btn.id = 'chaos-reroll';
    btn.className = 'chaos-reroll';
    el.appendChild(btn);
  }
  btn.textContent = `🎲 REROLL (${chaosRerollLeft})`;
  btn.onclick = () => {
    if(chaosRerollLeft <= 0) return;
    chaosRerollLeft--;
    snd('flip');
    // Rerolled into a stack of the same SHAPE: a Meltdown reroll that handed
    // back a single modifier would be a way to buy the tier's penalty off.
    const stacked = chaos.pending && chaos.pending.length > 1;
    let next = stacked ? chaosRollStack() : [chaosPickFrom(Math.random() < chaosBoonOdds() ? CHAOS_BOONS : CHAOS_HAZARDS)];
    if(stacked && !next.length) next = chaos.pending;
    chaos.pending = next;
    chaosAnnounce(chaos.pending);
  };
}

// Installed the moment the countdown ends, before the game starts.
// Accepts one modifier or a list; everything downstream reads chaos.stack.
function chaosArm(mod){
  const list = !mod ? [] : (Array.isArray(mod) ? mod.filter(Boolean) : [mod]);
  chaos.stack = chaos.lastStack = list;
  chaos.active = chaos.last = list[0] || null;
  if(!list.length) return;
  const on = id => list.some(c => c.id === id);

  if(on('inverse')) chaosInverse = true;
  if(on('double'))  chaosSpeedMul = 1.5;
  if(on('blind')){
    const area = document.querySelector('.g-area');
    chaos.blindTimer = setInterval(() => {
      if(!area) return;
      // 📸 Neither interval here runs on the round's frames, so neither saw
      // photo mode's freeze: the board went on blacking out and tilting under
      // a round that was meant to be standing still. Both skip while it is held.
      if(gPause.on) return;
      area.classList.add('blind-out');
      setTimeout(() => area.classList.remove('blind-out'), CHAOS_BLIND_FOR);
    }, CHAOS_BLIND_EVERY);
  }
  // 📉 PACKET LOSS. One interceptor in the capture phase, not twenty-one games
  // learning to ignore an input: a listener on window's capture phase sits
  // ahead of every bubble-phase handler in the document INCLUDING the
  // `window.onkeydown` property each game assigns, so stopping propagation
  // there is genuinely "this input never arrived".
  if(on('packet')){
    chaosDropOdds = 1 / 7;
    installPacketLoss();
  }
  // 📶 SIGNAL DEGRADATION is pure CSS over the play area. Nothing about the
  // round changes — which is the honest version of a rendering fault, and the
  // reason it can be armed over any of the twenty-one missions without one of
  // them knowing it exists.
  if(on('lowband')) document.querySelector('.g-area')?.classList.add('sig-degraded');
  // 🌀 AXIS DRIFT tilts the BOARD and boardPos() untilts the finger, so the
  // picture lies and the aim does not. Driven on a slow interval rather than in
  // a frame loop because there is no shared frame loop to hang it off — the DOM
  // missions have none at all.
  if(on('drift')){
    const frame = document.getElementById('board-frame');
    const area  = document.querySelector('.g-area');
    let phase = Math.random() * Math.PI * 2;
    chaosDriftTimer = setInterval(() => {
      if(gPause.on) return;
      phase += 0.065;
      chaosDrift = Math.sin(phase) * 0.20 + Math.sin(phase * 0.37) * 0.09;   // about 17 degrees
      const deg = (chaosDrift * 180 / Math.PI).toFixed(2);
      if(frame) frame.style.transform = `rotate(${deg}deg)`;
      else if(area) area.style.transform = `rotate(${deg}deg)`;
    }, 60);
  }
  // 🛡️ HARDENED SHELL arms the free absorb. Spent by chaosAbsorb() at whichever
  // fatal point asks first.
  if(on('bulwark')){
    chaosFreeShield = true;
    toast('🛡️ HARDENED SHELL ARMED — one fatal hit absorbed', 2600);
  }
  // ⚡ POINT SURGE and 📦 SUPPLY DROP arm nothing: they are entirely a fact
  // about what the round pays, and they are settled on the results card.
}

// The spend side of 🛡️ HARDENED SHELL, and the first thing every fatal point in
// the arcade asks before it asks about the shop's Shield Overlay — a free
// absorb must never be outlived by a consumable the player paid credits for.
function chaosAbsorb(){
  if(!chaosFreeShield) return false;
  chaosFreeShield = false;
  snd('shield');
  toast('🛡️ HARDENED SHELL ABSORBED THE HIT', 2000);
  return true;
}

// The one question every fatal point in the arcade should ask: "does anything
// stand between the player and this crash?" Free absorb first, then the paid
// consumable — and the caller does not need to know which one answered.
function survivedFatal(){
  return chaosAbsorb() || powerConsume('pu-shield', 'SHIELD ABSORBED');
}

// 🧯 CHAOS DAMPENER. Takes the handicaps off a round that is already running and
// leaves the windfalls alone, which is the whole reason it is worth buying: the
// stack you want to dampen is exactly the one that rolled a boon you would like
// to keep alongside a handicap you would not.
//
// Everything here is reversible BY CONSTRUCTION except one thing, and it is
// worth naming: DOUBLE SPEED halves every setInterval the game installed inside
// its own start() call, and those intervals were created once and cannot be
// slowed back down without reaching into each of twenty-one games. The
// hazard-speed multiplier that drives the frame-loop games does come back, so
// the round de-escalates — it just keeps whatever head start its clock took.
function chaosDampen(){
  const hazards = (chaos.stack || []).filter(c => c.kind === 'hazard');
  if(!hazards.length) return 0;

  chaosInverse = false;
  chaosSpeedMul = 1;
  removePacketLoss();

  clearInterval(chaos.blindTimer); chaos.blindTimer = 0;
  clearInterval(chaosDriftTimer);  chaosDriftTimer = 0; chaosDrift = 0;

  const frame = document.getElementById('board-frame');
  if(frame) frame.style.transform = '';
  const area = document.querySelector('.g-area');
  if(area){
    area.style.transform = '';
    area.classList.remove('blind-out', 'sig-degraded', 'pkt-drop');
  }

  // Put the two arrow buttons back the way the game bound them.
  if(chaosPadSwap){
    const { L, R, lc, rc, lp, rp } = chaosPadSwap;
    if(L && R){
      L.onclick = lc; R.onclick = rc;
      if(lp && rp){ bindHold(L, lp.down, lp.up); bindHold(R, rp.down, rp.up); }
    }
    chaosPadSwap = null;
  }

  // The stack keeps only what survived, so the results card pays for the boon
  // and stops pretending the handicaps were endured.
  chaos.stack = chaos.lastStack = (chaos.stack || []).filter(c => c.kind !== 'hazard');
  chaos.active = chaos.last = chaos.stack[0] || null;
  chaosAnnounce(chaos.stack.length ? chaos.stack : null);
  return hazards.length;
}

let _packetBound = null;
function installPacketLoss(){
  if(_packetBound) return;
  const drop = e => {
    if(!chaosDropOdds) return;
    // 📸 A held round takes no input for this to lose — every press on a
    // frozen board is the CAMERA's (Esc, H, the orbit drag), and dropping one
    // in seven of those is a broken photo mode, not a modifier.
    if(gPause.on) return;
    if(Math.random() >= chaosDropOdds) return;
    // A keystroke is always fair game. A pointer input only counts when it
    // lands on the play surface — dropping a press on Quit or on the power-up
    // dock would be a modifier that eats the controls of the arcade itself
    // rather than the controls of the round.
    const t = e.target;
    if(e.type !== 'keydown'){
      const area = document.querySelector('.g-area');
      if(!area || !t || !area.contains(t)) return;
      if(t.closest && t.closest('#pu-dock')) return;
    }
    // touchstart's own preventDefault never runs now that the game will not see
    // it, so do it here: otherwise the browser synthesises a mouse event and
    // the "dropped" tap arrives anyway, down the other path.
    if(e.cancelable && e.type === 'touchstart') e.preventDefault();
    e.stopImmediatePropagation();
    e.stopPropagation();
    flashPacketLoss();
  };
  const types = ['keydown', 'click', 'mousedown', 'touchstart'];
  types.forEach(t => window.addEventListener(t, drop, true));
  _packetBound = () => types.forEach(t => window.removeEventListener(t, drop, true));
}
function removePacketLoss(){
  chaosDropOdds = 0;
  if(_packetBound){ _packetBound(); _packetBound = null; }
}
// Deliberately a whisper, not an alert. The modifier's whole character is that
// you cannot tell a dropped input from your own mistake until the pattern adds
// up — a big red "DROPPED" would turn it into a fair, readable handicap.
function flashPacketLoss(){
  const area = document.querySelector('.g-area');
  if(!area) return;
  area.classList.remove('pkt-drop');
  void area.offsetWidth;
  area.classList.add('pkt-drop');
}
// Runs a game's start function under the active modifier.
//
// The setInterval swap is scoped to the SYNCHRONOUS call: every game installs
// its clock inside start(), so this catches exactly the intervals that belong
// to the round and none of the arcade's own (the music scheduler, the shop
// rotation ticker, the versus pacer) — all of which were created long before
// this line and are never re-created here.
function chaosRun(startFn){
  // Reads the STACK, not the first entry: on Meltdown the doubling can be
  // the second modifier of two, and asking chaos.active would have quietly
  // dropped it on exactly the tier that rolled it.
  const doubling = chaos.stack.some(c => c.id === 'double');
  const realSetInterval = window.setInterval;
  if(doubling){
    window.setInterval = function(fn, ms, ...rest){
      const scaled = typeof ms === 'number' && ms > 0 ? Math.max(8, ms / 2) : ms;
      return realSetInterval.call(window, fn, scaled, ...rest);
    };
  }
  try{
    startFn();
  } finally {
    if(doubling) window.setInterval = realSetInterval;
  }

  // Keyboard, after the fact: the game has just assigned its own handler, so
  // this wraps whatever is there instead of racing it. `code` and `key` are
  // read-only on a real KeyboardEvent, so the handler is handed a shim that
  // answers the swapped value and forwards everything else untouched.
  if(chaosInverse){
    const flip = h => h && (e => h(chaosMirrorKey(e)));
    window.onkeydown = flip(window.onkeydown) || window.onkeydown;
    window.onkeyup   = flip(window.onkeyup)   || window.onkeyup;

    // The on-screen pad is the other direction input. Swapping the two arrow
    // buttons' behaviour — rather than their labels — keeps ◀ where the eye
    // expects it while making it do what ▶ would have.
    const L = document.getElementById('ctrl-left'), R = document.getElementById('ctrl-right');
    if(L && R){
      const lc = L.onclick, rc = R.onclick;
      L.onclick = rc; R.onclick = lc;
      // A held direction is bound through bindHold, whose listeners are closed
      // over and cannot be read back — so the swap re-binds each button to the
      // other's recorded press/release pair. bindHold() clears the old binding
      // itself, which is why the pairs are captured before either call.
      const lp = L._holdPair, rp = R._holdPair;
      if(lp && rp){
        bindHold(L, rp.down, rp.up);
        bindHold(R, lp.down, lp.up);
      }
      // Recorded so 🧯 CHAOS DAMPENER can put them back. Everything else the
      // inversion does is a flag boardPos() and the key shim read live, so
      // clearing chaosInverse undoes it on the next input — the pad is the one
      // part that was a permanent rebinding, and a dampener that fixed the
      // stick and the keyboard while leaving the two arrows crossed would be
      // worse than one that did nothing.
      chaosPadSwap = { L, R, lc, rc, lp, rp };
    }
  }
}

// Returns an event-shaped object whose direction fields are mirrored. Only the
// fields a game actually reads are overridden; everything else — including
// preventDefault, which several games call — is delegated to the real event.
const CHAOS_KEY_SWAP = {
  ArrowLeft:'ArrowRight', ArrowRight:'ArrowLeft', ArrowUp:'ArrowDown', ArrowDown:'ArrowUp',
  KeyA:'KeyD', KeyD:'KeyA', KeyW:'KeyS', KeyS:'KeyW',
  a:'d', d:'a', w:'s', s:'w', A:'D', D:'A', W:'S', S:'W'
};
function chaosMirrorKey(e){
  // The wrapper installed by chaosRun() cannot be un-installed — the handler it
  // wrapped is a property the game assigned and there is no way to hand it back.
  // So the mirroring is decided HERE, on every event, off the live flag: clear
  // chaosInverse and the very next keystroke arrives untouched.
  if(!chaosInverse) return e;
  const code = CHAOS_KEY_SWAP[e.code] || e.code;
  const key  = CHAOS_KEY_SWAP[e.key]  || e.key;
  if(code === e.code && key === e.key) return e;   // not a direction — pass it straight through
  return {
    code, key,
    shiftKey: e.shiftKey, ctrlKey: e.ctrlKey, altKey: e.altKey, metaKey: e.metaKey,
    repeat: e.repeat, type: e.type, target: e.target,
    preventDefault: () => e.preventDefault(),
    stopPropagation: () => e.stopPropagation()
  };
}

function chaosClear(){
  chaosInverse = false;
  chaosSpeedMul = 1;
  chaosFreeShield = false;
  removePacketLoss();
  clearInterval(chaos.blindTimer); chaos.blindTimer = 0;
  clearTimeout(chaos.bannerTimer); chaos.bannerTimer = 0;
  // 🌀 AXIS DRIFT leaves a transform on a SHARED element. Left behind it tilts
  // the next round, the results card behind it and the hub — and nothing in
  // those places would ever explain why, because the round that caused it is
  // over. Cleared to the empty string rather than 'none' so the stylesheet's
  // own transform, if it ever gains one, still applies.
  clearInterval(chaosDriftTimer); chaosDriftTimer = 0; chaosDrift = 0;
  const frame = document.getElementById('board-frame');
  if(frame) frame.style.transform = '';
  const area = document.querySelector('.g-area');
  if(area){
    area.style.transform = '';
    area.classList.remove('blind-out', 'sig-degraded', 'pkt-drop');
  }
  const el = document.getElementById('chaos-banner');
  if(el){ el.style.display = 'none'; el.className = ''; }
  document.getElementById('chaos-reroll')?.remove();
  // IDEMPOTENT, and it has to be. stopGame() runs this, and stopGame() legitimately
  // runs more than once per round — Boss Rush stops the finished stage itself
  // before showResults() stops it again, a duel that ends as it is quit hits
  // both paths, and every ending that tidies up before reporting does the same.
  // Rolling `active` into `last` unconditionally meant the SECOND call recorded
  // "no modifier", so the results card silently dropped the chaos row and paid
  // the round at ×1 — a modifier the player had just spent the whole round
  // fighting, unpaid and unmentioned. Only a live stack is worth remembering.
  if(chaos.stack.length || chaos.active){
    chaos.last = chaos.active;      // survives into the results card
    chaos.lastStack = chaos.stack;  // and so does the whole stack
  }
  chaos.active = null;
  chaos.stack = [];
}

// ══════════════════════════════════════════════════════════════════════
//  🌀 CHAOS PROTOCOL — the opt-in
// ══════════════════════════════════════════════════════════════════════
// Until now a solo player could only meet a modifier inside Boss Rush or a
// Network Arena room, which meant the pool was invisible from the one screen
// anybody spends time on. Arming it here rolls one before every mission.
//
// It is deliberately NOT a third difficulty tier. The stability dial is a
// straight trade — more speed for more points, chosen in advance and the same
// every round. This is a gamble: you do not know what you are getting, a third
// of the pool is in your favour, and both halves pay. Two different appetites,
// two different controls, and a player can arm either, both or neither.
//
// Local, not on the profile: it is a preference about how you like to play
// rather than a fact about what you have earned, and it should follow the
// machine you are sitting at.
const CHAOS_OPTIN_KEY = 'pi_chaos_optin';
let chaosOptIn = (() => {
  try{ return localStorage.getItem(CHAOS_OPTIN_KEY) === '1'; }catch(e){ return false; }
})();

function setChaosOptIn(on){
  chaosOptIn = !!on;
  try{ localStorage.setItem(CHAOS_OPTIN_KEY, chaosOptIn ? '1' : '0'); }catch(e){}
  paintChaosToggle();
}

function paintChaosToggle(){
  const btn = document.getElementById('chaos-toggle');
  const sel = document.getElementById('chaos-selector');
  const state = document.getElementById('chaos-state');
  const note = document.getElementById('chaos-note');
  if(!btn) return;
  btn.classList.toggle('on', chaosOptIn);
  btn.setAttribute('aria-checked', String(chaosOptIn));
  sel?.classList.toggle('armed', chaosOptIn);
  if(state) state.textContent = chaosOptIn ? 'ARMED' : 'DISARMED';
  if(note){
    // Says what it will actually do at the tier that is selected right now,
    // because "one modifier" and "two modifiers" are very different offers and
    // the stability dial is the thing that decides which one you get.
    note.textContent = !chaosOptIn
      ? 'Roll a modifier before every mission — handicaps and windfalls both pay.'
      : currentDifficultyTier === CHAOS_STACK_TIER
        ? `Rolling ${Math.round(CHAOS_ODDS * 100)}% of rounds · MELTDOWN STACKS TWO · up to ×2.6 pay`
        : `Rolling ${Math.round(CHAOS_ODDS * 100)}% of rounds · ${CHAOS_HAZARDS.length} handicaps, ${CHAOS_BOONS.length} windfalls`;
  }
}

document.getElementById('chaos-toggle')?.addEventListener('click', () => {
  setChaosOptIn(!chaosOptIn);
  snd(chaosOptIn ? 'alarm' : 'click');
  if(chaosOptIn) toast('🌀 CHAOS PROTOCOL ARMED — every mission rolls the dice', 2800);
});
paintChaosToggle();

// ══════════════════════════════════════════════════════════════════════
//  📈 LEVELS & THE PERK TREE
// ══════════════════════════════════════════════════════════════════════
// XP is a flat tenth of every point awarded, and a level is a flat 100 XP — no
// curve, because the interesting number is already the score and a second
// curve on top of it would just make the first one harder to read.
//
// Levels are DERIVED from lifetime XP rather than stored as a running counter,
// so they can never drift out of step with it: a profile that syncs XP from
// two devices lands on the right level by arithmetic instead of by luck.
const XP_PER_LEVEL = 100;
const XP_RATE = 0.1;

function xpLevel(xp){
  const total = Math.max(0, Math.floor(xp || 0));
  const level = Math.floor(total / XP_PER_LEVEL) + 1;
  return { level, into: total % XP_PER_LEVEL, need: XP_PER_LEVEL, total };
}
// One point per level gained, first level free.
const perkPointsEarned = xp => xpLevel(xp).level - 1;
const perkPointsLeft   = () => user ? perkPointsEarned(user.xp) - (user.perkSpent || 0) : 0;

// A TREE, not a shelf. Two things make it one: `needs` names the node that has
// to be owned first, and cost rises with depth — so a point spent at the top is
// a decision about which branch you are going down rather than a purchase you
// were always going to make.
//
// The shape is deliberate. Every tier-1 node is an unconditional, boring,
// always-on percentage: those are the ones a new player can evaluate without
// knowing anything about the arcade. Everything below them is CONDITIONAL — it
// pays when you beat a ghost, when you roll a modifier, when you keep a streak
// — and a conditional bonus is only worth a point once you know you are the
// sort of player who meets that condition. The tree teaches its own economy in
// the order you walk it.
//
// `effect` is the one-line rule. `desc` is why it exists and what it interacts
// with; the tree shows both, because a perk whose interactions are invisible is
// a perk nobody can plan around.
const PERKS = [
  // ── TIER 1 · the unconditional percentages ──
  { id:'perk-score', icon:'📈', name:'Signal Amplifier', cost:1, tier:1,
    effect:'+5% score on arcade missions',
    desc:'Every solo mission and Boss Rush chain pays five percent more. Duel awards are untouched — a duel is already paying a win bonus, and Netrunner is the node for those.' },
  { id:'perk-ram',   icon:'🧠', name:'Accelerated RAM',  cost:1, tier:1,
    effect:'+25% RAM regen in Battle Bots',
    desc:'The siege economy fills faster, and the throughput upgrades you buy scale with it.' },
  { id:'perk-duel',  icon:'⚔️', name:'Netrunner',        cost:1, tier:1,
    effect:'+8% on every Network Arena award',
    desc:'The mirror of Signal Amplifier, on the side of the arcade it deliberately skips. Applies to a win and a loss alike: showing up to a duel you lose is still the hardest points in the game to earn.' },
  { id:'perk-xp',    icon:'🧬', name:'Neural Uplink',    cost:1, tier:1,
    effect:'+25% XP from every finished round',
    desc:'The only node that buys more nodes. Worth taking first if you intend to take many — and worth skipping entirely if you are here for one branch.' },

  // ── TIER 2 · the conditional ones ──
  { id:'perk-echo',    icon:'👻', name:'Echo Trace',     cost:2, tier:2, needs:'perk-score',
    effect:'+10% on any run that beats your pace ghost',
    desc:'Pays for the run you were already proud of. Needs a personal best on that mission and tier to race, so it is worth nothing on a mission you have never played and a great deal on the one you keep coming back to.' },
  { id:'perk-broker',  icon:'💱', name:'Data Broker',    cost:2, tier:2, needs:'perk-score',
    effect:'Points convert to credits at 70 instead of 100',
    desc:'A thirty percent discount on every cosmetic, consumable and exit state in the market. Converting the other way is unchanged — the broker buys, it does not sell.' },
  { id:'perk-filter',  icon:'🎲', name:'Signal Filter',  cost:2, tier:2, needs:'perk-xp',
    effect:'One chaos reroll per round',
    desc:'A REROLL button appears on the chaos banner while it is still full size. Rerolls into a stack of the same size, so a Meltdown round cannot buy its second modifier off.' },
  { id:'perk-pockets', icon:'🎒', name:'Deep Pockets',   cost:2, tier:2, needs:'perk-duel',
    effect:'Your kit holds twice as many of each consumable',
    desc:'Nine of each becomes eighteen. Matters most for Supply Drop, which refuses to pay out into a full kit.' },
  { id:'perk-cold',    icon:'❄️', name:'Cold Storage',   cost:2, tier:2, needs:'perk-xp',
    effect:'A streak survives one missed day',
    desc:'Thirty days running is the longest commitment the arcade asks for, and it used to end on one bad Tuesday. Two missed days in a row still breaks it.' },

  // ── TIER 3 · the ones that change how you play ──
  { id:'perk-wildcard', icon:'🃏', name:'Wildcard Protocol', cost:3, tier:3, needs:'perk-filter',
    effect:'Chaos rolls a windfall twice as often',
    desc:'Does not make chaos more frequent — makes more of it good. Together with Signal Filter it turns an armed Chaos Protocol from a tax into an edge.' },
  { id:'perk-salvage',  icon:'♻️', name:'Salvage Routine',  cost:3, tier:3, needs:'perk-broker',
    effect:'+1 credit for any run that takes 60% of a mission cap',
    desc:'The first income in the arcade that is not an achievement or a streak — a slow, reliable trickle for playing well rather than for playing long.' },
  { id:'perk-reserve',  icon:'⏳', name:'Chrono Reserve',   cost:3, tier:3, needs:'perk-pockets',
    effect:'A free Time Dilator in your kit each day',
    desc:'Collected the first time you reach the hub on a new UTC day, and skipped when the kit is already full of them.' }
];

const hasPerk = id => !!(user && user.perks && user.perks[id]);

// 🌳 Perk A. Applied in showResultsCard(), which is the one place a raw score
// becomes an award — the same seam the stability tier uses.
function perkScoreMult(gid, opts){
  // ⚔️ A duel card is the one place Signal Amplifier deliberately does not
  // reach, which is exactly why Netrunner exists — same seam, other side.
  if(opts && opts.internal) return hasPerk('perk-duel') ? 1.08 : 1;
  if(!hasPerk('perk-score')) return 1;
  if(!SOLO_START[gid] && gid !== 'bossrush' && gid !== 'endless') return 1;
  return 1.05;
}
// 🌳 Perk B. Read once by startBattleBots().
const perkRamMult = () => hasPerk('perk-ram') ? 1.25 : 1;

// Granted on every finished round, online or off.
function awardXp(award){
  if(!user || !(award > 0)) return;
  const before = xpLevel(user.xp || 0).level;
  // 🌳 Neural Uplink. Applied to the GRANT rather than to the level threshold,
  // so a profile that owns it and a profile that does not still mean the same
  // thing by "level 12" — one of them just got there faster.
  const xpMult = hasPerk('perk-xp') ? 1.25 : 1;
  user.xp = Math.max(0, Math.floor((user.xp || 0) + award * XP_RATE * xpMult));
  const after = xpLevel(user.xp).level;
  user.level = after;
  saveProfilePatch({ xp: user.xp, level: after });
  if(after > before){
    // Held back so it lands on the results card rather than under the death
    // sting the round is still playing.
    setTimeout(() => {
      snd('levelUp');
      const opened = Object.keys(SOLO_START)
        .filter(g => missionClearance(g) > before && missionClearance(g) <= after);
      toast(`📈 LEVEL ${after} — +${after - before} PERK POINT${after - before === 1 ? '' : 'S'}` +
            (opened.length ? ` · 🔓 ${opened.length} MISSION${opened.length === 1 ? '' : 'S'} DECLASSIFIED` : ''), 3600);
      // 🔒 Repaint straight away: the card the level just opened is on screen
      // behind the results card, and finding it still locked when you get back
      // to the hub reads as the level-up not having happened.
      paintMissionLocks();
    }, 1500);
  }
  paintXpRail();
}

function paintXpRail(){
  if(!user) return;
  const st = xpLevel(user.xp || 0);
  const lvl = document.getElementById('xp-lvl');
  const fill = document.getElementById('xp-fill');
  const num = document.getElementById('xp-num');
  const btn = document.getElementById('btn-perks');
  if(lvl)  lvl.textContent = `LVL ${st.level}`;
  if(fill) fill.style.width = `${(st.into / st.need) * 100}%`;
  if(num)  num.textContent = `${st.into} / ${st.need} XP · ${st.total.toLocaleString()} TOTAL`;
  // The tree button carries the count when there is something to spend, so the
  // "you have unspent points" nudge and the door to spend them are one control
  // rather than two competing for the same strip.
  const left = perkPointsLeft();
  if(btn){
    btn.textContent = left > 0 ? `🌳 ${left} PERK POINT${left === 1 ? '' : 'S'}` : '🌳 PERK TREE';
    btn.classList.toggle('btn-primary', left > 0);
    btn.classList.toggle('btn-secondary', left === 0);
    btn.classList.toggle('xp-perk-btn', left > 0);
  }
  document.getElementById('xp-rail')?.classList.toggle('has-points', left > 0);
  // 🎖️ The season button carries its own progress, and it lives on this rail,
  // so it repaints with it rather than needing its own hook on every path that
  // changes a score.
  if(typeof paintSeasonRail === 'function') paintSeasonRail();
}

// A node is OPEN when its prerequisite is owned and you can afford it, LOCKED
// when you cannot afford it, and BARRED when the branch above it is not yet
// unlocked. Three states rather than two, because "you have the points but not
// the parent" and "you have the parent but not the points" are different
// problems and a player has to be able to tell which one they are looking at.
const perkParent = p => p.needs ? PERKS.find(x => x.id === p.needs) : null;
const perkOpen   = p => !p.needs || hasPerk(p.needs);

function renderPerkTree(){
  const wrap = document.getElementById('perk-tree');
  if(!wrap || !user) return;
  const left = perkPointsLeft();
  const sub = document.getElementById('perk-sub');
  const st = xpLevel(user.xp || 0);
  const owned = PERKS.filter(p => hasPerk(p.id)).length;
  if(sub){
    sub.textContent = left > 0
      ? `Level ${st.level} · ${left} point${left === 1 ? '' : 's'} to spend · ${owned}/${PERKS.length} nodes`
      : `Level ${st.level} · ${st.need - st.into} XP to the next point · ${owned}/${PERKS.length} nodes`;
  }
  wrap.innerHTML = '';

  // Drawn tier by tier so the tree reads down the page in the order it is
  // walked. The rows are what make it a tree on screen — a flat list of twelve
  // cards would hide the one thing that matters about them, which is that half
  // of them cannot be bought yet.
  const TIER_LABEL = {
    1: { name: 'FOUNDATION', note: 'Always on. No conditions, no branches — take what you want first.' },
    2: { name: 'SPECIALISATION', note: 'Each one needs a foundation node. These pay when you meet their condition.' },
    3: { name: 'DOCTRINE', note: 'The deep nodes. Each changes how a whole system behaves rather than what it pays.' }
  };

  [1, 2, 3].forEach(tier => {
    const nodes = PERKS.filter(p => p.tier === tier);
    if(!nodes.length) return;
    const meta = TIER_LABEL[tier] || { name: `TIER ${tier}`, note: '' };
    const row = document.createElement('div');
    row.className = 'perk-row';
    row.innerHTML =
      `<div class="perk-tier-hdr"><span class="perk-tier-name">${esc(meta.name)}</span>` +
      `<span class="perk-tier-cost">${nodes[0].cost} PT${nodes[0].cost === 1 ? '' : 'S'} EACH</span>` +
      `<span class="perk-tier-note">${esc(meta.note)}</span></div>` +
      `<div class="perk-row-nodes"></div>`;
    const holder = row.querySelector('.perk-row-nodes');

    nodes.forEach(p => {
      const own = hasPerk(p.id);
      const open = perkOpen(p);
      const afford = left >= p.cost;
      const parent = perkParent(p);
      const state = own ? 'owned' : !open ? 'barred' : afford ? 'open' : 'locked';
      const node = document.createElement('div');
      node.className = `perk-node ${state}`;
      // The children a node unlocks are named on the node itself. Without it a
      // tier-1 perk looks like four interchangeable percentages, and the choice
      // of which to take first — which is the only real decision in the tree —
      // is being made blind.
      const kids = PERKS.filter(x => x.needs === p.id);
      node.innerHTML =
        `<span class="perk-ico">${p.icon}</span>` +
        `<div class="perk-name">${esc(p.name)}</div>` +
        `<div class="perk-effect">${esc(p.effect)}</div>` +
        `<div class="perk-desc">${esc(p.desc)}</div>` +
        (parent ? `<div class="perk-needs${open ? ' met' : ''}">` +
                  `${open ? '✔' : '🔒'} needs ${parent.icon} ${esc(parent.name)}</div>` : '') +
        (kids.length ? `<div class="perk-kids">→ unlocks ${kids.map(k => `${k.icon} ${esc(k.name)}`).join(', ')}</div>` : '') +
        (own
          ? `<div class="perk-tag">✔ ACTIVE</div>`
          : `<button class="btn ${open && afford ? 'btn-primary' : 'btn-secondary'} btn-sm perk-buy" data-perk="${p.id}"` +
            `${open && afford ? '' : ' disabled'}>` +
            `${!open ? `Locked behind ${esc(parent.name)}`
                     : afford ? `Unlock · ${p.cost} PT${p.cost === 1 ? '' : 'S'}`
                              : `Needs ${p.cost - left} more point${p.cost - left === 1 ? '' : 's'}`}</button>`);
      holder.appendChild(node);
    });
    wrap.appendChild(row);
  });

  wrap.querySelectorAll('.perk-buy').forEach(b => {
    b.onclick = () => buyPerk(b.dataset.perk);
  });
}

// ⏳ Chrono Reserve's payout. Collected on reaching the hub rather than on a
// timer, because "each day" has to mean "the first time you turn up that day"
// for a profile that is only open for ten minutes at a time.
function perkDailyGrant(){
  if(!user || !hasPerk('perk-reserve')) return;
  const today = dayKey();
  if(user.perkDay === today) return;
  user.perkDay = today;
  const item = findItem('powerups', 'pu-dilator');
  const held = powerHeld('pu-dilator');
  // A full kit is not an error and must not burn the day's grant silently —
  // leaving perkDay unwritten means it is offered again on the next visit,
  // once something has been spent.
  if(item && held >= stackCapFor(item)){ user.perkDay = null; return; }
  user.powerups['pu-dilator'] = held + 1;
  saveProfilePatch({ perkDay: today, ['powerups/pu-dilator']: user.powerups['pu-dilator'] });
  snd('purchase');
  toast(`⏳ CHRONO RESERVE — a Time Dilator has been added to your kit`, 3000);
  paintPowerKit();
}

async function buyPerk(id){
  const perk = PERKS.find(p => p.id === id);
  if(!perk || !user || hasPerk(id)) return;
  // Checked here as well as in the markup: the button is the polite refusal,
  // this is the real one. A tree whose prerequisites live only in the rendering
  // is a tree anyone can walk past with a console open.
  if(!perkOpen(perk)){
    const parent = perkParent(perk);
    snd('deny');
    toast(`🔒 ${perk.name} needs ${parent ? parent.name : 'an earlier node'} first.`, 2800);
    return;
  }
  if(perkPointsLeft() < perk.cost){ snd('deny'); toast('⚠️ Not enough perk points.'); return; }
  user.perks[id] = true;
  user.perkSpent = (user.perkSpent || 0) + perk.cost;
  await saveProfilePatch({ ['perks/' + id]: true, perkSpent: user.perkSpent });
  snd('levelUp');
  toast(`🌳 PERK UNLOCKED — ${perk.name}`, 3000);
  renderPerkTree();
  paintXpRail();
}

// ══════════════════════════════════════════════════════════════════════
//  ⚡ POWER-UPS — the consumable kit
// ══════════════════════════════════════════════════════════════════════
// Four consumables, three different shapes, and the difference is the whole
// design:
//
//   ⏳ TIME DILATOR   is PRESSED. It needs a live clock to add to, and the one
//                     thing every game with a clock shares is #g-time — so the
//                     dock reads that element, adds three, and writes it back.
//                     No game exposes its timer variable and none needs to.
//
//   🛡️ SHIELD OVERLAY is not pressed at all. It is armed for the round and
//                     spent by the crash it absorbs — which is why every fatal
//                     point in the arcade calls survivedFatal() rather than the
//                     dock doing anything. It used to be honoured by two
//                     missions out of eighteen, so a player bought a shield and
//                     then watched it not work in the sixteen places they
//                     happened to die; it now covers every mission that can end
//                     in a single fatal event, in both renderers.
//
//   ⚙️ OVERCLOCK CHIP is pressed and then does NOTHING for the rest of the
//                     round: it is a fact about what this round PAYS, settled on
//                     the results card next to the tier and the perk. That makes
//                     it the one consumable with no mission-specific behaviour
//                     at all, so it works on all twenty-one including the two
//                     that run on an infinite clock.
//
//   🧯 CHAOS DAMPENER is pressed and reaches back into the modifier engine —
//                     see chaosDampen(), which is written to be reversible for
//                     exactly this reason.
const powerHeld = id => (user && user.powerups && +user.powerups[id]) || 0;

// Spends one, if there is one. Returns whether it fired, so a caller can use it
// directly as the condition on a crash.
function powerConsume(id, label){
  if(powerHeld(id) <= 0) return false;
  user.powerups[id] = powerHeld(id) - 1;
  saveProfilePatch({ ['powerups/' + id]: user.powerups[id] });
  const item = findItem('powerups', id);
  snd('shield');
  toast(`${item ? item.emoji : '⚡'} ${label || (item && item.name) || 'POWER-UP SPENT'} · ${user.powerups[id]} left`, 2200);
  flashPowerDock(id);
  paintPowerDock();
  return true;
}

// 🌳 Deep Pockets raises what the kit will HOLD rather than what anything costs,
// which is the only version of that perk that is worth a point: credits already
// buy consumables, so a discount is just a slower version of playing more.
function stackCapFor(item){
  const base = (item && item.stack) || 9;
  return hasPerk('perk-pockets') ? base * 2 : base;
}

// 📦 SUPPLY DROP's payout, and the one path into the kit that is not a purchase.
// Refuses to hand over something the kit has no room for, and says so — a boon
// that silently evaporated would read as a bug in the boon.
function grantRandomConsumable(){
  if(!user) return null;
  const pool = SHOP_ITEMS.powerups.filter(i => powerHeld(i.id) < stackCapFor(i));
  if(!pool.length){ toast('📦 SUPPLY DROP REFUSED — kit is full', 2600); return null; }
  const item = pool[Math.floor(Math.random() * pool.length)];
  user.powerups[item.id] = powerHeld(item.id) + 1;
  saveProfilePatch({ ['powerups/' + item.id]: user.powerups[item.id] });
  snd('purchase');
  toast(`📦 SUPPLY DROP — ${item.emoji} ${item.name} added to your kit`, 3000);
  paintPowerKit();
  paintPowerDock();
  return item;
}

// ── THE IN-GAME DOCK ──
function showPowerDock(){
  const dock = document.getElementById('pu-dock');
  if(!dock) return;
  // A duel is a fair fight by construction — both boards run the same tier and
  // the same modifier — so the kit stays out of it.
  if(mp){ dock.style.display = 'none'; return; }
  paintPowerDock();
}
function hidePowerDock(){
  const dock = document.getElementById('pu-dock');
  if(dock){ dock.style.display = 'none'; dock.innerHTML = ''; }
}

function paintPowerDock(){
  const dock = document.getElementById('pu-dock');
  if(!dock || !user || mp) return;
  // 🎒 A loadout can nominate which consumable this build leads with. It is a
  // SORT, not a filter: the kit is still the whole kit, the named one is just
  // the one first under the thumb.
  const stock = SHOP_ITEMS.powerups.filter(i => powerHeld(i.id) > 0)
    .sort((a, b) => (b.id === loadoutLeadId ? 1 : 0) - (a.id === loadoutLeadId ? 1 : 0));
  if(!stock.length){ dock.style.display = 'none'; dock.innerHTML = ''; return; }
  // The shield is passive, so its button is a READOUT rather than a control —
  // it says "armed", and the crash that spends it is what presses it.
  dock.style.display = 'flex';
  dock.innerHTML = stock.map(i => {
    // The shield is the only PASSIVE one: it is spent by the crash it absorbs
    // rather than by a press, so its button is a readout. An overclocked round
    // reads the same way once the chip has been spent — there is nothing left
    // to press, and a live-looking button that refuses every press is worse
    // than one that says what it already did.
    const passive = i.id === 'pu-shield' || (i.id === 'pu-overclock' && runOverclock);
    return `<button class="pu-btn${passive ? ' passive' : ''}" data-pu="${i.id}"${passive ? ' disabled' : ''}
                    title="${esc(i.desc)}">
              <span class="pu-emoji">${i.emoji}</span>
              <span class="pu-label">${passive ? (i.id === 'pu-overclock' ? 'RUNNING' : 'ARMED') : esc(i.name)}</span>
              <span class="pu-count">${powerHeld(i.id)}</span>
            </button>`;
  }).join('');
  dock.querySelectorAll('.pu-btn:not(.passive)').forEach(b => {
    b.onclick = () => usePowerUp(b.dataset.pu);
  });
}

function flashPowerDock(id){
  const btn = document.querySelector(`.pu-btn[data-pu="${id}"]`);
  if(!btn) return;
  btn.classList.remove('fired');
  void btn.offsetWidth;
  btn.classList.add('fired');
}

const TIME_DILATOR_SECONDS = 3;

const OVERCLOCK_CHIP_MULT = 1.3;

function usePowerUp(id){
  if(id === 'pu-overclock') return useOverclockChip();
  if(id === 'pu-dampener')  return useChaosDampener();
  if(id !== 'pu-dilator') return;
  const el = document.getElementById('g-time');
  const raw = el ? el.textContent.trim() : '';
  const secs = parseClockText(raw);
  // Nothing to dilate: Flappy and Cyber Arena run on ∞, and a game between
  // rounds shows a dash. Refusing costs nothing; spending on nothing costs 5 CR.
  if(secs == null){
    snd('deny');
    toast('⏳ No clock to dilate on this mission.', 2400);
    return;
  }
  if(!powerConsume('pu-dilator', `+${TIME_DILATOR_SECONDS}s DILATED`)) return;
  const next = secs + TIME_DILATOR_SECONDS;
  if(roundClockAdd){
    // The mission owns its counter and has handed over the door to it, so the
    // seconds are genuinely added and the readout can be written to match.
    try{ roundClockAdd(TIME_DILATOR_SECONDS); }catch(e){ console.warn('Clock hook failed:', e); }
    el.textContent = raw.includes(':') ? fmtTime(next) : String(next);
  }else{
    // The fallback: hold the clock for three of its own ticks. Deliberately NO
    // write to the element — a +3 the mission overwrites a second later with
    // secs-1 is a four-second jump BACKWARDS, which reads as a bug. A clock
    // that visibly stops for three seconds reads as exactly what it is.
    _clockSkip += TIME_DILATOR_SECONDS;
  }
  // Its own countdown is the game's business; the progress bar is shared, and
  // leaving it where it was would show a full bar draining from the wrong place.
  const bar = document.getElementById('prog-fill');
  if(bar){
    const pct = parseFloat(bar.style.width) || 0;
    bar.style.width = Math.min(100, pct * (next / Math.max(1, secs))) + '%';
  }
  document.querySelector('.g-area')?.classList.add('dilated');
  setTimeout(() => document.querySelector('.g-area')?.classList.remove('dilated'), 700);
}

// ⚙️ OVERCLOCK CHIP. Unlike the dilator it asks nothing of the round — no clock
// to read, no state to write — so it is the one consumable that works on all
// twenty-one missions with no exceptions, including the two that run on ∞.
function useOverclockChip(){
  if(runOverclock){ snd('deny'); toast('⚙️ This round is already overclocked.', 2200); return; }
  if(!document.getElementById('game-screen').classList.contains('active')){
    snd('deny'); toast('⚙️ Nothing to overclock — start a round first.', 2400); return;
  }
  if(!powerConsume('pu-overclock', `OVERCLOCKED · +${Math.round((OVERCLOCK_CHIP_MULT - 1) * 100)}%`)) return;
  runOverclock = OVERCLOCK_CHIP_MULT;
  document.querySelector('.g-area')?.classList.add('overclocked-run');
}

// 🧯 CHAOS DAMPENER. Refuses rather than burns itself when there is nothing to
// dampen — a clean round and a round carrying only a windfall both have zero
// handicaps on them, and spending eight credits to confirm that is not a
// purchase anyone would make twice.
function useChaosDampener(){
  const hazards = (chaos.stack || []).filter(c => c.kind === 'hazard').length;
  if(!hazards){
    snd('deny');
    toast('🧯 Nothing to dampen — no handicap running.', 2400);
    return;
  }
  if(!powerConsume('pu-dampener', 'HANDICAPS DAMPENED')) return;
  const killed = chaosDampen();
  toast(`🧯 ${killed} HANDICAP${killed === 1 ? '' : 'S'} SHUT DOWN`, 2600);
}

// The shared clock element carries three shapes: a plain count of seconds, an
// m:ss readout from fmtTime(), and the placeholders (∞, —) games without a
// clock use. Returns seconds, or null when there is no clock to speak of.
function parseClockText(txt){
  if(!txt || txt === '∞' || txt === '—') return null;
  if(txt.includes(':')){
    const [m, s] = txt.split(':').map(n => parseInt(n, 10));
    return Number.isFinite(m) && Number.isFinite(s) ? m * 60 + s : null;
  }
  const n = parseInt(txt, 10);
  return Number.isFinite(n) ? n : null;
}

// The kit summary at the top of the market's Power-Ups tab.
function paintPowerKit(){
  const el = document.getElementById('pu-kit');
  if(!el || !user) return;
  const stock = SHOP_ITEMS.powerups.filter(i => powerHeld(i.id) > 0);
  el.innerHTML = stock.length
    ? `<div class="pu-kit-lbl">⚡ IN YOUR KIT</div><div class="pu-kit-row">` +
      stock.map(i => `<span class="pu-chip">${i.emoji} ${esc(i.name)} <em>×${powerHeld(i.id)}</em></span>`).join('') +
      `</div>`
    : `<div class="pu-kit-lbl empty">⚡ KIT EMPTY — consumables carry between runs and are spent the moment they fire.</div>`;
}

// ══════════════════════════════════════════════════════════════════════
//  ⏱️ THE TENSION HOOK — one observer, eighteen clocks
// ══════════════════════════════════════════════════════════════════════
// "When any game timer falls below 5 seconds" is a fact about #g-time, which is
// the one element every game with a clock writes to. Watching it is what lets
// the soundtrack react without eighteen games learning about the soundtrack —
// the same trick the score race plays with setLive().
const TENSION_AT = 5;
function watchGameClock(){
  const el = document.getElementById('g-time');
  if(!el || typeof MutationObserver !== 'function') return;
  const read = () => {
    // Off the game screen there is no round, so there is nothing to be tense
    // about — a card left showing "3" must not keep the hub lifted.
    if(!document.getElementById('game-screen').classList.contains('active')){
      musicTension(false);
      return;
    }
    const s = parseClockText(el.textContent.trim());
    musicTension(s != null && s > 0 && s <= TENSION_AT);
  };
  new MutationObserver(read).observe(el, { childList: true, characterData: true, subtree: true });
  read();
}
watchGameClock();

// ══════════════════════════════════════════════════════════════════════
//  📅 DAILY HACK — one seeded run, the same for everyone
// ══════════════════════════════════════════════════════════════════════
// The seed is the UTC day, hashed. Nothing about the challenge is stored
// anywhere: which mission it is, what tier it runs at and what the board looks
// like are all DERIVED from that number, so every client picks the same
// challenge with no server state, no scheduled job, and no way to be handed a
// different one than the person you are racing. Same reasoning as the market's
// featured rotation a few thousand lines up, applied to a whole round.
//
// The pool is every mission whose difficulty lives entirely in its GENERATED
// CONTENT — Math Blitz's questions, Overclock Path's circuit, and the four
// § 9 missions whose whole board (patrol schedule, packet feed, cipher, sector
// corruption) is generated inside start() off the seeded stream.
//
// The rule the pool has always enforced is that a frame-rate difference must
// not quietly make it a different run. That is why a canvas game with physics
// was excluded — and why COOLANT is in the pool anyway: its flight model runs
// on a FIXED 120Hz accumulator rather than on dt, so two machines integrate the
// identical trajectory from the identical inputs. A game that is deterministic
// by construction qualifies; one that merely looks the same does not.
const DAILY_POOL = ['math', 'path', 'trace', 'defrag', 'cutter', 'sorter', 'coolant'];
const DAILY_TIER = 'overclocked';       // "high-speed": less clock, faster board, ×1.5 pay

// Two separate facts, because a replay of today's hack is still a Daily Hack
// round — it just does not score. `dailyActive` governs the seeded stream, the
// fixed tier and the seed row on the results card; `dailyRun` governs whether
// the number goes on the board.
let dailyActive = false;
let dailyRun = false;
let dailyRng = null;                    // the day's stream while one is running
let dailyRestoreTier = null;

// mulberry32 — small, fast, and identical across engines, which is the only
// property that matters here. A shared Math.random would not be: two browsers
// agree on its distribution and nothing else.
function makeRng(seed){
  let a = seed >>> 0;
  return function(){
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const dailySeed  = (day = dayKey()) => hashStr('daily:' + day);

// ══ 📅 WHICH MISSION, ON WHICH DAY ══
// This was `DAILY_POOL[dailySeed(day) % DAILY_POOL.length]` — an independent
// draw every day. The seed changed daily and so did the mission, so it was not
// broken, but an independent draw from seven options is LUMPY in exactly the
// way people notice: over three weeks it gave Ice Cutter and Signal Trace five
// slots each while Defrag and Packet Sort got one, and it repeated the same
// mission on consecutive days about one day in seven. A daily that serves the
// same game two days running reads as "the daily is stuck" no matter what the
// seed says.
//
// A SHUFFLED BAG fixes both. Each 7-day cycle is a deterministic permutation of
// the pool, so every mission appears exactly once per cycle — a real rotation
// rather than a sequence of coin flips — and the boundary check below stops a
// cycle from opening with the mission the previous one closed on.
//
// Still a pure function of the date: every player worldwide gets the same
// mission on the same UTC day, which is the whole point of the mode. Nothing is
// stored, so there is no state to migrate or drift.
const DAY_MS = 86400000;
const dayIndex = (day = dayKey()) => Math.floor(Date.parse(day + 'T00:00:00Z') / DAY_MS);

// The raw permutation for a cycle. Fisher-Yates off the same mulberry32 the
// seeded rounds use, so it is identical on every engine.
function dailyBagRaw(cycle){
  const rng = makeRng(hashStr('dailybag:' + cycle));
  const bag = DAILY_POOL.slice();
  for(let i = bag.length - 1; i > 0; i--){
    const j = Math.floor(rng() * (i + 1));
    const t = bag[i]; bag[i] = bag[j]; bag[j] = t;
  }
  return bag;
}

// ⚠️ The boundary fix compares against the RAW previous bag on purpose, and
// that is not a shortcut — it is what keeps this non-recursive. The adjustment
// only ever swaps positions 0 and 1, and with a pool of 7 neither is the last
// position, so a cycle's LAST entry is always its raw last entry. Comparing
// against the raw bag is therefore exactly equivalent to comparing against the
// adjusted one, without dailyBag() having to call itself back through history.
function dailyBag(cycle){
  const bag = dailyBagRaw(cycle);
  if(cycle > 0 && bag.length > 1){
    const prevLast = dailyBagRaw(cycle - 1)[DAILY_POOL.length - 1];
    if(bag[0] === prevLast){ const t = bag[0]; bag[0] = bag[1]; bag[1] = t; }
  }
  return bag;
}

const dailyGid = (day = dayKey()) => {
  const n = DAILY_POOL.length;
  const idx = dayIndex(day);
  return dailyBag(Math.floor(idx / n))[((idx % n) + n) % n];
};
const dailySeedLabel = (day = dayKey()) => `${day} · #${(dailySeed(day) % 100000).toString().padStart(5, '0')}`;
// Used by the seeded games. Outside a Daily Hack it is plain Math.random, so a
// game can call it unconditionally and an ordinary round is unaffected.
const dailyRand  = () => dailyRng ? dailyRng() : Math.random();

// Today's run, if it was set today. A stale day key reads as no run at all,
// which IS the 24-hour reset — nothing has to be cleaned up on a schedule.
function dailyMine(day = dayKey()){
  const d = (user && user.daily) || {};
  return d.day === day ? d : null;
}

function startDailyHack(){
  if(!user) return;
  const day = dayKey(), gid = dailyGid(day);
  const done = dailyMine(day);
  if(done){
    // Replayable, but only the first run counts — otherwise "identical for all
    // users" would just mean "identical, best of however many tries you have
    // time for".
    toast(`📅 Today's hack is already logged at ${done.pts} PTS — this run is practice.`, 3600);
  }
  dailyActive = true;
  dailyRun = !done;
  dailyRng = makeRng(dailySeed(day));
  curGame = gid;
  // The run is played at a fixed tier for everyone, then the player's own dial
  // is put back — the same save/restore shape a duel uses for the room's tier,
  // including its guard: only the FIRST capture counts, or a second daily
  // started before the first was settled would record Overclock as the tier to
  // "restore" and strand the player's own dial there for good.
  if(dailyRestoreTier == null) dailyRestoreTier = currentDifficultyTier;
  setDifficultyTier(DAILY_TIER);

  document.getElementById('g-title').textContent = `📅 DAILY HACK · ${META[gid].name}`;
  showScreen('game-screen');
  snd('success');
  toast(`📅 DAILY HACK — ${META[gid].emoji} ${META[gid].name} · seed ${dailySeedLabel(day)}`, 3600);

  resetGameStage(gid);
  countdown(() => {
    // The board is generated inside the game's start() call, synchronously and
    // before a single frame renders — so patching Math.random across just that
    // call is enough to make the LAYOUT identical without the seeded stream
    // being drained at different rates by whatever else the page is animating.
    // Math Blitz, whose questions keep coming during play, reads dailyRand()
    // directly instead.
    //
    // 🧊 And the same seam every other mode uses: the 3D build first, the 2D one
    // as the fallback. The seeded stream is patched around BOTH, so a hack plays
    // on today's layout whichever renderer the player chose — the two builds
    // draw from that stream at their own rates, so a 3D board and a 2D board of
    // the same seed are not pixel-identical, but each is identical for every
    // operative running that renderer, and the score lands on the same board.
    const realRandom = Math.random;
    Math.random = dailyRand;
    try{
      runMissionStart(() => {
        if(!(window.PI3D && PI3D.startFor(gid))) SOLO_START[gid]();
      });
    }
    finally{ Math.random = realRandom; }
    showPowerDock();
  });
}

// Stands the challenge down and gives the player their own dial back. Called
// from BOTH endings — the results card and the walk-away — because a round that
// was quit has to release the tier just as much as one that finished.
function endDailyRun(){
  const scored = dailyRun;
  dailyActive = false;
  dailyRun = false;
  dailyRng = null;
  if(dailyRestoreTier != null){ setDifficultyTier(dailyRestoreTier); dailyRestoreTier = null; }
  return scored;
}

// Quitting mid-hack. Wired into enterHub() alongside abortBossRush(), which is
// the one place every "I'm done here" path passes through.
function abortDailyRun(){
  if(!dailyActive) return;
  endDailyRun();
  paintDailyBanner();
}

// Called by showResultsCard() when a Daily Hack round lands.
function settleDailyRun(gid, pts){
  const day = dayKey();
  const scored = endDailyRun();
  paintDailyBanner();
  // A replay of an already-logged hack is practice: it plays on the same seed
  // and reads the same, but today's board is not up for a second attempt.
  if(!scored || !user) return;

  // ⚠️ A ZERO DOES NOT CLAIM THE DAY.
  // The day's attempt is claimed by the first run that FINISHES, and both the
  // profile record and the board row are effectively write-once — the board's
  // database rule refuses a second write outright, so a row cannot be improved
  // or removed once it exists. That combination turned a three-second misclick
  // into a 24-hour lockout: the run banked 0, the slot was gone, and every
  // attempt after it played as practice that could never post. Nothing about a
  // zero is worth ranking anyway, so it is treated as a run that did not
  // happen — the tier is still handed back, and the player can try again.
  if(!(pts > 0)){
    toast('📅 No points banked — today\'s hack is still open. Run it again.', 3600);
    return;
  }

  const prev = dailyMine(day);
  if(prev && prev.pts >= pts) return;
  user.daily = { day, pts, gid };
  saveProfilePatch({ daily: user.daily });
  publishDailyScore(day, pts, gid);
  paintDailyBanner();
}

// ── THE BOARD ──
// Its own node, keyed by day. Nothing prunes it: yesterday's key is simply
// never read again, which costs a few bytes and saves a scheduled job.
//
// ⚠️ DATABASE RULES: if your rules name specific top-level nodes, "daily" needs
// to be one of them, with an .indexOn of "pts". The rules also decide whether a
// row can be written twice — this project's refuse a second write to
// daily/$day/$uid, which is why settleDailyRun() is careful about what it
// spends the day's one write on.
//
// A refused write is REPORTED, not swallowed. It used to be a bare
// console.warn, and the result was a board that quietly stopped updating with
// nothing on screen to say so — the failure looked exactly like "my score
// didn't count", which is the one thing a player will not shrug off. The run
// itself is never lost: it is already in the profile and on the main
// leaderboard, and the panel falls back to showing it.
function publishDailyScore(day, pts, gid){
  if(!db || offlineMode || isLocalSession() || !user) return;
  db.ref(`daily/${day}/${user.uid}`).set({
    name: user.username || 'Operative',
    pts: Math.max(0, Math.round(pts)),
    gid,
    at: firebase.database.ServerValue.TIMESTAMP
  }).then(() => loadDailyBoard())
    .catch(e => {
      const denied = String((e && e.code) || e || '').toUpperCase().includes('PERMISSION_DENIED');
      console.warn('Daily board write failed — kept locally:', e);
      if(denied){
        console.warn('[daily] The grid refused the write. Firebase Console → Realtime ' +
                     'Database → Rules: "daily" must be writable at daily/$day/$uid, and ' +
                     'a rule that only allows the FIRST write per day will refuse every ' +
                     'later one, including an improved score.');
      }
      toast(denied ? '📅 The grid refused today\'s board entry — your run is saved on this device.'
                   : '📅 Daily board is unreachable — your run is saved on this device.', 4200);
    });
}

function loadDailyBoard(){
  const panel = document.getElementById('dh-lb-panel');
  if(!panel) return;
  const day = dayKey();
  const mine = dailyMine(day);

  // The offline/no-rules fallback: your own run is still a board, and saying so
  // beats an empty panel that looks broken.
  const localOnly = () => {
    panel.innerHTML = mine
      ? dailyRow({ name: (user && user.username) || 'You', pts: mine.pts }, 1, true) +
        `<div class="lb-empty dh-note">Grid board unavailable — showing your own run.</div>`
      : `<div class="lb-empty">No runs logged for today yet.</div>`;
  };

  if(!db || offlineMode || !user){ localOnly(); return; }

  withTimeout(db.ref('daily/' + day).orderByChild('pts').limitToLast(10).once('value'), NET_WAIT)
    .then(snap => {
      const rows = [];
      snap.forEach(c => { const v = c.val() || {}; rows.push({ uid: c.key, name: v.name, pts: +v.pts || 0 }); });
      if(!rows.length){ localOnly(); return; }
      rows.sort((a, b) => b.pts - a.pts);
      panel.innerHTML = rows.map((r, i) => dailyRow(r, i + 1, r.uid === user.uid)).join('');
    })
    .catch(e => { console.warn('Daily board read failed:', e); localOnly(); });
}

function dailyRow(r, rank, isMe){
  const medal = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : `#${rank}`;
  // Same row furniture as the live leaderboard — .lb-row already owns the
  // podium tints and the "that's you" rail, so a second board built out of it
  // is one board the eye has to learn instead of two.
  return `<div class="lb-row dh-row${isMe ? ' me' : ''}${rank <= 3 ? ' r' + rank : ''}">` +
         `<span class="lb-rank">${medal}</span>` +
         `<span class="lb-name">${esc(r.name || 'Operative')}${isMe ? ' · YOU' : ''}</span>` +
         `<span class="lb-score">${(+r.pts || 0).toLocaleString()} PTS</span>` +
         `</div>`;
}

function paintDailyBanner(){
  const sub = document.getElementById('dh-banner-sub');
  const reset = document.getElementById('dh-reset');
  const day = dayKey(), gid = dailyGid(day), mine = dailyMine(day);
  if(sub){
    sub.textContent = mine
      ? `${META[gid].emoji} ${META[gid].name} · your run is logged at ${mine.pts.toLocaleString()} PTS. Seed ${dailySeedLabel(day)}.`
      : `${META[gid].emoji} ${META[gid].name} on ${DIFFICULTY_TIERS[DAILY_TIER].label} — the same board for every operative. Seed ${dailySeedLabel(day)}.`;
  }
  const btn = document.getElementById('btn-daily-hack');
  if(btn) btn.textContent = mine ? '📅 REPLAY (PRACTICE)' : '📅 DAILY HACK';
  if(reset) reset.textContent = `RESETS IN ${rotationLabel()}`;
  document.getElementById('dh-banner')?.classList.toggle('done', !!mine);
}

// ══ 🕒 THE ROLLOVER ══
// Everything about the Daily Hack is a pure function of dayKey(), so the day
// genuinely turns over at UTC midnight with no stored state to reset — but
// NOTHING WAS WATCHING THE CLOCK. paintDailyBanner() ran only on entering the
// hub and after settling a run, so a tab left open across midnight kept showing
// yesterday's mission behind a "RESETS IN 0m" that never moved, and the button
// started yesterday's hack. It corrected itself on the next reload, which is a
// poor way to find out.
//
// A minute is fine: the countdown it repaints is displayed in whole minutes, so
// there is nothing to see in between. Comparing the KEY rather than counting
// down also means a laptop that was asleep across the boundary rolls over on
// its first tick after waking — a setTimeout aimed at midnight would not.
let _dhDay = dayKey();
setInterval(() => {
  const now = dayKey();
  const rolled = now !== _dhDay;
  if(rolled) _dhDay = now;
  // Only touch the DOM while the hub is actually on screen: the elements do not
  // exist to repaint otherwise, and a round in progress must not be disturbed.
  if(!document.getElementById('hub-screen')?.classList.contains('active')) return;
  paintDailyBanner();
  if(rolled){
    // The shop's featured stock is keyed to the same day, and the board is
    // per-day too, so both are stale the moment the key changes.
    try{ if(typeof paintFeatured === 'function') paintFeatured(); }catch(e){}
    try{ if(typeof loadDailyBoard === 'function') loadDailyBoard(); }catch(e){}
    const g = dailyGid(now);
    toast('📅 NEW DAILY HACK — ' + META[g].emoji + ' ' + META[g].name + ' is live.', 4200);
  }
}, 60000);

// ══════════════════════════════════════════════════════════════════════
//  🏆 ACHIEVEMENT MATRIX — the shelf, opened out
// ══════════════════════════════════════════════════════════════════════
// The badge shelf under the leaderboard is a row of icons with a tooltip; this
// is the same ACHIEVEMENTS table with room to actually read it. Both render
// from the one array, so an achievement added there appears in both.
function renderAchievementMatrix(){
  const grid = document.getElementById('ach-matrix');
  if(!grid || !user) return;
  const owned = user.achievements || {};
  const got = ACHIEVEMENTS.filter(a => owned[a.id]).length;
  const pct = Math.round((got / ACHIEVEMENTS.length) * 100);

  const sub = document.getElementById('ach-sub');
  if(sub) sub.textContent = `${got} of ${ACHIEVEMENTS.length} unlocked · ${pct}% of the matrix`;
  const fill = document.getElementById('ach-progress-fill');
  if(fill) fill.style.width = pct + '%';

  // Unlocked first: a wall that opens with everything you have not done reads
  // as a chore list rather than as a trophy case.
  const sorted = [...ACHIEVEMENTS].sort((a, b) => (owned[b.id] ? 1 : 0) - (owned[a.id] ? 1 : 0));
  grid.innerHTML = sorted.map(a => {
    const has = !!owned[a.id];
    const when = has && typeof owned[a.id] === 'number'
      ? new Date(owned[a.id]).toISOString().slice(0, 10) : null;
    return `<div class="ach-cell ${has ? 'unlocked' : 'locked'}">
              <span class="ach-ico">${a.icon}</span>
              <div class="ach-name">${esc(a.name)}</div>
              <div class="ach-desc">${esc(a.desc)}</div>
              <div class="ach-foot">
                <span class="ach-cr">💎 ${a.cr} CR</span>
                <span class="ach-state">${has ? (when || 'UNLOCKED') : 'LOCKED'}</span>
              </div>
            </div>`;
  }).join('');
}

// ══════════════════════════════════════════════════════════════════════
//  💀 EXIT STATES — what the screen does on the way out
// ══════════════════════════════════════════════════════════════════════
// One host element, three classes. Every style ends by calling `done`, and a
// hard timeout calls it too — a cosmetic that failed to finish must never be
// the reason a player never sees their score.
const EXIT_MS = { bsod: 2200, matrix: 1500, static: 900,
                  glitch: 1200, purge: 1300, rewind: 1500 };

function playExitFx(gid, pts, opts, done){
  const stage = document.getElementById('exit-fx');
  const body  = document.getElementById('exit-fx-body');
  const item  = user && findItem('exits', user.equipped && user.equipped.exits);
  const fx    = item && item.fx;

  // No style equipped, no board to cover (a duel writes its own card), or the
  // element is missing on an older cached page — straight through.
  if(!fx || !stage || !body || VFX.reducedMotion){ done(); return; }

  let settled = false;
  const finish = () => {
    if(settled) return;
    settled = true;
    stage.className = '';
    stage.style.display = 'none';
    body.innerHTML = '';
    done();
  };

  stage.style.display = 'block';
  stage.className = 'show fx-' + fx;

  if(fx === 'bsod'){
    // The joke only lands if it reads like the real thing, so it is a real dump:
    // the mission, the score, the tier and the seed, in the same key/value shape
    // the results breakdown uses.
    const m = META[gid] || { name: 'UNKNOWN', emoji: '❔' };
    const code = '0x' + (hashStr(gid + ':' + pts).toString(16).toUpperCase().padStart(8, '0')).slice(0, 8);
    body.innerHTML =
      `<div class="bsod-face">:(</div>` +
      `<div class="bsod-head">Your run ran into a problem and needs to restart.</div>` +
      `<div class="bsod-sub">We're just collecting some error info, and then we'll restart for you.</div>` +
      `<pre class="bsod-dump">` +
      `STOP CODE: MISSION_TERMINATED_UNEXPECTEDLY\n` +
      `FAULT MODULE: ${esc(m.name.replace(/\s+/g, '_'))}.SYS\n` +
      `EXCEPTION:   ${code}\n` +
      `SCORE:       ${pts} PTS\n` +
      `STABILITY:   ${(DIFFICULTY_TIERS[currentDifficultyTier] || {}).label || 'STABLE CORE'}\n` +
      `MODIFIER:    ${chaos.last ? chaos.last.name : 'NONE'}\n` +
      `OPERATIVE:   ${esc((user && user.username) || 'GUEST')}\n` +
      `</pre>` +
      `<div class="bsod-pct" id="bsod-pct">0% complete</div>`;
    const pctEl = document.getElementById('bsod-pct');
    let p = 0;
    const t = setInterval(() => {
      p = Math.min(100, p + 7 + Math.floor(Math.random() * 11));
      if(pctEl) pctEl.textContent = p + '% complete';
      if(p >= 100) clearInterval(t);
    }, 130);
    setTimeout(() => { clearInterval(t); finish(); }, EXIT_MS.bsod);
  }
  else if(fx === 'matrix'){
    // Columns of falling glyphs, built as elements with staggered animation
    // delays rather than a canvas: the board underneath is still a canvas, and
    // this way the dissolve composites over it without fighting for the context.
    const CH = 'アイウエオカキクケコサシスセソ0123456789ABCDEF<>/\\|=+*';
    const cols = Math.max(14, Math.min(48, Math.floor(window.innerWidth / 26)));
    let html = '';
    for(let c = 0; c < cols; c++){
      const glyphs = Array.from({ length: 22 },
        () => CH[Math.floor(Math.random() * CH.length)]).join('<br>');
      html += `<span class="mx-col" style="left:${(c / cols) * 100}%;` +
              `animation-delay:${(Math.random() * 0.5).toFixed(2)}s;` +
              `animation-duration:${(0.9 + Math.random() * 0.7).toFixed(2)}s">${glyphs}</span>`;
    }
    body.innerHTML = html;
    setTimeout(finish, EXIT_MS.matrix);
  }
  else if(fx === 'static'){
    body.innerHTML = `<div class="crt-flash"></div><div class="crt-noise"></div><div class="crt-roll"></div>`;
    snd('bigExplode');
    setTimeout(finish, EXIT_MS.static);
  }
  else if(fx === 'glitch'){
    // Displaced bands rather than one sheared image: a datamosh is the picture
    // arriving in the wrong ORDER, so each band gets its own offset, its own
    // delay and its own channel tint, and the eye reassembles a broken stream.
    const bands = 14;
    let html = '<div class="gl-rgb"></div>';
    for(let i = 0; i < bands; i++){
      const off = (Math.random() * 2 - 1) * 22;
      html += `<span class="gl-band" style="top:${(i / bands) * 100}%;height:${100 / bands + 0.4}%;` +
              `--gx:${off.toFixed(1)}%;animation-delay:${(Math.random() * 0.45).toFixed(2)}s"></span>`;
    }
    body.innerHTML = html;
    snd('glitch');
    setTimeout(finish, EXIT_MS.glitch);
  }
  else if(fx === 'purge'){
    body.innerHTML = `<div class="pg-line"></div><div class="pg-flash"></div>`;
    snd('bigExplode');
    setTimeout(finish, EXIT_MS.purge);
  }
  else if(fx === 'rewind'){
    // The tracking bar is the whole effect — a band of noise walking UP the
    // picture is what a tape looks like running backwards, and it reads as that
    // instantly without a single frame of video.
    body.innerHTML = `<div class="rw-noise"></div><div class="rw-track"></div>` +
                     `<div class="rw-lbl">◀◀ REWIND</div>`;
    snd('glitch');
    setTimeout(finish, EXIT_MS.rewind);
  }
  else finish();

  // The backstop. Whatever happens above, the card lands.
  setTimeout(finish, (EXIT_MS[fx] || 1200) + 900);
}

// ══════════════════════════════════════════════════════════════════════
//  📟 GRID TERMINAL — the arcade's ambient traffic
// ══════════════════════════════════════════════════════════════════════
// Wired to the database when there is one, and to a local simulation when there
// is not. The simulation is not a stub standing in for the real thing: an
// arcade whose grid is genuinely empty at 3am should still read as a live
// system, so the ticker publishes the things a system would say — open room
// codes, leaderboard milestones, the daily seed, stability warnings.
const CHAT_MAX = 40;
const CHAT_PATH = 'chat';
let chatTicker = null, chatBound = false;

const CHAT_SYSTEM = [
  () => `NODE SWEEP COMPLETE · ${40 + Math.floor(Math.random() * 900)} SECTORS NOMINAL`,
  () => `⚙️ STABILITY DRIFT DETECTED ON SECTOR ${String.fromCharCode(65 + Math.floor(Math.random() * 26))}${Math.floor(Math.random() * 90) + 10}`,
  () => `📅 DAILY HACK SEED ${dailySeedLabel()} — ${META[dailyGid()].name} IS LIVE`,
  () => `🔥 STREAK BONUSES PAID TO ${3 + Math.floor(Math.random() * 40)} OPERATIVES`,
  () => `🛒 FEATURED STOCK ROTATES IN ${rotationLabel()}`,
  () => `🌐 ROOM ${mpMakeCode()} OPEN · ${MP_MODES[Object.keys(MP_MODES)[Math.floor(Math.random() * Object.keys(MP_MODES).length)]].name}`,
  () => `🏆 ${['Vex','Nyx','Cipher','Ronin','Kilo','Static','Halcyon','Zero'][Math.floor(Math.random() * 8)]}_${Math.floor(Math.random() * 900) + 100} BANKED ${(Math.floor(Math.random() * 18) + 3) * 100} PTS`,
  () => `⚡ POWER-UP MARKET RESTOCKED — TIME DILATORS AT 5 CR`,
  () => `🤖 ${2 + Math.floor(Math.random() * 9)} TRAINING DROIDS IDLE ON THE GRID`,
  () => `🌀 CHAOS PROTOCOL ARMED FOR BOSS RUSH AND ARENA ROUNDS`
];

function chatPush(line, cls){
  const log = document.getElementById('chat-log');
  if(!log) return;
  const row = document.createElement('div');
  row.className = 'chat-line' + (cls ? ' ' + cls : '');
  const t = new Date();
  const stamp = `${String(t.getHours()).padStart(2,'0')}:${String(t.getMinutes()).padStart(2,'0')}`;
  row.innerHTML = `<span class="chat-time">${stamp}</span><span class="chat-body">${line}</span>`;
  log.appendChild(row);
  while(log.children.length > CHAT_MAX) log.removeChild(log.firstChild);
  log.scrollTop = log.scrollHeight;
}

// A message from a player is untrusted text and reaches the DOM escaped; a
// system line is written by this file and carries its own emphasis.
const chatSay = (name, text) =>
  chatPush(`<b class="chat-who">${esc(name)}</b> ${esc(text)}`, 'said');
const chatSys = text => chatPush(`<span class="chat-sys">${text}</span>`, 'sys');

function startChatTerminal(){
  const log = document.getElementById('chat-log');
  if(!log) return;
  if(!chatBound){
    chatBound = true;
    document.getElementById('chat-send')?.addEventListener('click', sendChat);
    document.getElementById('chat-input')?.addEventListener('keydown', e => {
      if(e.key === 'Enter') sendChat();
    });
  }
  if(log.children.length === 0){
    chatSys('◈ GRID TERMINAL ONLINE');
    chatSys(`◈ OPERATIVE ${esc(((user && user.username) || 'GUEST').toUpperCase())} AUTHENTICATED`);
  }

  // ── LIVE, when the database allows it ──
  // limitToLast keeps the client from pulling a day of backlog, and child_added
  // then delivers each new line as it arrives. A rules rejection is not an
  // error worth showing — it just means this deploy runs the simulation.
  if(db && !offlineMode && !chatTicker){
    try{
      const ref = db.ref(CHAT_PATH).limitToLast(15);
      ref.on('child_added', s => {
        const v = s.val() || {};
        if(!v.text) return;
        if(v.uid && user && v.uid === user.uid) return;   // our own echo is already on screen
        chatSay(v.name || 'Operative', String(v.text).slice(0, 140));
      }, () => { /* rules said no — the simulation below carries it */ });
    }catch(e){ /* same */ }
  }

  // ── THE SIMULATION ──
  // Runs regardless. On a live grid it is the system voice alongside the
  // players; on a quiet one it IS the grid.
  clearInterval(chatTicker);
  chatTicker = setInterval(() => {
    if(!document.getElementById('hub-screen').classList.contains('active')) return;
    chatSys(CHAT_SYSTEM[Math.floor(Math.random() * CHAT_SYSTEM.length)]());
  }, 11000);
  chatSys(CHAT_SYSTEM[Math.floor(Math.random() * CHAT_SYSTEM.length)]());
}

function stopChatTerminal(){
  clearInterval(chatTicker);
  chatTicker = null;
}

function sendChat(){
  const input = document.getElementById('chat-input');
  if(!input) return;
  const text = input.value.trim().slice(0, 140);
  if(!text) return;
  input.value = '';
  chatSay((user && user.username) || 'You', text);
  snd('tab');
  if(db && !offlineMode && !isLocalSession() && user){
    db.ref(CHAT_PATH).push({
      uid: user.uid,
      name: user.username || 'Operative',
      text,
      at: firebase.database.ServerValue.TIMESTAMP
    }).catch(() => chatSys('⚠️ TRANSMISSION HELD LOCALLY — GRID RELAY UNAVAILABLE'));
  }else{
    chatSys('⚠️ OFFLINE — TRANSMISSION VISIBLE ON THIS TERMINAL ONLY');
  }
}

// ══════════════════════════════════════════════════════════════════════
//  📋 INSTANT REPLAY — a run as a string
// ══════════════════════════════════════════════════════════════════════
// The payload is small and self-describing: version, mission, score, tier,
// timestamp, seed. It is base64 of a compact JSON object with a checksum, so a
// code that was mangled in a chat client is REJECTED rather than decoded into a
// plausible-looking lie. This is a shareable receipt, not a credential — it
// grants nothing, and nothing reads it back into the profile.
const REPLAY_PREFIX = 'PIR1.';
let lastReplay = null;

// btoa only handles latin1, and a username can be anything at all — so the
// JSON is percent-encoded into ASCII first and decoded back on the way out.
const b64enc = s => btoa(unescape(encodeURIComponent(s))).replace(/=+$/, '');
const b64dec = s => decodeURIComponent(escape(atob(s)));

function stampReplay(gid, pts, tierKey){
  lastReplay = {
    v: 1,
    g: gid,
    p: Math.round(pts),
    t: tierKey,
    d: Date.now(),
    s: dailyActive ? dailySeed() : (chaos.last ? chaos.last.id : null),
    n: ((user && user.username) || 'Operative').slice(0, 20)
  };
  const out = document.getElementById('res-replay');
  if(out) out.textContent = '';
  const btn = document.getElementById('btn-replay-export');
  if(btn) btn.textContent = '📋 Export Replay Code';
}

function encodeReplay(r){
  const json = JSON.stringify(r);
  return REPLAY_PREFIX + b64enc(json) + '.' + hashStr(json).toString(36);
}

function decodeReplay(code){
  const raw = String(code || '').trim();
  if(!raw.startsWith(REPLAY_PREFIX)) throw new Error('That is not a Point Invaders replay code.');
  const parts = raw.slice(REPLAY_PREFIX.length).split('.');
  if(parts.length !== 2) throw new Error('Replay code is incomplete — it was cut short somewhere.');
  let json;
  try{ json = b64dec(parts[0]); }
  catch(e){ throw new Error('Replay code is corrupted and cannot be read.'); }
  if(hashStr(json).toString(36) !== parts[1]) throw new Error('Replay checksum failed — this code was altered in transit.');
  const r = JSON.parse(json);
  if(!r || !META[r.g]) throw new Error('That replay names a mission this build does not have.');
  return r;
}

async function exportReplay(){
  if(!lastReplay){ snd('deny'); return; }
  const code = encodeReplay(lastReplay);
  const out = document.getElementById('res-replay');
  const btn = document.getElementById('btn-replay-export');
  // Shown on screen whatever happens — the clipboard is blocked over plain http
  // and inside several in-app browsers, and a code you can read is a code you
  // can retype.
  if(out) out.innerHTML = `<div class="replay-code" id="replay-code">${esc(code)}</div>` +
                          `<div class="replay-hint">Paste this into LOAD REPLAY on any grid.</div>`;
  try{
    await navigator.clipboard.writeText(code);
    if(btn) btn.textContent = '✔ Copied to clipboard';
    snd('coin');
  }catch(e){
    if(btn) btn.textContent = '📋 Copy it from below';
  }
  setTimeout(() => { if(btn) btn.textContent = '📋 Export Replay Code'; }, 2600);
}

function loadReplay(){
  const input = document.getElementById('replay-input');
  const out = document.getElementById('replay-out');
  if(!input || !out) return;
  let r;
  try{ r = decodeReplay(input.value); }
  catch(e){
    snd('error');
    out.innerHTML = `<div class="replay-err">⚠️ ${esc(e.message)}</div>`;
    return;
  }
  const m = META[r.g];
  const tier = DIFFICULTY_TIERS[r.t] || DIFFICULTY_TIERS.stable;
  const when = new Date(r.d);
  const mine = (user && user.highScores && +user.highScores[r.g]) || 0;
  const delta = mine ? r.p - mine : null;
  snd('success');
  out.innerHTML =
    `<div class="replay-card">
       <div class="replay-head"><span class="replay-emoji">${m.emoji}</span>
         <div><div class="replay-title">${esc(m.name)}</div>
              <div class="replay-by">by ${esc(r.n || 'Operative')}</div></div>
         <div class="replay-score">${(+r.p || 0).toLocaleString()}<em>PTS</em></div>
       </div>
       <div class="res-row"><span>⚙️ Stability</span><span class="rv">${tier.icon} ${tier.label}</span></div>
       <div class="res-row"><span>🕒 Logged</span><span class="rv">${when.toISOString().slice(0,16).replace('T',' ')} UTC</span></div>
       ${r.s ? `<div class="res-row"><span>🔑 Seed / Modifier</span><span class="rv">${esc(String(r.s))}</span></div>` : ''}
       ${delta == null ? '' :
         `<div class="res-row"><span>📊 vs Your Best</span><span class="rv ${delta > 0 ? 'worse' : 'better'}">` +
         `${delta > 0 ? `${delta.toLocaleString()} AHEAD OF YOU` : delta < 0 ? `${Math.abs(delta).toLocaleString()} BEHIND YOU` : 'DEAD LEVEL'}</span></div>`}
     </div>
     <button class="btn btn-primary btn-sm replay-try" id="replay-try">▶ Run ${esc(m.name)}</button>`;
  document.getElementById('replay-try').onclick = () => {
    curGame = r.g;
    if(DIFFICULTY_TIERS[r.t]) setDifficultyTier(r.t);   // match the run you are chasing
    document.getElementById('g-title').textContent = m.name;
    showScreen('game-screen');
    prepGame(r.g);
  };
}

// ══════════════════════════════════════════════════════════════════════
//  🎵 MUSIC DRIVES — hand the equipped one to the sequencer
// ══════════════════════════════════════════════════════════════════════
// A drive is a cosmetic, so it is applied on the same pass as the colour and
// the pointer (applyEquippedCosmetics). The engine owns everything about what a
// drive SOUNDS like; this only decides which row of the table it is handed.
function applyMusicDrive(){
  if(!window.SFX || !SFX.setDrive) return;
  const item = (user && findItem('drives', user.equipped && user.equipped.drives)) || SHOP_ITEMS.drives[0];
  SFX.setDrive({ bpm: item.bpm, chords: item.chords, voice: item.voice });
}

// ══════════════════════════════════════════════════════════════════════
//  🔌 HUB WIRING — the new doors
// ══════════════════════════════════════════════════════════════════════
// Every binding is optional-chained for the same reason the originals are: a
// browser holding a cached older index.html against this app.js should lose one
// button, not every statement after it.

// ── OVERLAYS ──
// Both reuse the feedback modal's shell, so they get its backdrop and scroll
// behaviour; only the open/close wiring is local.
function openOverlay(id, render){
  const ov = document.getElementById(id);
  if(!ov || !user) return;
  if(render) render();
  ov.classList.add('show');          // the shell's own open state — see .fb-overlay.show
  ov.setAttribute('aria-hidden', 'false');
  snd('tab');
}
// Some modals are more than a CSS class. The feedback terminal and the save-
// account panel each keep their own open flag, timers and a CAPTURE-phase key
// listener inside an IIFE; the onboarding tour owes a "seen it" flag; the
// briefing owes the card id it was opened for. Flipping the class from out here
// — which is exactly what the gamepad's B button did — left the DOM closed and
// the module open: the button that opens it went dead, and the capture listener
// kept swallowing every keydown before the mission could see it.
//
// So the generic closer is a dispatcher. A modal with its own teardown
// registers it here and closeOverlay() runs THAT; everything else falls through
// to the plain class flip it always did.
const OVERLAY_CLOSERS = Object.create(null);
let overlayClosing = null, overlayBlipped = false;

// ownsSound: true for a closer that already plays its own back blip without
// going through here — closeBriefing() does — so the dispatcher stays quiet.
function registerOverlayCloser(id, fn, ownsSound){
  OVERLAY_CLOSERS[id] = { fn, ownsSound: !!ownsSound };
}

function closeOverlay(id){
  const ov = document.getElementById(id);
  if(!ov) return;
  const own = OVERLAY_CLOSERS[id];
  // overlayClosing is the loop-back guard: finishOnboard() closes through here,
  // so its own registration must not call it straight back into itself.
  if(own && overlayClosing !== id){
    const wasOpen = ov.classList.contains('show');
    const prev = overlayClosing;
    overlayClosing = id; overlayBlipped = false;
    try{ own.fn(); }
    catch(e){ console.error('[OVERLAY] closer for ' + id + ' failed:', e); }
    finally{ overlayClosing = prev; }
    // The back blip is for a close that actually happened: a modal mid-send
    // refuses to go, and one that already made the sound must not make it twice.
    if(wasOpen && !ov.classList.contains('show') && !overlayBlipped && !own.ownsSound){
      snd('uiBack');
    }
    return;
  }
  ov.classList.remove('show');
  ov.setAttribute('aria-hidden', 'true');
  overlayBlipped = true;
  snd('uiBack');
}

document.getElementById('btn-achievements')?.addEventListener('click',
  () => openOverlay('ach-overlay', renderAchievementMatrix));
document.getElementById('ach-close')?.addEventListener('click', () => closeOverlay('ach-overlay'));
document.getElementById('ach-overlay')?.addEventListener('click', e => {
  if(e.target.id === 'ach-overlay') closeOverlay('ach-overlay');
});

